\section{Alternative Expression of Being Not-Anywhere-Exponentially-Unbalanced}
Def.~\ref{PhiBalanced}, the definition of being not-anywhere-exponentially-unbalanced used herein and in Ref.~\cite{jackson2025explainingubiquityphasetransitions}, may be re-expressed as an equivalent, more mathematical, expression. This is given below as Def~\ref{def:NewNAEU}.
\begin{definition}
    \label{def:NewNAEU}
    A language, $\mathcal{L} \subseteq \Sigma^*$, is \underline{not-anywhere-exponentially-unbalanced} if and only if:
    \begin{align}
        \dfrac{\big \vert \big \{x \in \mathcal{B}_n^{\phi} \text{ } \vert \text{ } \mathcal{P}(x) = \text{Accept} \text{ } \big\} \cap \mathcal{L} \big \vert}{\big \vert \mathcal{B}_n^{\phi} \big \vert},
         \dfrac{\big \vert \big \{x \in \mathcal{B}_n^{\phi} \text{ } \vert \text{ } \mathcal{P}(x) = \text{Reject} \text{ } \big\} \cap \mathcal{L}^c \big \vert}{\big \vert \mathcal{B}_n^{\phi} \big \vert}
         \geq \big( \textit{Poly}(x) \big)^{-1},
    \end{align}
    where $\mathcal{P}: \Sigma^* \longrightarrow \{\text{Accept}, \text{Reject}, \perp\}$  and $\phi: \Sigma^* \longrightarrow \Sigma^*$ are as in Def.~\ref{def:RoughP}, and $\mathcal{L}^c = \big\{ x \in \Sigma^* \text{ }\vert  \text{ } x \not \in \mathcal{L} \big\}$; for some polynomial, $\textit{Poly}: \mathbb{N}_0 \longrightarrow \mathbb{R}$, such that: $\forall n \in \mathbb{N}_0$,
    \begin{align}
    \dfrac{\partial}{\partial x} \bigg(\textit{Poly}(x) \cdot \big( 1 / \sqrt{2} \big)^x \bigg) \bigg \vert_{x = n} \leq 0.
    \end{align}
\end{definition}
For convenience of comparison, I also restate Def.~\ref{PhiBalanced} below.
\begin{definitionRestate}\ref{PhiBalanced} (Restated)\\
    \label{PhiBalancedRestate}
    A language is \underline{not-anywhere-exponentially-unbalanced} if there exists some polynomial, $\textit{Poly}: \mathbb{N} \longrightarrow \mathbb{R}$, such that $\forall n \in \mathbb{N}$, neither the fraction of $\mathcal{B}_n^{\phi}$ that is in the language (and $\mathcal{P}$ decides correctly) nor the fraction not in the language (and $\mathcal{P}$ decides correctly) are less than $\big( \textit{Poly}(n) \big)^{-1}$, and $\textit{Poly}(n) \cdot \big( 1 / \sqrt{2} \big)^n$ is monotonically decreasing.
\end{definitionRestate}
For completeness, I state the below Lemma~\ref{lem:defsEquiv} without proof (as Def.~\ref{def:NewNAEU} is just Def.~\ref{PhiBalanced} expressed more mathematically).
\begin{lemma}
    \label{lem:defsEquiv}
    Def.~\ref{PhiBalanced} and Def.~\ref{def:NewNAEU} are equivalent.
\end{lemma}


\section{Auxiliary Lemmas for the Proof of Theorem~\ref{lem:MainLemma}}
\label{app:LemsForMainLemma}
This appendix states and proves Lemma~\ref{lem:PIsoExists} and Lemma~\ref{lem:PisoImpliesPhase}, both of which are required by the proof of Theorem~\ref{lem:MainLemma} in Sec.~\ref{sec:proofOfMainLemma}.
There are also several other lemmas, in this appendix, to assist in proving these lemmas.
\subsection{Proving Lemma~\ref{lem:PIsoExists}}
\begin{lemma}
    \label{lem:BasicIsomorpLemma}
    Any language over an alphabet $\Sigma = \{ 1, 2, ..., \vert \Sigma \vert \}$ is preserving-P-isomorphic to a language over the alphabet $\Pi = \{ 1, 2, ..., \vert \Sigma \vert,  \vert \Sigma \vert + 1 \}$.
\end{lemma}
\begin{proof}
    Let $\mathcal{L} \subseteq \Sigma^*$ be a language. I then aim to construct the required language over $\Pi$ that $\mathcal{L}$ is preserving-P-isomorphic to.
    This is accomplished by defining the language $\mathcal{L}$ is preserving-P-isomorphic to, $\mathcal{H}$, by:
    \begin{align}
        \label{eqn:preservinginAppendixA}
        \xi(x) \in \mathcal{H} \iff x \in \mathcal{L},
    \end{align}
    where $\xi: \Sigma^* \longrightarrow \Pi^*$ is some to-be-defined polynomial-time computable P-isomorphism. I.e. Eqn.~\ref{eqn:preservinginAppendixA} is tautologically true.

    Note that this definition automatically makes $\xi$ a preserving-P-isomorphism (as in Def.~\ref{def:preservingPIso}) between $\mathcal{L}$ and $\mathcal{H}$.

    Properly defining $\xi$ first requires defining two functions that are composed to form it, in Def.~\ref{def:OmegaSigma} and Def.~\ref{def:alphaPi}.
    \begin{definition}
        \label{def:OmegaSigma}
        Define $\theta_{\Sigma}: \Sigma^* \longrightarrow \mathbb{N}_0$ by: $\forall x \in \Sigma^*$,
        \begin{align}
            \theta_{\Sigma}(x)
            &=
            \sum^{\vert x \vert - 1}_{j = 0} \bigg( \vert \Sigma \vert^j \big[ x \big]_j \bigg),
        \end{align}
        where $\big[ \cdot \big]_j: \Sigma^* \longrightarrow \mathbb{N}^{\leq \vert \Sigma \vert}$ returns the symbol with index $j \in \mathbb{N}$ (using zero-indexing) in its argument word~\footnote{$\big[ \cdot \big]_j$ is also defined polymorphically to function correctly regardless of the alphabet in use.}. I.e. $\theta_{\Sigma}$ interprets any string in $\Sigma^*$ as a little-endian expression of an integer, in base $\vert \Sigma \vert$, and returns that integer.
    \end{definition}
    \begin{definition}
        \label{def:alphaPi}
        Define~\footnote{Note that this formula, in Eqn.~\ref{eqn:alphaDefiniEquation}, is zero-indexing.} $\alpha_{\Pi}: \mathbb{N}_0 \longrightarrow \Pi^*$ by: $\forall n \in \mathbb{N}_0$, $\forall j \in \mathbb{N}^{\leq \vert \alpha_{\Pi}(n) \vert - 1}$ \footnote{I note that $\vert \alpha_{\Pi}(n) \vert$ can always be efficiently calculated without using Eqn.~\ref{eqn:alphaDefiniEquation}.},
        \begin{align}
            \label{eqn:alphaDefiniEquation}
            \big[ \alpha_{\Pi}(n) \big]_{j}
            &=
            \bigg \lfloor \dfrac{n}{\vert \Pi \vert^j}  \bigg \rfloor \text{ mod } \vert \Pi \vert.
        \end{align}
    \end{definition}
    I then define my proposed preserving-P-isomorphism, $\xi: \Sigma^* \longrightarrow \Pi^*$, as in Def.~\ref{def:DefingXi}.
    \begin{definition}
    \label{def:DefingXi}
        Define the preserving-P-isomorphism, 
        $\forall x \in \Sigma^*$, $\xi: \Sigma^* \longrightarrow \Pi^*$, by:
    \begin{align}
        \xi(x)
        &=
        \alpha_{\Pi} \big( \theta_{\Sigma}(x) \big).
    \end{align}
    As each of its constituent parts are polynomial-time computable, so is $\xi$. 
    \end{definition}

    Therefore it only remains to show $\xi: \Sigma^* \longrightarrow \Pi^*$ is an isomorphism. For this, I propose the following candidate for the inverse of $\xi$ (i.e. $\xi^{-1}: \Pi^* \longrightarrow \Sigma^*$): $\forall y \in \Pi^*$,
    \begin{align}
        \xi^{-1}(y) &= \alpha_{\Sigma} \big( \theta_{\Pi}(y) \big).
    \end{align}
    $\xi^{-1}$ is polynomial time computable as, like $\xi$, it is composed of a fixed number of polynomial time functions and inverts $\xi$ as: for any alphabet, $\Xi$, and $\forall z \in \Xi^*$, $\forall n \in \mathbb{N}_0$,
    \begin{align}
        &\forall j \in \mathbb{N}^{\leq \vert \alpha_{\Xi} \big( \theta_{\Xi}(z) \big) \vert - 1}, \big[  \alpha_{\Xi} \big( \theta_{\Xi}(z) \big) \big]_{k}
        =
        \bigg \lfloor \dfrac{\sum^{\vert z \vert - 1}_{j = 0} \big( \vert \Xi \vert^j \big[ z \big]_j \big)}{\vert \Xi \vert^k}  \bigg \rfloor \text{ mod } \vert \Xi \vert
        =
        \bigg \lfloor \sum^{\vert z \vert - 1}_{j = 0} \big( \vert \Xi \vert^{j-k} \big[ z \big]_j \big)  \bigg \rfloor \text{ mod } \vert \Xi \vert
         =
         \sum^{\vert z \vert -1}_{j = k} \big( \vert \Xi \vert^{j-k} \big[ z \big]_j \big) \text{ mod } \vert \Xi \vert
         =
        \big[ z \big]_{k}
        \label{Eqn:FirstToRedInEqn}\\
        &\text{ and; as } \forall n \in \mathbb{N}_0, \exists q_n \in \Xi^* \text{ such that } \theta_{\Xi}(q_n) = n; \hspace{0.5cm} \theta_{\Xi} \big( \alpha_{\Xi}\big (n \big) \big)
        =
        \theta_{\Xi} \big( \alpha_{\Xi}\big ( \theta_{\Xi}(q_n) \big) \big)
        =
        \theta_{\Xi}(q_n)
        = n
        \label{Eqn:secondToRedInEqn},
    \end{align}
    where the second equality in Eqn.~\ref{Eqn:secondToRedInEqn} follows from Eqn.~\ref{Eqn:FirstToRedInEqn}. Therefore, I conclude this proof by showing: $\forall x \in \Sigma^*$, $\forall y \in \Pi^*$,
    \begin{align}
        \xi^{-1} (\xi(x))
        =
        \alpha_{\Sigma} \big( \theta_{\Pi}( \alpha_{\Pi} \big( \theta_{\Sigma}(x) \big)) \big)
        =
        \alpha_{\Sigma} \big( \theta_{\Sigma}(x) \big)
        =
        x
       \hspace{0.5cm} \text{ and } \hspace{0.5cm}
        \xi(\xi^{-1}(y)) 
        &=
        \alpha_{\Pi} \big( \theta_{\Sigma}( \alpha_{\Sigma} \big( \theta_{\Pi}(y) \big) ) \big)
        = 
        \alpha_{\Pi} \big( \theta_{\Pi}(y) \big)
        =
        y.
    \end{align}
    Hence $\xi$ is an isomorphism. Therefore, also using Eqn.~\ref{eqn:preservinginAppendixA} and that $\xi$ can be impliemented efficiently, I conclude that  $\xi$ is a preserving-P-isomorphism.
\end{proof}
