\begin{lemma}
    \label{lem:polyBoundedIfPoly}
    If $\textit{Poly(n)} \big( 1 / \sqrt{2} \big)^n$ is monotonically decreasing and, $\forall n \in \mathbb{N}_0$,
    \begin{align}
        \dfrac{\partial}{ \partial x} \bigg( \textit{Poly}(x) \bigg) \bigg \vert_{ x = 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big)}
        \leq
        \dfrac{\big \vert \ln{\big( 1 / \sqrt{2} \big)} \big \vert}{2 \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big)} \textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big),
    \end{align}
    then
    $\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n$ is monotonically decreasing.
\end{lemma}
\begin{proof}
    Consider $\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n$ and take the derivative with respect to $n$:
    \begin{align}
        \dfrac{\partial}{ \partial n} \bigg(\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n \bigg)
        =&
        2 \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big( 1 / \sqrt{2} \big)^n \dfrac{\partial}{ \partial x} \bigg( \textit{Poly}(x) \bigg) \bigg \vert_{ x = 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big)} \nonumber\\
        &+
        \label{eqn:FirstForPropertyTwo}
        \ln{\big( 1 / \sqrt{2} \big)}\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n.
    \end{align}
    For $\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n$ to be monotonically decreasing, Eqn.~\ref{eqn:FirstForPropertyTwo} must be less than or equal to zero for all $n \in \mathbb{N}$.
    Rearranging the required inequality, $\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n$ being monotonically decreasing is equivalent to:
    \begin{align}
        \label{eqn:FirstForPropertyTwoNumberTwo}
        2 \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big( 1 / \sqrt{2} \big)^n \dfrac{\partial}{ \partial x} \bigg( \textit{Poly}(x) \bigg) \bigg \vert_{ x = 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big)}
        &\leq
        \big \vert \ln{\big( 1 / \sqrt{2} \big)} \big \vert\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n\\
        \iff
        \dfrac{\partial}{ \partial x} \bigg( \textit{Poly}(x) \bigg) \bigg \vert_{ x = 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big)}
        &\leq
        \dfrac{\big \vert \ln{\big( 1 / \sqrt{2} \big)} \big \vert}{2 \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big)} \textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big).
    \end{align}
    Eqn.~\ref{eqn:FirstForPropertyTwoNumberTwo}, by assumption, holds. Therefore, $\textit{Poly} \big( 2n \log_{\vert \Sigma \vert} \big( \vert \Sigma \vert + 1 \big) \big) \big( 1 / \sqrt{2} \big)^n$ is monotonically decreasing.
\end{proof}

\begin{lemma}
    \label{lem:PisoImpliesPhase}
	Any language that is preserving-P-isomorphic to a language that exhibits a phase transition also exhibits a phase transition.
\end{lemma}
\begin{proof}
Let $\Sigma$ and $\Pi$ be alphabets.
	Additionally, let $\mathcal{L} \subset \Sigma^*$ be a language and $\xi: \Sigma^* \longrightarrow \Pi^*$ be a preserving-P-isomorphism from $\mathcal{L}$ to $\mathcal{H}$, where $\mathcal{H} \subset \Pi^*$ is a language that exhibits a phase transition.

	Suppose $\gamma: \Pi^* \longrightarrow \mathbb{R}$ is the parameter that induces the phase transition in $\mathcal{H}$. I then define another parameter, $\gamma': \Sigma^* \longrightarrow \mathbb{R}$, intended to induce a phase transition in $\mathcal{L}$ by: $\forall x \in \Sigma^*$,
	\begin{align}
		\gamma'(x)
		=
		\big( \xi \circ \gamma \big)(x).
	\end{align}
	To show that $\gamma': \Sigma^* \longrightarrow \mathbb{R}$ induces a phase transition in $\mathcal{L}$, I consider each condition (abbreviated $\bold{Cond.}$ below) of phase transitions (as defined in Def.~\ref{PhaseDef}), in turn, and show they are met:\\

\begin{enumerate}
	\item[\underline{\textbf{Cond. 1:}}] Define $\Tilde{S}^{\gamma}_n = \big \{ y \in \Pi^* \text{ } \vert \text{ } \gamma(y) = n \big \} \subseteq \Pi^*$ (where the tilde is used to denote that $\Tilde{S}^{\gamma}_n$ is a subset of $\Pi^*$) and consider:
	\begin{align}
		S^{\gamma'}_n &= S^{\xi \circ \gamma}_n = \big \{ x \in \Sigma^* \text{ } \vert \text{ } ( \xi \circ \gamma )(x) = n \big \} \nonumber \\
        \label{eqn:equivOfSgammaStuff}
		\Rightarrow
		\xi \big( S^{\gamma'}_n \big) 
		&=
		 \big \{ \xi(x) \in \Pi^* \text{ } \vert \text{ } x \in \Sigma^* \text{ and } ( \xi \circ \gamma )(x) = n \big \}
		=
		 \big \{ y \in \Pi^* \text{ } \vert \text{ } ( \xi \circ \gamma )(\xi^{-1}(y)) = n \big \}
		 =
		 \big \{ y \in \Pi^* \text{ } \vert \text{ } \gamma(y) = n \big \}
		 =
		 \Tilde{S}^{\gamma}_n.
	\end{align}
	Switching focus, let $\mathcal{A}_{\mathcal{H}} \big[ \Tilde{S} \big]$ be the fraction of $\Tilde{S} \subseteq \Pi^*$ that is in $\mathcal{H}$; known as the acceptance fraction of $\mathcal{H}$ in $\Tilde{S}$. Similarly, let $\mathcal{A}_{\mathcal{L}} \big[ S \big]$ be the fraction of $S \subseteq \Sigma^*$ that is in $\mathcal{L}$. As, by assumption, $\mathcal{H}$ exhibits a phase transition:
	\begin{align}
        \label{eqn:limitingOfALp}
		\lim_{n \longrightarrow \infty} \bigg( \mathcal{A}_{\mathcal{H}} \big[ \Tilde{S}^{\gamma}_n \big] \bigg) 
		=
		1.
	\end{align}
	As $\xi$ is a preserving-P-isomorphism, $\xi$ is bijective and, $\forall x \in \Sigma^*$, $x \in \mathcal{L} \iff \xi(x) \in \mathcal{H}$. Therefore, also using that $\xi \big( S^{\gamma'}_n \big) = \Tilde{S}^{\gamma}_n$ (as shown in Eqn.~\ref{eqn:equivOfSgammaStuff}), the equation for $\mathcal{A}_{\mathcal{L}} \big[ S^{\gamma'}_n \big]$ (Eqn.~\ref{eqn:indef:acceptingFraction}) in Def.~\ref{def:acceptingFraction} implies that: $\forall n \in \mathbb{N}_0$,
	\begin{align}
        \label{eqn:equatingAs}
		\mathcal{A}_{\mathcal{L}} \big[ S^{\gamma'}_n \big]
		=
        \dfrac{\big \vert \mathcal{L} \cap S^{\gamma'}_n \big \vert}{\big \vert S^{\gamma'}_n \big \vert}
        =
        \dfrac{\big \vert \xi \big( \mathcal{L} \cap S^{\gamma'}_n \big) \big \vert}{\big \vert \xi \big( S^{\gamma'}_n \big) \big \vert}
        =
        \dfrac{\big \vert \xi \big( \mathcal{L} \big) \cap \xi \big( S^{\gamma'}_n \big) \big \vert}{\big \vert \xi \big( S^{\gamma'}_n \big) \big \vert}
        =
        \dfrac{\big \vert \mathcal{H} \cap \Tilde{S}^{\gamma}_n \big \vert}{\big \vert \Tilde{S}^{\gamma}_n \big \vert}
		=
		\mathcal{A}_{\mathcal{H}} \big[ \Tilde{S}^{\gamma}_n \big].
	\end{align}
	Hence, combining Eqn.~\ref{eqn:limitingOfALp} and Eqn.~\ref{eqn:equatingAs} gives the required $\mathbf{Cond~1}$ for $\mathcal{L}$:
	\begin{align}
		\lim_{n \longrightarrow \infty} \bigg( \mathcal{A}_{\mathcal{L}} \big[ S^{\gamma'}_n \big] \bigg)
		=
		\lim_{n \longrightarrow \infty} \bigg( \mathcal{A}_{\mathcal{H}} \big[ \Tilde{S}^{\gamma}_n \big] \bigg) 
		=
		1.
	\end{align}		  	 

	\item[\underline{\textbf{Cond. 2:}}] Using similar reasoning to above, as, by assumption, $\mathcal{H}$ exhibits a phase transition and $\xi$ is a preserving-P-isomorphism:
	\begin{align}
		\lim_{n \longrightarrow -\infty} \bigg( \mathcal{A}_{\mathcal{L}} \big[ S^{\gamma'}_n \big] \bigg)
		=
		\lim_{n \longrightarrow -\infty} \bigg( \mathcal{A}_{\mathcal{H}} \big[ \Tilde{S}^{\gamma}_n \big] \bigg) 
		=
		0.
	\end{align}

	\item[\underline{\textbf{Cond. 3:}}] As $\xi: \Sigma^* \longrightarrow \Pi^*$ is a preserving-P-isomorphism, it is a bijection, therefore: $\forall S \subseteq \Sigma^*$,
	\begin{align}
		\big \vert \xi (S) \big \vert 
		=
		\big \vert S \big \vert.
	\end{align}
	The next step first requires a brief diversion to define a useful subset, in Def.~\ref{def:SinRange}.
    \begin{definition}
        \label{def:SinRange}
    For a fixed $\delta \in \mathbb{R}$, $\forall A \in \mathbb{R}$, define $\underline{\Tilde{S}^{\gamma}_{A, A+\delta}}  \subset \Pi^*$ by:
	\begin{align}
		\Tilde{S}^{\gamma}_{A, A+\delta}
		=
		\big \{ x \in \Pi^* \text{ }\vert \text{ } \gamma(x) \in [A, A + \delta] \big \},
	\end{align}
    and similarly define $S^{\gamma'}_{A, A + \delta} = \big \{ y \in \Sigma^* \text{ } \vert \text{ } \gamma (\xi(y)) \in [A, A + \delta ] \big \}$.
        \end{definition}
        Resuming the main thread of this proof, and using Def.~\ref{def:SinRange}:
	\begin{align}
        \label{eqn:xi-1SThing}
		 \xi^{-1} \big( \Tilde{S}^{\gamma}_{A, A + \delta} \big)
		 &=
		 \big \{ \xi^{-1}(x) \in \Sigma^* \text{ } \vert \text{ } x \in \Pi^* \text{ and } \gamma(x) \in [A, A + 			\delta ] \big \}
		 =
		 \big \{ y \in \Sigma^* \text{ } \vert \text{ } \gamma (\xi(y)) \in [A, A + \delta ] \big \}
		 =
		 S^{\gamma'}_{A, A + \delta}
         \subseteq
         \Sigma^*.
	\end{align}
	As $\mathcal{H}$, by assumption, exhibits a phase transition, $\vert \Tilde{S}^{\gamma}_{A, A+\delta} \vert $ decays sufficiently quickly (i.e. exponentially) as $A$ approaches its own, corresponding, threshold to meet the third required condition of phase transitions. Therefore, using that $\xi^{-1}: \Pi^* \longrightarrow \Sigma^*$ is a P-isomorphism (as shown in Lemma~\ref{Lem:inverseIsPreserve}, in Appendix~\ref{sec:PIsoDetailsAppendix}), and therefore a bijection, Eqn.~\ref{eqn:xi-1SThing} implies:
	\begin{align}
		\big \vert \Tilde{S}^{\gamma}_{A, A+\delta} \big \vert
		=
		\big \vert \xi^{-1} \big( \Tilde{S}^{\gamma}_{A, A+\delta} \big) \big \vert
		=
		\big \vert S^{\gamma'}_{A, A + \delta} \big \vert.
	\end{align}
	I then conclude that $\big \vert S^{\gamma'}_{A, A + \delta} \big \vert$ must also decay sufficiently quickly, as $A$ approaches the threshold, and so meets the third required condition of phase transitions in Def.~\ref{PhaseDef}. 
\end{enumerate}
	I have therefore shown for each requirement of phase transitions (in Def.~\ref{PhaseDef}) that if $\mathcal{H}$ meets it then $\mathcal{L}$ also meets it by virtue of the preserving-P-isomorphism, $\xi: \Sigma^* \longrightarrow \Pi^*$, between them. So, if $\mathcal{H} \subseteq \Pi^*$ has a phase transition, so does $\mathcal{L} \subseteq \Sigma^*$.
\end{proof}

