    \centering

    \begin{tikzcd}[scale cd=1.9, row sep=huge,column sep=huge]
\text{POW} \big( \Pi^* \big) \arrow[dd, "\xi^{-1}"] \arrow[rrd, "\mathcal{A}_{\mathcal{H}}"]           &  &                     \\
                                                                                                       &  & {\big [ 0, 1 \big]} \\
\text{POW} \big( \Sigma^* \big) \arrow[uu, "\xi", bend left] \arrow[rru, "\mathcal{A}_{\mathcal{L}}"'] &  &                    
