    \label{fig:Lemma5Diagram}
\end{figure}

\section{The Incompatibility of Padding and Sparsity}
\label{app:PaddingSparsity}
The purpose of this appendix is to examine the relationship between sparsity and paddability, showing that they are incompatible and hence arguing -- informally -- that being paddable and not-anywhere-exponentially-unbalanced are commonly found together.

Before beginning this appendix, I first must define a particular subset of $\Sigma^*$, in Def.~\ref{def:SigmaN}.
\begin{definition}
    \label{def:SigmaN}
    $\forall n \in \mathbb{N}_0$, define $\Sigma^n \subseteq \Sigma^*$ by: $\Sigma^n
        =
        \big \{ x \in \Sigma^* \text{ } \vert \text{ } \vert x \vert = n \big \}$.
    Similarly, I define, $\Sigma^{\leq n} \subseteq \Sigma^*$ by:
    \begin{align}
        \Sigma^{\leq n}
        &=
        \bigcup_{j = 0}^n \bigg( \Sigma^j \bigg). 
    \end{align}

\end{definition}
Then I define the density of a language (in Def.~\ref{def:density}), which is the basis for sparsity (defined in Def.~\ref{def:sparseLanguages}).
\begin{definition}
    \label{def:density}
    For any alphabet, $\Sigma$, and any language, $\mathcal{L} \subseteq \Sigma^*$, the density of $\mathcal{L}$ in $ \Sigma^n$, $\textit{Dens}_{\mathcal{L}}: \mathbb{N}_0 \longrightarrow \mathbb{N}_0$, is defined by: $\forall n \in \mathbb{N}_0$,
    \begin{align}
        \textit{Dens}_{\mathcal{L}} \big( n \big) = \big \vert \mathcal{L} \cap \Sigma^{\leq n} \big \vert.
    \end{align}
\end{definition}
\begin{definition}
    \label{def:sparseLanguages}
    A language, $\mathcal{L} \subseteq \Sigma^*$, is sparse if and only if there exists a polynomial, $\textit{Poly}_{s}: \mathbb{N} \longrightarrow \mathbb{N}$, such that: $\forall n \in \mathbb{N}$,
    \begin{align}
        \textit{Dens}_{\mathcal{L}} \big( n \big) 
        \leq
        \textit{Poly}_{s}(n).
    \end{align}
\end{definition}
With the foundational concepts defined, I move to the crux of Appendix~\ref{app:PaddingSparsity}: a prohibition on languages being both sparse and paddable.
\begin{lemma}
    \label{lem:padSparseisNO}
    No paddable language (over an alphabet of size at least two) is sparse.
\end{lemma}
\begin{proof}(Based on Ref.~\cite{sparseAndPaddaple})\\
    Assume, for the sake of contradiction, $\mathcal{L} \subseteq \Sigma^*$ is a language (where $\vert \Sigma \vert \geq 2$) that is sparse (with the polynomial $\textit{Poly}_{s}: \mathbb{N}_0 \longrightarrow \mathbb{R}$ bounding the density of $\mathcal{L}$) and paddable (with padding function, $\textit{Pad}_{\mathcal{L}}: \Sigma^* \times \Sigma^* \longrightarrow \Sigma^*$).

    As, by definition, $\textit{Pad}_{\mathcal{L}}: \Sigma^* \times \Sigma^* \longrightarrow \Sigma^*$ runs in polynomial (in the size of the combined inputs) time, there exists a polynomial, $\textit{Poly}_{p}: \mathbb{N} \longrightarrow \mathbb{N}$, such that: $\forall x, y \in \Sigma^*$,
    \begin{align}
        \big \vert \textit{Pad}_{\mathcal{L}} (x,y) \big \vert \leq \textit{Poly}_{p} \big( \vert x \vert + \vert y \vert \big).
    \end{align}
    Then, for any fixed $x \in \mathcal{L}$, as $\textit{Pad}_{\mathcal{L}}$ by definition preserves membership of $\mathcal{L}$, $\mathcal{L}$ being sparse implies -- using Def.~\ref{def:sparseLanguages} -- that there exists a polynomial, $\textit{Poly}_{s}: \mathbb{N}_0 \rightarrow \mathbb{N}_0$, such that: $\forall n \in \mathbb{N}$,
    \begin{align}
        \label{eqn:sparsityBounds}
        \big \vert \big \{ \textit{Pad}_{\mathcal{L}} (x,y) \in \mathcal{L} \text{ } \vert \text{ } y \in \Sigma^{\leq n} \big \} \big \vert 
        \leq
        \sum_{j = 0}^{n} \bigg( \textit{Poly}_{s} \big( \textit{Poly}_{p} \big( \vert x \vert + j \big) \big) \bigg).
    \end{align}
     However, as $\textit{Pad}_{\mathcal{L}}: \Sigma^* \longrightarrow \Sigma^*$ is bijective (in its second input, as shown in Lemma~\ref{def:paddingBijective} in Appendix~\ref{App:paddIso}) and
     \begin{align}
         \big \vert \Sigma^{\leq n} \big \vert = \sum_{j = 0}^n \bigg( \big \vert \Sigma \big \vert^j \bigg) = \dfrac{ \vert \Sigma \vert^{n + 1} - 1 }{ \vert \Sigma \vert - 1 },
    \end{align}
    it follows that: $\forall n \in \mathbb{N}$,
     \begin{align}
        \label{Eqn:sizeOfSet}
         \big \vert \big \{ \textit{Pad}_{\mathcal{L}} (x,y) \in \Sigma^* \text{ } \vert \text{ } y \in \Sigma^{\leq n} \big \} \big \vert
         &=
         \dfrac{\vert \Sigma \vert^{n + 1} - 1}{\vert \Sigma \vert - 1}.
     \end{align}
     For convenience, I then define another polynomial, $\textit{Poly}_{sp}: \mathbb{N} \longrightarrow \mathbb{N}$, by: $\forall n \in \mathbb{N}$,
    \begin{align}
        \label{eqn:newPoly}
        \textit{Poly}_{sp}(n)
        &=
        \sum_{j = 0}^{n} \bigg( \textit{Poly}_{s} \big( \textit{Poly}_{p} \big( \vert x \vert + j \big) \big) \bigg).
    \end{align}
     Therefore, combining Eqn.~\ref{eqn:sparsityBounds}, Eqn.~\ref{Eqn:sizeOfSet}, and  Eqn.~\ref{eqn:newPoly} gives: $\forall n \in \mathbb{N}$,
     \begin{align}
         \label{eqn:contraDictStatement}
         \dfrac{\vert \Sigma \vert^{n + 1} - 1}{\vert \Sigma \vert - 1}
         \leq
         \textit{Poly}_{sp}(n).
     \end{align}
     As I assumed $\vert \Sigma \vert \geq 2$, there will always exist a sufficiently large $n \in \mathbb{N}$ to render Eqn.~\ref{eqn:contraDictStatement} false. Hence, the assertion in Eqn.~\ref{eqn:contraDictStatement} is a contradiction and $\mathcal{L} \subseteq \Sigma^*$ cannot exist as described. I.e. no language can be both paddable and sparse.
\end{proof}

\section{P-isomorphism Auxiliary Lemma}
\label{sec:PIsoDetailsAppendix}
The below Lemma~\ref{Lem:inverseIsPreserve} is used in the proof of Lemma~\ref{lem:PisoImpliesPhase}, to show that the third condition of phase transitions are met.
\begin{lemma}
    \label{Lem:inverseIsPreserve}
    For any preserving-P-isomorphism, $\xi: \Sigma^* \longrightarrow \Pi^*$, its inverse, $\xi^{-1}: \Pi^* \longrightarrow \Sigma^*$, is also a preserving-P-isomorphism.
\end{lemma}
\begin{proof}
    A preserving-P-isomorpism, as defined in Def.~\ref{def:preservingPIso}, is also a P-isomorphism.

    By definition (in Def.~\ref{def:PIsomorph}), if $\xi: \Sigma^* \longrightarrow \Pi^*$ is an P-isomorphism, so is its inverse, $\xi^{-1}: \Pi^* \longrightarrow \Sigma^*$. Then, using that for any $x \in \Sigma^*$ there exists a $y \in \Pi^*$ such that $y = \xi (x)$ (as $\xi$ is a bijection), alongside Eqn.~\ref{eqn:PreservingAspect} (in Def.~\ref{def:preservingPIso}): $\forall y \in \Pi^*$,
    \begin{align}
        \label{eqn:inversePreservingAspect}
        \xi^{-1}(y) \in \mathcal{L} \iff  x \in \mathcal{L} \iff \xi(x) \in \mathcal{H} \iff y \in \mathcal{H}.
    \end{align}
    So, as Eqn.~\ref{eqn:inversePreservingAspect} is the equivalent of Eqn.~\ref{eqn:PreservingAspect} but for $\xi^{-1}$, I conclude that $\xi^{-1}: \Pi^* \longrightarrow \Sigma^*$ is a preserving-P-isomorphism.
\end{proof}
\section{Padding Function Isomorphism Auxiliary Lemma}
\label{App:paddIso}
The aim of this appendix is to provide the statement and proof of the below Lemma~\ref{def:paddingBijective}, which is used in the proof of Lemma~\ref{lem:PisoImpliesPhase}, in Appendix~\ref{app:LemsForMainLemma} which in turn contributes to the proof of Theorem~\ref{lem:MainLemma}. 
\begin{lemma}
    \label{def:paddingBijective}
    For any alphabet, $\Sigma$, and paddable language, $\mathcal{L} \subset \Sigma^*$ the padding function of $\mathcal{L}$, $\textit{Pad}_{\mathcal{L}}: \Sigma^* \times \Sigma^* \longrightarrow \Sigma^*$, is bijective in its second argument. I.e. $\forall x \in \Sigma^*$, the function, $\textit{Pa}_{x}: \Sigma^* \longrightarrow \Sigma^*$, defined by: $\forall y \in \Sigma^*$,
    \begin{align}
        \textit{Pa}_{x}(y)
        &=
        \textit{Pad}_{\mathcal{L}} (x, y),
    \end{align}
    where $x \in \Sigma^*$ is fixed, is bijective.
\end{lemma}
\begin{proof}
    It is easy to see that, $\forall y \in \Sigma^*$, $\textit{Pa}_{x}(y)$ only returns a single value. It then only remains to show that $y$ can be uniquely recovered from $\textit{Pa}_{x}(y)$, which would then imply each input to $\textit{Pa}_{x}(y)$ is the only input that gives the output it gives and hence $\textit{Pa}_{x}(y)$ is a bijection.

    To show that $y$ can be uniquely recovered, I propose the following mapping as a left inverse of $\textit{Pa}_{x}(y)$: $\forall z \in \Sigma^*$,
    \begin{align}
        \textit{Pa}^{-1}_{x}(z)
        &=
        \textit{Dec}_{\mathcal{L}}(z),
    \end{align}
    where $\textit{Dec}_{\mathcal{L}}: \Sigma^* \longrightarrow \Sigma^*$ is the decoding function of $\mathcal{L}$, which must exist as it is paddable. This can be seen to correctly and uniquely recover $y$ as:
    \begin{align}
        \textit{Pa}^{-1}_{x}(\textit{Pa}_{x}(y))
        &=
        \textit{Dec}_{\mathcal{L}}( \textit{Pad}_{\mathcal{L}} (x, y))
        =
        y.
    \end{align}
\end{proof}

