\section{Fixed-point iterations for the pseudospectral abscissa 
				of a nonlinear eigenvalue problem}\label{sec:fp_mat_val}
The first-order approximation formula in (\ref{eq:main_char_psa_nle}) in Theorem \ref{thm:fo_estimate} 
for $\alpha_{\epsilon}(T)$ gives a good estimate if $\epsilon$ is small. For larger
values of $\epsilon$, this estimate is crude. Here, we describe two fixed-point iterations
for an accurate estimation of $\alpha_{\epsilon}(T)$ even when $\epsilon$ is large
based on the perturbation theory presented in the previous section. The idea
behind the fixed-iterations makes use of also the following backward error result, whose proof
is given in Appendix \ref{sec:proof_bw_nle_error}. Similar backward errors are considered
in the literature extensively; see, e.g., \cite[Section 4.2]{TisM01}, \cite[Section 2.2]{TisH01},
\cite[Theorem 1]{MicGWN06}.
\begin{theorem}\label{thm:berror_NEP}
Let $z \in {\mathbb C}$. We have
\vskip 1ex
\begin{equation*}
	\min \bigg\{ \epsilon \;\:  \bigg| \;\: \exists \Delta T \in {\mathcal P}_{\epsilon}	
				\;\, \mathrm{s.t.} \;\,	\mathrm{det}\big\{ (T + \Delta T)(z) \big\} = 0	\bigg\}	
		\;	=	\;
		\frac{\sigma_{\min}(T(z))}{\sqrt{ w_1^2 | t_1(z) |^2 + \dots + w_\kappa^2 | t_\kappa(z) |^2}}
				=:		\varphi(z)	
	\;	,
\end{equation*}
\vskip 1ex
\noindent
where ${\mathcal P}_{\epsilon}$ is the set defined in (\ref{eq:defn_NEP_pspec}).
Moreover, letting $u, v$ be consistent unit left, unit right singular vectors corresponding to 
$\sigma_{\min}(T(z))$, we have 
\vskip 1.5ex
\begin{tabular}{l}
		\hskip -4ex		\phantom{i}\textbf{(i)}
		$\mathrm{det}\left\{ (T + \underline{\Delta T})(z) \right\} = 0$, and	\\[.45em]
		\hskip -4ex		\textbf{(ii)}
		the inclusion $\underline{\Delta T} \in {\mathcal P}_{\varphi(z)}$
\end{tabular} 
\vskip 1.5ex
\noindent
for  $\underline{\Delta T}(\lambda) 
			= t_1(\lambda) w_1 \underline{\Delta T}_{\, 1} + \dots 
						+ t_\kappa(\lambda) w_\kappa \underline{\Delta T}_{\, \kappa}$
with
\begin{equation}\label{eq:defn_Tj}
	\underline{\Delta T}_{\, j}
		\;	:=	\;
	\frac{-\varphi(z) w_j \overline{t_j(z)} u v^\ast}{\sqrt{ w_1^2 | t_1(z) |^2 + \dots + w_\kappa^2 | t_\kappa(z) |^2}}	\:	,
	\quad	j = 1, \dots , \kappa.
\end{equation}
Indeed, $u^\ast \{ (T + \underline{\Delta T})(z) \} = 0$ and $\{ (T + \underline{\Delta T})(z) \} v = 0$, i.e.,
$u, v$ are left, right eigenvectors of $(T + \underline{\Delta T})(\lambda)$ corresponding to its eigenvalue $z$.
\end{theorem}

\noindent
The quantity $\varphi(z)$ in Theorem \ref{thm:berror_NEP} is the backward error of $z \in {\mathbb C}$ to be an 
eigenvalue of $T(\lambda)$. In other words, it is the norm of the smallest perturbation of $T(\lambda)$ so 
that $z$ is an eigenvalue of the perturbed matrix-valued function. 
As an immediate corollary of Theorem \ref{thm:berror_NEP},
the $\epsilon$-pseudospectrum of $T$ can be characterized as follows.
\begin{theorem}\label{thm:pspec_char}
The following assertion holds:
\begin{equation}\label{eq:pspec_char}
	\Lambda_{\epsilon}(T)
		\;	=	\;
	\left\{ z \in {\mathbb C}	\;\;\;		\bigg|	\;\;\;
		\frac{\sigma_{\min}(T(z))}
			{\sqrt{ w_1^2 | t_1(z) |^2 + \dots + w_\kappa^2 | t_\kappa(z) |^2}}  \; \leq \; \epsilon	
		\right\}	\:	.
\end{equation}
\end{theorem}


%%% \medskip


Now we describe a 
fixed-point iteration to estimate $\alpha_{\epsilon}(T)$. We start by perturbing $T$ in the direction
$\Delta T^{(0)}(\lambda) = t_1(\lambda) w_1 \Delta T^{(0)}_1 + 
			\dots + t_{\kappa}(\lambda) w_{\kappa} \Delta T^{(0)}_\kappa$
such that
\[
	\Delta T^{(0)}_{j}
			\;	:=	\;
	\frac{w_j \, \overline{t_j(\lambda_R)} y_0 x^\ast_0}
				{\sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(\lambda_R) |^2}}	\;	,	
	\;\;\;	j	=	1,	\dots , \kappa \: ,
\]
where $\lambda_R$ is an eigenvalue of $T$, and $y_0, x_0$ are unit left, right eigenvectors of 
$T(\lambda)$ corresponding  to $\lambda_R$ normalized so that
\[
	\|x_0 \|_2 = \| y_0 \|_2 = 1
	\quad	\text{and}		\quad
	y^\ast_0 T'(\lambda_R) x_0 \text{ is real and negative}	. 
\]
This initial perturbation is similar to the one used in the fixed-point iteration in \cite{MicG12} for a slightly 
different definition of the $\epsilon$-pseudospectrum.
Letting $\Delta^{(0)} = (\Delta T^{(0)}_1 , \dots , \Delta T^{(0)}_\kappa)$, as asserted by Theorem \ref{thm:max_LDelta}, 
this choice is justified by the property
\[
		\Delta^{(0)}	\, \in \,	
			\argmax_{\Delta \in {\mathcal S}}	\:	\text{Re} \left\{ \mu'(0; \Delta, \lambda_R, T) \right\}
			\:	.
\]


%%% \vskip 3ex


% \noindent
Let $z_1$ be the rightmost eigenvalue of $(T + \epsilon \Delta T^{(0)})(\lambda)$. Clearly,
$z_1 \in \Lambda_{\epsilon}(T)$. In addition to $\epsilon \Delta T_0 \in {\mathcal P}_{\epsilon}$, 
there may be several perturbations $\Delta T \in {\mathcal P}_{\epsilon}$ such that $z_1$ 
is an eigenvalue of 
$(T + \Delta T)(\lambda)$. In particular, by Theorem \ref{thm:berror_NEP}, a minimal perturbation 
$\underline{\Delta T}^{(0)}(\lambda) = t_1(\lambda) w_1 \underline{\Delta T}^{(0)}_{\, 1} 
						+ \dots + t_{\kappa}(\lambda) w_{\kappa} \underline{\Delta T}^{(0)}_{\, \kappa}$ 
such that $z_1$ is an eigenvalue of $(T + \underline{\Delta T}^{(0)})(\lambda)$ is given by
the choice
\[
	\underline{\Delta T}^{(0)}_{\, j}
			\;	:=	\;
	\frac{-\varphi(z_1) w_j \overline{t_j(z_1)} u_1 v_1^\ast}
					{\sqrt{ \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell(z_1) |^2}}	
	\;	,	
	\;\;\;	j	=	1,	\dots , \kappa \:		,
\] 
where 
$\varphi(z_1) = \sigma_{\min}(T(z_1))/\sqrt{ \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell(z_1) |^2} \,$ and 
$u_1, v_1$ are consistent unit left, right singular vectors corresponding to 
$\sigma_{\min}(T(z_1))$. 
Recall also that, by Theorem \ref{thm:berror_NEP}, $u_1, v_1$ are left, right
eigenvectors of $(T + \underline{\Delta T}^{(0)})(\lambda)$ corresponding to its eigenvalue $z_1$. 
Consider instead the left, right eigenvectors $\widetilde{u}_1, \widetilde{v}_1$ of $(T + \underline{\Delta T}^{(0)})(\lambda)$ 
corresponding to the eigenvalue $z_1$ normalized such that
\begin{equation}\label{eq:nle_norm_cond}
	\| \widetilde{u}_1 \|_2 = \| \widetilde{v}_1 \|_2 = 1
	\quad\;\;	\text{and}		\quad\;\;
	\widetilde{u}_1^\ast \, \{ (T + \underline{\Delta T}^{(0)})'(z_1) \}  \widetilde{v}_1 
										\text{ is real and negative}	.
\end{equation}
Note that, to fulfill the normalization conditions in (\ref{eq:nle_norm_cond}), 
we can choose $\widetilde{u}_1 = -e^{{\rm i} \theta} u_1$, 
$\widetilde{v}_1 = v_1$, where $\theta$ is such that   
\begin{equation*}
\begin{split}
	\rho e^{{\rm i} \theta}
		\;	&	=	\;
		u_1^\ast \left\{ (T + \underline{\Delta T}^{(0)})'(z_1) \right\} v_1
			\;	=	\;
		u_1^\ast \left\{ T'(z_1) + (\underline{\Delta T}^{(0)})'(z_1) \right\} v_1		\\
		\;	&	=	\;
		u_1^\ast T'(z_1) v_1
				+
		\left\{ \frac{-\sigma_{\min}(T(z_1))}{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z_1) |^2} \right\}
		\sum_{\ell=1}^\kappa
			w_\ell^2 t_\ell'(z_1) \overline{t_\ell(z_1)}	\:	.
\end{split}
\end{equation*}
Now $\Delta^{(1)} = (\Delta T^{(1)}_1 , \dots , \Delta T^{(1)}_{\kappa})$ with
\[
	\Delta T^{(1)}_{j}
			\;	:=	\;
	\frac{w_j \, \overline{t_j(z_1)} \, \widetilde{u}_1 \widetilde{v}_1^\ast}
					{\sqrt{\sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell(z_1) |^2}}	\;	,	
	\;\;\;	j	=	1,	\dots , \kappa \: 
\] 
corresponding to the perturbation 
$\Delta T^{(1)}(\lambda) = t_1(\lambda) w_1 \Delta T^{(1)}_1 + \dots + t_{\kappa}(\lambda) w_{\kappa} \Delta T^{(1)}_\kappa$
satisfies
\[
		\Delta^{(1)}	\, \in \,	
		\argmax_{\Delta \in {\mathcal S}}	\:	
				\text{Re} \left\{ \mu'(0; \Delta, z_1, T + \underline{\Delta T}^{(0)}) \right\}	\:	.
\]
We define $z_2$ as the rightmost eigenvalue of 
$(T + \epsilon \Delta T^{(1)})(\lambda)$, and
repeat the procedure. The resulting fixed-point iteration is outlined in 
Algorithm \ref{alg:fixed_point} below.


\begin{algorithm}
\begin{algorithmic}[1]
	\REQUIRE{A matrix-valued function $T$ as in (\ref{eq:mat_fun}), a real number $\epsilon > 0$,
				tolerance for termination $\mathsf{tol} > 0$.}
	\ENSURE{Estimates $f$ for $\alpha_{\epsilon}(T)$ and $z$
						for globally rightmost point in $\Lambda_{\epsilon}(T)$.}	
	\vskip 1.2ex
	\STATE{$z_0 \; \gets$ an eigenvalue of $T$.}\label{line_alg1:zm1}

	\vskip 1.2ex		

	\STATE{$x, y \; \gets$ unit right, left eigenvectors corr. to
				rightmost eigenvalue of $T$.}	\label{line_alg1:z0}

	\vskip 1.5ex

	\STATE{$y \; \gets \; - \{ (y^\ast T'(z_0) x) / | y^\ast T'(z_0) x| \} y $.}

	\vskip 1.7ex

	\STATE{$\Delta T^{(0)}_{j}
			\gets
			\left\{	 w_j \, \overline{t_j(z_0)} y x^\ast  \right\}	/
					\sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z_0) |^2 }  \,$ 
				for $j = 1, \dots , \kappa$.} 

	\vskip 1.3ex

\STATE{$\Delta T^{(0)}(\lambda) \; \gets \;  
			t_1(\lambda) w_1 \Delta T^{(0)}_1 + \dots + t_{\kappa}(\lambda) w_{\kappa} \Delta T^{(0)}_\kappa$.}
			\label{line_alg1:T0}

	\vskip 1.5ex

	\FOR{$k=1,2,\dots$}

	\vskip 1.2ex

	\STATE{$z_k \; \gets \;$ rightmost eigenvalue of $(T + \epsilon \Delta T^{(k-1)})(\lambda)$.}

	\vskip 1.2ex

	\STATE{\textbf{If} $| z_{k} - z_{k-1} | < \mathsf{tol} \;$ \textbf{return} 
						$z \gets z_k$, $f \gets \text{Re}(z_k)$.}\label{line:fp1_nle_ter}

	\vskip 1.2ex

	\STATE{$v_k, u_k \; \gets \;$ unit consistent right, left
							singular vectors corr. to $\sigma_{\min}(T(z_k))$.} 

	\vskip 1.9ex

	\STATE{$\delta_k \; \gets \; 	\left\{-\sigma_{\min}(T(z_k))
								/ \sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z_k) |^2 \right\}
		\sum_{j=1}^\kappa
			w_j^2 t_j'(z_k) \overline{t_j(z_k)}$}\label{line:fp1_nle_delta}				

	\vskip 1.8ex

	\STATE{$u_k \; \gets \; - \left\{ [u_k^\ast T'(z_k) v_k + \delta_k ]  
							/ | u_k^\ast T'(z_k) v_k + \delta_k | \right\} u_k $.}

	\vskip 1.3ex

	\STATE{$\Delta T^{(k)}_{j}
			\gets
			\left\{ w_j \, \overline{t_j(z_k)} u_k v_k^\ast \right\} /
				\sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z_k) |^2}  \,$ 
					for $j = 1, \dots , \kappa$.}  

	\vskip 1ex

	\STATE{$\Delta T^{(k)}(\lambda) \; \gets \;  
		t_1(\lambda) w_1 \Delta T^{(k)}_1 + \dots + t_{\kappa}(\lambda) w_{\kappa} \Delta T^{(k)}_\kappa$.}

	\vskip 1.5ex

	\ENDFOR
\end{algorithmic}
\caption{Fixed-point iteration for the pseudospectral abscissa of a matrix-valued function}
\label{alg:fixed_point}
\end{algorithm}

\subsection{Fixed-points of Algorithm \ref{alg:fixed_point}}\label{sec:fp_analysis}
We next analyze the fixed-points of Algorithm \ref{alg:fixed_point}.
% Just like any fixed-point iteration defined in terms a continuous fixed-point
% function, Algorithm \ref{alg:fixed_point} without termination
%(i.e., without line \ref{line:fp1_nle_ter}), if it converges, it can only converge to a fixed point. 
To be precise, the fixed-point function associated with Algorithm \ref{alg:fixed_point}
is the continuous map $\zeta : {\mathcal D} \rightarrow {\mathcal D}$ such that $\widetilde{z} = \zeta(z)$
for any $z \in {\mathcal D}$ is defined as follows:
\begin{enumerate}
	\item Let $v, u$ be unit consistent right, left
							singular vectors corresponding to $\sigma_{\min}(T(z))$.

	\item Set $\widetilde{u} := - \left\{ [u^\ast T'(z) v + \delta ]  
							/ | u^\ast T'(z) v + \delta | \right\} u $, with
		\[
			\delta	:=  	-\frac{\sigma_{\min}(T(z))}{\sum_{\ell =1}^\kappa w_\ell^2 | t_\ell(z) |^2} 
				\sum_{\ell=1}^\kappa
						w_\ell^2 t_\ell'(z) \overline{t_\ell(z)}	.
		\]
	\item Set  
			$\Delta T(\lambda)  :=
				t_1(\lambda) w_1 \Delta T_1 + \dots + t_{\kappa}(\lambda) w_{\kappa} \Delta T_\kappa$,
		where
		\[
			\Delta T_{j}
				:=
			\frac{w_j \, \overline{t_j(z)} \widetilde{u} v^\ast} 
				{\sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2}}	 \: ,	\quad 
					j = 1, \dots , \kappa  \: .
		\]
	\item $\widetilde{z}$ is the rightmost eigenvalue of $(T + \epsilon \Delta T)(\lambda)$
	(if the rightmost eigenvalue is not unique, take one of the rightmost eigenvalues, e.g., the one with the
	largest imaginary part).
\end{enumerate}
The iterates of Algorithm \ref{alg:fixed_point} can be expressed as $z^{(k+1)} = \zeta(z^{(k)})$ for $k \geq 0$,
so, by the continuity of $\zeta$, the sequence $\{ z^{(k)} \}$ generated by Algorithm \ref{alg:fixed_point} 
without termination (i.e., without line \ref{line:fp1_nle_ter}) can only converge to the fixed-points of $\zeta$.

% Our main result here makes use of the following lemma regarding 
% differentiable locally rightmost points of $\Lambda_{\epsilon}(T)$,

The subsequent arguments make use of the matrix-valued function
\begin{equation}\label{eq:defn_M}
	M(\lambda)
		\;	:=	\;
		\frac{T(\lambda)}{\sqrt{ w_1^2 | t_1(\lambda) |^2 + \dots + w_\kappa^2 | t_\kappa(\lambda) |^2}}	\:	,
\end{equation}
which is not analytic because of the term in the denominator.
However, the matrix-valued function ${\mathcal M}(s_1, s_2) := M(s_1 + {\rm i} s_2)$ over the domain 
$\{ (x, y) \; | \; x, y \in {\mathbb R}\, \text{ s.t. }\, x + {\rm i} y \in {\mathcal D} \} \subseteq {\mathbb R}^2$ is real-analytic, 
i.e., the real and imaginary parts of ${\mathcal M}(s_1, s_2)$
are real-analytic. We denote with ${\mathcal M}_{s_1}$, ${\mathcal M}_{s_2}$ the partial
derivatives of ${\mathcal M}$ with respect to $s_1$, $s_2$, respectively.
These (possibly complex) partial derivatives at a point $(x, y) \in {\mathbb R}^2$
such that $z = x + {\rm i} y \in {\mathcal D}$ are explicitly given by
 \small
\begin{equation}\label{eq:der_M}
\begin{split}
	&	
\hskip -.5ex
		{\mathcal M}_{s_1}(x,y)
			=
	\frac{1}{ \sqrt{ \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (z) |^2}}
	\left\{  T'(z)  	-		
			\frac{ T(z) }{  \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (z) |^2  }
			\sum_{\ell=1}^\kappa
						w_\ell^2 \text{Re}\left[ t'_\ell(z) \overline{t_\ell(z)} \right]		\right\} \: ,	\\[.4em]	
	&	
\hskip -.5ex
		{\mathcal M}_{s_2}(x,y)
			=
	\frac{1}{ \sqrt{\sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (z) |^2}}
	\left\{  {\mathrm i} T'(z)  	+		
			\frac{ T(z) }{  \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (z) |^2  }
			\sum_{\ell=1}^\kappa
						w_\ell^2 \text{Im}\left[ t'_\ell(z) \overline{t_\ell(z)} \right]		\right\}	\:	.
\end{split}
\end{equation}
\normalsize
In our analysis, we make use of the map
\begin{equation}\label{eq:nond_opt_map}
	{\mathcal S} : {\mathcal D} \rightarrow {\mathbb C}	\,	,	\;\;\;
	{\mathcal S}(z)  \; = \;  \text{Re}\left\{ u^\ast {\mathcal M}_{s_1}(x,y) v \right\} 	\: -  \:	 
						{\rm i} \cdot \text{Re}\left\{ u^\ast {\mathcal M}_{s_2}(x,y) v \right\}	\:	,
\end{equation} 
where $x, y \in {\mathbb R}$ are such that $z = x + {\rm i} y \in {\mathcal D}$, and
$u$, $v$ denote a pair of consistent unit left, 
		unit right singular vectors of $T(z)$ corresponding to $\sigma_{\min}(T(z))$.
We define nondegenerate points of $\Lambda_{\epsilon}(T)$ 
in terms of ${\mathcal S}$ (and so in terms of ${\mathcal M}, M$) as follows.
\begin{definition}\label{defn:nondegenerate}
	A point $z \in \Lambda_{\epsilon}(T)$ is called nondegenerate if
	\begin{enumerate}
		\item the smallest singular value of $T(z)$ is simple, and
		\item ${\mathcal S}(z) \neq 0$.
	\end{enumerate}
\end{definition}

\noindent
Our main result in this subsection makes use of the following lemma regarding 
nondegenerate points on the boundary of $\Lambda_{\epsilon}(T)$.
A proof of the lemma is included in Appendix \ref{sec:opt_rightmost_pt}.
\begin{lemma}\label{Lem:char_rightp}
Let $z \in {\mathcal D}$ be a nondegenerate point. If the point $z$ is a locally rightmost 
point in $\Lambda_{\epsilon}(T)$, then ${\mathcal S}(z)$ is real and positive.
\end{lemma}

\noindent
A nondegenerate point $z \in {\mathcal D}$ on the boundary of $\Lambda_{\epsilon}(T)$
such that ${\mathcal S}(z)$ is real and positive corresponds to a point
on the right boundary of $\Lambda_{\epsilon}(T)$ (i.e., in the sense that
$z + h$ does not belong to $\Lambda_{\epsilon}(T)$ for all positive $h \in {\mathbb R}$
sufficiently small) with a vertical tangent line. We give a special name to such points.
\begin{definition}\label{defn:rbvt_point} % [A Right Boundary Point with a Vertical Tangent] $\;$ \\
We call $z \in {\mathbb C}$ an rbvt (right boundary with a vertical tangent) point if 
\begin{enumerate}
	\item $z$ is nondegenerate,
	\item $z$ is on the boundary of $\Lambda_{\epsilon}(T)$, and
	\item ${\mathcal S}(z)$ is real and positive. 
\end{enumerate} 
\end{definition}

\noindent
Lemma \ref{Lem:char_rightp} shows that a nondegenerate locally rightmost
point in $\Lambda_{\epsilon}(T)$ is indeed an rbvt point. Conversely, an rbvt point is 
likely to be, but not necessarily, a locally rightmost point in $\Lambda_{\epsilon}(T)$.
In particular, if, at an rbvt point $z$, the second derivative of $\sigma_{\min}(M(\lambda))$
with respect to the imaginary part of $\lambda$ is negative, then every ball 
${\mathcal B}_r(z) = \{ \widetilde{z} \in {\mathbb C} \; | \; |\widetilde{z} - z | < r \}$ with 
positive radius $r$ contains a point inside $\Lambda_{\epsilon}(T)$ with real part
greater than $\text{Re}(z)$, so $z$ is not locally rightmost in $\Lambda_{\epsilon}(T)$.

%%% \medskip

% \noindent
We now present the main result that characterizes the fixed points of the
map $\zeta$ associated with Algorithm \ref{alg:fixed_point}. This result
implies that Algorithm \ref{alg:fixed_point}, if it converges to a nondegenerate point of $\Lambda_{\epsilon}(T)$,
the converged point must be an rbvt point, likely to be a locally rightmost point in $\Lambda_{\epsilon}(T)$.

\begin{theorem}\label{thm:fp_main_result}
Let $z \in \Lambda_{\epsilon}(T)$ be nondegenerate, and $\zeta$ be the fixed-point
map associated with Algorithm \ref{alg:fixed_point} defined as above.
\begin{enumerate}
	\item If $z$ is not an rbvt point,
	then $z$ is not a fixed-point of $\zeta$.
	\item If $z$ is the unique globally rightmost point in $\Lambda_{\epsilon}(T)$,
	then $z$ is a fixed-point of $\zeta$.
\end{enumerate}
\end{theorem}
\begin{proof}
Let us first prove 2. Since $z$ is a globally rightmost point and nondegenerate, we must have
${\mathcal S}(z)$ real and positive by Lemma \ref{Lem:char_rightp}. Now,
recalling the definition of ${\mathcal S}(z)$ in (\ref{eq:nond_opt_map}) with $u$, $v$
denoting a pair of consistent unit left, unit right singular vectors corresponding to $\sigma_{\min}(T(z))$, 
and observing $u^\ast T(z) v = \sigma_{\min}(T(z)) \| u \|_2^2 = \sigma_{\min}(T(z))$ is real,
it follows from the expressions in (\ref{eq:der_M}) for the partial derivatives of ${\mathcal M}$ that
\begin{equation*}
	{\mathcal S}(z)
		\;		=	\;
	\frac{1}{ \sqrt{\sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (z) |^2}}
	\left\{ u^\ast T'(z) v 	-		
			\frac{u^\ast T(z) v}{  \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (z) |^2  }
			\sum_{\ell=1}^\kappa
						w_\ell^2 t_\ell'(z) \overline{t_\ell(z)}		\right\}	\:	.
\end{equation*}
As a result, since ${\mathcal S}(z)$ is real and positive,
\begin{equation}\label{eq:same_as_Mp}
	 u^\ast T'(z) v 	-		
			\frac{u^\ast T(z) v}{  \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (z) |^2  }
			\sum_{\ell=1}^\kappa
						w_\ell^2 t_\ell'(z) \overline{t_\ell(z)}		
\end{equation}
is also real and positive, implying $\widetilde{u} = -u$  in the definition of $\zeta$. It follows that
\[
	\Delta T_{j}
				:=
			- \frac{w_j \, \overline{t_j(z)} u v^\ast} 
				{\sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2}}	 \: ,	\quad 
					j = 1, \dots , \kappa  \: .
\]
By definition, $\widetilde{z} = \zeta(z)$ is a rightmost eigenvalue of $(T + \epsilon \Delta T)(\lambda)$,
where $\Delta T(\lambda) = \sum_{\ell = 1}^\kappa w_\ell t_\ell(\lambda) \Delta T_\ell$. Additionally,
\begin{equation}\label{eq:fp1_der_int}	
\begin{split}
	\left\{ (T + \epsilon \Delta T)(z) \right\} v	\;	&	=	\;
				T(z) v	+	\epsilon \Delta T(z) v		\\[.4em]
				&	=	\;
				\sigma_{\min} (T(z)) u		+	\epsilon \sum_{j = 1}^\kappa  w_j t_j(z) \Delta T_j v	\\[.2em]
				&	=	\;
				\epsilon \left\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \right\} u
							-
		\epsilon \sum_{j=1}^\kappa \frac{w_j^2 | t_j(z) |^2}{\sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2}}u	\\[.6em]
				&	=	\;
				\epsilon \left\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \right\} u
							-
				\epsilon \left\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \right\} u		\;	=	\;	0	\:	,	
\end{split}
\end{equation}
where for the third equality, we note 
$\sigma_{\min} (T(z)) = \epsilon \bigg\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \bigg\}$,
as $z$ is the globally rightmost point in $\Lambda_{\epsilon}(T)$, using also the characterization
of $\Lambda_{\epsilon}(T)$ in (\ref{eq:pspec_char}).
This shows that $z$ is also an eigenvalue of $(T + \epsilon \Delta T)(\lambda)$. Indeed, the point $z$ must be
the unique rightmost eigenvalue of $(T + \epsilon \Delta T)(\lambda)$, as otherwise 
(i.e., if, in addition to $z$, the matrix-valued function
$(T + \epsilon \Delta T)(\lambda)$ has other rightmost eigenvalues) $z$ cannot be the
unique rightmost point in $\Lambda_{\epsilon}(T)$. Consequently, $\widetilde{z} = z$, proving that $z$
is a fixed-point of $\zeta$.

As for 1. let us first assume $z$ is on the boundary of $\Lambda_{\epsilon}(T)$. Since $z$ is not an
rbvt point, then 
the scalar ${\mathcal S}(z)$ is either not real, or real but negative. Following the steps in the previous paragraph,
${\mathcal S}(z)$ and the matrix in (\ref{eq:same_as_Mp}) have the same complex sign, say $e^{{\rm i} \theta}$
such that $\theta \neq 0$. Consequently, $\widetilde{u} = - e^{{\rm i} \theta} u$. Now let 
$\{v, v_2, \dots , v_n \}$ and $\{u, u_2, \dots , u_n \}$ be the orthonormal sets consisting of all right 
singular vectors and left singular vectors, respectively, of $T(z)$ satisfying $T(z) v_j = \sigma_j(z) u_j$
for $j = 2, \dots , n$, where $\sigma_j(z)$ is a singular value of $T(z)$ other than $\sigma_{\min}(T(z))$.
Take any vector $\widehat{v} \in {\mathbb C}^n$ and expand it as 
$\widehat{v} = c v + c_2 v_2 + \dots + c_n v_n$ for some scalars $c, c_2, \dots , c_n \in {\mathbb C}$.
Now suppose
\begin{equation}\label{eq:fp1_der_int2}
\begin{split}
	0	\;	&	=	\;
	\left\{ (T + \epsilon \Delta T)(z) \right\} \widehat{v}	\;		=	\;
				T(z) \widehat{v}	+	\epsilon \Delta T(z) \widehat{v}		\\[.2em]
				&	\quad\quad\quad	=	\;
		\epsilon \left\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \right\} c u + \sum_{j=2}^n c_j \sigma_j(z) u_j 
			-
		\epsilon \left\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \right\} c e^{{\rm i} \theta} u	\:	,
\end{split}
\end{equation}
where the steps when passing to the second line are similar to those in (\ref{eq:fp1_der_int}).
By the linear independence of $\{u, u_2, \dots , u_n \}$, we have $c_2 = \dots = c_n = 0$,
and $c(1 - e^{{\rm i} \theta}) = 0$, which implies $c = 0$ as $\theta \neq 0$. Consequently, $\widehat{v} = 0$.
This shows that $(T + \epsilon \Delta T)(z)$ is invertible, so
$z$ is not an eigenvalue of $(T + \epsilon \Delta T)(\lambda)$, whereas $\widetilde{z}$
is an eigenvalue of $(T + \epsilon \Delta T)(\lambda)$ by definition. Consequently, $\widetilde{z} \neq z$,
and $z$ is not a fixed-point of $\zeta$. 

Finally, if $z$ is in the interior of $\Lambda_{\epsilon}(T)$, then by the nondegeneracy of $z$, 
we have ${\mathcal S}(z) \neq 0$.
If $\sigma_{\min}(M(z)) = \epsilon$, then $z$ is a local maximizer of $\sigma_{\min}(M(z))$,
but this contradicts with ${\mathcal S}(z) \neq 0$ (i.e., the first-order necessary conditions
for $z$ to be a local maximizer of $\sigma_{\min}(M(z))$ imply ${\mathcal S}(z) = 0$). 
Thus, $\sigma_{\min}(M(z)) < \epsilon$, equivalently 
\[
	\sigma_{\min}(T(z)) = \rho \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2}
	< \epsilon \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2}.
\]
for some nonnegative real number $\rho < \epsilon$. Proceeding as in the previous paragraph, letting
$\{v, v_2, \dots , v_n \}$ and $\{u, u_2, \dots , u_n \}$ be the orthonormal sets consisting of all right 
singular vectors and left singular vectors, take any $\widehat{v} \in {\mathbb C}$, and
expand it as $\widehat{v} = c v + c_2 v_2 + \dots + c_n v_n$ for some scalars $c, c_2, \dots , c_n \in {\mathbb C}$.
Calculations analogous to (\ref{eq:fp1_der_int2}) yield
\begin{equation}\label{eq:fp1_der_int3}
\begin{split}
	0	\;	&	=	\;
	\left\{ (T + \epsilon \Delta T)(z) \right\} \widehat{v}	\;		=	\;
				T(z) \widehat{v}	+	\epsilon \Delta T(z) \widehat{v}		\\[.2em]
				&	\quad\quad\quad	=	\;
		\rho \left\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \right\} c u + \sum_{j=2}^n c_j \sigma_j(z) u_j 
			-
		\epsilon \left\{ \sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \right\} c e^{{\rm i} \theta} u	\:	,
\end{split}
\end{equation}
where now $\theta$ can be zero or nonzero. Linear independence of $\{u, u_2, \dots , u_n \}$ leads again to
$c_2 = \dots = c_n = 0$, as well as
and $c(\rho - \epsilon e^{{\rm i} \theta}) = 0$ implying $c = 0$ as $\rho < \epsilon$. It follows that
$\widehat{v} = 0$, and $(T + \epsilon \Delta T)(z)$ is invertible. Once again $z$ is not eigenvalue
and $\widetilde{z}$ is an eigenvalue of  $(T + \epsilon \Delta T)(\lambda)$, so $\widetilde{z} \neq z$.
\end{proof}



\subsection{An alternative fixed-point iteration}
Here we present an alternative fixed-point iteration to compute $\alpha_{\epsilon}(T)$
based on constant matrix perturbations of $T(\lambda)$. For a moment, let us assume
$T(\lambda)$ in (\ref{eq:mat_fun}) is such that $t_{\kappa}(\lambda) = 1$, and the weights
are such that $w_1  = \dots = w_{\kappa - 1} = 0$ and $w_\kappa = 1$. 
In this special case, the definition of the $\epsilon$-pseudospectrum given by (\ref{eq:defn_NEP_pspec})
and its characterization in (\ref{eq:pspec_char}) take the form
\begin{equation}\label{eq:psa_cons_per}
	\Lambda_{\epsilon}(T)
		\;	=	\;
	\bigcup_{\Delta \in {\mathbb C}^{n\times n}, \| \Delta \|_2 \leq \epsilon}
	\Lambda(T + \Delta)
		\;	=	\;
	\left\{
		z \in {\mathbb C}	\;	|	\;
			\sigma_{\min}(T(z)) \leq \epsilon
	\right\},
\end{equation}
where $\: (T + \Delta)(\lambda)	=	\left\{ \sum_{\ell = 1}^{\kappa - 1} t_{\ell}(\lambda) T_\ell \right\}
										+ \left\{ T_{\kappa} + \Delta \right\}$.
Hence,  in this case, $\Lambda_{\epsilon}(T)$ is defined in terms of only constant
perturbations of $T_{\kappa}$, whereas the perturbations of other coefficients
are not allowed. In this setting, Algorithm \ref{alg:fixed_point} takes
the special form in Algorithm \ref{alg:fixed_point1m}. We note that $\delta_k$ in 
line \ref{line:fp1_nle_delta} of Algorithm \ref{alg:fixed_point} becomes zero in 
the special setting, as $w_1 = \dots = w_{\kappa - 1} = 0$ and $t'_{\kappa}(\lambda) = 0$. 
The specialized algorithm is based on constant perturbations of $T_{\kappa}$;
in particular,
\begin{equation*}
	(T + \epsilon \Delta^{(k-1)})(\lambda) = 
				\left\{ \sum_{\ell = 1}^{\kappa - 1} t_{\ell}(\lambda) T_\ell \right\}
										+ \left\{ T_{\kappa} + \epsilon \Delta^{(k-1)} \right\}
\end{equation*}
in line \ref{line_alg2:cons_per} of Algorithm \ref{alg:fixed_point1m}.

\begin{algorithm}
\begin{algorithmic}[1]
	\REQUIRE{A matrix-valued function $T$ as in (\ref{eq:mat_fun}) with $t_{\kappa}(\lambda) = 1$
	and $w_1 = \dots = w_{\kappa - 1} = 0$, $w_{\kappa} = 1$, a real number $\epsilon > 0$,
				tolerance for termination $\mathsf{tol} > 0$.}
	\ENSURE{Estimates $f$ for $\alpha_{\epsilon}(T)$ and $z$
						for globally rightmost point in $\Lambda_{\epsilon}(T)$.}	
	\vskip 1.2ex
	\STATE{$z_0 \; \gets$ an eigenvalue of $T$.}\label{line_alg1:zm1}

	\vskip 1.2ex		

	\STATE{$x, y \; \gets$ unit right, left eigenvectors corr. to
				rightmost eigenvalue of $T$.}	\label{line_alg1:z0}

	\vskip 1.5ex

	\STATE{$y \; \gets \; - \{ (y^\ast T'(z_0) x) / | y^\ast T'(z_0) x| \} y $.}

	\vskip 1.7ex

	\STATE{$\Delta^{(0)}
			\gets
			 y x^\ast$.} 
			\label{line_alg2:Del0}

	\vskip 1.5ex

	\FOR{$k=1,2,\dots$}

	\vskip 1.2ex

	\STATE{$z_k \; \gets \;$ rightmost eigenvalue of $(T + \epsilon \Delta^{(k-1)})(\lambda)$.}\label{line_alg2:cons_per}

	\vskip 1.5ex

	\STATE{\textbf{If} $| z_{k} - z_{k-1} | < \mathsf{tol} \;$ \textbf{return} 
						$z \gets z_k$, $f \gets \text{Re}(z_k)$.}\label{line:fp2_nle_ter}

	\vskip 1.2ex

	\STATE{$v_k, u_k \; \gets \;$ unit consistent right, left
							singular vectors corr. to $\sigma_{\min}(T(z_k))$.} 


	\vskip 1.8ex

	\STATE{$u_k \; \gets \; - \left\{ [u_k^\ast T'(z_k) v_k  ]  
							/ | u_k^\ast T'(z_k) v_k  | \right\} u_k $.}

	\vskip 2.3ex

	\STATE{$\Delta^{(k)}
			\gets
			u_k v_k^\ast$}   


	\vskip 1.5ex

	\ENDFOR
\end{algorithmic}
\caption{Fixed-point iteration for the
pseudospectral abscissa of a matrix-valued function subject to constant perturbations}
\label{alg:fixed_point1m}
\end{algorithm} 		


Going back to our general setting in (\ref{eq:defn_NEP_pspec}), we can view $\Lambda_{\epsilon}(T)$ as the
$\epsilon$-pseudospectrum of
\begin{equation}\label{eq:defn_M2}
\begin{split}
	&
	M(\lambda)		=	\widetilde{t}_1(\lambda)	\widetilde{T}_1
						+	\dots		+	\widetilde{t}_\kappa(\lambda) \widetilde{T}_{\kappa}
						+	\widetilde{t}_{\kappa + 1}(\lambda) \widetilde{T}_{\kappa + 1}	
				\\[.7em]
	&
	\text{with}	\quad
	\widetilde{T}_j	\;	=	\;	T_j	\:	,	\quad
	\widetilde{t}_j(\lambda)	=
			\frac{t_j(\lambda)}
				{\sqrt{ w_1^2 | t_1(\lambda) |^2 + \dots + w_\kappa^2 | t_\kappa(\lambda) |^2}} \: ,
				\;\;\;\;		j = 1, \dots , \kappa	\:	, 	\\[.2em]
	&
	\phantom{\text{with}}	\quad
	\widetilde{T}_{\kappa + 1}	= 0	\:	,	\quad
	\widetilde{t}_{\kappa + 1}(\lambda) =1	\:	,		\\[.2em]
\end{split}
\end{equation}
and the weights $\widetilde{w}_{1} = \dots = \widetilde{w}_{\kappa} = 0$ 
and $\widetilde{w}_{\kappa+1} = 1$. Indeed, it follows from (\ref{eq:psa_cons_per}) that
\begin{equation*}
\begin{split}
	\Lambda_{\epsilon}(M)	
		\;	&	=	\;
	\left\{
		z \in {\mathbb C}	\;	|	\;
			\sigma_{\min}(M(z)) \leq \epsilon
	\right\}		\\[.3em]
		\;	&	=	\;
	\left\{ z \in {\mathbb C}	\;\;\;		\bigg|	\;\;\;
		\frac{\sigma_{\min}(T(z))}
			{\sqrt{ w_1^2 | t_1(z) |^2 + \dots + w_\kappa^2 | t_\kappa(z) |^2}}  \; \leq \; \epsilon	
		\right\}
			\;	=	\;
	\Lambda_{\epsilon}(T)	\:	,
\end{split}
\end{equation*}
where the second equality is due to
\[
	M(\lambda)
		\;	=	\;
	\frac{T(\lambda)}
				{\sqrt{ w_1^2 | t_1(\lambda) |^2 + \dots + w_\kappa^2 | t_\kappa(\lambda) |^2}}  \: ,
\]
as is apparent from (\ref{eq:defn_M2}). Hence, $\Lambda_{\epsilon}(T)$
is the same as the $\epsilon$-pseudospectrum of $M$ but when it is subject
to constant perturbations only. Now $\alpha_{\epsilon}(M) = \alpha_{\epsilon}(T)$,
and it seems we can apply Algorithm \ref{alg:fixed_point1m} to $M(z)$ to compute 
$\alpha_{\epsilon}(T)$. However, there is a technical difficulty, namely $M(\lambda)$ is not
analytic, and the ideas behind Algorithm \ref{alg:fixed_point1m} relies on the analyticity of $T(\lambda)$.
It is for instance not possible to replace $T(\lambda)$ in lines \ref{line_alg2m:normal1} 
and \ref{line_alg2m:normal2} of Algorithm \ref{alg:fixed_point1m} with $M(\lambda)$, as
$M(\lambda)$ is not differentiable (i.e., not holomorphic).


%%% \medskip


We instead proceed on the real-analytic counterpart ${\mathcal M}(s_1 , s_2) := M(s_1 + {\rm i} s_2)$,
when analyticity plays a role.
Let us in particular describe how we form $\Delta^{(k)}$ at iteration $k$
given the perturbation $\Delta^{(k-1)}$ from the previous iteration.
The point $z_k$ is now the rightmost eigenvalue of $(M + \epsilon \Delta^{(k-1)})(\lambda)$,
and $v_k$, $u_k$ are unit consistent right, left singular vectors corresponding to $\sigma_{\min}(M(z_k)) =: \gamma$. 
The point $z_k$ is also an eigenvalue of $(M + \gamma \underline{\Delta}^{(k-1)})(\lambda)$
for $\underline{\Delta}^{(k-1)} = u_k v_k^\ast$, and the vectors $v_k$, $u_k$ are corresponding right, left eigenvectors.
We assume $z_k$ is a simple eigenvalue of $(M + \gamma \underline{\Delta}^{(k-1)})(\lambda)$.
The perturbation $\Delta_k$ is the matrix $\Delta \in {\mathbb C}^{n\times n}$, $\| \Delta \|_2 \leq 1$ 
maximizing the rate of change in the real part of the eigenvalue $z_k$ of
$(M + \gamma \underline{\Delta}^{(k-1)} + \eta \Delta)(\lambda)$ at $\eta = 0$.

Hence, consider any 
$\Delta \in {\mathbb C}^{n\times n}$ such that $\| \Delta \|_2 \leq 1$. By the analytic implicit function
theorem, there exist an open interval $U$ containing 0 and unique real-analytic functions 
$\mu_1(\eta ; \Delta),  \mu_2(\eta ; \Delta)$ satisfying 
$\mu_1(0; \Delta) = \text{Re}(z_k), \; \mu_2(0 ; \Delta) = \text{Im}(z_k)$ and
\[
	\text{det}
	\{  ( {\mathcal M} + \gamma \underline{\Delta}^{(k-1)} + \eta \Delta)
		( \mu_1(\eta ; \Delta), \mu_2(\eta ; \Delta) ) \}	=	0	\quad	\forall \eta \in U.
\]
There is also an analytic matrix-valued function $v(\eta; \Delta)$
such that $v(0; \Delta) = v_k$ and
\[
	\left\{ \left( {\mathcal M} + \gamma \underline{\Delta}^{(k-1)} + \eta \Delta \right)
		\left( \mu_1(\eta ; \Delta), \mu_2(\eta ; \Delta) \right) \right\} \, v(\eta ; \Delta) 	\;	=	\;	0
		\:	
\]
for all $\eta \in U$ \cite[pages 32-33]{Rel69}. The equation above is analogous to (\ref{eq:eig_eqn}).
Differentiating the last equation at $\eta = 0$, then multiplying with $u_k^\ast$ from left, we obtain
\begin{equation}\label{eq:alg_der_nlp_inter}
	\mu_1'  \left\{ u^\ast_k {\mathcal M}_{s_1}(x_k, y_k) v_k \right\}		+	
			\mu_2'  \left\{ u^\ast_k {\mathcal M}_{s_2}(x_k , y_k) v_k \right\}
				+	u^\ast_k \Delta v_k 		\;	=	\;	0,
\end{equation}
where $x_k$, $y_k$ are real, imaginary parts of $z_k$, and
explicit expressions for ${\mathcal M}_{s_1}$, ${\mathcal M}_{s_2}$
are as in (\ref{eq:der_M}). Let
\begin{equation}\label{eq:defn_Md}
		M^{D}(\lambda)
			\;	:=	\;
		\frac{1}{ \sqrt{\sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (\lambda) |^2}}
		\left\{T'(\lambda)  	-		
			\frac{ T(\lambda) }{  \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell (\lambda) |^2  }
			\sum_{\ell=1}^\kappa
						w_\ell^2 t_\ell'(\lambda) \overline{t_\ell(\lambda)}		\right\}	\:	.
\end{equation}
It turns out that setting $\widetilde{u}_k = -u_k e^{{\rm i} \theta}$, $\widetilde{v}_k = v_k$
for $\theta$ such that $u_k^\ast M^{D}(z_k) v_k = \rho e^{{\rm i} \theta}$, we have
\[
	\text{Re} \{ \widetilde{u}^\ast_k {\mathcal M}_{s_1}(x_k, y_k) \widetilde{v}_k \}	
			=
		\widetilde{u}_k^\ast M^{D}(z_k) \widetilde{v}_k		\quad	\text{and}		\quad
	\text{Re} \{ \widetilde{u}^\ast_k {\mathcal M}_{s_2}(x_k, y_k) \widetilde{v}_k \}	
			=		0	\:	.
\]
Thus, multiplying (\ref{eq:alg_der_nlp_inter}) with $-e^{-{\rm i} \theta}$ and taking the real parts
yield
\begin{equation*}
\begin{split}
	0	\;	&	=	\;
		\mu_1' \text{Re} \left\{ \widetilde{u}^\ast_k {\mathcal M}_{s_1}(x_k, y_k) \widetilde{v}_k \right\}		+	
			\mu_2' \text{Re} \left\{ \widetilde{u}^\ast_k {\mathcal M}_{s_2}(x_k , y_k) \widetilde{v}_k \right\}
				+	\text{Re} \left\{ \widetilde{u}^\ast_k \Delta \widetilde{v}_k \right\}		\\[.5em]
		&	=	\;
				\mu'_1 \left\{ \widetilde{u}_k^\ast M^{D}(z_k) \widetilde{v}_k \right\}	+	
						\text{Re} \left\{ \widetilde{u}^\ast_k \Delta \widetilde{v}_k \right\}	\:	.	
\end{split}
\end{equation*}
Finally, as $\widetilde{u}_k^\ast M^{D}(z_k) \widetilde{v}_k = -\rho$ is real and negative,
we deduce
\[
	\mu'_1
		\;	=	\;
	- \frac{\text{Re} \left\{ \widetilde{u}^\ast_k \Delta \widetilde{v}_k \right\}}
				{\widetilde{u}_k^\ast M^{D}(z_k) \widetilde{v}_k}
		\;	=	\;
	\frac{\text{Re} \left\{ \widetilde{u}^\ast_k \Delta \widetilde{v}_k \right\}}
				{| \widetilde{u}_k^\ast M^{D}(z_k) \widetilde{v}_k |}	\:	.
\]
It follows that the matrix $\Delta$ with $\| \Delta \|_2 \leq 1$
maximizing $\mu'_1$ is given by $\Delta_k = \widetilde{u}_k \widetilde{v}_k^\ast$.
Initially, we start from an eigenvalue $z_0$ of $M(\lambda)$ (equivalently $T(\lambda)$), 
so $v_0 = x$, $u_0 =  y$ are right, left
eigenvectors of $M(\lambda)$ (equivalently $T(\lambda)$) corresponding to $z_0$.
The derivation above applies but with the simplification
$u_0^\ast M^D(z_0) v_0 = y^\ast T'(z_0) x$.
These arguments lead us to Algorithm \ref{alg:fixed_point2m} given below.


We emphasize that Algorithm \ref{alg:fixed_point2m} is inspired from the ideas behind
Algorithm \ref{alg:fixed_point1m} but designed for $M(z)$, and stated mostly in terms of $T(z)$
for which the $\epsilon$-pseudospectral abscissa is aimed at. To this end,
in line \ref{line_alg2m:cons_per} of Algorithm \ref{alg:fixed_point2m}, the point
$z_k$ is indeed a rightmost eigenvalue of $(M + \epsilon \Delta^{(k-1)})(\lambda)$,
which is equal to  
$\{ T(\lambda) / \sqrt{ \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell(\lambda) |^2} \}
			+ \epsilon \Delta^{(k-1)}$.
Additionally, in line \ref{line:fp2_nle_sval}, the vectors $v_k, u_k$ are consistent unit right,
unit left singular vectors of $M(z_k)$ corresponding to its smallest singular value,
as it turns out that the singular vectors of $T(z_k)$ and $M(z_k)$ are the same. 

\begin{algorithm}
\begin{algorithmic}[1]
	\REQUIRE{A matrix-valued function $T$ as in (\ref{eq:mat_fun}), a real number $\epsilon > 0$,
				tolerance for termination $\mathsf{tol} > 0$.}
	\ENSURE{Estimates $f$ for $\alpha_{\epsilon}(T)$ and $z$
						for globally rightmost point in $\Lambda_{\epsilon}(T)$.}	
	\vskip 1.2ex
	\STATE{$z_0 \; \gets$ an eigenvalue of $T$.}\label{line_alg2m:zm1}

	\vskip 1.2ex		

	\STATE{$x, y \; \gets$ unit right, left eigenvectors corr. to
				rightmost eigenvalue of $T$.}	\label{line_alg2m:z0}

	\vskip 1.5ex

	\STATE{$y \; \gets \; - \{ (y^\ast T'(z_0) x) / | y^\ast T'(z_0) x| \} y $.}\label{line_alg2m:normal1}

	\vskip 1.7ex

	\STATE{$\Delta^{(0)}
			\gets
			 y x^\ast$.} 
			\label{line_alg2m:Del0}

	\vskip 1.5ex

	\FOR{$k=1,2,\dots$}

	\vskip 1.2ex

	\STATE{$z_k \; \gets \;$ rightmost eigenvalue of 
	$\left\{ T(\lambda) / \sqrt{ \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell(\lambda) |^2} \right\}
		+  \epsilon \Delta^{(k-1)}$.}\label{line_alg2m:cons_per}

	\vskip 1.5ex

	\STATE{\textbf{If} $| z_{k} - z_{k-1} | < \mathsf{tol} \;$ \textbf{return} 
						$z \gets z_k$, $f \gets \text{Re}(z_k)$.}\label{line:fp2_nle_ter}

	\vskip 1.6ex

	\STATE{$v_k, u_k \; \gets \;$ unit consistent right, left
					singular vectors corr. to $\sigma_{\min}(T(z_k))$.}\label{line:fp2_nle_sval}


	\vskip 1.8ex

	\STATE{$u_k \; \gets \; - \left\{ [u_k^\ast M^D(z_k) v_k  ]  
							/ | u_k^\ast M^D(z_k) v_k  | \right\} u_k $.}\label{line_alg2m:normal2}

	\vskip 2.3ex

	\STATE{$\Delta^{(k)}
			\gets
			u_k v_k^\ast$}   


	\vskip 1.5ex

	\ENDFOR
\end{algorithmic}
\caption{Fixed-point iteration for the
pseudospectral abscissa of a matrix-valued function based on constant perturbations}
\label{alg:fixed_point2m}
\end{algorithm} 	

As Algorithm \ref{alg:fixed_point1m} is a special case of Algorithm \ref{alg:fixed_point},
the analysis concerning the fixed-points of Algorithm \ref{alg:fixed_point} in Section
\ref{sec:fp_analysis} applies to Algorithm \ref{alg:fixed_point1m} as well. In particular
Theorem \ref{thm:fp_main_result} still holds, but now in the definition of a nondegenerate
point the  condition ${\mathcal S}(z) \neq 0$ (see Definition \ref{defn:nondegenerate}, part 2.)  
simplifies as $u^\ast T'(z) v \neq 0$, in the definition of an rbvt point the condition
${\mathcal S}(z)$ is real and positive (see Definition \ref{defn:rbvt_point}, part 3.)  
simplifies as $u^\ast T'(z) v$ is real and positive (as the denominator in (\ref{eq:defn_M})
is constant one in this special case), and the fixed-point function $\zeta$, letting
$\widetilde{z} = \zeta(z)$,  simplifies as follows:
\begin{enumerate}
	\item Let $v, u$ be unit consistent right, left
							singular vectors corresponding to $\sigma_{\min}(T(z))$.

	\item Set $\widetilde{u} := - \left\{ u^\ast T'(z) v / | u^\ast T'(z) v  | \right\} u $.
	\item Set  
			$\Delta   :=	\widetilde{u} v^\ast$.
	\item $\widetilde{z}$ is the rightmost eigenvalue of $T(\lambda) + \epsilon \Delta$.
\end{enumerate}
In item 4., if there are multiple rightmost eigenvalues, one of them can be taken
as explained before. 
% As before, if Algorithm \ref{alg:fixed_point1m} in the special setting
% converges to a nondegenerate point, this must be a locally rightmost point.

As for Algorithm \ref{alg:fixed_point2m},
the associated fixed-point function that we now denote by $\zeta_3$ (to distinguish
the fixed-point functions associated with Algorithm \ref{alg:fixed_point},
Algorithm \ref{alg:fixed_point1m} explicitly), letting $\widetilde{z} = \zeta_3(z)$,
is defined as follows:
\begin{enumerate}
	\item Let $v, u$ be unit consistent right, left
							singular vectors corresponding to $\sigma_{\min}(T(z))$.

	\item Set $\widetilde{u} := - \left\{ u^\ast M^D(z) v / | u^\ast M^D(z) v  | \right\} u $.
	\item Set  
			$\Delta   :=	\widetilde{u} v^\ast$.
	\item $\widetilde{z}$ is the rightmost eigenvalue of 
	$\{ T(\lambda) / \sqrt{ \sum_{\ell = 1}^\kappa w_\ell^2 | t_\ell(\lambda) |^2} \} + \epsilon \Delta$.
\end{enumerate}
We state the fixed-point results for $\zeta_3$ formally below. Its proof is similar
to that for Theorem \ref{thm:fp_main_result} concerning the fixed-point function $\zeta$
associated with Algorithm \ref{alg:fixed_point}. The only difference in the proof is that
equations (\ref{eq:fp1_der_int}),
(\ref{eq:fp1_der_int2}), (\ref{eq:fp1_der_int3}) now involve $\{ (M + \epsilon \Delta)(z) \} v  = 0$
or $\{ (M + \epsilon \Delta)(z) \} \widehat{v}  = 0$
with $\Delta = \widetilde{u} v^\ast \:$ (rather than $\{ (T + \epsilon \Delta T)(z) \} v = 0$
or $\{ (T + \epsilon \Delta T)(z) \} \widehat{v} = 0$ with 
$\Delta T(\lambda) = 
			\sum_{j = 1}^\kappa w_j t_j(\lambda) \Delta T_j \,$,
	$\,\Delta T_j = \big\{ w_j \, \overline{t_j(z)} \widetilde{u} v^\ast \big/ 
						\sqrt{\sum_{\ell=1}^\kappa w_\ell^2 | t_\ell(z) |^2} \big\}$
						for $j = 1, \dots, \kappa$). % \\[-2.4em]
\begin{theorem}\label{thm:fp_main_result2}
Let $z \in \Lambda_{\epsilon}(T)$ be nondegenerate (in the sense of 
Definition \ref{defn:nondegenerate}, with ${\mathcal S}(z)$ in part 2 as in (\ref{eq:nond_opt_map})), and
$\zeta_3$ be the fixed-point  map associated with Algorithm \ref{alg:fixed_point2m} defined as above.
\begin{enumerate}
	\item If $z$ is not an rbvt point (in the sense of Definition \ref{defn:rbvt_point}) 
	in $\Lambda_{\epsilon}(T)$, then $z$ is not a fixed-point of $\zeta_3$.
	\item If $z$ is the unique globally rightmost point in $\Lambda_{\epsilon}(T)$,
	then $z$ is a fixed-point of $\zeta_3$.
\end{enumerate}
\end{theorem}
% \vskip -2.4ex
\noindent
According to Theorem \ref{thm:fp_main_result2}, just like Algorithm \ref{alg:fixed_point},
assuming Algorithm \ref{alg:fixed_point2m} converges to a nondegenerate point,
this point must be an rbvt point.


\begin{example}\label{ex:damp1_2}
\rm{Let us again consider the damping problem in Example \ref{ex:damp1},
in particular the matrix polynomial $P(\lambda) = \lambda^2 M + \lambda C_{\mathrm{int}} + K$
in that example, i.e., without external damping, that is with the damping parameter $\nu = 0$.
We apply Algorithms \ref{alg:fixed_point} and \ref{alg:fixed_point2m}
to compute the rightmost point in $\Lambda_{\epsilon}(P)$ for $\epsilon = 0.1$ and $\epsilon = 0.2$
with the weights $w_1 = w_2 = w_3 = 1$ and the tolerance ${\sf tol} = 10^{-10}$.

Both Algorithm \ref{alg:fixed_point} and Algorithm \ref{alg:fixed_point2m} are initialized
with $z_0$ equal to the eigenvalue with the largest imaginary part.
The two algorithms as well as the criss-cross algorithm \cite[Section 2.1]{MehM24} return 
the same globally rightmost points up to prescribed tolerances, specifically 
$0.3049280 + 7.7520368{\rm i}$ and $0.6614719 + 7.8301883{\rm i}$ for 
$\epsilon = 0.1$ and $\epsilon = 0.2$, respectively. These computed globally
rightmost points together with the boundary of $\Lambda_{\epsilon}(P)$ for 
$\epsilon = 0.1, 0.2$ are illustrated in Figure \ref{fig:poly_psa}.
Additionally, Table \ref{tab:nle_iterates} list the number of iterations needed
by Algorithm \ref{alg:fixed_point} and Algorithm \ref{alg:fixed_point2m} to reach the 
prescribed tolerance ${\sf tol} = 10^{-10}$, as well as the first few iterates of the 
algorithms until the first five decimal digits of the iterates become correct. In these
two applications of the algorithms with $\epsilon = 0.1$, $\epsilon = 0.2$,
Algorithm \ref{alg:fixed_point} requires fewer iterations for the prescribed accuracy
and seems to be converging faster. This is a general pattern we observe for
decent values of $\epsilon$. However, for larger values of $\epsilon$ close to $\sigma_{\min}(M)$
(note that $\Lambda_{\epsilon}(P)$ is unbounded for $\epsilon > \sigma_{\min}(M)$),
it seems that Algorithm \ref{alg:fixed_point2m} converges more reliably;
we refer to Section \ref{sec:num_examp} for numerical examples with larger $\epsilon$ values
for which Algorithm \ref{alg:fixed_point2m} converges accurately, while Algorithm \ref{alg:fixed_point} 
does not converge.}
\end{example}								



