\subsection{Fixed-point iteration for the $\epsilon$-pseudospectral abscissa of a matrix}
The first-order, second-order approximation of the previous two subsections yield estimates
of the $\epsilon$-pseudospectral abscissa of a matrix with errors 
${\mathcal O}(\epsilon^2)$, ${\mathcal O}(\epsilon^3)$, respectively.
For arbitrarily high accuracy, here, we briefly summarize the specialization of the fixed-point iterations 
in Section \ref{sec:fp_mat_val} to estimate the $\epsilon$-pseudospectral abscissa of a matrix-valued function
for a matrix $A \in {\mathbb C}^{n\times n}$. 
The approximation ideas of the previous two subsections can be employed to initialize
the fixed-point iteration below, but we postpone a proper discussion of this to Section \ref{sec:glob_opts}.
% \ref{sec:est_glob_opt_psa}.
% ; see in particular Remark \ref{rem:init_psa}.


%%% \bigskip


The matrix $A$ is initially perturbed by
$\Delta^{(0)} :=  y_0 x_0^\ast$, 
where $y_0, x_0$ are left, right
eigenvectors of $A$ corresponding to an eigenvalue $\lambda_R$ normalized so that
\[
	\|x_0 \|_2 = \| y_0 \|_2 = 1
	\quad	\text{and}		\quad
	y^\ast_0 x_0 \text{ is real and positive}	\:	,
\]
since
$\:
		\Delta^{(0)}	\, \in \,	
			\argmax
			\left\{
					\text{Re} \left\{ \mu'(0; \Delta, \lambda_R, A) \right\}
						\;	|	\;
					\Delta \in {\mathbb C}^{n\times n} \text{ s.t. } \| \Delta \|_2 \leq 1	
			\right\}
$.


%%% \bigskip


Letting $z_1$ be the rightmost eigenvalue of $A + \epsilon \Delta^{(0)}$,
by the Eckart-Young-Mirsky theorem \cite[Theorem 2.5.3]{GolVL96},
the minimal perturbation $\underline{\Delta}^{(0)} \in {\mathbb C}^{n\times n}$ 
(with the smallest 2-norm possible)
such that $z_1$ is an eigenvalue of $A + \underline{\Delta}^{(0)}$ is given by
\[
	\underline{\Delta}^{(0)}	\;	:=	\;	-\gamma u_1 v_1^\ast
\] 
where $\gamma := \sigma_{\min}(z_1 I - A)$ and $u_1, v_1$ are corresponding
consistent unit left, right singular vectors, which also turn out to be left, right
eigenvectors of $A + \underline{\Delta}^{(0)}$ corresponding to its eigenvalue $z_1$. 
Normalizing the eigenvectors $u_1$, $v_1$ into  
$\widetilde{u}_1, \widetilde{v}_1$ so that
\[
	\| \widetilde{u}_1 \|_2 = \| \widetilde{v}_1 \|_2 = 1
	\quad	\text{and}		\quad
	\widetilde{u}_1^\ast \widetilde{v}_1 \text{ is real and positive}	,
\]
the matrix $\Delta^{(1)} := \widetilde{u}_1 \widetilde{v}_1^\ast$ satisfies
\[
		\Delta^{(1)}	 \in 
		\argmax
		\left\{	
				\text{Re} \left\{ \mu'(0; \Delta, z_1, A + \underline{\Delta}^{(0)}) \right\}		
					\:	|	\:
					\Delta \in {\mathbb C}^{n\times n} \text{ s.t. } \| \Delta \|_2 \leq 1	
		\right\}	\:	.
\]
Setting $z_2$ as the rightmost eigenvalue of $A + \epsilon \Delta^{(1)}$, we
repeat the procedure. The fixed-point iteration specialized
for the $\epsilon$-pseudospectral abscissa 
of a matrix is given in Algorithm \ref{alg:fixed_point_matrix} below.




\begin{algorithm}
\begin{algorithmic}[1]
	\REQUIRE{A matrix $A\in {\mathbb C}^{n\times n}$, a real number $\epsilon > 0$,
				tolerance for termination $\mathsf{tol} > 0$.}
	\ENSURE{Estimates $f$ for $\alpha_{\epsilon}(A)$ and $z$
						for globally rightmost point in $\Lambda_{\epsilon}(A)$.}	
	\vskip 1.2ex
	\STATE{$z_0 \; \gets$ an eigenvalue of $A$.}\label{line_alg4A:zm1}

	\vskip 1.2ex

	\STATE{$x, y \; \gets$ unit right, left eigenvectors corr. to
				rightmost eigenvalue of $A$.}
	\vskip 1.2ex
	\STATE{$y \; \gets \;\,  \{ (y^\ast x) / | y^\ast x| \} y $.}
	\vskip 1.2ex
	\STATE{$\Delta^{(0)} \; \gets \; y x^\ast$.}\label{line_alg4:D0}
	\vskip 1.2ex
	\FOR{$k=1,2,\dots$}
	\vskip 1.2ex
	\STATE{$z_k \; \gets \;$ rightmost eigenvalue of $A + \epsilon \Delta^{(k-1)}$.}
	\vskip 1.2ex
	\STATE{\textbf{If} $| z_{k} - z_{k-1} | < \mathsf{tol} \;$ \textbf{return} 
						$z \gets z_k$, $f \gets \text{Re}(z_k)$.}
	\vskip 1.2ex
	\STATE{$v_k, u_k \; \gets \;$ unit consistent right, left
							singular vectors corr. to $\sigma_{\min}(z_k I_n - A)$.} 
	\vskip 1.2ex
	\STATE{$u_k \; \gets \;\, \{ ( u_k^\ast v_k ) / | u_k^\ast v_k | \}  u_k $.}
	\vskip 1.2ex
	\STATE{$\Delta^{(k)} \gets u_k v_k^\ast$.}
	\vskip 1.5ex
	\ENDFOR
\end{algorithmic}
\caption{Fixed-point iteration for the pseudospectral abscissa of a matrix}
\label{alg:fixed_point_matrix}
\end{algorithm}


\subsubsection{Fixed-points of Algorithm \ref{alg:fixed_point_matrix}.}
Consider Algorithm \ref{alg:fixed_point} applied to $T(\lambda) = \lambda I - A$
(i.e., $t_1(\lambda) = \lambda$, $t_2(\lambda) = -1$ and $T_1 = I$, $T_2 = A$)
with the weights $w_1 = 0$, $w_2 = 1$. The fixed-point map $\zeta$ in 
Section \ref{sec:fp_analysis} in this special case, letting $\widetilde{z} = \zeta(z)$,
is defined as follows:
\begin{enumerate}
	\item Let $v, u$ be consistent unit right, left
							singular vectors corresponding to $\sigma_{\min}(zI - A)$.

	\item Set $\widetilde{u} := - \left\{ u^\ast  v  / | u^\ast v  | \right\} u $.
	\item Set  
			$\Delta  := -\widetilde{u} v^\ast$.
	\item $\widetilde{z}$ is the rightmost eigenvalue of 
	$T(\lambda) + \epsilon (- \Delta) = \lambda I - (A + \epsilon \Delta)$, that is the rightmost 
	eigenvalue of 
	$A - \epsilon \widetilde{u} v^\ast	= 	A  +   \epsilon \left\{ u^\ast  v  / | u^\ast v  | \right\} u v^\ast$.
\end{enumerate}
Now looking at one iteration of Algorithm \ref{alg:fixed_point_matrix},
for the associated fixed-point function $\zeta_4$,
the point $\widetilde{z} = \zeta_4(z)$ is the rightmost eigenvalue
of $A  +   \epsilon \left\{ u^\ast  v  / | u^\ast v  | \right\} u v^\ast$. Hence,
the algorithms have the same fixed-point functions. It can also be verified 
that $z_1$ for both algorithms are the same, provided that the algorithms 
are started with the same $z_0$. It follows that
Algorithm \ref{alg:fixed_point_matrix} and Algorithm \ref{alg:fixed_point}
applied to $T(\lambda) = \lambda I - A$ with $w_1 = 0$, $w_2 = 1$
generate the same sequence $\{ z_k \}$. The next result is now
an immediate corollary of Theorem \ref{thm:fp_main_result}, noting that
$\Lambda_{\epsilon}(A) = \Lambda_{\epsilon}(T)$ for 
$T(\lambda) = \lambda I - A$ with $w_1 = 0$, $w_2 = 1$, and the definition
of an rbvt point simplifies as follows.
\begin{definition}\label{defn:rbvt_point_matrix} % [A Right Boundary Point with a Vertical Tangent] $\;$ \\
\hskip -.45ex
We call $z \in {\mathbb C}$ an rbvt (right boundary with a vertical tangent) point in $\Lambda_{\epsilon}(A)$ if 
\begin{enumerate}
	\item the smallest singular value of $zI - A$ is simple,
	\item $z$ is on the boundary of $\Lambda_{\epsilon}(A)$, and
	\item $u^\ast v$ is real and positive, where $u$, $v$ denote a pair of consistent
	left, right singular vectors corresponding to $\sigma_{\min}(zI - A)$. 
\end{enumerate} 
\end{definition}
\begin{theorem}\label{thm:convergence_matrix_case}
Let $z \in \Lambda_{\epsilon}(A)$ be such that the smallest singular
value of $zI - A$ is simple, and, denoting with $u$, $v$ a pair of left,
right singular vectors corresponding to $\sigma_{\min}(zI - A)$, such that 
$u^\ast v \neq 0$.  Moreover, let $\zeta_4$ be the fixed-point
map associated with Algorithm \ref{alg:fixed_point_matrix}.
\begin{enumerate}
	\item If $z$ is not an rbvt point in $\Lambda_{\epsilon}(A)$,
	then $z$ is not a fixed-point of $\zeta_4$.
	\item If $z$ is the unique globally rightmost point in $\Lambda_{\epsilon}(A)$,
	then $z$ is a fixed-point of $\zeta_4$.
\end{enumerate}
\end{theorem}

\noindent
Analogous to the earlier conclusions made regarding the convergence 
of Algorithm \ref{alg:fixed_point}, we infer from Theorem \ref{thm:convergence_matrix_case} 
that if the sequence $\{ z_k \}$ by Algorithm \ref{alg:fixed_point_matrix} 
converges to a point $z_\ast$ such that 
\begin{enumerate}
	\item $\sigma_{\min}(z_\ast I - A)$ is simple, and 
	\item $u^\ast v \neq 0$ for the left, right singular vectors $u$, $v$ 
	corresponding to $\sigma_{\min}(z_\ast I - A)$, 
\end{enumerate}
the converged point $z_\ast$ is an rbvt point in $\Lambda_{\epsilon}(A)$,
probably a locally rightmost point in $\Lambda_{\epsilon}(A)$.



