\section{Proof of Theorem \ref{thm:berror_NEP}}\label{sec:proof_bw_nle_error}
\begin{proof}
Observe that
\begin{equation*}
\begin{split}
	\left\{ (T + \underline{\Delta T})(z)	\right\}	v
			\;	=	\;
	T(z) v	+	\Delta T(z) v			
			\; &	=	\;
	\sigma_{\min}(T(z)) u		+	\sum_{j=1}^\kappa t_j(z) w_j \underline{\Delta T}_j v		\\
			&	=	\;
	\sigma_{\min}(T(z)) u		+	
		\sum_{j=1}^\kappa t_j(z) w_j \left\{ \frac{ -\varphi(z) w_j \overline{t_j(z)} u }  
								{ \sqrt{\sum_{\ell = 1}^\kappa w^2_{\ell} | t_{\ell}(z) |^2} } \right\}		\\
			&	=	\;
	\sigma_{\min}(T(z)) u		-	\left\{ \sqrt{\sum_{\ell = 1}^\kappa w^2_{\ell} | t_{\ell}(z) |^2} \right\}   \varphi(z) u
		\;	=	\;	0	\:	,
\end{split}	
\end{equation*}
where the second equality is due to the fact $u$, $v$ are consistent unit left, unit right singular vectors
corresponding to $\sigma_{\min}(T(z))$, and we employ the definition of $\underline{\Delta T}_j$
in (\ref{eq:defn_Tj}) for the third equality. Consequently, $\mathrm{det}\left\{ (T + \underline{\Delta T})(z) \right\} = 0$. 
By analogous calculations $u^\ast \left\{ (T + \underline{\Delta T})(z)	\right\} = 0$ as well. 
Furthermore,
$
	\left\|
			\left[
			\begin{array}{ccc}
				\underline{\Delta T}_1	&	\dots		&	\underline{\Delta T}_{\kappa}
			\end{array}
			\right]
	\right\|_2	=	\varphi(z)
$
so that $\underline{\Delta T} \in {\mathcal P}_{\varphi(z)}$ 
from the definition of ${\mathcal P}_{\varphi(z)}$ in (\ref{eq:defn_NEP_pspec}).
Combining $\underline{\Delta T} \in {\mathcal P}_{\varphi(z)}$ with 
$\mathrm{det}\left\{ (T + \underline{\Delta T})(z) \right\} = 0$ yield
\begin{equation}\label{eq:berror_ub}
	\inf\{ \epsilon \; | \; \exists \Delta T \in {\mathcal P}_{\epsilon}	
			\text{ s.t. }	\mathrm{det}\left\{ (T + \Delta T)(z) \right\} = 0	\}
				\;	\leq		\;	\varphi(z)	\:	.
\end{equation}

Take any 
$\Delta T(\lambda) 
			= t_1(\lambda) w_1\Delta T_{\, 1} + \dots 
						+ t_\kappa(\lambda) w_\kappa \Delta T_{\, \kappa}$
such that $\mathrm{det}\left\{ (T + \Delta T)(z) \right\} = 0$.
By the Eckart-Young-Mirsky theorem \cite[Theorem 2.5.3]{GolVL96}, we have
\begin{equation*}
\begin{split}
		\sigma_{\min}(T(z))	
			\;	\leq		\;
		\| \Delta T(z) \|_2 	\;	&	=	\;
		\left\|
		\left[
			\begin{array}{ccc}
				\Delta T_1		&	\dots		&	\Delta T_\kappa
			\end{array}
		\right]
		\left[
			\begin{array}{c}
				w_1 \, t_1(z) I		\\
					\vdots		\\
				w_\kappa  \, t_\kappa(z) I
			\end{array}
		\right]	
		\right\|_2			\\
			\;	&		\leq		\;
			\left\|
			\left[
				\begin{array}{ccc}
					\Delta T_1		&	\dots		&	\Delta T_\kappa
				\end{array}
			\right]
		\right\|_2
		\sqrt{w_1^2 | t_1(z) |^2 +  \dots  + w_\kappa^2 | t_\kappa(z) |^2}	\:	.
\end{split}
\end{equation*}
This shows that 
$
		\left\|
			\left[
				\begin{array}{ccc}
					\Delta T_1		&	\dots		&	\Delta T_\kappa
				\end{array}
			\right]
		\right\|_2	\geq \varphi(z)
$, that is $\Delta T \not\in {\mathcal P}_{\epsilon}$ for any $\epsilon < \zeta(z)$, implying
\begin{equation}\label{eq:berror_lb}
	\inf\{ \epsilon \; | \; \exists \Delta T \in {\mathcal P}_{\epsilon}	
			\text{ s.t. }	\mathrm{det}\left\{ (T + \Delta T)(z) \right\} = 0	\}
				\;	\geq		\;	\varphi(z)	\:	.
\end{equation}
Combining (\ref{eq:berror_ub}) and (\ref{eq:berror_lb}), we deduce
$\inf\{ \epsilon \; | \; \exists \Delta T \in {\mathcal P}_{\epsilon}	
			\text{ s.t. }	\mathrm{det}\left\{ (T + \Delta T)(z) \right\} = 0	\} = \varphi(z)$.
Moreover, this infimum is attained for $\Delta T = \underline{\Delta T}$,
so can be replaced by minimum.
\end{proof}



\section{Proof of Lemma \ref{Lem:char_rightp}}\label{sec:opt_rightmost_pt}
\begin{proof}
Suppose $z \in {\mathbb C}$ is a locally rightmost point in $\Lambda_{\epsilon}(T)$.
By the continuity of the smallest singular value
$\sigma_{\min}(M(\cdot))$, assuming $\sigma_{\min}(M(z)) = 0$ implies that
for every ball ${\mathcal B}_r(z) = \{ \widetilde{z} \; | \; |\widetilde{z} - z | < r \}$ 
with positive radius $r$ sufficiently small, we have $\sigma_{\min}(M(\lambda)) \leq \epsilon \:$
$\forall \lambda \in {\mathcal B}_r(z)$, that is $\lambda \in \Lambda_{\epsilon}(T) \:$
$\forall \lambda \in {\mathcal B}_r(z)$. But this contradicts with the fact that
$z$ is a locally rightmost point. Thus, $\sigma_{\min}(M(z)) > 0$. 
Recall also that $\sigma_{\min}(T(z))$ is simple, so $\sigma_{\min}(M(z))$ is simple as well.
Letting $(x,y) = (\text{Re}(z), \text{Im}(z)) \in {\mathbb R}^2$, and
by employing continuity once again, $\sigma_{\min}({\mathcal M}(u))$ 
is positive and simple for all $u$
in an open neighborhood of ${\mathcal U}$ of $(x,y)$. Then $\sigma_{\min}({\mathcal M}(u))$ 
is real analytic (so is
differentiable infinitely many times)
in ${\mathcal U}$ \cite[Lemma 2.5]{MehM24}, in particular at $(x,y) \in {\mathcal U}$.


%%% \medskip

%%% \noindent
Now, letting $\sigma(s_1, s_2) :=  \sigma_{\min}({\mathcal M}(s_1 , s_2))$ 
for $s_1, s_2 \in {\mathbb R}$, consider the optimization problem
\begin{equation}\label{eq:pspa_opt_char}
	\max \{  s_1 \; | \; s = (s_1, s_2) \in {\mathbb R}^2 \text{ s.t. } \sigma(s_1, s_2) \leq \epsilon \}
	\:	,
\end{equation}
for which $(x,y) = (\text{Re}(z), \text{Im}(z))$ is a local maximizer.
From the analytical formula for the derivative of a singular value function \cite[Lemma 2.5]{MehM24}, we have
\begin{equation}\label{eq:sval_par_ders}
	\nabla \sigma(x,y)
		\;	=	\;
	\left(
		\frac{\partial \sigma}{\partial s_1}(x,y)	,
		\frac{\partial \sigma}{\partial s_2}(x,y)
	\right)	
		\;		=	\;
	\bigg(
		\text{Re}\{ u^\ast {\mathcal M}_{s_1}(x,y) v \} \:	,  \:	\text{Re} \{ u^\ast {\mathcal M}_{s_2}(x,y) v \}
	\bigg)	\:	,
\end{equation}
where we assume without loss of generality that the singular vectors $u$, $v$ are of unit norm
(i.e., as $u^\ast {\mathcal M}_{s_1}(x,y) v$, $u^\ast {\mathcal M}_{s_2}(x,y) v$ are positive multiples 
of $\widehat{u}^\ast {\mathcal M}_{s_1}(x,y) \widehat{v}$, $\widehat{u}^\ast {\mathcal M}_{s_2}(x,y) \widehat{v}$,
respectively, for any other
pair of consistent left, right singular vectors $\widehat{u}$, $\widehat{v}$ corresponding to
$\sigma_{\min}(T(z))$, it suffices to show $u^\ast M'(z) v$ is positive, real).
Thus, it follows from ${\mathcal S}(z) \neq 0$ (by the nondegeneracy of $z$) that
$\nabla \sigma(x,y) \neq 0$. As a result, the linear independence constraint
qualification holds for the optimization problem in (\ref{eq:pspa_opt_char}) at $(x,y)$.
From the first-order necessary conditions \cite[Theorem 12.1]{NocW00} applied
to (\ref{eq:pspa_opt_char}), there exists a nonnegative Lagrange multiplier $\mu$ such that
\begin{equation}\label{eq:opt_cond}
		1	-	\mu \frac{\partial \sigma}{\partial s_1}(x,y)	\;	=	\;	0	\:	
		\quad\quad\;	\text{and}		\quad\quad\;\;
		\mu	\frac{\partial \sigma}{\partial s_2}(x,y)	\;	=	\;	0	\:	.
\end{equation}
It follows from the left-hand equality in (\ref{eq:opt_cond}) that $\mu \neq 0$, so $\mu > 0$.
Now plugging the expressions in (\ref{eq:sval_par_ders}) for the partial derivatives of $\sigma(s_1, s_2)$
at $(x,y)$ in (\ref{eq:opt_cond}), we obtain
\[
	\text{Re}\{ u^\ast {\mathcal M}_{s_1}(x,y) v \}	=	1/\mu
	\quad\quad\;	\text{and}		\quad\quad\;\;
	\text{Re} \{ u^\ast {\mathcal M}_{s_2}(x,y) v \}	=	0	\:	.	
\]
Consequently, ${\mathcal S}(z)$ is real and positive as claimed. 
\end{proof}


