\subsection{Lattices and related properties}
In this section, we introduce the definition of lattices and some necessary properties we used in the rest of the paper.

\begin{definition}[\cite{MGbook}]\label{def:Lattice}
(Lattice). Given linearly independent vectors $\boldsymbol{b_1},\boldsymbol{b_2},...,\boldsymbol{b_d}\in\mathbb{R}^{m}$,  the lattice generated by these vectors is defined as \begin{align*}
\mathcal{L}=L(\boldsymbol{B})=L(\boldsymbol{b_1},\boldsymbol{b_2},...,\boldsymbol{b_d})=\left\{\sum_{i=1}^dz_i\boldsymbol{b}_i:z_i\in\mathbb{Z}\right\},
\end{align*}
where $d$ and $m$ are called the rank and the dimension of the lattice, respectively. Specially, if $d=m$, the lattice is called full-rank.
\end{definition}
\begin{definition}[\cite{MGbook}]\label{def:Determinant}
(Determinant). Let $\mathcal{L}=L(\mathbf{B})$ be a lattice of rank $d$.  The determinant of $\mathcal{L}$, denoted $\det(\mathcal{L})=\sqrt{\det\left(\mathbf{B}^{T}\mathbf{B} \right)}$. Specially, if $\mathcal{L}$ is full-rank, $\det(\mathcal{L})=|\det(\mathbf{B})|$.
\end{definition}
\begin{definition}[\cite{MGbook}]
(Unimodular Matrix). A matrix $\mathbf{U}\in \mathbb{Z}^{d\times d}$ is called unimodular if $\det(\mathbf{U})=\pm 1$.
\end{definition}
\begin{lemma}[\cite{MGbook}]\label{lem:B=BU}
Two bases $\mathbf{B_1},\mathbf{B_2}\in \mathbb{R}^{m\times d}$ are equivalent if and only if $\mathbf{B_2}=\mathbf{B_1}\mathbf{U}$ for some unimodular matrix $\mathbf{U}$.
\end{lemma}
\begin{definition}[\cite{MGbook}]\label{def:Successive minimum}
(Successive Minima). Let $\mathcal{L}$ be a lattice of rank $d$. For $k\in \left\{1,...,d \right\}$, the $k$th successive minimum is defined as
\begin{align*}
   \lambda_k(\mathcal{L})=\mathrm{inf}\{r>0: \mathrm{dim}(\mathrm{span}(\mathcal{B}(\boldsymbol{o},r)\cap \mathcal{L}))\ge k\}, 
\end{align*}
where, for any computable norm $\|\cdot\|$, $\mathcal{B}(\boldsymbol{o},r)=\left\{ \mathbf{x}\in \mathbb{R}^{m}:||\mathbf{x}||<r \right\}$ represents the open ball of radius $r$ centered at the origin.
\end{definition}

%不加证明的前人已有的结果，以备后续证明之用
For two-dimensional lattices, Lagrange \cite{Lag73} introduced the concept of a reduced basis for two-dimensional lattices. That is,
\begin{definition}[\cite{Lag73,MGbook}]
Let $\mathbf{B}=[\mathbf{a}\ \mathbf{b}]$ with $\mathbf{a}=(a_1\ a_2)^T$ and $\mathbf{b}=(b_1\ b_2)^T$ be a basis of the lattice $\mathcal{L}=L(\mathbf{B})$. The basis is called Lagrange-reduced if it satisfies the condition: $\|\mathbf{a}\|,\|\mathbf{b}\|\le \|\mathbf{a}+\mathbf{b}\|,\|\mathbf{a}-\mathbf{b}\|.$
Here, $\|\cdot\|$ refers to any computable norm.
\end{definition}
For a Lagrange-reduced basis, the following result is well-known:
\begin{lemma}[\cite{MGbook}]\label{lem:Lag}
If $\mathbf{B}=[\mathbf{a}\ \mathbf{b}]$ is Lagrange-reduced, then for any computable norm $\|\cdot\|$,  we have
$\min\{ \|\mathbf{a}\|,\|\mathbf{b}\|\}=\lambda_1(\mathcal{L})$ and $\max\{\|\mathbf{a}\|,\|\mathbf{b}\|\}=\lambda_2(\mathcal{L})$. 
\end{lemma}
The above property is derived from the following general fact:
\begin{lemma}[\cite{MGbook}]
For any two vectors $\mathbf{x}$, $\mathbf{y}$ and any computable norm $\|\cdot\|$, if $\|\mathbf{x}\|\le \ (resp. <)\|\mathbf{x}+\mathbf{y}\|$, then $\|\mathbf{x}+\mathbf{y}\|\le\  (resp. <)\|\mathbf{x}+\alpha\mathbf{y}\|$ for any $\alpha>1$·
\end{lemma}

\subsection{Hermite Normal Form}
The Hermite Normal Form (HNF) of a matrix is a canonical form used in linear algebra and number theory for integer matrices. 
\begin{definition}[\cite{PYB2019}]
(Hermite Normal Form). A nonsingular matrix $\mathbf{H} \in \mathbb{Z}^{d\times d}$ is said to be in HNF if (1) $h_{i,i}>0$ for $1\leq i \leq d$. (2) $h_{j,i}=0$ for $i<j\leq d$. (3) $0\leq h_{j,i}<h_{i,i}$ for $1\leq j<i$.
\end{definition}
For any nonsingular integer matrix \(\mathbf{A}\), there exists a unique matrix \(\mathbf{H}\) in Hermite Normal Form (HNF) and a unique unimodular matrix \(\mathbf{U}\) such that \(\mathbf{H} = \mathbf{U}\mathbf{A}\) \cite{PYB2019}. Specifically, for any two-dimensional lattice, the basis matrix can be efficiently converted into its HNF using the following lemma.  
\begin{lemma}[\cite{EIS01}]
Given a matrix $\mathbf{B}=\begin{pmatrix}
a_1 & b_1\\
a_2 & b_2
\end{pmatrix}\in \mathbb{Z}^{2\times 2}$, let $c=\gcd(a_2,b_2)=xa_2+yb_2$ be the greatest common divisor of $a_2$ and $b_2$, then
\begin{align*}
\begin{pmatrix}
a_1 & b_1\\
a_2 & b_2
\end{pmatrix}
\begin{pmatrix}
b_2/\gcd(a_2,b_2)  & x\\
-a_2/\gcd(a_2,b_2) & y
\end{pmatrix}=
\begin{pmatrix}
a & b\\
0 & c
\end{pmatrix}\in \mathbb{Z}^{2\times 2}
\end{align*}
with $a=(a_1b_2-a_2b_1)/\gcd(a_2,b_2)$ and $b=a_1x+b_1y$.
By applying elementary vector transformations, we can ensure that the matrix satisfy the HNF conditions.
\end{lemma}

\section{Our new reduced basis and its properties}\label{sec:relation}
In this section, we first introduce a new reduced basis and then present its properties. Throughout this section and the rest of the paper, unless otherwise specified, the notations \(\|\mathbf{x}\|\) and $\|\mathbf{x}\|_2$ are used to represent the Minkowski metric (\(\ell_\infty\) norm) of \(\mathbf{x}\) and the Euclidean metric  (\(\ell_2\) norm), respectively.
%\subsection{A new reduced basis}
\begin{definition}\label{def:Eucred}
Given a lattice $\mathcal{L}=L(\boldsymbol{B})$ with a basis 
\begin{align}\label{eq:basis}
   \mathbf{B}=[\mathbf{a}\ \mathbf{b}]=\begin{pmatrix}
		a_{1} & b_{1}\\
		a_{2} & b_{2} 
	\end{pmatrix}\in\mathbb{R}^{2\times 2},
\end{align} we call $\mathbf{B}$ is reduced if 
\begin{equation}\label{eq:con}
a_1a_2b_1b_2\le 0 \wedge (|a_1|-|a_2|)(|b_1|-|b_2|)\le 0
\end{equation}	
\end{definition}
It should be remarked that the equation (\ref{eq:con}) also can be equivalently reformulated as
$a_1a_2b_1b_2\le 0 \wedge |a_1b_1-a_2b_2|\le |\det(\mathbf{B})|.$
Now we present two important properties of the new defined reduced basis. The first theorem establishes the minimality of the reduced basis under the Minkowski ($\ell_{\infty}$) norm, while the second theorem demonstrates a similar property under the Euclidean ($\ell_2$) norm. 

\begin{theorem}\label{thm:Eucred}
Let $\mathcal{L}=L(\boldsymbol{B})$ be a lattice with basis $\mathbf{B}$ defined in equation (\ref{eq:basis}), and let $\lambda_1(\mathcal{L})$ and $\lambda_2(\mathcal{L})$ denote the successive minima under $\ell_\infty$ norm. If $\mathbf{B}$ is reduced, then
$\lambda_1(\mathcal{L})=\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}.$ Further,
let $\mathbf{c}=(c_1\ c_2)\in\mathcal{L}$ be a vector achieving $\lambda_2(\mathcal{L})$. Then $\mathbf{c}=\mathrm{argmax}\{\|\mathbf{a}\|,\|\mathbf{b}\|\}-z\cdot\mathrm{argmin}\{\|\mathbf{a}\|,\|\mathbf{b}\|\}$, where $z$ is determined as follows:

(1) If $a_1b_1\ge 0,a_2b_2\leq 0$, then
\begin{align*}
z=\left\{
\begin{array}{ll}
\left\lfloor\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rfloor\ \mbox{or}\ \left\lceil\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rceil,&\|\mathbf{a}\|\le \|\mathbf{b}\|\\
\left\lfloor\frac{|a_1|-|a_2|}{|b_1|+|b_2|}\right\rfloor\ \mbox{or}\ \left\lceil\frac{|a_1|-|a_2|}{|b_1|+|b_2|}\right\rceil,&\|\mathbf{a}\|>\|\mathbf{b}\|
\end{array}
\right.
\end{align*}

(2) If $a_1b_1<0,a_2b_2\ge 0$, then
\begin{align*}
z=\left\{
\begin{array}{ll}
\left\lfloor\frac{|b_2|-|b_1|}{|a_1|+|a_2|}\right\rfloor\ \mbox{or}\ \left\lceil\frac{|b_2|-|b_1|}{|a_1|+|a_2|}\right\rceil,&\|\mathbf{a}\|\le \|\mathbf{b}\|\\
\left\lfloor\frac{|a_2|-|a_1|}{|b_1|+|b_2|}\right\rfloor\ \mbox{or}\ \left\lceil\frac{|a_2|-|a_1|}{|b_1|+|b_2|}\right\rceil,&\|\mathbf{a}\|>\|\mathbf{b}\|
\end{array}
\right.
\end{align*}
Specially,  if $a_1a_2b_1b_2=0$ and none of the above cases apply, negate  $\mathbf{a}$ or $\mathbf{b}$ as necessary to fit into one of the above cases.
\end{theorem}

\begin{proof}
%Consider a special case is when an element in the matrix is $0$, for example $b_2=0$, and $sgn(a_1)=sgn(a_2)\ne sgn(b_1)$. In this case, it also satisfies $a_1a_2b_1b_2\leq 0$. For the convenience of analysis, if the above situation occurs, we need to negate $\mathbf{a}$ or $\mathbf{b}$ so that $a_1$ and $b_1$ have the same sign. 

Without loss of generality, we only consider the case 
$a_1b_1\ge 0$ and $a_2b_2\le 0$. We aim to prove that for any non-zero lattice vector $\mathbf{v}=z_1\mathbf{a}+z_2\mathbf{b}=(z_1a_1+z_2b_1\ z_1a_2+z_2b_2)^T$, the following inequality holds:
\begin{align}\label{eq:lambda1}
\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}\le \|\mathbf{v}\|.
\end{align}
Clearly,  in case that $z_1=0,z_2\neq 0$,
\begin{align*}
\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}=\max\{|z_2b_1|, |z_2b_2|\}\ge \max\{|b_1|,|b_2|\}=\|\mathbf{b}\|\ge \min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}.
\end{align*}
and, in case that $z_1\neq 0,z_2=0$,
\begin{align*}
\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}=\max\{|z_1a_1|, |z_1a_2|\}\ge \max\{|a_1|,|a_2|\}=\|\mathbf{a}\|\ge\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}.
\end{align*}
We now analyze the case $z_1z_2\neq 0$ based on the properties of the reduced  basis
($i.e., (|a_1|-|a_2|)(|b_1|-|b_2|)\le 0$).
\begin{enumerate}
\item $|a_1|= |a_2|$. Here, 
$\|\mathbf{a}\|=\max\{|a_1|,|a_2|\}=|a_1|=|a_2|$.  
Then, if $z_1z_2>0$, we have
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_1+z_2b_1|\ge \max\{|a_1|,|b_1|\}\ge |a_1|=\|\mathbf{a}\|\ge \min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}$
and, if $z_1z_2<0$, we have 
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_2+z_2b_2|\ge |a_2|= \|\mathbf{a}\|\ge\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}.$

\item $|b_1|= |b_2|$. Here, 
$\|\mathbf{b}\|=\max\{|b_1|,|b_2|\}=|b_1|=|b_2|$.  
Then, if $z_1z_2>0$, we have
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_1+z_2b_1|\ge \max\{|a_1|,|b_1|\}\ge |b_1|=\|\mathbf{b}\|\ge \min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}$
and, if $z_1z_2<0$, we have 
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_2+z_2b_2|\ge |b_2|= \|\mathbf{b}\|\ge\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}.$

\item $|a_1|< |a_2|$ and $|b_1|> |b_2|$. Here, 
$\|\mathbf{a}\|=\max\{|a_1|,|a_2|\}=|a_2|$ and $\|\mathbf{b}\|=\max\{|b_1|,|b_2|\}=|b_1|$.  
Then, if $z_1z_2>0$, we have
%\begin{align*}
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_1+z_2b_1|\ge \max\{|a_1|,|b_1|\}=|b_1|=\|\mathbf{b}\|\ge \min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}$
%\end{align*}
and, if $z_1z_2<0$, we have%\begin{align*}
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_2+z_2b_2|\ge |a_2|= \|\mathbf{a}\|\ge\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}.$
%\end{align*}
\item $|a_1|> |a_2|$ and $|b_1|< |b_2|$. Here, 
$\|\mathbf{a}\|=\max\{|a_1|,|a_2|\}=|a_1|$ and $\|\mathbf{b}\|=\max\{|b_1|,|b_2|\}=|b_2|$.  
Then, if $z_1z_2>0$, we have
%\begin{align*}
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_1+z_2b_1|\ge \max\{|a_1|,|b_1|\}\ge |a_1|= \|\mathbf{a}\|\ge \min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}$,%\end{align*}
and, if $z_1z_2<0$, we have
%\begin{align*}
$\|\mathbf{v}\|=\max\{|z_1a_1+z_2b_1|,|z_1a_2+z_2b_2|\}\ge |z_1a_2+z_2b_2|\ge |b_2|= \|\mathbf{b}\|\ge \|\mathbf{a}\|\ge \min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}.$
%\end{align*}
\end{enumerate}
Overall, the equation (\ref{eq:lambda1}) holds, confirming that  $\lambda_1(\mathcal{L})=\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}$. Next, we will analyze the vector that achieves the second successive minimum $\lambda_2(\mathcal{L})$, by considering two distinct cases.

Case 1: $\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}=\|\mathbf{a}\|=\lambda_1(\mathcal{L})$, \emph{i.e.}, $\max\{|a_1|,|a_2|\}\le \max\{|b_1|,|b_2|\}$. Define the function 
\begin{align*}
f(x)=\|\mathbf{b}-x\mathbf{a}\|=\max\{|b_1-xa_1|,|b_2-xa_2|\}\triangleq\max\{f_1(x),f_2(x)\}.
\end{align*}
Let $f(z)=\min_{z\in\mathbb{Z}}f(x)$. Then, $\|\mathbf{a}\|\le f(z)=\|\mathbf{b}-z\mathbf{a}\|\le f(z+1)=\|\mathbf{b}-(z+1)\mathbf{a}\|=\|\mathbf{a}-(\mathbf{b}-z\mathbf{a})\|$ and $f(z-1)=\|\mathbf{b}-(z-1)\mathbf{a}\|=\|\mathbf{a}+(\mathbf{b}-z\mathbf{a})\|$. By \textbf{Lemma \ref{lem:Lag}}, it follows that $\lambda_2(\mathcal{L})=f(z)$. Thus, we only need to estimate $z$. We now consider the case where  $a_1a_2\neq 0$.  The argument is essentially the same for cases where $a_1=0$ or $a_2=0$. From the definitions of $f_1(x)$ and $f_2(x)$, we have
\begin{align*}
f_1(x)=\left\{\begin{array}{ll}
|a_1|x-|b_1|,& x\ge \frac{b_1}{a_1}\\
-|a_1|x+|b_1|,& x< \frac{b_1}{a_1}
\end{array}\right.,\
f_2(x)=\left\{\begin{array}{ll}
|a_2|x+|b_2|,& x\ge \frac{b_2}{a_2}\\
-|a_2|x-|b_2|,& x< \frac{b_2}{a_2}
\end{array}\right..
\end{align*}
The minimum $f(z)$ is achieved at the integer closest to the point of intersection where $-|a_1|x+|b_1|=|a_2|x+|b_2|$ (\emph{i.e.}, $x=\frac{|b_1|-|b_2|}{|a_1|+|a_2|}$). Therefore,
\begin{equation*}
z=\left\lfloor\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rfloor\ \mbox{or}\ \left\lceil\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rceil.
\end{equation*}


Case 2: $\min\{\|\mathbf{a}\|,\|\mathbf{b}\|\}=\|\mathbf{b}\|$, \emph{i.e.}, $\max\{|a_1|,|a_2|\}\ge \max\{|b_1|,|b_2|\}$. Define the function 
\begin{align*}
g(y)=\|\mathbf{a}-y\mathbf{b}\|=\max\{|a_1-yb_1|,|a_2-yb_2|\}\triangleq\max\{g_1(y),g_2(y)\}.
\end{align*}
Let $g(z)=\min_{z\in\mathbb{Z}}g(y)$. Then $\|\mathbf{b}\|\le g(z)=\|\mathbf{a}-z\mathbf{b}\|\le g(z+1)=\|\mathbf{a}-(z+1)\mathbf{b}\|=\|\mathbf{b}-(\mathbf{a}-z\mathbf{b})\|$ and $g(z-1)=\|\mathbf{b}-(z-1)\mathbf{a}\|=\|\mathbf{b}+(\mathbf{a}-z\mathbf{b})\|$. By \textbf{Lemma \ref{lem:Lag}}, it follows that $\lambda_2(\mathcal{L})=g(z)$. Thus, we only need to estimate $z$. We now consider the case where  $b_1b_2\neq 0$.  The argument is essentially the same for cases where $b_1=0$ or $b_2=0$. From the definitions of $g_1(y)$ and $g_2(y)$, we have
\begin{align*}
g_1(y)=\left\{\begin{array}{ll}
|b_1|y-|a_1|,& y\ge \frac{a_1}{b_1}\\
-|b_1|y+|a_1|,& y< \frac{a_1}{b_1}
\end{array}\right.,\
g_2(y)=\left\{\begin{array}{ll}
|b_2|y+|a_2|,& y\ge \frac{a_2}{b_2}\\
-|b_2|y-|a_2|,& y< \frac{a_2}{b_2}
\end{array}\right..
\end{align*}
The minimum $g(z)$ will achieve at the integer around the point of intersection $-|b_1|y+|a_1|=|b_2|y+|a_2|$ (\emph{i.e.}, $y=\frac{|a_1|-|a_2|}{|b_1|+|b_2|}$). Therefore,
\begin{equation*}
z=\left\lfloor\frac{|a_1|-|a_2|}{|b_1|+|b_2|}\right\rfloor\ \mbox{or}\ \left\lceil\frac{|a_1|-|a_2|}{|b_1|+|b_2|}\right\rceil.
\end{equation*}
\end{proof}


\begin{theorem}\label{thm:l2}
Let $\mathcal{L}=L(\boldsymbol{B})$ be a lattice with basis $\mathbf{B}$ defined in equation (\ref{eq:basis}), and let $\lambda_1(\mathcal{L})$ and $\lambda_2(\mathcal{L})$ denote the successive minims under $\ell_2$ norm. If $\mathbf{B}$ is reduced, then $\mathbf{u}=\mathrm{argmin}\{\|\mathbf{a}\|_2,\|\mathbf{b}\|_2, \|\mathbf{a}+\mathbf{b}\|_2,\|\mathbf{a}-\mathbf{b}\|_2\}$ is a shortest non-zero lattice vector under the $\ell_2$ norm. That is, $\lambda_1(\mathcal{L})=\|\mathbf{u}\|_2$. Further, for any vector $\mathbf{x}\in \{\mathbf{a},\mathbf{b}\}\setminus \{\mathbf{u}\}$,   $\mathbf{v}=\mathbf{x}-q\mathbf{u}$ with $q=\left\lceil\frac{\langle\mathbf{x}, \mathbf{u}\rangle}{\langle \mathbf{u}, \mathbf{u}\rangle}\right\rfloor$  is a lattice vector achieving $\lambda_2(\mathcal{L})$. That is, 
$\lambda_2(\mathcal{L})=\|\mathbf{v}\|_2$.
\end{theorem}
\begin{proof}
First, we prove $\lambda_1(\mathcal{L})=\|\mathbf{u}\|_2$.  Namely, we need to prove $\forall (z_1\ z_2)\in \mathbb{Z}^2\backslash \{\mathbf{0}\}, \|\mathbf{v}\|_2=\|z_1\mathbf{a}+z_2\mathbf{b}\|_2\geq \|\mathbf{u}\|_2$. Clearly, if $z_1z_2=0$ or $z_1=z_2$, we can easily deduce that $\|\mathbf{v}\|_2\ge \min\{\|\mathbf{a}\|_2,\|\mathbf{b}\|_2, \|\mathbf{a}+\mathbf{b}\|_2\}\ge\|\mathbf{u}\|_2$; Without loss of generality, we now assume $\|\mathbf{a}\|_2\le \|\mathbf{b}\|_2$, $a_1b_1\ge 0,a_2b_2\leq 0$ and $z_1z_2\ne 0 \wedge z_1\ne z_2$.

(1) $\mathbf{u} = \mathbf{a}$. In this case, we need to prove
\begin{align}\label{eq:target1}
\|z_1\mathbf{a}+z_2\mathbf{b}\|_2\geq \|\mathbf{a}\|_2\Longleftrightarrow (z_1^{2}-1)(a_1^{2}+a_2^{2})+z_2^{2}(b_1^{2}+b_2^{2})+2z_1z_2(a_1b_1+a_2b_2)\geq 0.
\end{align}
If $(z_1z_2)(a_1b_1+a_2b_2)\ge 0$, the above inequality clearly holds.  Meanwhile, from $\|\mathbf{a}\|_2 \le\|\mathbf{b}\|_2$ and $\|\mathbf{a}\|_2\le\|\mathbf{a}+\mathbf{b}\|_2, \|\mathbf{a}-\mathbf{b}\|_2$, we have 
\begin{align}\label{eq:bound}
a_1^2+a_2^2\le b_1^2+b_2^2\ \wedge\ -(b_1^{2}+b_2^{2})\leq 2(a_1b_1+a_2b_2)\leq b_1^{2}+b_2^{2}.
\end{align}
 Applying these bounds, we conclude that inequality \eqref{eq:target1} follows from
\begin{align*}
  &(z_1^{2}-1)(a_1^{2}+a_2^{2})+z_2^{2}(b_1^{2}+b_2^{2})+2z_1z_2(a_1b_1+a_2b_2)\\
  \geq &(z_1^{2}-1)(a_1^{2}+a_2^{2})+z_2^{2}(b_1^{2}+b_2^{2})-z_1z_2(b_1^{2}+b_2^{2})\\
  \geq &(z_1^{2}-1)(a_1^{2}+a_2^{2})+(z_2^{2}-z_1z_2)(b_1^{2}+b_2^{2})\geq 0
\end{align*}
Thus, it remains to consider the case where
$(z_1z_2)(a_1b_1+a_2b_2)< 0$ and $|z_1|>|z_2|\ge 1$. We proceed by analyzing this scenario in detail.\begin{itemize}
 \item $z_1z_2>0$ and $a_1b_1+a_2b_2<0$, we have 
\begin{align}
   &(z_1^{2}-1)(a_1^{2}+a_2^{2})+z_2^{2}(b_1^{2}+b_2^{2})+2z_1z_2(a_1b_1+a_2b_2)\nonumber\\
   =&(z_1^{2}-1)a_1^{2}+(z_1^{2}-1)a_2^{2}+z_2^{2}b_1^{2}+z_2^{2}b_2^{2}-2|z_1||z_2|(|a_2b_2+a_1b_1|)\nonumber\\
      =&(z_1^{2}-1)a_1^{2}+(z_1^{2}-1)a_2^{2}+z_2^{2}b_1^{2}+z_2^{2}b_2^{2}-2|z_1||z_2|(|a_2||b_2|-a_1b_1)\nonumber\\
   =&z_1^{2}a_2^{2}+z_2^{2}b_2^{2}-2|z_1||z_2||a_2||b_2|+(z_1^{2}-1)a_1^{2}+z_2^{2}b_1^{2}+2z_1z_2a_1b_1-a_2^{2}\label{eq:noa}
\end{align} 
Clearly, if $|a_1|\geq|a_2|$, then the equation $(\ref{eq:noa})\ge (z_1^2-1) a_1^{2}-a_2^{2}\ge 3a_1^2-a_2^2\ge 0$, and, if $|b_1|\ge |a_2|$, then the equation $(\ref{eq:noa})\ge z_2^2 b_1^{2}-a_2^{2}\ge b_1^2-a_2^2\ge 0$. Consequently, the remaining case to consider is $|a_1|<|a_2| \wedge |b_1|<|a_2|$. From $|a_1|<|a_2|$ and the definition of the reduced base, we know $|b_1|\ge |b_2|$. Combining this with $|b_1|<|a_2|$ and the bound $a_1^2+a_2^2\le b_1^2+b_2^2$ (equation (\ref{eq:bound})), we deduce $|a_1|<|b_2|$. Thus, 
the remaining case is \[|a_1|<|b_2|\le |b_1|<|a_2|.\] In this case, if $|z_2|\ge 2$, the the equation
$(\ref{eq:noa})\ge z_2^{2}b_1^{2}-a_2^{2}\ge 4 b_1^{2}-a_2^{2}\ge 2b_1^2+2b_2^2-a_2^2\ge 2(a_1^2+a_2^2)-a_2^2\ge 0.$
If $|z_2|=1$, the equation (\ref{eq:noa}) is
\begin{align*}
&(b_1^{2}+b_2^{2})-(a_1^2+a_2^2)+2|z_1|a_1b_1+z_1^{2}(a_1^{2}+a_2^{2})-2|z_1||a_2||b_2|\\
\ge& z_1^2a_2^{2}-2|z_1||a_2||b_2|\ge z_1^2|a_2||b_2|-2|z_1||a_2||b_2|=( z_1^2-2|z_1|)|a_2||b_2|\ge 0.
\end{align*}

\item $z_1z_2<0$ and $a_1b_1+a_2b_2> 0$, we have 
\begin{align}
   &(z_1^{2}-1)(a_1^{2}+a_2^{2})+z_2^{2}(b_1^{2}+b_2^{2})+2z_1z_2(a_1b_1+a_2b_2)\nonumber\\
   =&(z_1^{2}-1)a_1^{2}+(z_1^{2}-1)a_2^{2}+z_2^{2}b_1^{2}+z_2^{2}b_2^{2}-2|z_1||z_2|(a_1b_1-|a_2b_2|)\nonumber\\
   =&z_1^{2}a_1^{2}+z_2^{2}b_1^{2}-2|z_1||z_2|a_1b_1+(z_1^{2}-1)a_2^{2}+z_2^{2}b_2^{2}+2|z_1||z_2||a_2||b_2|-a_1^{2}.\label{eq:nob} 
\end{align} 

Clearly, if $|a_2|\ge |a_1|$, then the equation $(\ref{eq:nob})\ge (z_1^2-1) a_2^{2}-a_1^{2}\ge 3a_2^2-a_1^2\ge 0$, and, if $|b_2|\ge |a_1|$, then the equation $(\ref{eq:nob})\ge z_2^2 b_2^{2}-a_1^{2}\ge b_2^2-a_1^2\ge 0$. Consequently, the left case is $|a_1|>|a_2| \wedge |a_1|>|b_2|$. From $|a_1|>|a_2|$ and the definition of the reduced base, we know $|b_1|\le |b_2|$, and, $|a_1|>|b_2|$ and $a_1^2+a_2^2\le b_1^2+b_2^2$ (equation (\ref{eq:bound})) implies $|a_2|<|b_1|$. That is, 
the left case is \[|a_2|<|b_1|\le |b_2|<|a_1|.\] In this case, if $|z_2|\ge 2$, then the equation $(\ref{eq:nob})\ge z_2^{2}b_2^{2}-a_1^{2}\ge 4 b_2^{2}-a_2^{2}\ge 2b_1^2+2b_2^2-a_1^2\ge 2(a_1^2+a_2^2)-a_1^2\ge 0.$
 If $|z_2|=1$, the equation (\ref{eq:nob}) is
\begin{align*}
 &z_1^{2}(a_1^{2}+a_2^{2})+(b_1^{2}+b_2^{2})-(a_1^{2}+a_2^{2})-2|z_1|a_1b_1+2|z_1||a_2||b_2|\nonumber\\
\ge & z_1^{2}a_1^{2}-2|z_1|a_1b_1\ge z_1^{2}|a_1||b_1|-2|z_1|a_1b_1=(z_1^{2}-2|z_1|)a_1b_1\ge 0.
\end{align*}
\end{itemize}

(2) $\mathbf{u} = \mathbf{a}+\mathbf{b}$. In this case,   we need to prove \begin{align}\label{eq:target}
&||z_1\mathbf{a}+z_2\mathbf{b}||\geq ||\mathbf{a}+\mathbf{b}||\Longleftrightarrow (z_1^{2}-1)(a_1^{2}+a_2^{2})+(z_2^{2}-1)(b_1^{2}+b_2^{2})+2(z_1z_2-1)(a_1b_1+a_2b_2)\geq 0.
\end{align}


From $\|\mathbf{a}+\mathbf{b}\|_2\le \|\mathbf{a}\|_2\le \|\mathbf{b}\|_2$,  we  have
\begin{align}\label{eq:bound2}
a_1b_1+a_2b_2<0\ \wedge \  a_1^{2}+a_2^{2}\le b_1^{2}+b_2^{2} \leq -2(a_1b_1+a_2b_2)=2(|a_2||b_2|-|a_1||b_1|)\leq (a_1^{2}+a_2^{2})+(b_1^{2}+b_2^{2}).
\end{align}
Since $a_1b_1+a_2b_2<0$, the target inequality (\ref{eq:target}) clearly holds if $z_1z_2-1\le 0$. We only need to consider the case that $z_1z_2> 1$.

In fact, by equation (\ref{eq:bound2}),
\begin{align}
&(z_1^{2}-1)(a_1^{2}+a_2^{2})+(z_2^{2}-1)(b_1^{2}+b_2^{2})+2(z_1z_2-1)(a_1b_1+a_2b_2)\nonumber\\
=&(z_1^{2}-1)(a_1^{2}+a_2^{2})+(z_2^{2}-1)(b_1^{2}+b_2^{2})+2z_1z_2(a_1b_1+a_2b_2)-2(a_1b_1+a_2b_2)\nonumber\\
=&z_1^{2}a_1^{2}+z_1^2a_2^{2}-(a_1^{2}+a_2^{2})+z_2^{2}b_1^{2}+z_2^2b_2^{2}-(b_1^{2}+b_2^{2})-2z_1z_2|a_2||b_2|+2z_1z_2|a_1||b_1|-2(a_1b_1+a_2b_2)\nonumber\\
=&(z_1^2a_2^{2}-2z_1z_2|a_2||b_2|+z_2^2b_2^{2})+2z_1z_2|a_1||b_1|+(z_1^2-1)a_1^2+z_2^2b_1^2+(-2(a_1b_1+a_2b_2)-(b_1^{2}+b_2^{2}))-a_2^2\label{eq:lbound1}\\
=&(z_1^2a_2^{2}-2z_1z_2|a_2||b_2|+z_2^2b_2^{2})+2z_1z_2|a_1||b_1|+z_1^2a_1^2+(z_2^2-1)b_1^2+(-2(a_1b_1+a_2b_2)-(a_1^{2}+a_2^{2}))-b_2^2\label{eq:lbound2}% \\ \ge& 2z_1z_2|a_1||b_1|+(z_1^2-1)a_1^2+z_2^2b_1^2-a_2^2.
\end{align}
If $|b_1|\ge |a_2|$, then the equation $(\ref{eq:lbound1})\ge z_2^2b_1^2-a_2^2\ge b_1^2-a_2^2\ge 0$. Hence, we only argue the case that $|b_1|<|a_2|$. Here, since $a_1^2+a_2^2\le b_1^2+b_2^2$, we have $|b_2|>|a_1|$.  Also, $(|a_1|-|a_2|)(|b_1|-|b_2|)\le 0$ implies that (1) $|b_1|<|a_2|\le |a_1|<|b_2|$ or (2) $|a_1|<|b_2|\le |b_1|<|a_2|$. Now, we argue each case as follows.
\begin{itemize}
\item  $|b_1|<|a_2|\le |a_1|<|b_2|$. If $|z_1|\ne 1$, then the equation $(\ref{eq:lbound1})\ge (z_1^2-1)a_1^2-a_2^2\ge 3a_1^2-a_2^2\ge 0$. If $|z_1|=1$, then $|z_2|\ge 2$ and the equation (\ref{eq:lbound1}) is 
\begin{align*}
&z_2^2b_1^2+z_2^2b_2^{2}-2|z_2||a_2||b_2|+2|z_2||a_1||b_1|+(2(|a_2||b_2|-|a_1||b_1|)-(b_1^{2}+b_2^{2}))\nonumber\\
\ge& z_2^2b_2^{2}-2|z_2||a_2||b_2|\ge  z_2^2|a_2||b_2|-2|z_2||a_2||b_2|=( z_2^2-2|z_2|)|a_2||b_2|\ge 0. 
\end{align*}


\item $|a_1|<|b_2|\le |b_1|<|a_2|$. If $|z_2|\ne 1$, then the equation $(\ref{eq:lbound2})\ge (z_2^2-1)b_1^2-b_2^2\ge 3b_1^2-b_2^2\ge 0$. If $|z_2|=1$, then $|z_1|\ge 2$ and the equation $(\ref{eq:lbound2})$ is 
\begin{align*}
&z_1^2a_2^{2}-2|z_1||a_2||b_2|+2|z_1||a_1||b_1|+z_1^2a_1^2+(-2(a_1b_1+a_2b_2)-(a_1^{2}+a_2^{2}))\\
\ge& z_1^2a_2^2-2|z_1||a_2||b_2|\ge z_1^2|a_2||b_2|-2|z_1||a_2||b_2|\ge (z_1^2-2|z_1|)|a_2||b_2|\ge 0.
\end{align*}
\end{itemize}

 (3) $\mathbf{u}=\mathbf{a}-\mathbf{b}$. The proof for this case follows the same logic as case $\mathbf{u}=\mathbf{a}+\mathbf{b}$, and thus we omit the details.

Combining the three cases (1)-(3) above, we complete the proof of \(\lambda_1(\mathcal{L})\).  To prove \(\lambda_2(\mathcal{L}) = \|\mathbf{v}\|_2\), by \textbf{Lemma \ref{lem:Lag}}, it suffices to show that the pair \([\mathbf{u}, \mathbf{v}]\) is Lagrange-reduced, i.e.,  
\[
\|\mathbf{u}\|_2 \leq \|\mathbf{v}\|_2 \leq \min\left\{\|\mathbf{u}+\mathbf{v}\|_2, \|\mathbf{u}-\mathbf{v}\|_2\right\}.
\]  
In fact, by the choice of \(q\), we have:  
\[
\begin{aligned}
\|\mathbf{v}\|_2 &= \|\mathbf{x} - q\mathbf{u}\|_2 \leq \|\mathbf{x} - (q+1)\mathbf{u}\|_2 = \|\mathbf{v} - \mathbf{u}\|_2, \\
\|\mathbf{v}\|_2 &= \|\mathbf{x} - q\mathbf{u}\|_2 \leq \|\mathbf{x} - (q-1)\mathbf{u}\|_2 = \|\mathbf{v} + \mathbf{u}\|_2.
\end{aligned}
\]  
Thus, the inequalities \(\|\mathbf{v}\|_2 \leq \|\mathbf{u} \pm \mathbf{v}\|_2\) hold, completing the proof.


\end{proof}

