\section{Our new reduced algorithm and its analysis}

Building upon our new defined reduced basis (\textbf{Definition \ref{def:Eucred}}) and its properties (\textbf{Theorem \ref{thm:Eucred}}), we introduce an algorithm that directly transforms any given two-dimensional lattice basis into a reduced basis. This approach eliminates the necessity for an initial conversion to HNF as employed by Eisenbrand \cite{EIS01}.

\subsection{Design Idea}
For any input lattice basis  $[\mathbf{a}\ \mathbf{b}]$ with $\mathbf{a}=(a_1\ a_2)^T$, $\mathbf{b}=(b_1\ b_2)^T$ and $\|\mathbf{a}\|\ge \|\mathbf{b}\|$, if it is not reduced, then we have two possible cases:
(1) $a_1a_2b_1b_2>0$ or (2) $a_1a_2b_1b_2\le 0$ and $(|a_1|-|a_2|)(|b_1|-|b_2|)>0$. 

We first consider the case (2), without loss of generality, assume $a_1\ge b_1\ge 0$ and $a_2b_2\le 0$.  If these conditions are not met, we can adjust the basis vectors using negation or swapping operations to achieve them.

If $|a_1|>|a_2|$ and $|b_1|>|b_2|$, inspired by prior work \cite{EIS01,CTJ22}, we can compute a new basis $[\mathbf{b}\ \mathbf{c}]$ with $\mathbf{c}=\mathbf{a}-q\mathbf{b}$, where $q=\lfloor\frac{a_1}{b_1}\rfloor_o>0$. Then
\begin{align*}
a_1>b_1>c_1\ge 0,\ b_2c_2\le 0,\ |c_2|=|a_2-qb_2|=|a_2|+q|b_2|>|b_2|.
\end{align*}
As a result, $b_1b_2c_1c_2\le 0$. If $|c_1|-|c_2|\le 0$, the new basis $[\mathbf{b}\ \mathbf{c}]$ is reduced. Otherwise, we have $|b_1|-|b_2|>|c_1|-|c_2|>0$. Repeating this process iteratively reduces the difference between the absolute values of the first and second coordinates of the new vector until the terminal condition (the equation (\ref{eq:con})) is satisfied. 

If $|a_1|<|a_2|$ and $|b_1|<|b_2|$, in this case, we focus on the second coordinate. Using a similar process, we compute a new basis $[\mathbf{b}\ \mathbf{c}]$, where $\mathbf{c}=\mathbf{a}-q\mathbf{b}$ and $q=\lfloor\frac{a_2}{b_2}\rfloor_o\le0$. Then 
\begin{align*}
c_1>a_1>b_1\ge 0,\ b_2c_2\le 0,\ |c_2|=|a_2-qb_2|=|a_2|-|q||b_2|<|b_2|.
\end{align*}
Thus, $b_1b_2c_1c_2\le 0$. If $|c_1|-|c_2|\ge 0$, the new basis $[\mathbf{b}\ \mathbf{c}]$ is reduced. Otherwise, we have $|b_1|-|b_2|<|c_1|-|c_2|<0$. Repeating this process iteratively reduces the difference between the absolute values of the coordinates until the terminal condition (the equation (\ref{eq:con})) is satisfied.

For the case (1). When $a_1a_2b_1b_2>0$, the key is to transform the basis such that $a_1a_2b_1b_2\le0$. Since $\mathbf{a}$ and $\mathbf{b}$ are linearly independent, it holds that $\frac{a_1}{b_1}\neq \frac{a_2}{b_2}$. Let $q_1\triangleq\lfloor\frac{a_1}{b_1}\rfloor_o, q_2\triangleq \lfloor\frac{a_2}{b_2}\rfloor_o$. If $q_1\neq q_2$,  we choose
\[
q = 
\begin{cases} q_1, & \text{if }  |a_1| \geq |a_2| \wedge q_1 \geq q_2, \\%[1em]
q_1+1, & \text{if } |a_1| \geq |a_2| \wedge q_1 < q_2,\\
q_2, & \text{if } |a_1| < |a_2| \wedge q_2 \geq q_1, \\%[1em]
q_2+1, & \text{if }  |a_1| < |a_2| \wedge q_2 < q_1.
\end{cases}\
\] 
Then the new basis $[\mathbf{b}\ \mathbf{c}]$ with $\mathbf{c}=\mathbf{a}-q\mathbf{b}$ ensures $b_1b_2c_1c_2\le0$, achieving the goal. Otherwise $q=q_1=q_2$, iteratively reduce the basis $[\mathbf{b}\ \mathbf{c}]$ with the same method until $q_1\neq q_2$.

\subsection{Algorithm Description and Analysis}
Based on the proposed design concept, the detailed steps of our algorithm are provided in \textbf{Algorithm \ref{alg:CrossEuc}}. It should be noted that the \textbf{Algorithm \ref{alg:CrossEuc}} invokes two sub-algorithms: \textbf{UMTrans1}$^\star$ and \textbf{UMTrans2}$^\star$, which are variants of \textbf{UMTrans1} (\textbf{Algorithm \ref{alg:TransPositive}}) and \textbf{UMTrans2} (\textbf{Algorithm \ref{alg:TransNegative}}), respectively. The only difference is whether the returned result includes the integer \(q\).    

Before discussing the correctness and complexity of \textbf{Algorithm \ref{alg:CrossEuc}},  we first present two lemmas to analyze the properties of \textbf{Algorithm \ref{alg:TransPositive}} and \textbf{Algorithm \ref{alg:TransNegative}}.




\begin{algorithm}
\caption{\textbf{UMTrans1}($\mathbf{a},\mathbf{b}$)}\label{alg:TransPositive}
\begin{algorithmic}[1]
\REQUIRE  A basis $[\mathbf{a}\ \mathbf{b}]$ where $\mathbf{a}=(a_1\ a_2)^T$ and $\mathbf{b}=(b_1\ b_2)^T$, satisfying $a_1a_2b_1b_2>0$
\ENSURE  A new base $\mathbf{a}=(a_1\ a_2)^T$, $\mathbf{b}=(b_1\ b_2)^T$ and an integer $q$
\STATE \textbf{if} ($|a_1|\geq|a_2|$)
\STATE \quad $q :=\left\lfloor\frac{a_1}{b_1}\right\rfloor_o$ 
\STATE  \quad \textbf{if} ($|a_2-qb_2|\geq|b_2|\wedge sgn(a_2)=sgn(a_2-qb_2)$), $q := q+1$
\STATE \textbf{else}
\STATE \quad $q :=\left\lfloor\frac{a_2}{b_2}\right\rfloor_o$ 
\STATE  \quad \textbf{if} ($|a_1-qb_1|\geq|b_1|\wedge sgn(a_1)=sgn(a_1-qb_1)$), $q := q+1$
\STATE ($\mathbf{a},\mathbf{b}$) := ($\mathbf{b},\mathbf{a}-q\mathbf{b}$)
\STATE \textbf{return} $\mathbf{a},\mathbf{b}, q$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{\textbf{UMTrans2}($\mathbf{a},\mathbf{b}$)}\label{alg:TransNegative}
\begin{algorithmic}[1]
\REQUIRE  A basis $[\mathbf{a}\ \mathbf{b}]$ where $\mathbf{a}=(a_1\ a_2)^T$ and $\mathbf{b}=(b_1\ b_2)^T$, satisfying $a_1a_2b_1b_2\leq0$ and $(|a_1|-|a_2|)(|b_1|-|b_2|)>0$
\ENSURE  A new basis $\mathbf{a}=(a_1\ a_2)^T$, $\mathbf{b}=(b_1\ b_2)^T$ and an integer $q$
\STATE \textbf{if} ($|a_1|>|a_2|$)
\STATE \quad $q :=\left\lfloor\frac{a_1}{b_1}\right\rfloor_o$ 
\STATE \textbf{else}
\STATE \quad $q :=\left\lfloor\frac{a_2}{b_2}\right\rfloor_o$ 
\STATE ($\mathbf{a},\mathbf{b}$) := ($\mathbf{b},\mathbf{a}-q\mathbf{b}$)
\STATE \textbf{return} $\mathbf{a},\mathbf{b}, q$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{\textbf{CrossEuc}($\mathbf{a},\mathbf{b}$)}\label{alg:CrossEuc}
\begin{algorithmic}[1]
\REQUIRE  A basis $[\mathbf{a}\ \mathbf{b}]\in\mathbb{Z}^{2\times 2}$ with $\mathbf{a}=(a_1\ a_2)^T$, $\mathbf{b}=(b_1\ b_2)^T$
\ENSURE  A new basis $\mathbf{a}=(a_1\ a_2)^T$, $\mathbf{b}=(b_1\ b_2)^T$ satisfy $a_1a_2b_1b_2\leq 0 \wedge (|a_1|-|a_2|)(|b_1|-|b_2|)\leq 0$
\STATE \textbf{While} ($a_1a_2b_1b_2>0$), \textbf{do}
\STATE \quad $(\mathbf{a}, \mathbf{b})\leftarrow\textbf{UMTrans1}^\star(\mathbf{a}, \mathbf{b})$
\STATE \textbf{Endwhile}
\STATE \textbf{While} ($(|a_1|-|a_2|)(|b_1|-|b_2|)> 0$), \textbf{do}
\STATE \quad $(\mathbf{a}, \mathbf{b})\leftarrow\textbf{UMTrans2}^\star(\mathbf{a}, \mathbf{b})$
\STATE \textbf{Endwhile}
\STATE \textbf{If} (($a_1b_1=0 \wedge sgn(a_2)\ne sgn(b_2))$ or ($a_2b_2=0 \wedge sgn(a_1)\ne sng(b_1)$)), $\mathbf{b} :=-\mathbf{b}$.
\STATE  \textbf{If} $\|\mathbf{a}\|> \|\mathbf{b}\|$, Swap($\mathbf{a}, \mathbf{b}$)
\STATE  \textbf{If} $\mathbf{a} =[0,0]$, \textbf{Return}[$\mathbf{a}, \mathbf{b}$]
\STATE  \textbf{Else}
\STATE \quad \textbf{if} ($a_2b_2\leq0$)\label{crosseuc:step11}
\STATE  \quad \quad $\mathbf{b} :=\min\left\{\mathbf{b}-\left\lfloor\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rfloor \mathbf{a}, \mathbf{b}-\left\lceil\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rceil \mathbf{a}\right\}$
\STATE \quad \textbf{else}
\STATE  \quad \quad $\mathbf{b} :=\min\left\{\mathbf{b}-\left\lfloor\frac{|b_2|-|b_1|}{|a_1|+|a_2|}\right\rfloor \mathbf{a}, \mathbf{b}-\left\lceil\frac{|b_2|-|b_1|}{|a_1|+|a_2|}\right\rceil \mathbf{a}\right\}$\label{crosseuc:step14}
\STATE  \quad \textbf{Return} $[\mathbf{a}\ \mathbf{b}]$.
\end{algorithmic}
\end{algorithm}

