\begin{lemma}\label{lem:key1}
For any lattice basis  
$\mathbf{B}$ defined in equation (\ref{eq:basis}) satisfying $\|\mathbf{a}\|\ge \|\mathbf{b}\|$ and $a_1 a_2 b_1 b_2 > 0$, let \( q_i = \lfloor \frac{a_i}{b_i} \rfloor_o \) for \( i = 1,2 \).  

If \( |a_1| \geq |a_2| \), define  
\[
q := 
\begin{cases} q_1, & \text{if } q_1 \geq q_2, \\%[1em]
q_1+1, & \text{if } q_1 < q_2.
\end{cases}
\]
%\[\begin{pmatrix} a_1^\prime & b_1^\prime\\ a_2^\prime & b_2^\prime \end{pmatrix} :=  \begin{cases} \begin{pmatrix}b_1 & a_1 - q_1 b_1\\ b_2 & a_2 - q_1 b_2 \end{pmatrix}, & \text{if } q_1 \geq q_2, \\[1em] \begin{pmatrix} b_1 & a_1 - (q_1 + 1) b_1\\ b_2 & a_2 - (q_1 + 1) b_2 \end{pmatrix}, & \text{if } q_1 < q_2. \end{cases} \]

If \( |a_1| < |a_2| \), define  
\[
q := 
\begin{cases} q_2, & \text{if } q_2 \geq q_1, \\%[1em]
q_2+1, & \text{if } q_2 < q_1.
\end{cases}
\]
%\[ \begin{pmatrix} a_1^\prime & b_1^\prime\\ a_2^\prime & b_2^\prime \end{pmatrix} :=  \begin{cases}  \begin{pmatrix} b_1 & a_1 - q_2 b_1\\ b_2 & a_2 - q_2 b_2 \end{pmatrix}, & \text{if } q_2 \geq q_1, \\[1em] \begin{pmatrix} b_1 & a_1 - (q_2 + 1) b_1\\ b_2 & a_2 - (q_2 + 1) b_2 \end{pmatrix}, & \text{if } q_2 < q_1. \end{cases} \]
Then the new matrix  
\[
\mathbf{B}^\prime =[\mathbf{a}^\prime\ \mathbf{b}^\prime]=
\begin{pmatrix}
a_1^\prime & b_1^\prime\\
a_2^\prime & b_2^\prime
\end{pmatrix}:=[\mathbf{b}\ \mathbf{a}-q\mathbf{b}]=\mathbf{B}\begin{pmatrix}
0 & 1\\
1 & -q
\end{pmatrix} \in \mathbb{R}^{2 \times 2}
\]
forms a valid basis, satisfying one of the following conditions:
\begin{enumerate}
\item \( a_1^\prime a_2^\prime b_1^\prime b_2^\prime \leq 0 \), with $(\|\mathbf{a}^\prime\|=\|\mathbf{b}\|)\wedge(\|\mathbf{b}^\prime\|<\max\{\|\mathbf{a}\|\cdot\|\mathbf{b}\|,\|\mathbf{a}\|,\|\mathbf{b}\|\})$ or  
\item \( a_1^\prime a_2^\prime b_1^\prime b_2^\prime > 0 \), with $(\|\mathbf{b}^\prime\|\le \min\{\|\mathbf{a}-\mathbf{b}\|, \|\mathbf{a}+\mathbf{b}\|\}) \wedge(\|\mathbf{b}^\prime\|<\|\mathbf{a}^\prime\|) \wedge (\|\mathbf{b}^\prime\|<\frac{1}{2}\|\mathbf{a}\|)$.
% \( |b_1^\prime| < |a_1^\prime|, |b_1^\prime|<\frac{|a_1|}{2} \) and \( |b_2^\prime|<|a_2^\prime|, |b_2^\prime| < \frac{|a_2|}{2} \).  
\end{enumerate}
\end{lemma}  


\begin{proof}
Due to the property of the unimodular matrix transformation, it is evident that \(\mathbf{B}^\prime\) forms a basis. Without loss of generality, we assume \(a_1b_1 > 0\) and \(a_2b_2 > 0\), focusing on the case where \(|a_1| \geq |a_2|\); the argument for \(|a_1| < |a_2|\) follows analogously.

Let \( a_1 = q_1b_1 + r_1 \) and \( a_2 = q_2b_2 + r_2 \). Then \( \text{sgn}(r_1) = \text{sgn}(a_1) = \text{sgn}(b_1) \), \( \text{sgn}(r_2) = \text{sgn}(a_2) = \text{sgn}(b_2) \), and  $0 \leq |r_1| < |b_1|, 0 \leq |r_2| < |b_2|.$

 (1) \( q_1 > q_2.\) In this case,  
\[
\begin{pmatrix}
a_1^\prime & b_1^\prime \\
a_2^\prime & b_2^\prime
\end{pmatrix}
:=
\begin{pmatrix}
b_1 & a_1 - q_1b_1 \\
b_2 & a_2 - q_1b_2
\end{pmatrix}.
\]
Clearly, \( \text{sgn}(a_1^\prime) = \text{sgn}(b_1) = \text{sgn}(a_1 - q_1b_1) = \text{sgn}(b_1^\prime) \). Assuming \( q_1 = q_2 + k \) with \(1\le k\le q_1=\lfloor \frac{a_1}{b_1}\rfloor_o\le \frac{a_1}{b_1} \), we have  
\begin{align*}
 &0 \leq |a_2 - q_2b_2| = |r_2| < |b_2|\\
  \implies&(k-1)|b_2| < |a_2 - q_1b_2| = |r_2 - kb_2|=k|b_2|-|r_2| \le k|b_2|\le \frac{a_1}{b_1}|b_2|\le |a_1||b_2|\le\|\mathbf{a}\|\cdot\|\mathbf{b}\|\\
 \implies&\|\mathbf{b}^\prime\|=\max\{|a_1-q_1b_1|,|a_2-q_1b_2|\}=\max\{|r_1|,|r_2-kb_2|\}\le \|\mathbf{a}\|\cdot \|\mathbf{b}\|
%\left\{ \begin{array}{l} \|\mathbf{b}^\prime\|=\max\{|a_1-q_1b_1|,|a_2-q_1b_2|\}=\max\{|r_1|,|r_2-kb_2|\}\le \|\mathbf{a}\|\cdot \|\mathbf{b}\| \\ \|\mathbf{b}^\prime\|=\max\{|a_1-q_1b_1|,|a_2-q_1b_2|\}=\max\{|a_1-b_1|,|a_2b_2|\}\le \|\mathbf{a}\|\cdot \|\mathbf{b}\|  \end{array},\right.
\end{align*}
and \( \text{sgn}(a_2^\prime) = \text{sgn}(b_2) \neq \text{sgn}(a_2 - q_1b_2) = \text{sgn}(b_2^\prime) \), which implies  
$a_1^\prime a_2^\prime b_1^\prime b_2^\prime \leq 0.$

 (2) \( q_1 < q_2.\) In this case, 
\[
\begin{pmatrix}
a_1^\prime & b_1^\prime \\
a_2^\prime & b_2^\prime
\end{pmatrix}
:=
\begin{pmatrix}
b_1 & a_1 - (q_1 + 1)b_1 \\
b_2 & a_2 - (q_1 + 1)b_2
\end{pmatrix}.
\]
Clearly,  
$
|b_1^\prime| = |a_1 - (q_1 + 1)b_1| = |r_1 - b_1| \leq |b_1| = |a_1^\prime|,
$
and \( \text{sgn}(a_1^\prime) = \text{sgn}(b_1) \neq \text{sgn}(a_1 - (q_1 + 1)b_1) = \text{sgn}(b_1^\prime) \).  
Assuming \( q_2 = q_1 + k \) with \( k \geq 1 \),  we have
\begin{align*}
&|a_2 - (q_1 + 1)b_2| = |a_2 - (q_2 - k + 1)b_2| = |r_2 + (k - 1)b_2| < k|b_2|<q_2|b_2| < |a_2|\le \|\mathbf{a}\|\\
\implies &\|\mathbf{b}^\prime\|=\max\{|b_1^\prime|,|b_2^\prime|\}=\max\{|r_1-b_1|,|r_2+(k-1)b_2|\}\le \max\{|b_1|, |a_2|\}\le \max\{\|\mathbf{a}\|,\|\mathbf{b}\|\},
\end{align*}
and \( \text{sgn}(a_2^\prime) = \text{sgn}(b_2) = \text{sgn}(a_2 - (q_1 + 1)b_2) = \text{sgn}(b_2^\prime) \), leading to  
$a_1^\prime a_2^\prime b_1^\prime b_2^\prime \leq 0.$

 (3)  \( q_1 = q_2.\) In this case, 
\[
\begin{pmatrix}
a_1^\prime & b_1^\prime \\
a_2^\prime & b_2^\prime
\end{pmatrix}
:=
\begin{pmatrix}
b_1 & a_1 - q_1b_1 \\
b_2 & a_2 - q_1b_2
\end{pmatrix}
=
\begin{pmatrix}
b_1 & r_1 \\
b_2 & r_2
\end{pmatrix}.
\]
If \( r_1 = 0 \) or \( r_2 = 0 \), then \( a_1^\prime a_2^\prime b_1^\prime b_2^\prime \leq 0 \) and $\max\{|a_1^\prime|, |a_2^\prime|, |b_1^\prime|, |b_2^\prime|\}=\max\{|b_1|,|b_2|\}$. Otherwise,  $a_1^\prime a_2^\prime b_1^\prime b_2^\prime>0$ and
\begin{align*}
&\left.\begin{array}{c}
    (|b_1^\prime| = |r_1|=|a_1-q_1b_1|\le \min\{|a_1-b_1|,|a_1+b_1|\}) \wedge (|b_1^\prime |=|r_1|< |b_1|=|a_1^\prime|)\wedge  (|b_1^\prime| =|r_1|< \frac{|a_1|}{2}),\\
   (|b_2^\prime| = |r_2|=|a_2-q_2b_2|\le \min\{|a_2-b_2|,|a_2+b_2|\})\wedge (|b_2^\prime |=|r_2|< |b_2|=|a_2^\prime|)\wedge (|b_2^\prime| = |r_2|< \frac{|a_2|}{2}).  
\end{array}\right\}\\
&\implies(\|\mathbf{b}^\prime\|\le \min\{\|\mathbf{a}-\mathbf{b}\|, \|\mathbf{a}+\mathbf{b}\|\}) \wedge(\|\mathbf{b}^\prime\|<\|\mathbf{a}^\prime\|) \wedge (\|\mathbf{b}^\prime\|<\frac{1}{2}\|\mathbf{a}\|).
\end{align*}
\end{proof}


\begin{lemma}\label{lem:key2}
Let $\mathbf{B}$ be a lattice basis as defined in equation (\ref{eq:basis}) satisfying $\|\mathbf{a}\|\ge \|\mathbf{b}\|$, $a_1a_2b_1 b_2\le 0$ and $(\left | a_{1}  \right | - \left | a_{2}  \right |)(\left | b_{1}  \right |-\left | b_{2}  \right |) > 0$.  

If \(|a_1|>|a_2| \), define  \( q_1 = \lfloor \frac{a_1}{b_1} \rfloor_o \) and
\[
\mathbf{B}^\prime=[\mathbf{a}^\prime\ \mathbf{b}^\prime]=\begin{pmatrix}
a_1^\prime & b_1^\prime\\
a_2^\prime & b_2^\prime
\end{pmatrix} := 
\begin{pmatrix}
b_1 & a_1 - q_1 b_1\\
b_2 & a_2 - q_1 b_2
\end{pmatrix}=[\mathbf{b}\ \mathbf{a}-q_1\mathbf{b}]=\mathbf{B}\begin{pmatrix}0 & 1\\ 1 & -q_1\end{pmatrix}
\]

If \( |a_1| < |a_2| \), define  \( q_2 = \lfloor \frac{a_2}{b_2} \rfloor_o \) and
\[
\mathbf{B}^\prime=[\mathbf{a}^\prime\ \mathbf{b}^\prime]=\begin{pmatrix}
a_1^\prime & b_1^\prime\\
a_2^\prime & b_2^\prime
\end{pmatrix} := 
\begin{pmatrix}
b_1 & a_1 - q_2 b_1\\
b_2 & a_2 - q_2 b_2
\end{pmatrix}=[\mathbf{b}\ \mathbf{a}-q_2\mathbf{b}]=\mathbf{B}\begin{pmatrix}0 & 1\\1 & -q_2\end{pmatrix}
\]
Then the new matrix  $\mathbf{B}^\prime$ forms a valid basis, satisfying one of the following conditions:
\begin{enumerate}
\item \(\mathbf{B}^\prime\) is reduced, or  
\item \( a_1^\prime a_2^\prime b_1^\prime b_2^\prime \le 0 \), with \((\|\mathbf{b}^\prime\|\le \min\{\|\mathbf{a}-\mathbf{b}\|, \|\mathbf{a}+\mathbf{b}\|\}) \wedge(\|\mathbf{b}^\prime\|<\|\mathbf{a}^\prime\|) \wedge (\|\mathbf{b}^\prime\|<\frac{1}{2}\|\mathbf{a}\|)\wedge(||b_1^\prime|-|b_2^\prime|| < \frac{||a_1|-|a_2||}{2}) \).  
\end{enumerate}
\end{lemma} 
\begin{proof}
Clearly, \(\mathbf{B}^\prime\) forms a basis as a direct consequence of the properties of unimodular matrix transformations. Without loss of generality, we focus on the case where \(|a_1|> |a_2|\); the argument for \(|a_1| < |a_2|\) follows analogously.

In case that $|a_1|>|a_2|$, since $a_1a_2b_1b_2\le 0$ and $(|a_1|-|a_2|)(|b_1|-|b_2|)>0$, we have $|a_1|>|a_2|\ge 0$, $|b_1|>|b_2|\ge 0$ and, without loss of generality, we assume $a_1b_1>0$ and $a_2b_2\le 0$. Let \( a_1 = q_1b_1 + r_1 \). Then $q_1>0$, \( \text{sgn}(r_1) = \text{sgn}(a_1) = \text{sgn}(b_1) \), and  
\[
0 \leq |r_1| < |b_1| \implies 0 \leq |r_1| <\frac{|a_1|}{2}.
\]
Additionally, \( \text{sgn}(a_1^\prime) = \text{sgn}(b_1) = \text{sgn}(a_1 - q_1b_1) = \text{sgn}(b_1^\prime) \) and \( \text{sgn}(a_2^\prime) = \text{sgn}(b_2) \neq \text{sgn}(a_2 - q_1b_2) = \text{sgn}(b_2^\prime) \), which implies  $a_1^\prime a_2^\prime b_1^\prime b_2^\prime \leq 0.$
Furthermore,  if $|b_1^\prime|-|b_2^\prime|\le 0$, then $(|a_1^\prime|-|a_2^\prime|)(|b_1^\prime|-|b_2^\prime|)\le 0$ and thus $\mathbf{B}^\prime$ is reduced. Otherwise, $|b_2^\prime|<|b_1^\prime|=|r_1|$, which implies 
\begin{align*}
&\|\mathbf{b}^\prime\|=\max\{|b_1^\prime|, |b_2^\prime|\}=|b_1^\prime|=|r_1|=|a_1-q_1b_1|\le \min\{|a_1-b_1|,|a_1+b_1|\}\le \min\{\|\mathbf{a}-\mathbf{b}\|, \|\mathbf{a}+\mathbf{b}\|\},\\
 &\|\mathbf{b}^\prime\|=\max\{|b_1^\prime|, |b_2^\prime|\}=|b_1^\prime|=|r_1|<|b_1|\le \max\{|b_1|,|b_2|\}=\|\mathbf{b}\|=\|\mathbf{a}^\prime\|,\\
 &\|\mathbf{b}^\prime\|=\max\{|b_1^\prime|, |b_2^\prime|\}=|b_1^\prime|=|r_1|<\frac{|a_1|}{2}=\frac{1}{2}\max\{|a_1|,|a_2|\}=\frac{1}{2}\|\mathbf{a}\|,\\
&|b_1^\prime|-|b_2^\prime|=|r_1|-|a_2-q_1b_2|=|r_1|-(|a_2|+q_1|b_2|)\le|r_1|-|a_2|<\frac{|a_1|-|a_2|}{2}.
\end{align*}    
\end{proof}

Based on \textbf{Lemma \ref{lem:key1}} and \textbf{Lemma \ref{lem:key2}}, we can establish the correctness and complexity of \textbf{Algorithm \ref{alg:CrossEuc}}. Specifically, the following theorem holds

\begin{theorem}\label{thm:Par-Euc}
  Given a lattice basis $\mathbf{B}=[\mathbf{a}\ \mathbf{b}]\in\mathbb{Z}^{2\times 2}$ with $\mathbf{a}=(a_1\ a_2)^T$, $\mathbf{b}=(b_1\ b_2)^T$, and $\#(\mathbf{a},\mathbf{b})=n$, \textbf{Algorithm \ref{alg:CrossEuc}}  outputs a basis $\mathbf{B}^\prime=[\mathbf{a}^\prime\ \mathbf{b}^\prime]$ satisfying $\|\mathbf{a}^\prime\|=\lambda_1(L(\mathbf{B}))$ and $\|\mathbf{b}^\prime\|=\lambda_2(L(\mathbf{B}))$ with a time complexity of $O(n^2)$.  
\end{theorem}


\begin{proof}
If the input lattice basis satisfies $a_1a_2b_1b_2>0$, we assume that the reduced lattice basis sequence in the first \textbf{While} loop of \textbf{Algorithm \ref{alg:CrossEuc}} is as follows:
\begin{align} 
\mathbf{B}^{(0)}=[\mathbf{a}^{(0)}\ \mathbf{b}^{(0)}]=\begin{pmatrix}
a_{1}^{(0)} & b_{1}^{(0)}\\
a_{2}^{(0)} & b_{2}^{(0)}
\end{pmatrix}=
\begin{pmatrix}
a_{1} & b_{1}\\
a_{2} & b_{2}
\end{pmatrix}\to \mathbf{B}^{(1)}=[\mathbf{a}^{(1)}\ \mathbf{b}^{(1)}]=\begin{pmatrix}
a_{1}^{(1)} & b_{1}^{(1)}\\
a_{2}^{(1)} & b_{2}^{(1)}
\end{pmatrix}\to \cdots\nonumber\\
\to
\mathbf{B}^{(k-1)}=[\mathbf{a}^{(k-1)}\ \mathbf{b}^{(k-1)}]=\begin{pmatrix}
a_{1}^{(k-1)} & b_{1}^{(k-1)}\\
a_{2}^{(k-1)} & b_{2}^{(k-1)}
\end{pmatrix}\to
\mathbf{B}^{(k)}=[\mathbf{a}^{(k)}\ \mathbf{b}^{(k)}]=\begin{pmatrix}
a_{1}^{(k)} & b_{1}^{(k)}\\
a_{2}^{(k)} & b_{2}^{(k)}
\end{pmatrix},\label{eq:latticeseq1}
\end{align}
where $\mathbf{a}^{(i)}=\mathbf{b}^{(i-1)}$ for $i=1,\cdots,k$, and, with loss of generality, we assume $k$ is even.
By \textbf{Lemma \ref{lem:key1}},  we have $a_1^{(k)}a_2^{(k)}b_1^{(k)}b_2^{(k)}\le 0$ and
\begin{align*}
&\|\mathbf{a}^{(k)}\|=\|\mathbf{b}^{(k-1)}\|<\frac{1}{2}\|\mathbf{a}^{(k-2)}\|<\cdots<\frac{1}{2^{k/2}}\|\mathbf{a}\|,\\
&\|\mathbf{a}^{(k-1)}\|<\frac{1}{2}\|\mathbf{a}^{(k-3)}\|<\cdots<\frac{1}{2^{(k-2)/2}}\|\mathbf{a}^{(1)}\|=\frac{1}{2^{(k-2)/2}}\|\mathbf{b}\|\\
  % & a_1^{(k)}=b_1^{(k-1)}<\frac{|a_1^{(k-2)}|}{2}<\frac{|a_1^{(k-4)}|}{2^2}<\cdots<\frac{|a_1^{(0)}|}{2^{k/2}}=\frac{|a_1|}{2^{k/2}},\\
  % & a_2^{(k)}=b_2^{(k-1)}<\frac{|a_2^{(k-2)}|}{2}<\frac{|a_2^{(k-4)}|}{2^2}<\cdots<\frac{|a_2^{(0)}|}{2^{k/2}}=\frac{|a_2|}{2^{k/2}},\\
  %  &a_1^{(k-1)}=b_1^{(k-2)}<\frac{|a_1^{(k-3)}|}{2}<\frac{|a_1^{(k-5)}|}{2^2}<\cdots<\frac{|a_1^{(1)}|}{2^{k/2}}=\frac{|b_1|}{2^{(k-2)/2}},\\
   % &a_2^{(k-1)}=b_2^{(k-2)}<\frac{|a_2^{(k-2)}|}{2}<\frac{|a_2^{(k-4)}|}{2^2}<\cdots<\frac{|a_2^{(1)}|}{2^{k/2}}=\frac{|b_2|}{2^{(k-2)/2}},
%\end{align*} and \begin{align*}
&\|\mathbf{b}^{(k)}\|<\|\mathbf{a}^{(k-1)}\|\cdot\|\mathbf{b}^{(k-1)}\|<\frac{1}{2^{k/2}}\|\mathbf{a}\|\cdot \frac{1}{2^{(k-2)/2}}\|\mathbf{b}\|=\frac{1}{2^{k-1}}\|\mathbf{a}\|\cdot \|\mathbf{b}\|.
\end{align*}
Since $1\le \min\{\|\mathbf{a}^{(k)}\|,\|\mathbf{b}^{(k)}\|\}<\frac{1}{2^{k-1}}|\mathbf{a}\|\cdot \|\mathbf{b}\|$, it follows that $k<\log \|\mathbf{a}\|+\log \|\mathbf{b}\|+1$ is finite.

Further, if $(|a_1^{(k)}|-|a_2^{(k)}|)(|b_1^{(k)}|-|b_2^{(k)}|)>0$, then during the second \textbf{While} loop, we assume the reduced lattice basis sequence is 
\begin{align}\label{eq:latticeseq2}
\mathbf{B}^{(k)}=[\mathbf{a}^{(k)}\ \mathbf{b}^{(k)}]=\begin{pmatrix}
a_{1}^{(k)} & b_{1}^{(k)}\\
a_{2}^{(k)} & b_{2}^{(k)}
\end{pmatrix}\to \mathbf{B}^{(k+1)}=[\mathbf{a}^{(k+1)}\ \mathbf{b}^{(k+1)}]=\begin{pmatrix}
a_{1}^{(k+1)} & b_{1}^{(k+1)}\\
a_{2}^{(k+1)} & b_{2}^{(k+1)}
\end{pmatrix}\to \cdots\nonumber\\ \to
\mathbf{B}^{(k+s-1)}=[\mathbf{a}^{(k+s-1)}\ \mathbf{b}^{(k+s-1)}]=\begin{pmatrix}
a_{1}^{(k+s-1)} & b_{1}^{(k+s-1)}\\
a_{2}^{(k+s-1)} & b_{2}^{(k+s-1)}
\end{pmatrix}\to
\mathbf{B}^{(k+s)}=[\mathbf{a}^{(k+s)}\ \mathbf{b}^{(k+s)}]=\begin{pmatrix}
a_{1}^{(k+s)} & b_{1}^{(k+s)}\\
a_{2}^{(k+s)} & b_{2}^{(k+s)}
\end{pmatrix},
\end{align} where $\mathbf{a}^{(k+i)}=\mathbf{b}^{(k+i-1)}$ for $i=1,\cdots,s$, and, without loss of generality, we assume $s$ is even. Then, by \textbf{Lemma \ref{lem:key2}},  we have $a_1^{(k+i)}a_2^{(k+i)}b_1^{(k+i)}b_2^{(k+i)}\le 0$ for $i=0,\cdots,s$,
\begin{align*}
  1\le|a_1^{(k+s)}|-|a_2^{(k+s)}|= |b_1^{(k+(s-1))}|-|b_2^{(k+(s-1))}| <\frac{|a_1^{(k+(s-2))}|-|a_2^{(k+(s-2))}|}{2}<
   \cdots<\frac{|a_1^{(k)}|-|a_2^{(k)}|}{2^{s/2}},
\end{align*}
and $|b_1^{(k+s)}|-|b_2^{(k+s)}|\le 0.$
Consequently, after the second \textbf{While} loop, we have 
 \begin{align*}
 a_1^{(k+s)}a_2^{(k+s)}b_1^{(k+s)}b_2^{(k+s)}\le 0 \wedge (|a_1^{(k+s)}|-|a_2^{(k+s)}|)(|b_1^{(k+s)}|-|b_2^{(k+s)}|)\le 0,
\end{align*}
and thus, the lattice basis $\mathbf{B}^{(k+s)}=[\mathbf{a}^{(k+s)}\ \mathbf{b}^{(k+s)}]$ is reduced.
%\begin{align*}\mathbf{B}^{(k+s)}=\begin{pmatrix}a_{1}^{(k+s)} & b_{1}^{(k+s)}\\a_{2}^{(k+s)} & b_{2}^{(k+s)} \end{pmatrix}\end{align*}
Finally, by \textbf{Theorem \ref{thm:Eucred}}, the returned basis $\mathbf{B}^\prime=[\mathbf{a}^\prime\ \mathbf{b}^\prime]$ of \textbf{Algorithm \ref{alg:CrossEuc}} satisfies $\|\mathbf{a}^\prime\|=\lambda_1(L(\mathbf{B}))$ and $\|\mathbf{b}^\prime\|=\lambda_2(L(\mathbf{B}))$

Now, we estimate the time complexity. Without loss of generality, we assume $\|\mathbf{a}^{(0)}\|\ge \|\mathbf{b}^{(0)}\|$, $\#\mathbf{a}^{(i)}=n_{i}$ and $\#q^{(i)}=\ell_{i}$ for $i=1,\cdots,k,k+1,\cdots, k+s$.  For the first \textbf{While} loop,  since $\mathbf{a}^{(i-1)}=q^{(i)}\mathbf{b}^{(i-1)}+\mathbf{b}^{(i)}=q^{(i)}\mathbf{a}^{(i)}+\mathbf{a}^{(i+1)}$, where 
\begin{align}\label{eq:q}
 q^{(i)}\in\left\{\left\lfloor\frac{a_1^{(i-1)}}{b_1^{(i-1)}}\right\rfloor_0=\left\lfloor\frac{a_1^{(i-1)}}{a_1^{(i)}}\right\rfloor_0, \left\lfloor\frac{a_1^{(i-1)}}{b_1^{(i-1)}}\right\rfloor_0+1=\left\lfloor\frac{a_1^{(i-1)}}{a_1^{(i)}}\right\rfloor_0+1,\right.\nonumber\\
 \left.\left\lfloor\frac{a_2^{(i-1)}}{b_2^{(i-1)}}\right\rfloor_0=\left\lfloor\frac{a_2^{(i-1)}}{a_2^{(i)}}\right\rfloor_0, \left\lfloor\frac{a_2^{(i-1)}}{b_2^{(i-1)}}\right\rfloor_0+1=\left\lfloor\frac{a_2^{(i-1)}}{a_2^{(i)}}\right\rfloor_0+1\right\},
\end{align} we have $n_{i-1}=n_i+\ell_i$. Therefore, in each loop, the time complexity of division is bounded by $O(n_{i-1}\ell_i)$ and the time complexity of multiplication is bounded by $O(n_i\ell_i)$. Consequently, the total complexity of the first \textbf{While} loop is $T_1=O(\sum_{i = 1}^{k}(n_{i-1}\ell_i+n_i\ell_i))=O(\sum_{i=1}^k (n_i+n_{i-1})(n_{i-1}-n_i))=O(\sum_{i=1}^k (n_{i-1}^2-n_i^2))=O(n_0^2-n_k^2)$. Similarly, for the second \textbf{While} loop, the total complexity is $T_2=O(\sum_{i=k+1}^{k+s}(n_{i-1}\ell_i+n_i\ell_i))=O(\sum_{i=k+1}^{k+s} (n_i+n_{i-1})(n_{i-1}-n_i))=O(\sum_{i=k+1}^{k+s} (n_{i-1}^2-n_i^2))=O(n_k^2-n_{k+s}^2)$.
 Therefore, the total complexity of  \textbf{Algorithm \ref{alg:CrossEuc}} is $T=O(T_1+T_2)=O(n_0^2)=O(n^2)$.
\end{proof}

\begin{remark}
According to the property established in \textbf{Theorem \ref{thm:l2}}, the $\ell_2$-shortest basis $[\mathbf{u}\ \mathbf{v}]$ can be obtained via a minor modification of \textbf{Algorithm \ref{alg:CrossEuc}}. Specifically, by replacing Steps \ref{crosseuc:step11}–\ref{crosseuc:step14} with the following:
$$
\mathbf{u} = \arg\min\left\{\|\mathbf{a}\|_2,\ \|\mathbf{b}\|_2,\ \|\mathbf{a} + \mathbf{b}\|_2,\ \|\mathbf{a} - \mathbf{b}\|_2\right\}, 
$$
and setting
$$
\mathbf{v} = \mathbf{x} - q\mathbf{u}, \quad \text{where } \mathbf{x} \in \{\mathbf{a}, \mathbf{b}\} \setminus \{\mathbf{u}\} \text{ and } q = \left\lceil \frac{\langle \mathbf{x}, \mathbf{u} \rangle}{\langle \mathbf{u}, \mathbf{u} \rangle} \right\rfloor.
$$
This substitution yields a basis satisfying the $\ell_2$-shortest condition. The same remark is also applicable to the upcoming \textbf{Algorithm \ref{alg:HGCD-Par-Euc2}} (\textbf{HVecSBP}).
\end{remark}




\section{Optimized algorithm and its analysis}
%首先借鉴两个整数的Half-gcd算法\cite{??},给出两个向量版本的Half-SVP，
For two integers with bit lengths of \( n \), the well-known Half-GCD algorithm \cite{moller2006robust,moller2008schonhage} can efficiently find two integers of approximately \( n/2 \)-bit length that share the same common divisor.  %(up to a unimodular transformation). 
Inspired by the Half-GCD algorithm, this section first explores the \textbf{HVec} algorithm, which rapidly reduces a lattice basis to a new basis with bit lengths approximately halved from the original, along with a complexity analysis. Furthermore, we leverage this algorithm to optimize and accelerate the \textbf{CrossEuc} algorithm presented in the previous section.


\subsection{\textbf{HVec} algorithm and its analysis}


Analogous to the case of two integers, our design for the input of two vectors is based on the following key observation:

Assume $[\mathbf{a}^\prime\ \mathbf{b}^\prime]$ and $[\mathbf{c}^\prime\ \mathbf{d}^\prime]$ are two different bases for the same lattice, \emph{i.e.},
\begin{align}\label{eq:keyobser1}
[\mathbf{a}^\prime\ \mathbf{b}^\prime]=\begin{pmatrix}
a_{1}^\prime & b_{1}^\prime\\
a_{2}^\prime & b_{2}^\prime 
\end{pmatrix}=\begin{pmatrix}
c_{1}^\prime & d_{1}^\prime\\
c_{2}^\prime & d_{2}^\prime 
\end{pmatrix}\mathbf{M}^\prime=[\mathbf{c}^\prime\ \mathbf{d}^\prime] \mathbf{M}^\prime
\end{align}
for some unimodular matrix \(\mathbf{M}^\prime \). The two new vectors 
\begin{align}\label{eq:keyobser2}
[\mathbf{a}\ \mathbf{b}]=\begin{pmatrix}
a_1 & b_1\\
a_2 & b_2 
\end{pmatrix}=2^{n_\ell}\begin{pmatrix}
a_{1}^\prime & b_{1}^\prime\\
a_{2}^\prime & b_{2}^\prime 
\end{pmatrix}+\begin{pmatrix}
a_{1}^{\prime\prime} & b_{1}^{\prime\prime}\\
a_{2}^{\prime\prime} & b_{2}^{\prime\prime} 
\end{pmatrix}= 2^{n_\ell}[\mathbf{a}^\prime\ \mathbf{b}^\prime]+[\mathbf{a}^{\prime\prime}\ \mathbf{b}^{\prime\prime}],
\end{align}
where \( [\mathbf{a}^{\prime\prime}\ \mathbf{b}^{\prime\prime}] \) represents the \( n_\ell \) least significant bits, and \( [\mathbf{a}^\prime\ \mathbf{b}^\prime] \) refers to the \( n_h = \#(\mathbf{a},\mathbf{b}) - n_\ell \) most significant bits of \( [\mathbf{a}\ \mathbf{b}] \).
Additionally, the vectors \( [\mathbf{c}\ \mathbf{d}] \) satisfy
\begin{align}
  [\mathbf{a}\ \mathbf{b}]=
\begin{pmatrix}
a_1 & b_1\\
a_2 & b_2 
\end{pmatrix}=\begin{pmatrix}
c_{1} & d_{1}\\
c_{2} & d_{2} 
\end{pmatrix}\mathbf{M}^\prime=[\mathbf{c}\ \mathbf{d}]\mathbf{M}^\prime   
\end{align}
for the same unimodular matrix \( \mathbf{M}^\prime \). Then, we have
\begin{align}\label{eq:keyobser3}
 [\mathbf{c}\ \mathbf{d}]=[\mathbf{a}\ \mathbf{b}](\mathbf{M}^\prime)^{-1}=2^{n_\ell}[\mathbf{c}^\prime\ \mathbf{d}^\prime]+[\mathbf{a}^{\prime\prime}\ \mathbf{b}^{\prime\prime}](\mathbf{M}^\prime)^{-1} 
\end{align}

Building on the above fact, we can halve the bit-length of \( [\mathbf{a}\ \mathbf{b}] \) by adopting a recursive reduction strategy. \textbf{Algorithm \ref{alg:HVec}} provides the details of our design. We now provide a rigorous theoretical analysis to establish the correctness and complexity of \textbf{Algorithm \ref{alg:HVec}}. That is, we argue the following result:

\begin{algorithm}
%\begin{center}
\caption{\textbf{HVec}($\mathbf{a}\ \mathbf{b}$)} \label{alg:HVec}
%\def\temptablewidth{0.5\textwidth}
\begin{algorithmic}[1]
\REQUIRE  Two vectors $\mathbf{a}=(a_1,a_2)^{T}, \mathbf{b}=(b_1,b_2)^{T}$ and $\#(\mathbf{a},\mathbf{b})=n,\underline{\#}(\mathbf{a},\mathbf{b})>\left\lfloor\frac{n}{2}\right\rfloor+1, \underline{\#}(\mathbf{a}+\mathbf{b},\mathbf{a}-\mathbf{b})>\lfloor\frac{n}{2}\rfloor+1$
\ENSURE  Two vectors $\mathbf{c}=(c_1,c_2)^{T},\mathbf{d}=(d_1,d_2)^{T}$ and an unimodular matrix $\mathbf{M}$ such that $[\mathbf{a}\ \mathbf{b}]=[\mathbf{c}\ \mathbf{d}]\mathbf{M}$. Meanwhile, either $(\#(\mathbf{c},\mathbf{d})\le n) \wedge (\underline{\#}(\mathbf{c},\mathbf{d})> \lfloor\frac{n}{2}\rfloor+1) \wedge (\underline{\#}(\mathbf{c}+\mathbf{d},\mathbf{c}-\mathbf{d})\leq\lfloor\frac{n}{2}\rfloor+1)$,   or $[\mathbf{c}\ \mathbf{d}]$ is reduced.
\STATE  $\mathbf{c}:=\mathbf{a},\mathbf{d}:=\mathbf{b}$, $\mathbf{M}:=\mathbf{I}$
\IF{$c_1c_2d_1d_2\leq0 \wedge (|c_1|-|c_2|)(|d_1|-|d_2|)\leq 0$}
\RETURN $\mathbf{c},\mathbf{d},\mathbf{M}$
\ENDIF
\STATE $n:=\#(\mathbf{c},\mathbf{d})$
\STATE $s:=\lfloor\frac{n}{2}\rfloor+1$
\STATE  \textbf{if} $\underline{\#}(\mathbf{c},\mathbf{d})\geq \lfloor\frac{3}{4}n\rfloor+2$, \textbf{then} \label{Hvec:stepif1start}
\STATE \quad $n_{\ell 1}:=\lfloor n/2\rfloor$
\STATE \quad $a_{1}^\prime:=\lfloor c_1/2^{n_{\ell 1}}\rfloor $, $a_{1}^{\prime\prime}:=c_1-2^{n_{\ell 1}}a_{1}^\prime$, $a_{2}^\prime:=\lfloor c_2/2^{n_{\ell 1}}\rfloor$, $a_{2}^{\prime\prime}:=c_2-2^{n_{\ell 1}}a_{2}^\prime$
\STATE \quad $b_{1}^\prime:=\lfloor d_1/2^{n_{\ell 1}}\rfloor $, $b_{1}^{\prime\prime}:=d_1-2^{n_{\ell 1}}b_{1}^\prime$, $b_{2}^\prime:=\lfloor d_2/2^{n_{\ell 1}}\rfloor$, $b_{2}^{\prime\prime}:=d_2-2^{n_{\ell 1}}b_{2}^{\prime}$
\STATE \quad $\mathbf{a}^{\prime}:=(a_{1}^\prime,a_{2}^\prime)^{T},\mathbf{b}^\prime :=(b_{1}^\prime,b_{2}^\prime)^{T}$, $\mathbf{a}^{\prime\prime}:=(a_{1}^{\prime\prime},a_{2}^{\prime\prime})^{T},\mathbf{b}^{\prime\prime} :=(b_{1}^{\prime\prime},b_{2}^{\prime\prime})^{T}$
%\STATE \quad $\mathbf{M_1}:= \mathbf{I}$
\STATE \quad $(\mathbf{c}^\prime,\mathbf{d}^\prime,\mathbf{M}_1^\prime)\leftarrow \textbf{HVec}(\mathbf{a}^\prime, \mathbf{b}^\prime)$
\STATE \quad $[\mathbf{c}\ \mathbf{d}]:= 2^{n_{\ell 1}}[\mathbf{c}^\prime\  \mathbf{d}^\prime]+[\mathbf{a}^{\prime\prime}\ \mathbf{b}^{\prime\prime}](\mathbf{M}_1^\prime)^{-1}$\label{Hvec:stepcd1}
\STATE \quad $\mathbf{M}:=\mathbf{M}_1^\prime\mathbf{M}$
\STATE \textbf{end if}\label{Hvec:stepif1end}
\STATE \textbf{while}    $\#(\mathbf{c},\mathbf{d})>\lfloor 3n/4\rfloor+1$ and $\underline{\#}(\mathbf{c}-\mathbf{d},\mathbf{c}+\mathbf{d})>s$ \label{hvec:stepwhile1} \textbf{do}
\STATE \quad \textbf{if} ($c_1c_2d_1d_2\leq0 \wedge (|c_1|-|c_2|)(|d_1|-|d_2|)\leq 0$), \textbf{return} $\mathbf{c},\mathbf{d},\mathbf{M}$
\STATE \quad \textbf{if} ($c_1c_2d_1d_2>0$),
\STATE \qquad $(\mathbf{c}, \mathbf{d}, q)\leftarrow \textbf{UMTrans1}(\mathbf{c},\mathbf{d})$ 
\STATE \quad \textbf{else}
\STATE \qquad $(\mathbf{c}, \mathbf{d}, q)\leftarrow \textbf{UMTrans2}(\mathbf{c},\mathbf{d})$ 
\STATE \quad \textbf{if} ($\#\mathbf{d}\leq s$), $q := q-1, \mathbf{d} := \mathbf{c}+\mathbf{d}$\label{hvec:stephalf1}
\STATE \quad $\mathbf{M} := \begin{pmatrix}q&1\\ 1&0\end{pmatrix}\mathbf{M}$
\STATE \textbf{end while}
%\STATE \textbf{if} $\underline{\#}(c_1,d_1)>s+2$ or $\underline{\#}(c_2,d_2)>s+2$, \textbf{then}
\STATE \textbf{if} $\underline{\#}(\mathbf{c},\mathbf{d})>s+2$, \textbf{then}\label{Hvec:stepif2start}
\STATE \quad  $n^\prime:=\#(\mathbf{c},\mathbf{d})$, $n_{\ell 2}:=2s-n^\prime+1$
\STATE \quad $a_{1}^\prime:=\lfloor c_1/2^{n_{\ell 2}}\rfloor$, $a_{1}^{\prime\prime}:=c_1-2^{n_{\ell 2}}a_{1}^\prime$, $a_{2}^\prime:=\lfloor c_2/2^{n_{\ell 2}}\rfloor$, $a_{2}^{\prime\prime}:=c_2-2^{n_{\ell 2}}a_{2}^\prime$
\STATE \quad $b_{1}^\prime:=\lfloor d_1/2^{n_{\ell 2}}\rfloor $, $b_{1}^{\prime\prime}:=d_1-2^{n_{\ell 2}}b_{1}^\prime$, $b_{2}^\prime:=\lfloor d_2/2^{n_{\ell 2}}\rfloor$, $b_{2}^{\prime\prime}:=d_2-2^{n_{\ell 2}}b_{2}^\prime$
\STATE \quad $\mathbf{a}^\prime :=(a_{1}^\prime,a_{2}^\prime)^{T},\mathbf{b}^\prime :=(b_{1}^\prime,b_{2}^\prime)^{T}$, $\mathbf{a}^{\prime\prime}:=(a_{1}^{\prime\prime},a_{2}^{\prime\prime})^{T},\mathbf{b}^{\prime\prime} :=(b_{1}^{\prime\prime},b_{2}^{\prime\prime})^{T}$
\STATE \quad $(\mathbf{c}^\prime,\mathbf{d}^\prime,\mathbf{M}_2^\prime)\leftarrow \textbf{HVec}(\mathbf{a}^\prime, \mathbf{b}^\prime)$
\STATE \quad $[\mathbf{c}\ \mathbf{d}]:= 2^{n_{\ell 2}}[\mathbf{c}^\prime\  \mathbf{d}^\prime]+[\mathbf{a}^{\prime\prime}\ \mathbf{b}^{\prime\prime}] (\mathbf{M}_2^\prime)^{-1}$
\STATE \quad $\mathbf{M}:=\mathbf{M}_2^\prime\mathbf{M}$
\STATE \textbf{end if}\label{Hvec:stepif2end}
\STATE \textbf{while}   $\underline{\#}(\mathbf{c}-\mathbf{d}, \mathbf{c}+\mathbf{d})>s$ \textbf{do}\label{hvec:stepwhile2}
\STATE \quad \textbf{if} ($c_1c_2d_1d_2\leq0 \wedge (|c_1|-|c_2|)(|d_1|-|d_2|)\leq 0$), \textbf{return} $\mathbf{a},\mathbf{b},\mathbf{M}$
\STATE \quad \textbf{if} ($c_1c_2d_1d_2>0$),
\STATE \qquad $(\mathbf{c}, \mathbf{d}, q)\leftarrow \textbf{UMTrans1}(\mathbf{c},\mathbf{d})$ 
\STATE \quad \textbf{else}
\STATE \qquad $(\mathbf{c}, \mathbf{d}, q)\leftarrow \textbf{UMTrans2}(\mathbf{c},\mathbf{d})$ 
\STATE \quad \textbf{if} ($\#\mathbf{d}\leq s$), $q := q-1, \mathbf{d} := \mathbf{c}+\mathbf{d}$\label{hvec:stephalf2}
\STATE \quad $\mathbf{M} := \begin{pmatrix}q&1\\ 1&0\end{pmatrix}\mathbf{M}$
\STATE \textbf{end while}
\STATE \textbf{return} $\mathbf{c},\mathbf{d},\mathbf{M}$\\
\end{algorithmic}
\end{algorithm}



\begin{theorem} \label{thm:HVec}
For any input basis $\mathbf{B}=[\mathbf{a}\ \mathbf{b}]%=\begin{pmatrix}a_1 & b_1\\a_2 & b_2 \end{pmatrix}
\in\mathbb{Z}^{2\times 2}$ with $\#(\mathbf{a},\mathbf{b})=n$, \textbf{Algorithm \ref{alg:HVec}} will output a new basis $\mathbf{B}^\prime=[\mathbf{c}\ \mathbf{d}]%=\begin{pmatrix}c_1 & d_1\\c_2 & d_2\end{pmatrix}
$ 
and an unimodular matrix $\mathbf{M}$ such that $[\mathbf{a}\ \mathbf{b}]=[\mathbf{c}\ \mathbf{d}]\mathbf{M}$ in time $T(n)=O\left(M(n)\log n\right)$, 
where $M(n)$ refers to the time complexity of multiplying two  $n$-bit integers. Additionally, the basis $[\mathbf{c}\ \mathbf{d}]$ satisfies one of the following two conditions:
\begin{enumerate}
  \item $[\mathbf{c},\mathbf{d}]$ is reduced, or
  \item $\underline{\#}(\mathbf{c},\mathbf{d})> \lfloor\frac{n}{2}\rfloor+1$, and $\underline{\#}(\mathbf{c}-\mathbf{d}, \mathbf{c}+\mathbf{d})\leq \lfloor\frac{n}{2}\rfloor+1$.   
\end{enumerate}
\end{theorem}
\begin{proof}
First, we argue that the algorithm will inevitably terminate. Assume 
\[
(\mathbf{c}^{new},\ \mathbf{d}^{new},q)\gets \textbf{UMTrans1}(\mathbf{c}\ \mathbf{d}) (\textrm{resp.}\ \textbf{UMTrans2}(\mathbf{c}\ \mathbf{d})).
\]
Then, by \textbf{Lemma \ref{lem:key1}} and \textbf{Lemma \ref{lem:key2}}, if $[\mathbf{c}^{new},\ \mathbf{d}^{new}]$ is not reduced, the following inequalities hold except for a special case where  $c_1c_2d_1d_2>0$ and $c_1^{new}c_2^{new}d_1^{new}d_2^{new}\leq 0$, which occurs only once during execution and can be ignored:
\[(\mathbf{c}^{new}=\mathbf{d})\wedge(\|\mathbf{d}^{new}\|\le\min\{\|\mathbf{c}-\mathbf{d}\|,\|\mathbf{c}+\mathbf{d}\|\})\wedge(\|\mathbf{d}^{new}\|< \|\mathbf{c}^{new}\|)\wedge (\|\mathbf{d}^{new}\|<\frac{1}{2}\|\mathbf{c}\|),\] 
which implies that 
\begin{align}\label{eq:dnew}
  \#(\mathbf{c}^{(new)},\mathbf{d}^{(new)})<\#(\mathbf{c},\mathbf{d}), \ \#\mathbf{d}^{(new)}\le \underline{\#}(\mathbf{c}+\mathbf{d},\mathbf{c}-\mathbf{d}),\  \#\mathbf{d}^{(new)}<\#\mathbf{c}-1.
\end{align}  Meanwhile, steps \ref{hvec:stephalf1} and \ref{hvec:stephalf2} ensure that $\underline{\#}(\mathbf{c}^{(new)},\mathbf{d}^{(new)})>s=\lfloor\frac{n}{2}\rfloor+1$ 
Consequently, the \textbf{While} conditions in Step \ref{hvec:stepwhile1} and Step \ref{hvec:stepwhile2} will eventually be violated. That is, \textbf{Algorithm \ref{alg:HVec}} will terminate. Additionally,  by equations (\ref{eq:keyobser1})-(\ref{eq:keyobser3}) and the properties of the unimodular transformations \textbf{UMTrans1} and \textbf{UMTrans2}, the output $(\mathbf{c}, \mathbf{d},\mathbf{M})$ satisfies 
$[\mathbf{a}\ \mathbf{b}]=[\mathbf{c}\ \mathbf{d}]\mathbf{M}$ and one of the following conditions holds: 

(1) $[\mathbf{c}\ \mathbf{d}]$ is reduced, or

(2) $\underline{\#}(\mathbf{c},\mathbf{d})>\lfloor\frac{n}{2}\rfloor+1$ and $\underline{\#}(\mathbf{c}-\mathbf{d}, \mathbf{c}+\mathbf{d})\leq \lfloor\frac{n}{2}\rfloor+1$.

Now, we estimate the time complexity.  We need to estimate the bit size of the numbers and the time complexity of each \textbf{while} loop during execution. According to our recursive design, the underlying operations are the unimodular transformations \textbf{UMTrans1} and \textbf{UMTrans2}. For each recursive invocation
$(\mathbf{c}^\prime, \mathbf{d}^\prime, \mathbf{M}^\prime)\gets\textbf{HVec}(\mathbf{a}^\prime\ \mathbf{b}^\prime)$, we adopt the same notations as in the proof of \textbf{Theorem \ref{thm:Par-Euc}} for brevity. Assume that $\|\mathbf{a}^\prime\|\ge\|\mathbf{b}^\prime\|$ and the lattice basis sequence is given by 
\begin{align*}
    \mathbf{B}^{(0)}=[\mathbf{a}^{(0)}\ \mathbf{b}^{(0)}]=[\mathbf{a}^\prime\ \mathbf{b}^\prime]\to \mathbf{B}^{(1)}=[\mathbf{a}^{(1)}\ \mathbf{b}^{(1)}]\to \cdots\to \mathbf{B}^{(m)}=[\mathbf{a}^{(m)}\ \mathbf{b}^{(m)}]=[\mathbf{c}^\prime\ \mathbf{d}^\prime],
\end{align*}
where, for $i=1,\cdots,m$, 
\begin{align} \label{eq:Eucdiv}
\mathbf{a}^{(i)}=\mathbf{b}^{(i-1)}, \mathbf{a}^{(i-1)}=q^{(i)}\mathbf{b}^{(i-1)}+\mathbf{b}^{(i)}=q^{(i)}\mathbf{a}^{(i)}+\mathbf{a}^{(i+1)}
\end{align} and $q^{(i)}$ is defined in equation (\ref{eq:q}). Then $[\mathbf{a}^\prime\ \mathbf{b}^\prime]=[\mathbf{c}^\prime\ \mathbf{d}^\prime]\mathbf{M}^\prime$ with
\begin{align}\label{eq:M}
    \mathbf{M}^\prime=\begin{pmatrix}q^{(m)} & 1\\ 1 & 0\end{pmatrix}\begin{pmatrix}q^{(m-1)} & 1\\ 1 & 0\end{pmatrix}\cdot\cdots\cdot\begin{pmatrix}q^{(1)} & 1\\ 1 & 0\end{pmatrix}.
\end{align} 
Furthermore, by \textbf{Lemma \ref{lem:key1}} and \textbf{Lemma \ref{lem:key2}}, the following inequalities hold for almost all \( i \in \{1, \dots, m\} \), with at most one exception, which does not affect the proof and can be ignored:
\[
\|\mathbf{a}^{(i+1)}\| = \|\mathbf{b}^{(i)}\| < \frac{1}{2} \|\mathbf{a}^{(i-1)}\| \quad \text{and} \quad \|\mathbf{b}^{(i)}\| < \|\mathbf{a}^{(i)}\|.
\]
Then, the equation (\ref{eq:Eucdiv}) indicate that $\#\mathbf{a}^{(i-1)}=\# q^{(i)}+\#\mathbf{a}^{(i)}$.
While, the equation (\ref{eq:M}) implies that $\#\mathbf{M}^\prime<\sum_{i=1}^m\# q^{(i)}+1$.
Hence, \begin{align}\label{eq:bit}
    &\#\mathbf{a}^{(0)}=\# q^{(1)}+\#\mathbf{a}^{(1)}=\sum_{i=1}^m\# q^{(i)}+\# \mathbf{a}^{(i)}>\#\mathbf{M}^\prime-1+\#\mathbf{c}^\prime\nonumber\\
    &\implies \#\mathbf{M}^\prime<\#\mathbf{a}^{(0)}-\#\mathbf{c}^\prime+1\le\#(\mathbf{a}^\prime,\mathbf{b}^\prime)-\underline{\#}(\mathbf{c}^\prime,\mathbf{d}^\prime)+1.
\end{align}
Based on the above observation, in step \ref{Hvec:stepif1start}-step \ref{Hvec:stepif1end},
we have 
\begin{align*}
&\#(\mathbf{c}^\prime,\mathbf{d}^\prime)\le n-n_{\ell 1} \wedge \underline{\#}(\mathbf{c}^\prime,\mathbf{d}^\prime)>\lfloor\frac{n-n_{\ell 1}}{2}\rfloor+1 \wedge \underline{\#}(\mathbf{c}^\prime+\mathbf{d}^\prime,\mathbf{c}^\prime-\mathbf{d}^\prime)\le \lfloor\frac{n-n_{\ell 1}}{2}\rfloor+1 \wedge\\
& \#\mathbf{M}_1^\prime\le\#(\mathbf{a}^\prime,\mathbf{b}^\prime)-\underline{\#}(\mathbf{c}^\prime,\mathbf{d}^\prime)+1<n-n_{\ell 1}-(\lfloor\frac{n-n_{\ell 1}}{2}\rfloor+1)+1.
\end{align*}
Thus, the equation $[\mathbf{c}\ \mathbf{d}]= 2^{n_{\ell 1}}[\mathbf{c}^\prime\  \mathbf{d}^\prime]+[\mathbf{a}^{\prime\prime}\ \mathbf{b}^{\prime\prime}](\mathbf{M}_1^\prime)^{-1}$ in step \ref{Hvec:stepcd1} implies that
\begin{align*}
  &\#(\mathbf{c},\mathbf{d})\le \max\{n_{\ell 1}+\#(\mathbf{c}^\prime,\mathbf{d}^\prime), n_{\ell 1}+\#\mathbf{M}_1^\prime\}+1=n+1,\\
 &\underline{\#}(\mathbf{c}\pm\mathbf{d})=\underline{\#}(2^{n_{\ell 1}}(\mathbf{c}^\prime+\mathbf{d}^\prime)+(\mathbf{a}^{\prime\prime}+\mathbf{b}^{\prime\prime})(\mathbf{M}_1^\prime)^{-1}, 2^{n_{\ell 1}}(\mathbf{c}^\prime-\mathbf{d}^\prime)+(\mathbf{a}^{\prime\prime}-\mathbf{b}^{\prime\prime})(\mathbf{M}_1^\prime)^{-1})\\
 &=\min\{\# (2^{n_{\ell 1}}(\mathbf{c}^\prime+\mathbf{d}^\prime)+(\mathbf{a}^{\prime\prime}+\mathbf{b}^{\prime\prime})(\mathbf{M}_1^\prime)^{-1}), \#(2^{n_{\ell 1}}(\mathbf{c}^\prime-\mathbf{d}^\prime)+(\mathbf{a}^{\prime\prime}-\mathbf{b}^{\prime\prime})(\mathbf{M}_1^\prime)^{-1}))\}\\
 &=\min\{\max\{n_{\ell 1}+\#(\mathbf{c}^\prime+\mathbf{d}^\prime),\#(\mathbf{a}^{\prime\prime}+\mathbf{b}^{\prime\prime})+\#\mathbf{M}_1^\prime\}+1, \max\{n_{\ell 1}+\#(\mathbf{c}^\prime-\mathbf{d}^\prime),\#(\mathbf{a}^{\prime\prime}-\mathbf{b}^{\prime\prime})+\#\mathbf{M}_1^\prime\}+1\}\\
 &\le \max\{n_{\ell 1}+\underline{\#}(\mathbf{c}^\prime\pm \mathbf{d}^\prime), \max\{\#\mathbf{a}^{\prime\prime},\#\mathbf{b}^{\prime\prime}\}+1+\#\mathbf{M}_1^\prime\}+1\\
 &\le \max\{n_{\ell 1}+\lfloor\frac{n-n_{\ell 1}}{2}\rfloor+1, n_{\ell 1}+1+n-n_{\ell 1}-(\lfloor\frac{n-n_{\ell 1}}{2}\rfloor+1)+1\}\\
 &=\max\{n_{\ell 1}+\lfloor\frac{n_{\ell 1}}{2}\rfloor+1, n-\lfloor\frac{n_{\ell 1}}{2}\rfloor+1\}<\frac{3n}{4}+3<\lfloor\frac{3n}{4}\rfloor+4.
\end{align*}
By the equation (\ref{eq:dnew}), the bit length of the new vector generated by the unimodular matrix transformation \textbf{UMTrans1} (resp. \textbf{UMTrans2}) is less that $\min\{\underline{\#}(\mathbf{c}+\mathbf{d},\mathbf{c}-\mathbf{d}), \#\mathbf{c}-1\}$. Therefore, the \textbf{while} loop in step \ref{hvec:stepwhile1}  will terminate after at most $8$ iterations and thus the time complexity is $O(M(n))$. Similarly, in step \ref{Hvec:stepif2start}-step \ref{Hvec:stepif2end}, we have 
\begin{align*}
