\subsection{\textbf{HVecSBP} algorithm and its complexity analysis}


By cyclically invoking the proposed \textbf{HVec} algorithm, the reduced basis can ultimately be obtained. This design, referred to as \textbf{HVecSBP}, is detailed in \textbf{Algorithm \ref{alg:HGCD-Par-Euc2}}. Clearly, by \textbf{Theorem \ref{thm:HVec}}, the \textbf{HVecSBP} algorithm will output a reduced basis with a worst-case time complexity of \begin{align*}
  O\left(T(n)+T\left(\frac{n}{2}\right)+\cdots+T\left(\frac{n}{2^{\log n}}\right) \right)=O\left(M(n)\log n +M\left(\frac{n}{2}\right) \log \frac{n}{2}+\cdots+ M\left(\frac{n}{2^{\log n}}\right) \log \frac{n}{2^{\log n}}\right)\\
  =O\left(M(n)\log n +\frac{1}{2}M\left(n\right) \log n+\cdots+ \frac{1}{2^{\log n}}M\left(n\right) \log n\right)=O(M(n)\log n)  
\end{align*}

\begin{algorithm}
\caption{\textbf{HVecSBP}($\mathbf{a}, \mathbf{b}$)}   \label{alg:HGCD-Par-Euc2}
\begin{algorithmic}[1]
\REQUIRE  A base $[\mathbf{a}\ \mathbf{b}]$ with $\mathbf{a}=(a_1\ a_2)^T$, $\mathbf{b}=(b_1\ b_2)^T$
\ENSURE  A reduced base $[\mathbf{a}\ \mathbf{b}]$
%\STATE \textbf{If}($a_1a_2b_1b_2\leq0 \wedge (|a_1|-|a_2|)(|b_1|-|b_2|)\leq 0$), \textbf{Return} $[\mathbf{a}\ \mathbf{b}]$.
\STATE $\mathbf{M}=\mathbf{I}$
\STATE \textbf{While}(1)
%\STATE \quad \textbf{if} $\|\mathbf{a}\|< \|\mathbf{b}\|$, Swap($\mathbf{a}, \mathbf{b}$) \quad //let $q\geq 1$
\STATE \quad \textbf{if} ($a_1a_2b_1b_2\leq0 \wedge (|a_1|-|a_2|)(|b_1|-|b_2|)\leq 0$) \textbf{break}
\STATE \quad \textbf{if} $\|\mathbf{a}\|< \|\mathbf{b}\|$, Swap($\mathbf{a}, \mathbf{b}$)
\STATE \quad $n := \#\mathbf{a}$
\STATE \quad \textbf{if} $\#\mathbf{b}\leq \left\lfloor\frac{n}{2}\right\rfloor +1 $
\STATE \qquad \textbf{if} ($|a_1|\geq|a_2| \wedge b_1\ne 0$), $q :=\left\lfloor\frac{a_1}{b_1}\right\rfloor_o$
\STATE \qquad \textbf{else} $q :=\left\lfloor\frac{a_2}{b_2}\right\rfloor_o$
\STATE \qquad ($\mathbf{a},\mathbf{b}$) := ($\mathbf{b},\mathbf{a}-q\mathbf{b}$)
\STATE \qquad \textbf{continue}
\STATE \quad $(\mathbf{a},\mathbf{b},\mathbf{M})\leftarrow \textbf{HVec}(\mathbf{a}, \mathbf{b})$
\STATE \quad \textbf{if}  $\#(\mathbf{a}+\mathbf{b})\leq\lfloor\frac{n}{2}\rfloor+1$, ($\mathbf{a},\mathbf{b}$) := ($\mathbf{b},\mathbf{a}+\mathbf{b}$)
\STATE \quad \textbf{else if} $\#(\mathbf{a}-\mathbf{b})\leq\lfloor\frac{n}{2}\rfloor+1$, ($\mathbf{a},\mathbf{b}$) := ($\mathbf{b},\mathbf{a}-\mathbf{b}$)
\STATE \textbf{If} (($a_1b_1=0 \wedge sgn(a_2)\ne sgn(b_2))$ or ($a_2b_2=0 \wedge sgn(a_1)\ne sng(b_1)$)), $\mathbf{b} := -\mathbf{b}$
\STATE  \textbf{If} $\|\mathbf{a}\|> \|\mathbf{b}\|$, Swap($\mathbf{a}, \mathbf{b}$)
\STATE  \textbf{If} $\mathbf{a} = [0,0]$, \textbf{Return}[$\mathbf{a}, \mathbf{b}$]
\STATE  \textbf{Else}
\STATE \quad \textbf{if} ($a_2b_2\leq0$)
\STATE  \quad \quad $\mathbf{b} :=\min\left\{\mathbf{b}-\left\lfloor\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rfloor \mathbf{a}, \mathbf{b}-\left\lceil\frac{|b_1|-|b_2|}{|a_1|+|a_2|}\right\rceil \mathbf{a}\right\}$
\STATE \quad \textbf{else}
\STATE  \quad \quad $\mathbf{b} :=\min\left\{\mathbf{b}-\left\lfloor\frac{|b_2|-|b_1|}{|a_1|+|a_2|}\right\rfloor \mathbf{a}, \mathbf{b}-\left\lceil\frac{|b_2|-|b_1|}{|a_1|+|a_2|}\right\rceil \mathbf{a}\right\}$
\STATE  \quad \textbf{Return} $[\mathbf{a}\ \mathbf{b}]$
\end{algorithmic}
\end{algorithm}
