\begin{pmatrix}
a_1^{(1)} & b_1^{(1)}\\
a_2^{(1)} & b_2^{(1)}
\end{pmatrix}\to\cdots\to
\begin{pmatrix}
a_1^{(k)} & b_1^{(k)}\\
a_2^{(k)} & b_2^{(k)}
\end{pmatrix}\to\cdots
\end{align*}
assume $\left\lfloor\frac{a_1^{(i)}}{b_1^{(i)}}\right\rfloor=\left\lfloor\frac{a_2^{(i)}}{b_2^{(i)}}\right\rfloor$ for all $i\leq k$, then $k\leq\log_{2}{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}, k\in \mathbb{Z}$.
