\begin{pmatrix}
a_{1}^{(0)} & b_{1}^{(0)}\\
a_{2}^{(0)} & b_{2}^{(0)}
\end{pmatrix}\to\cdots
\to\begin{pmatrix}
a_1^{(k)} & b_1^{(k)}\\
a_2^{(k)} & b_2^{(k)}
\end{pmatrix},\left|\frac{a_1^{(k)}}{b_1^{(k)}}-\frac{a_2^{(k)}}{b_2^{(k)}}\right|=\frac{\left|a_1^{(k)}b_2^{(k)}-a_2^{(k)}b_1^{(k)}\right|}{\left|b_1^{(k)}b_2^{(k)}\right|}=\frac{\left|a_1b_2-b_1a_2\right|}{\left|b_1^{(k)}b_2^{(k)}\right|}\geq1
\end{align*}
In the process of Euclidean division, the determinant of the matrix remains unchanged, so we only need to estimate how many times it takes to reduce $b_1^{(0)}b_2^{(0)}$ to $b_1^{(k)}b_2^{(k)}$, consider the following process:
\begin{align*}
\begin{pmatrix}
a_{1}^{(0)} & b_{1}^{(0)}\\
a_{2}^{(0)} & b_{2}^{(0)}
\end{pmatrix}\to
\begin{pmatrix}
a_1^{(1)} & b_1^{(1)}\\
a_2^{(1)} & b_2^{(1)}
\end{pmatrix}\to
\begin{pmatrix}
a_1^{(2)} & b_1^{(2)}\\
a_2^{(2)} & b_2^{(2)}
\end{pmatrix}\to\cdots
\end{align*}
According to Euclid's properties, we have $a_1^{(1)}=b_1^{(0)},a_2^{(1)}=b_2^{(0)},b_1^{(2)}<\frac{a_1^{(1)}}{2},b_2^{(2)}<\frac{a_2^{(1)}}{2}$, so we can get after two times of Euclidean division, $b_1^{(2)}b_2^{(2)}<\frac{b_1^{(0)}b_2^{(0)}}{4}$. By analogy, every time we perform two Euclidean divisions, the corresponding product is less than $\frac{1}{4}$ of the original, so
\begin{align*}
\left(\frac{1}{4}\right)^{\frac{k}{2}}|b_1b_2|=|a_1b_2-b_1a_2|\Rightarrow k=\log_{2}{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}
\end{align*}
Here we assume that the denominator of the difference between the quotients of the two dimensions of the matrix becomes $\frac{1}{4}$ of the original value after each execution of the Euclidean matrix. In the actual process, the decrease is much greater than this value each time, so $k$ is at most $\log_{2}{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}$.
\end{proof}
\begin{lemma}\label{lem:HGCD loop times}
Let a lattice basis close to linear correlation $\mathbf{B}=[\mathbf{a}\ \mathbf{b}]=\begin{pmatrix}
a_{1} & b_{1}\\
a_{2} & b_{2} 
\end{pmatrix}\in\mathbb{R}^{2\times 2}$ as the input of \textbf{Algorithm \ref{alg:HVec}}, after we call it at most $\log\log{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}+\mathrm{c}$ ($\mathrm{c}$ is a constant number) times, the algorithm no longer works, which means the conditions for reduced basis have been satisfy.
\end{lemma}
\begin{proof}
If the input lattice is not nearly linearly related or there are three data with the same sign in the matrix, \textbf{Algorithm \ref{alg:HVec}} will no longer work after a very small number of executions. So we only consider two vectors that are very nearly linearly related. Without loss of generality, assume that all input data are positive integers, according to \textbf{Lemma \ref{lem:Continued fraction equal execution times}}, we have the number of times that $q$ calculated by the first dimension and the second dimension are equal is at most $\log_{2}{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}$. For the purpose of this proof, suppose that after executing the \textbf{Algorithm \ref{alg:HVec}} $k$ times, the quotients $q$ calculated from the two dimensions are equal for the final time and if the algorithm is executed again, the quotients will no longer be equal, which means\begin{align*}
\left(\frac{1}{2}\right)^{k}\log{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}=1\Rightarrow k = \log\log{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}.
\end{align*}
If the \textbf{Algorithm \ref{alg:HVec}} input and output are the same, a linear transformation is required to make \textbf{Algorithm \ref{alg:HVec}} work, and if there are three data with the same sign in the matrix, it may still be necessary to perform a constant number of \textbf{Algorithm \ref{alg:HVec}} to satisfy the conditions of the reduced basis. which means we need to add a constant number, so the $k$ at most $\log\log{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}+\mathrm{c}$.
\end{proof}
Building on the above analysis, we present the following theorem, which establishes the correctness and complexity of the \textbf{HVec-SBP} algorithm.
\begin{theorem}\label{thm: HGCD-Par-Euc2}
Given a basis $\mathbf{B}=[\mathbf{a}\ \mathbf{b}]=\begin{pmatrix}
a_{1} & b_{1}\\
a_{2} & b_{2} 
\end{pmatrix}\in\mathbb{R}^{2\times 2}$, \textbf{Algorithm \ref{alg:HGCD-Par-Euc2}} can outputs a reduced basis $\mathbf{b}^\prime=[\mathbf{a}^\prime\ \mathbf{b}^\prime]=\begin{pmatrix}
a'_{1} & b'_{1}\\
a'_{2} & b'_{2} 
\end{pmatrix}$ which satisfy 
$a'_1a'_2b'_1b'_2\le 0 \wedge (|a'_1|-|a'_2|)(|b'_1|-|b'_2|)\le 0.$ It requires $O(\log n\log\log n M(n))$. 
\end{theorem}
\begin{proof}
The partial Euclidean algorithm calculates $q$ through one dimension in the matrix. We apply this idea to the \textbf{HVec} algorithm. \textbf{Algorithm \ref{alg:HGCD-Par-Euc2}} obtains the reduced basis by continuously calling the \textbf{Algorithm \ref{alg:HVec}}. Each time the \textbf{Algorithm \ref{alg:HVec}} is called, we need to re-judge whether the current lattice basis meets the conditions of the next \textbf{Algorithm \ref{alg:HVec}}, that is we need to perform a linear transformation to ensure that the next \textbf{Algorithm \ref{alg:HVec}} works(\textbf{Algorithm \ref{alg:HVec}} does not work, which means that the input and output remain unchanged and the current lattice basis does not satisfy the conditions for a reduced basis.)

Condition 1: $\#(\mathbf{a},\mathbf{b})=n,\underline{\#}(\mathbf{a},\mathbf{b})\leq\left\lfloor\frac{n} {2}\right\rfloor+1$ 
\begin{align*}
    &\#(\mathbf{a},\mathbf{b})=n, \#\mathbf{a}\geq\#\mathbf{b}\Longrightarrow\#\mathbf{b}=n^{\prime}\leq\left\lfloor\frac{n}{2}\right\rfloor\\
    &\textbf{if} \ |a_1|\geq|a_2|\wedge |b_1|\ne 0, q=\left\lfloor\frac{a_1}{b_1}\right\rfloor, \textbf{else} \ q=\left\lfloor\frac{a_1}{b_1}\right\rfloor\Longrightarrow(\mathbf{a},\mathbf{b})=(\mathbf{b},\mathbf{a}-q\mathbf{b})\\
    &\underline{\#}(\mathbf{a}-q\mathbf{b})=n^{\prime\prime}\leq n^{\prime}
\end{align*}

according to the definition of \textbf{HVec}, we need to ensure the input matrix satisfy $\underline{\#}(\mathbf{a},\mathbf{b})>\left\lfloor\frac{n} {2}\right\rfloor+1$,  if $\underline{\#}(\mathbf{a},\mathbf{b})\leq \left\lfloor\frac{n}{2}\right\rfloor+1$, \textbf{Algorithm \ref{alg:HVec}} will not split the data into high and low bits,  we use a one-step partial Euclidean to ensure that this condition is satisfy or close to it. Obviously, if we perform a Euclidean division and the resulting vector $n^{\prime\prime}\leq \left\lfloor\frac{n^{\prime}}{2}\right\rfloor+1$ still does not satisfy the \textbf{HVec} condition, but the length of the vector is getting shorter, we can continue to perform this single-step operation. 

Condition 2: $\#(\mathbf{a},\mathbf{b})=n,\#(\mathbf{a}+\mathbf{b})\leq \left\lfloor\frac{n}{2}\right\rfloor$ or $\#(\mathbf{a}-\mathbf{b})\leq \left\lfloor\frac{n}{2}\right\rfloor$
\begin{align*}
&\#(\mathbf{a},\mathbf{b})=n, \#\mathbf{a}\geq\#\mathbf{b}\Longrightarrow\#\mathbf{b}\leq n\\
&(\mathbf{a}, \mathbf{b}) = \textbf{HVec}(\mathbf{a}, \mathbf{b}) \Longleftrightarrow \#(\mathbf{a}\pm\mathbf{b})\leq \left\lfloor\frac{n}{2}\right\rfloor+1\Longrightarrow \mathrm{HighBit}_{\frac{n}{2}}(\mathbf{a})=\mathrm{HighBit}_{\frac{n}{2}}(\mathbf{b})\ at\ least\Longrightarrow\#\mathbf{b}\geq\frac{n}{2}\\
&\mathbf{if} \ \#(\mathbf{a}+\mathbf{b})\leq\left\lfloor\frac{n}{2}\right\rfloor+1,\ \mathbf{then} \ (\mathbf{a}, \mathbf{b}) :=(\mathbf{b}, \mathbf{a}+\mathbf{b}),\#(\mathbf{b},\mathbf{a}+\mathbf{b})=\#\mathbf{b},\#(\mathbf{b}\pm(\mathbf{a}+\mathbf{b}))>\left\lfloor\frac{\#\mathbf{b}}{2}\right\rfloor+1\\
&\mathbf{if} \ \#(\mathbf{a}-\mathbf{b})\leq\left\lfloor\frac{n}{2}\right\rfloor+1,\ \mathbf{then} \ (\mathbf{a}, \mathbf{b}) :=(\mathbf{b}, \mathbf{a}-\mathbf{b}),\#(\mathbf{b},\mathbf{a}-\mathbf{b})=\#\mathbf{b},\#(\mathbf{b}\pm(\mathbf{a}-\mathbf{b}))>\left\lfloor\frac{\#\mathbf{b}}{2}\right\rfloor+1
\end{align*} 

the above two steps ensure that \textbf{Algorithm \ref{alg:HVec}} will continue to work without an infinite loop until the reduced basis is reached. This is similar to the polynomial \textbf{HGCD} algorithm. Each time the polynomial \textbf{HGCD} is executed, if the final result is not obtained, a Euclidean division must be performed, and then the polynomial \textbf{HGCD} algorithm is called again. 

As for the time complexity, the worst lattice basis for the input is when the two vectors are very close to being linearly related, according to \textbf{Theorem \ref{thm:HVec}} and \textbf{Lemma \ref{lem:HGCD loop times}}, each time we call \textbf{Algorithm \ref{alg:HVec}}, the time is $O(\log n M(n))$, and a total of $\log\log{\frac{|b_1b_2|}{|a_1b_2-b_1a_2|}}+\mathrm{c}\approx \log\log n$ calls are required, so the total time complexity is $O(\log n\log\log n M(n))$.
\end{proof}\fi

\section{Practical Performance Evaluation}
\subsection{Experimental Methodology}

To comprehensively evaluate the practical efficiency of our proposed algorithm \textbf{CrossEuc} and its optimized variant \textbf{HVecSBP} against existing methods, we will conduct extensive experiments considering both metric types and lattice basis forms. In terms of the metric, we compare the practical performance of various algorithms under both the Euclidean and Minkowski metrics. Regarding the input basis, it is evident that the performance of existing algorithms is highly dependent on the structure of the input lattice basis. We focus on two common types: the \emph{HNF-form} basis \(\mathbf{B} = [\mathbf{a}\ \mathbf{b}] = \begin{pmatrix} a & b \\ 0 & c \end{pmatrix}\), where \(a > b > |c|> 0\), and the \emph{general-form} basis \(\mathbf{B} = [\mathbf{a}\ \mathbf{b}] = \begin{pmatrix} a_1 & b_1 \\ a_2 & b_2 \end{pmatrix}\). For general-form bases, the degree of linear dependence between the two basis vectors clearly affects algorithmic performance. 
We define the linear dependency measure \(\Delta(\mathbf{a}, \mathbf{b})\) as:  
\[
\Delta(\mathbf{a}, \mathbf{b}) = \left| \frac{a_1}{b_1} - \frac{a_2}{b_2} \right|.
\]  
It is clear that a smaller \(\Delta\) value indicates a higher degree of linear dependency between vectors \(\mathbf{a}\) and \(\mathbf{b}\).  


(1)  Evaluation for $\ell_2$-shortest basis. 
We compare five algorithms: our proposed fundamental reduction algorithm \textbf{CrossEuc},  Lagrange reduction algorithm \textbf{LagRed}  under the \(\ell_2\) metric \cite{Lag73, MGbook} (see Appendix \ref{App:LagRed}), Yap's fundamental algorithm \textbf{CRS} \cite{yap1992fast} (see Appendix \ref{App:CRS}),  our optimized algorithm \textbf{HVecSBP} and Yap's optimized algorithm (\textbf{HalfGaussianSBP}) \cite{yap1992fast} (see Appendix \ref{App:HalfGaussian}).  
\begin{itemize}
\item  For \emph{HNF-form} bases, we assessed the practical performance of the above-mentioned algorithms across different bit sizes of $c$.

\item For general-form bases, we assess the practical performance of the above-mentioned algorithms across different \(\Delta\) values.
\end{itemize}

(2) Evaluation for $\ell_\infty$-shortest basis.
\begin{itemize}
\item For \emph{HNF-form} bases, our algorithm \textbf{CrossEuc} is identical to the continued fraction-based algorithm (\textbf{ParEuc}) \cite{EIS01,CTJ22}. Thus, we only compare three algorithms: the optimized Lagrange algorithm under the \(\ell_\infty\) metric (\textbf{GolEuc}) \cite{Lag73,CTJ22}, the continued fraction-based algorithm (\textbf{ParEuc}) \cite{EIS01,CTJ22}, and our optimized algorithm (\textbf{HVecSBP}).

\item For general-form bases, we evaluate the practical performance of the following algorithms across different \(\Delta\) values.
\begin{itemize}
    \item \textbf{GolEuc}: The optimized Lagrange algorithm under the \(\ell_\infty\) metric presented in \cite{CTJ22}.  
\item \textbf{EEA-HNF-ParEuc}: An algorithm that first transforms the basis into HNF using the extended Euclidean algorithm (EEA) and then reduces it with the continued fraction-based algorithm (\textbf{ParEuc}).  Visually
\begin{align*} 
\begin{pmatrix} a_1 & b_1\\  a_2 & b_2 \end{pmatrix}\overset{\textbf{EEA}}{\longrightarrow} \begin{pmatrix} a & b\\ 0 & c \end{pmatrix} \overset{\textbf{ParEuc}}{\longrightarrow}\mbox{reduced\ basis}
\end{align*}

\item \textbf{CrossEuc}: Our proposed reduced algorithm without using \textbf{Hvec} .  

\item \textbf{HGCD-HNF-ParEuc}: Similar to \textbf{EEA-HNF-ParEuc}, but the basis is transformed into HNF using the HGCD-based extended Euclidean algorithm.   Visually
\begin{align*} 
\begin{pmatrix} a_1 & b_1\\  a_2 & b_2 \end{pmatrix}\overset{\textbf{HGCD}}{\longrightarrow}  \begin{pmatrix} a & b\\ 0 & c \end{pmatrix} \overset{\textbf{ParEuc}}{\longrightarrow} \mbox{reduced\ basis}
\end{align*}

\item \textbf{HGCD-HNF-HVecSBP}: Similar to \textbf{HGCD-HNF-ParEuc}, but the HNF is reduced using our proposed \textbf{HVecSBP} algorithm.   Visually
\begin{align*} 
\begin{pmatrix} a_1 & b_1\\  a_2 & b_2 \end{pmatrix}\overset{\textbf{HGCD}}{\longrightarrow}\begin{pmatrix} a & b\\ 0 & c \end{pmatrix} \overset{\textbf{HVecSBP}}{\longrightarrow}  \mbox{reduced\ basis}
\end{align*}
\item \textbf{HVecSBP}: Our proposed algorithm applied directly to the input basis without prior transformation to HNF.  
\end{itemize}

\end{itemize}




\subsection{Experimental Environment and  Result Analysis}
Our experiment are performed on a Ubuntu 22.04 machine with Intel Core i7-9750H, 2.6 GHz CPU and 16 GB RAM and implement the algorithm with C language. The detailed experimental results and their analysis are presented as follows.


