\section{The optimized Lagrange algorithm under the \(\ell_\infty\) metric \textbf{GolEuc}.}\label{App:GolEuc}
\begin{algorithm}\scriptsize
	%\begin{center}
	\caption{\textbf{GloEuc}\cite{CTJ22}}   \label{alg:Gol-Euc}
	%\def\temptablewidth{0.5\textwidth}
	\begin{algorithmic}[1]
		\REQUIRE A basis $[\mathbf{a} \ \mathbf{b}]$.
		\ENSURE  An $\ell_\infty$-shortest basis for $\mathcal{L}([\mathbf{a}\ \mathbf{b}])$
		\STATE  \textbf{If} $\|\mathbf{a}\|>\|\mathbf{b}\|,$ \textbf{then} swap ($\mathbf{a}, \mathbf{b}$)
		\STATE  \textbf{If} $\|\mathbf{a}-\mathbf{b}\|>\|\mathbf{a}+\mathbf{b}\|,$ \textbf{then} $\mathbf{b}: = -\mathbf{b}$
		\STATE \textbf{If} $\|\mathbf{b}\|\leq\|\mathbf{a}-\mathbf{b}\|,$ \textbf{then} return $[\mathbf{a} \ \mathbf{b}]$
		\STATE \textbf{If} $\|\mathbf{a}\|\leq\|\mathbf{a}-\mathbf{b}\|,$ \textbf{then} goto \emph{loop}
		\STATE \textbf{If} $\|\mathbf{a}\|=\|\mathbf{b}\|,$ \textbf{then} return $[\mathbf{a} \ \mathbf{a}-\mathbf{b}]$
		\STATE  $[\mathbf{a} \ \mathbf{b}]:=[\mathbf{b}-\mathbf{a} \ \mathbf{a}]$
		\STATE  \emph{loop}
		\STATE  \quad \textbf{If} $\frac{b_1}{a_1}, \frac{b_2}{a_2} \neq 0$ and $sgn\left(\frac{b_1}{a_1}\right)=sgn\left(\frac{b_2}{a_2}\right)$ \textbf{then}
		\STATE  \quad \quad Find $\mu \in \left\{ \left\lceil \frac{|b_1| + |b_2|}{|a_1| + |a_2|} \right\rceil, \left\lfloor \frac{|b_1| + |b_2|}{|a_1| +|a_2|} \right\rfloor \right\},$ s.t. $\|\mathbf{b} - \mu\mathbf{a}\|$ is minimal
		\STATE  \quad \textbf{Else}
		\STATE  \quad \quad Find $\mu \in \left\{ \left\lceil \frac{\big||b_2| - |b_1|\big|}{|a_2| + |a_1|} \right\rceil, \left\lfloor \frac{\big||b_2| - |b_1|\big|}{|a_2| + |a_1|} \right\rfloor\right\},$ s.t. $\|\mathbf{b} - \mu\mathbf{a}\|$ is minimal
		\STATE \quad $ \mathbf{b}: = \mathbf{b} - \mu\mathbf{a}$
		\STATE \quad  \textbf{If} $\|\mathbf{a} - \mathbf{b}\| > \|\mathbf{a} + \mathbf{b}\|$ \textbf{then} $\mathbf{b}: = -\mathbf{b}$
		\STATE \quad Swap($\mathbf{a},\mathbf{b}$)
		\STATE \quad \textbf{If} $[\mathbf{a} \ \mathbf{b}]$ is Lagrange-reduced, \textbf{then} return $[\mathbf{a} \ \mathbf{b}]$
		\STATE \quad goto \emph{loop}
	\end{algorithmic}
\end{algorithm}

\section{Lagrange's reduction algorithm under the \(\ell_2\) metric \textbf{LagRed}} \label{App:LagRed}

\begin{algorithm}\scriptsize
	\caption{\textbf{LagRed} \cite{MGbook}} \label{alg:Lagl2norm}
	\def\temptablewidth{0.5\textwidth}
	\begin{algorithmic}[1]
		\REQUIRE A basis $[\mathbf{a} \ \mathbf{b}]$.
		\ENSURE  An $\ell_2$-shortest basis for $\mathcal{L}([\mathbf{a}\ \mathbf{b}])$
		\STATE  \textbf{If} $\|\mathbf{a}\|_{2}>\|\mathbf{b}\|_{2},$ \textbf{then} swap ($\mathbf{a}, \mathbf{b}$)
		\STATE  \textbf{If} $\|\mathbf{a}-\mathbf{b}\|_{2}>\|\mathbf{a}+\mathbf{b}\|_{2},$ \textbf{then} $\mathbf{b}: = -\mathbf{b}$
		\STATE \textbf{If} $\|\mathbf{b}\|_{2}\leq\|\mathbf{a}-\mathbf{b}\|_{2},$ \textbf{then} return $[\mathbf{a} \ \mathbf{b}]$
		\STATE \textbf{If} $\|\mathbf{a}\|_{2}\leq\|\mathbf{a}-\mathbf{b}\|_{2},$ \textbf{then} goto \emph{loop}
		\STATE \textbf{If} $\|\mathbf{a}\|_{2}=\|\mathbf{b}\|_{2},$ \textbf{then} return $[\mathbf{a} \ \mathbf{a}-\mathbf{b}]$
		\STATE  $[\mathbf{a} \ \mathbf{b}]:=[\mathbf{b}-\mathbf{a} \ \mathbf{a}]$
		\STATE  \emph{loop}
		\STATE  \quad $\mu := \left \lceil \frac{<\mathbf{a},\mathbf{b}>}{||\mathbf{a}||_{2}^{2}} \right \rfloor $
		%\STATE \quad \textbf{If} $\mu = 0$, \textbf{then} return $[\mathbf{a}, \mathbf{b}]$
		\STATE \quad $ \mathbf{b}: = \mathbf{b} - \mu\mathbf{a}$
		\STATE \quad  \textbf{If} $\|\mathbf{a} - \mathbf{b}\|_{2} > \|\mathbf{a} + \mathbf{b}\|_{2}$ \textbf{then} $\mathbf{b}: = -\mathbf{b}$
		\STATE \quad Swap($\mathbf{a},\mathbf{b}$)
		\STATE \quad \textbf{If} $[\mathbf{a} \ \mathbf{b}]$ is Lagrange-reduced, \textbf{then} return $[\mathbf{a} \ \mathbf{b}]$
		\STATE \quad goto \emph{loop}
	\end{algorithmic}
\end{algorithm}

