\caption{UAV Landing Decision Process}
\label{alg:UAV_Landing}

\KwIn{Segmentation results of landing video frame $X_{seg}$, predefined threshold $\delta$, vision center$(x_{\text{center}},y_{\text{center}})$, target area $(x_{\text{target}},y_{\text{target}})$, the nest length $l$ in image.}
\KwOut{UAV deviation information}

\BlankLine
