We know that:

\begin{align}
\frac{\partial \lambda_{\omega}(t)}{\partial \alpha_{\omega, \omega'}} = \sum_{t_j^{\omega'} \leq t} e^{-\beta_{\omega,\omega'}(t - t_j^{\omega'})} \mathbf{1}_{\{t \geq t_j^{\omega'}\}}.
\end{align}

Therefore, the gradient of the integral term is:

\begin{align}
- \int_0^T \sum_{t_j^{\omega'} \leq t} e^{-\beta_{\omega,\omega'}(t - t_j^{\omega'})} \mathbf{1}_{\{t \geq t_j^{\omega'}\}} \, dt.
\end{align}

We perform the integral from \( t_j^{\omega'} \) to \( T \):

\begin{align}
\int_{t_j^{\omega'}}^T e^{-\beta_{\omega,\omega'}(t - t_j^{\omega'})} \, dt = \frac{1}{\beta_{\omega,\omega'}} \left( 1 - e^{-\beta_{\omega,\omega'}(T - t_j^{\omega'})} \right).
\end{align}

Thus, the gradient of the integral term is:

\begin{align}
- \sum_{j=1}^{N_{\omega'}} \frac{1}{\beta_{\omega, \omega'}} \left[ 1 - e^{-\beta_{\omega,\omega'}(T - t_j^{\omega'})} \right].
\end{align}

\textbf{Final Gradient Expression}

Combining the log term and integral term gradients, the complete gradient with respect to \( \alpha_{\omega, \omega'} \) is:

\begin{align}
\frac{\partial \mathcal{L}}{\partial \alpha_{\omega, \omega'}} = 
\sum_{i=1}^{N_{\omega}} \frac{1}{\lambda_{\omega}(t_i^{\omega})} 
\sum_{j=1}^{N_{\omega'}} e^{-\beta_{\omega,\omega'}(t_i^{\omega} - t_j^{\omega'})} 
\mathbf{1}_{\{t_j^{\omega'} < t_i^{\omega}\}} 
- 
\end{align}
\begin{align}
\sum_{j=1}^{N_{\omega'}} \frac{1}{\beta_{\omega,\omega'}} 
\left[ 1 - e^{-\beta_{\omega,\omega'}(T - t_j^{\omega'})} \right].
\end{align}




