\noindent
The utility of our new parameter comes from noticing that vertices in different connected components of a temporal graph need not be placed in the same bag despite being active at the same time. Therefore, when considering temporal problems where we can consider the connected components of each snapshot independently, we can use TIM width in place of VIM width. Note that, in this section, we assume all temporal graphs have connected underlying graphs. For clarity, we refer to \emph{vertices} of the original graph and \emph{nodes} of the indexing tree.
\begin{definition}[Tree-Interval-Membership Width]\label{def:TIMW}
    We say a triple $(T,B,\tau)$ is a \emph{tree-interval-membership decomposition} (TIM decomposition) of a temporal graph $\mathcal{G}$ with lifetime $\Lambda$ if $T$ is a labelled directed tree, where $B = \{B(s) : s\in V(T)\}$ is a collection of subsets of $V(\mathcal{G})$, called \emph{bags}, and $\tau: B\to [\Lambda]$ is a function which labels each bag with a time, satisfying:
    \begin{enumerate}
        \item For all vertices $v\in V(\mathcal{G})$ and times $t\in [\Lambda]$, there exists a unique node $i\in V(T)$ such that $\tau(B(i))=t$ and $v$ appears in a unique bag $B(i)$.
        \item For all time-edges $(uv,t)\in\mathcal{E}(\mathcal{G})$, there exists a unique node $i\in V(T)$ such that $\{u,v\}\subseteq B(i)$ and $\tau(B(i))=t$.
        \item The set of arcs of $T$ is given by $\{(i,j) : B(i)\cap B(j)\neq \emptyset \text{ and } \tau(B(j))=\tau(B(i))+ 1\}$.
    \end{enumerate}
The \emph{width} of a TIM decomposition is defined to be $\max\{|B(s)|:s\in V(T)\}$. The \emph{TIM width} of a temporal graph $\mathcal{G}$ is the minimum $\phi$ such that $G$ has a TIM decomposition of with $\phi$. 
\end{definition}

\noindent
Figure~\ref{fig:eg-tim} gives an example of a TIM decomposition. Using simple consequences of this definition, we obtain a polynomial-time algorithm to compute a TIM decomposition of minimum width.

Based on Definition~\ref{def:TIMW}, we have some observations.
\begin{observation}\label{obs:tim-node-bound}
    There are at most $n\Lambda$ nodes in a TIM decomposition.
\end{observation}

\begin{observation}\label{obs:tim-all-one-bag}
    The decomposition found by creating one bag at every timestep containing all vertices in a temporal graph is a TIM decomposition.
\end{observation}

\begin{observation}\label{obs:tim-neighbours}
    For a bag $B(s)$ of a TIM decomposition with time $t=\tau(B(s))$, any neighbours of $s$ must be assigned $t'\in\{t+1,t-1\}$ by $\tau$.
\end{observation}

\begin{observation}\label{obs:tim-no-children}
    Any bag in a TIM decomposition has at most $2\phi$ neighbours, where $\phi$ is the width of the decomposition.
\end{observation}

\begin{observation}\label{obs:tim-directed-path}
    For all vertices $v\in V(\mathcal{G})$, $T[\{s:v\in B(s)\}]$ is a directed path. That is, for each vertex, the subgraph of the TIM decomposition obtained by deleting every node not containing $v$ in its bag from $T$ is a directed path.
\end{observation}

\begin{observation}\label{obs:tim-timeedge-appear-once}
    Every time-edge appears in exactly one bag of a TIM decomposition.
\end{observation}

As a result of the above observation, we can extend this reasoning to entire connected components of a snapshot of a temporal graph.

\begin{observation}\label{obs:tim-connected-component}
    Let $u$ and $v$ be vertices in the same connected component of $G_t$ for some $t$. Then, if $u\in B(i)$ and $\tau(B(i))=t$, $v\in B(i)$.
\end{observation}

We conclude our observations with a note on edges which are active more than once.

\begin{observation}\label{obs:tim:nonsimple-edge}
    If $uv$ is an edge in $\mathcal{G}_{\downarrow}$ and $u$ and $v$ are in different bags of a TIM decomposition at time $t$, then either $t>\max(\lambda(uv))$ or $t<\min(\lambda(uv))$.
\end{observation}

Using the above observations, we now give an algorithm for computing a minimum TIM decomposition of a temporal graph $\mathcal{G}$ whose underlying graph is connected.
\begin{algorithm}\caption{\textsc{Finding a minimum TIM decomposition}}\label{alg:TIMW}
    \begin{algorithmic}[1]
    \Require A temporal graph $\mathcal{G}$ with a connected underlying graph $\mathcal{G}_{\downarrow}$.
    \Ensure A TIM  decomposition of $\mathcal{G}$ with minimum width.
    \State Initialise the empty function $\tau$ and $T=\emptyset$.
    \ForAll{$t=1$ to $t=\Lambda$}\label{alg:TIMW-for-loop}
    \State Create a bag $B\in T$ such that $\tau(B)=t$ containing each connected component in the graph $G_t$.
    \If{there is a bag $B'$ that has a non-empty intersection with $B$ where $\tau(B')=t-1$}\label{alg:TIMW-if}
    \State Add an arc $(B,'B)$ to $T$.
    \EndIf
    \EndFor
    \While{The underlying graph of the decomposition contains a cycle $C$}\label{alg:TIMW-while}
    \ForAll{Pairs of bags $B(i)$, $B(i')\in C$ such that $\tau(B(i))=\tau(B(i'))$}\label{alg:TIM-for-union}
    \State $B(i) \leftarrow B(i)\cup B(i')$
    \ForAll{Arcs $a$ with $i'$ as an endpoint}\label{alg:TIM-for-arcs}
    \State Replace $i'$ with $i$ in $a$
    \EndFor
    \State Delete $B(i')$ from $T$
    \EndFor
    \EndWhile
    \State return $(T,B,\tau)$.
    \end{algorithmic}
\end{algorithm}
