\begin{algorithm}
\caption{Counting all the hitting sets in a hypergraph}
\label{alg:hitting_sets}
\begin{algorithmic}[1]
\REQUIRE The set of connected components $\{G_1, \dots, G_h\}$ of a hypergraph $H$
\ENSURE The cardinality of  $hit_H$
\STATE $nhit \leftarrow 1$
\FOR{$i =1$ to $h$}
    \STATE let $e$ be a hyperedge in $G_i$
%    \STATE $nhit_i \leftarrow 0$
	\STATE $nhit_i \leftarrow \sum_{s\subseteq e, s\neq \emptyset}|hit_H(e,s)|$
%    \FOR{$j = 0$ to $|e|-1$}
%        \FOR{all subsets $p$ of $e$ of cardinality $j$}
%            \STATE  $s \leftarrow e\setminus p$
%            \STATE  $H_1 \leftarrow G_i \setminus p$ 
%            \STATE $H_2 \leftarrow H_1 \setminus N_{H_1}(s)$
%            \STATE $V_j \leftarrow V(H_1) \setminus (V(H_2) \cup s)$
%            %\STATE Let $nhit_i'$ be the number of hitting sets of $H_2$
%            \STATE $nhit_i \leftarrow 2^{|V_j|} \cdot |hit_{H_2}| + nhit_i$
%        \ENDFOR
%    \ENDFOR
    \STATE $nhit \leftarrow nhit \cdot nhit_i$
\ENDFOR
\RETURN $nhit$
\end{algorithmic}
\end{algorithm}

\begin{lemma}
Algorithm \ref{alg:hitting_sets} correctly computes the number of hitting sets of a hypergraph.
\end{lemma}
\begin{proof}
The correctness directly follows from Lemma \ref{hit_subset} and  Lemma \ref{algorithm_subset}.
\end{proof}


\begin{example} [continued]
Consider the  bipartite representation of the hypergraph of Figure \ref{fig:example}(A) and let $e = \{0,3\}$. In  Example  \ref{ex:algorithm_hit} we already computed $|hit_H(e, \{0\})|$. Note that we need now to compute $|hit_H(e, \{3\})|$ and $|hit_H(e, \{0,3\})|$. In the first case it is easy to see that $H_2 = \{\{4\}, \{1,2\}\}$ and $H_2$ has two connected components. The first component, $\{\{4\}\}$, has only one hitting set and the second component $\{\{1,2\}\}$, has three hitting sets. Therefore $|hit_H(e, \{3\})|= 3$. 
As for $|hit_H(e, \{0,3\})|$ we note that $H_1=H$ and after removing $N_H(\{0,3\})$ from $H$ then $H_2= \emptyset$. In this case $|hit_{H_2}|=1$ and $V_1 = V(H_1)\setminus (V(H_2) \cup \{0,3\})= \{1,2,4\}$. Therefore $|hit_H(e, \{0,3\})|= 2^{|V_1|} \cdot hit_{H_2}= 2^3= 8$.
In the end, the sum of all hitting sets is $16$ and the hypergraph is self-dual, as it is easy to check. 
\end{example}
\subsection{Simple algorithm to search a minimal hitting set}

Given a PIDNF $H$ of a Boolean function $f$ satisfying \eqref{eq:intersect}, we can leverage Algorithm Dual in order to find, if any, a $x \in \{0,1\}^n$ such that $f(x)=f(\overline{x})$. By Lemma \ref{less_than_2}, if \eqref{eq:intersect} holds, then when $f(x)=1$ we are guaranteed that $f(\overline{x})=0$. However if \eqref{eq:intersect} holds and $f$ is not self-dual there must exists a $x \in \{0,1\}^n$ such that $f(x)=0$ and $f(\overline{x})=0$. If $x \in \{0,1\}^n$, we define the $w(x)$ the hamming weight of $x$, that is $w(x)=\sum_{i=0}^{n-1} x_i$. We search such an $x$ in Algorithm \ref{alg:minimal_hitting_sets}.

\begin{algorithm}
\caption{Search minimal hitting set}
\label{alg:minimal_hitting_sets}
\begin{algorithmic}[1]
\REQUIRE The PIDNF $F$ of a Boolean function satisfying \eqref{eq:intersect}.
\ENSURE True if $f$ is self-dual. %An $x \in \{0,1\}^n$ such that $f(x)=0$ and $f(\overline{x})=0$ otherwise.
\STATE $n \leftarrow |V(F)|$
%\STATE $k \leftarrow  \min \{|e| : e \in F\}$
\FOR{$i =1$ to $\left \lfloor \dfrac{n}{2} \right \rfloor$}
	\FOR{all $x \in \{0,1\}^n$ such that $w(x)=i$}
	    \IF {$f(x)=0$ and $f(\overline{x})=0$}
	      \RETURN $x$
    	\ENDIF
    \ENDFOR
\ENDFOR
\RETURN True
\end{algorithmic}
\end{algorithm}

\section{Experiments' results}

We generate hypergraphs with the following methodology. We pick a random number $x$ such that  $n_1\leq x < n_2$ where $0<n_1 < n_2< 2^n$. We choose $n_1= 2^{n-3}$ and $n_2 = 2^n-n_1$ where $n= |V(H)|$ is the number of variable of the Boolean function.  Then we consider the binary representation of $x$ as the characteristic vector of a set $t \subseteq \{0,1, \dots n-1\}$. We add $t$ to the hypergraph $H$ provided that no other hyperedge of $H$ is contained in $t$ and $t$ is not contained in any other hyperedge and that hypergraph satisfies \eqref{eq:intersect}.
Surprisingly Algorithm \ref{alg:minimal_hitting_sets} outperform all the other algorithms while, as expected, the algorithm for counting the hitting sets with brute force (\emph{HS brute force}) which counts all the hitting sets by checking for each $t \subseteq V(H)$ if $t$ is a hitting set, is the worst performing. It is also worth to note that Algorithm \ref{alg:hitting_sets}, surprisingly, outperform Algorithm A.

