\section*{Appendix B: Listings for Different Multiplication Widths\label{sect:appendixB}}

\noindent
5-by-3 multiplication, with rounding $(+ (1 << 4))$, correction up to and including 3 ulps of error:
\begin{lstlisting}[breaklines=true,language=C,lineskip=-1pt,mathescape=true]
unsigned long long recip_final_correction(
  unsigned long long X_24_23, // binary point at position 23 // interval [1, 2)
  unsigned long long Y_24_24 // interval (0.5, 1]
                                          ) {
  // 1/x == 1 <=> x == 1
  if (X_24_23 == ONE_24_23) {
    return ONE_24_23;
  }

  // HALF_24_24 has shifted place value; it shares the same bit pattern as ONE_24_23
  unsigned long long HALF_24_24 = ONE_24_23;
  // approximation is left of the interval [0.5, 1)
  if (Y_24_24 < HALF_24_24) {
    Y_24_24 = HALF_24_24;
  }

  // Precondition: R_48_47 is positive
  assert(ONE_48_47 >= X_24_23 * Y_24_24);
  unsigned long long R_48_47 = ONE_48_47 - X_24_23 * Y_24_24;

  // Since Y is within 8ulps of 1/X, we know
  assert(R_48_47 < (1ull << 27) /* 8ulps */);
  unsigned long long R_27_47 = R_48_47;

  // 5bit-by-3bit mult, with rounding (+ (1 << 4)) = up to and including 3 ulps
  //    C = ((R_27_47 >> 21) * (Y_24_24 >> 20) + (1 << 4)) >> 5;
  unsigned long long R_6_26 = R_27_47 >> 21;
  unsigned long long Y_3_3   = Y_24_24 >> 21;
  assert(R_6_26 < 32);
  unsigned long long R_5_26 = R_6_26;
  assert(Y_3_3 < 8);
  unsigned long long C_4_24 =
    (R_5_26 * Y_3_3 + (1 << 4)) >> 5;
  assert(C_4_24 < 8);
  unsigned long long C_3_24 = C_4_24;

  unsigned long long B_28_47 = ((2 * C_3_24 + 1) * X_24_23);

  // R_27_47 * 2 = R_28_47
  if ((R_27_47 * 2) < B_28_47) {
    return Y_24_24 + C_3_24;
  } else {
    return Y_24_24 + (C_3_24 + 1);
  }
}

\end{lstlisting}

