\begin{lemma}[Cordes inequality \cite{fujii1993norm}]\label{l:cordes}
Let $\mathcal{A}$ and $\mathcal{B}$ be two positive bounded linear operators on a
separable Hilbert space. Then for $0\leq s \leq 1$
\begin{align*}
    \|\mathcal{A}^s\mathcal{B}^s\| \leq \|\mathcal{A}\mathcal{B}\|^s.
\end{align*}
\end{lemma}


\begin{lemma}[Lemma 5 from \cite{rudi2015less}]\label{l:rudi_15_1}
     If assumptions \ref{as:1} and \ref{as:4} hold, then for any $\delta>0$, $n \geq O(G^2\log(G^2/\delta))$ and $\frac{19G^2\log(n/\delta)}{n}\leq\lambda \leq \|\calc\|$, we have,
     \begin{align*}
         \|\calc_{\lambda}^{1/2}\cdot\calc_{n\lambda}^{-1/2}\| < 2
     \end{align*}
     with probability $1-\delta$.
\end{lemma}
The assumption on $n$ can be removed, (see Lemma 5.3 in \cite{lin2020optimal}) but leads to a more complicated upper bound depending on $G^2$ in place of constant $2$. In this work, we are interested in a large $n$ regime and therefore assume $n \geq O(G^2\log(G^2/\delta))$ obtaining a constant upper bound.
\begin{lemma}[Proposition 1 from \cite{rudi2015less}]
If assumptions \ref{as:1} and \ref{as:4} hold, then for any $\delta>0$, $n =O(G^2\log(G^2/\delta))$ and $\frac{19G^2\log(n/\delta)}{n}\leq\lambda \leq \|\calc\|$, we have,
 \begin{align*}
     d_{n\lambda}(\K) \leq 3\mathcal{N}(\lambda)
 \end{align*}
with probability $1-\delta$.
\end{lemma}
The next two results are essentially taken from \cite{lin2020optimal} and upper bound the true bias and the sample variance terms in our analysis.


\begin{lemma}[Adapted from Lemma 5.2 in \cite{lin2020optimal}]\label{l:true_bias}
Let $0\leq a \leq \zeta$ and $\omega=\calc_\lambda^{-1}\cals_\rho^*f_\calh$. Under assumption \ref{as:3}
    \begin{align*}
        \big\|\call^{-a}(\cals_\rho\omega-f_\calh)\big\|_\rho \leq R\lambda^{\zeta-a}.
    \end{align*}
\end{lemma}


\begin{lemma}[Adapted from Lemma 5.6 in \cite{lin2020optimal}]\label{l:sample_variance} Let $\hat\y = \y/\sqrt{n}$ and $\omega=\calc_\lambda^{-1}\cals_\rho^*f_\calh$. Then under assumptions \ref{as:1}, \ref{as:2}, \ref{as:3}, \ref{as:4} for any $\delta>0$
    \begin{align*}
        \big\|\calc_{n\lambda}^{-1/2}[\cals_n^*\hat\y-\calc_n\omega]\big\|_{\calh} \leq C'\Big(\lambda^\zeta + \frac{1}{n\lambda^{\max(1/2,1-\zeta)}} + \frac{1}{\sqrt{n\lambda^{\gamma}}} \Big)\log(1/\delta)
    \end{align*}
    with probability $1-\delta$. The constant $C'$ depends on $R,G,M,C,c_\gamma,\zeta,$ and $\sigma^2$.
\end{lemma}

\section{Spectral approximation with Block-Nystr\"om}
\label{a:concentration}
We start this section by proving the spectral approximation guarantee (\ref{eq:approx}) provided by the Block-Nystr\"om approximation of $\A$.
\begin{theorem}[Spectral approximation with  Block-Nystr\"om (Restated Theorem \ref{t:Nys_spectral_approximation})]\label{t:Nys_spectral_approximation_2}
    Let $\lambda>0$ be fixed and $\lambda'>\lambda$. Let $\{p_i\}_{i=1}^n$ denote the $O(1)$-approximate $\lambda'$-ridge leverage scores of $\A$. Let $\hat\A_{[q]}=\frac{1}{q}\sum_{i=1}^{q}{\hat\A_i}$ where $\hat\A_i$'s are iid Nystr\"om approximations of $\A$ sampled independently from $\{p_i\}_{i=1}^n$, each with $\tilde O(d_{\lambda'}(\A)\log(n/\delta))$ landmarks and $\A_\lambda= \A+\lambda\I$.
    Then with probability $1-\delta$,
    \begin{align*}
\|\A_{\lambda}^{1/2}\big(\hat\A_{[q]} +\lambda\I\big)^{-1}\A_{\lambda}^{1/2}\| \leq 16\sqrt{\frac{\lambda'}{\lambda}}
    \end{align*}
    if $q > 64\sqrt{\frac{\lambda'}{\lambda}}\log(n/\delta)$.
\end{theorem}
\begin{proof}
    Define random matrices $\Z_i = \A_{\lambda}^{-1/2}(\hat\A_i +\lambda\I)\A_{\lambda}^{-1/2}$, where  $\hat\A_{i} = \A\S_i^\top(\S_i\A\S_i^\top)^\dagger\S_i\A $ and $\A_\lambda=\A+\lambda\I$. Here each $\S_i$ is a sub-sampling matrix corresponding to a set drawn independently from $\{1,2,\cdots,n\}$ with probability distribution $\{p_i\}_{i=1}^n$. As $\hat\A_i \preceq \A$ for all $i$, we have $\Z_i \preceq \I$ for all $i$. Therefore $\|\Z_i\| \leq 1:=R$. Let $\mu_{\min}$ denote the minimum eigenvalue of $\E\Z_i$. We have,
    \begin{align*}
        \mu_{\min} &= \lambda_{\min}(\A_{\lambda}^{-1/2}\E[\hat\A_i+\lambda\I]\A_{\lambda}^{-1/2})\\
&\geq\frac{1}{2}\lambda_{\min}\Big(\A_{\lambda}^{-1/2}\big(\A\A_{\lambda'}^{-1}\A+\lambda\I\big)\A_{\lambda}^{-1/2}\Big)\\
&=\frac{1}{2}\min_{j}\Big(\frac{1}{\lambda_j+\lambda}\cdot\big(\frac{\lambda_j^2}{\lambda_j+\lambda'}+\lambda\big)\Big)\\
&=\frac{1}{2}\min_{j}\Big(\frac{\lambda_j^2+\lambda\lambda_j+\lambda\lambda'}{\lambda_j^2+\lambda\lambda_j +\lambda'\lambda_j +\lambda\lambda'}\Big)
    \end{align*}
   The second inequality holds due to Lemma \ref{rls-projection} as $\E\hat\A_{i} \succeq \frac{1}{2}\A(\A+\lambda'\I)^{-1}\A$. Considering $\lambda_j$ as a variable $x$, a routine calculus exercise shows that the minimum is attained when $x = \sqrt{\lambda\lambda'}$. Therefore, we get,
    \begin{align*}
        \mu_{\min} \geq \frac{1}{2}\frac{\lambda\lambda' + \lambda\sqrt{\lambda\lambda'} + \lambda\lambda'}{\lambda\lambda' + \lambda\sqrt{\lambda\lambda'} + \lambda'\sqrt{\lambda\lambda'} + \lambda\lambda'} \geq \frac{1}{2}\frac{\lambda\lambda'}{4\lambda'\sqrt{\lambda\lambda'}} = \frac{1}{8}\sqrt{\frac{\lambda}{\lambda'}}.
    \end{align*}
    Applying matrix Chernoff concentration inequality we get
    \begin{align*}
        \Pr\Big(\lambda_{\min}\big(\frac{1}{q}\sum_{i=1}^{q}{\Z_i}\big) \leq (1-\epsilon)\mu_{\min}\Big) \leq n\cdot\exp\Big(-\frac{\epsilon^2q\mu_{\min}}{2R}\Big).
    \end{align*}
    Substitute $R=1$ and $\epsilon=\frac{1}{2}$, we get if $q>64\sqrt{\frac{\lambda'}{\lambda}}\log(n/\delta)$, then with
    probability $1-\delta$ $\lambda_{\min}\big(\frac{1}{q}\sum_{i=1}^{q}{\Z_i}\big) \geq \frac{\mu_{\min}}{2}.$
    This gives us
\vspace{-2mm}    \begin{align*}
        \frac{1}{16}\sqrt{\frac{\lambda}{\lambda'}}\A_{\lambda} \preceq \frac{1}{q}\sum_{i=1}^{q}{\hat\A_{i}+\lambda\I} \preceq \A_{\lambda},
    \end{align*}
and finishes the proof.
\end{proof}
The following result is needed in the proof of our recursive solver for inverting Block-Nystr\"om.
\begin{theorem}[Matrix concentration for Block-Nystr\"om]\label{t:exp_nys_con}
Let $\lambda'>0$ and for $1 \leq i \leq q$, let $\hat\A_i$ be Nystr\"om approximations of $\A$ sampled from $O(1)$-approximate $\lambda'$-ridge leverage scores of $\A$, each with $\tilde O(d_{\lambda'}(\A)\log(n/\delta))$ landmarks. Then for any $\lambda>0$ satisfying $\lambda \leq \lambda'$ and for any $0<\theta<1$, $q>\frac{200\sqrt{\lambda'/\lambda}\log(2n/\delta)}{\theta^2}$, with probability $1-\delta$ we get
\begin{align*}
   (1-\theta/2)(\E\hat\A+\lambda\I)\preceq   \frac{1}{q}\sum_{i=1}^{q}{\hat\A_i+\lambda\I} \preceq (1+\theta/2)(\E\hat\A +\lambda\I).
\end{align*}
\end{theorem}


\begin{proof}
First note that due to Lemma \ref{rls-projection},
$\big(\E\hat\A_{i} +\lambda\I\big)^{-1} \preceq 2\big(\A\A_{\lambda'}^{-1}\A+\lambda\I\big)^{-1}$. Define $\Z_i = (\E\hat\A+\lambda\I)^{-1/2}(\hat\A_i+\lambda\I)(\E\hat\A+\lambda\I)^{-1/2}$. We have $\E[\Z_i] =\I$ and therefore $\mu_{\max}(\E\Z_i) = \mu_{\min}(\E\Z_i)=1$, where $\mu_{\max}$ and $\mu_{\min}$ denotes the maximum and minimum eigenvalues of $\E\Z_i$. Now we upper bound $\|\Z_i\|$. Let $\A_\lambda=\A+\lambda\I$.
\begin{align*}
    \|\Z_i\|
    &\leq \|(\E\hat\A+\lambda\I)^{-1/2}(\A+\lambda\I)(\E\hat\A+\lambda\I)^{-1/2}\|\\
&\leq2\lambda_{\max}\Big(\A_\lambda^{1/2}(\E\hat\A+\lambda\I)^{-1}\A_\lambda^{1/2}\Big)\\
&\leq2\max_{i}\Big(\frac{\lambda_i+\lambda}{\frac{\lambda_i^2}{\lambda_i+\lambda'}+\lambda}\Big)\\
&=2\max_{i}\Big(\frac{1+\frac{\lambda}{\lambda_i}}{\frac{\lambda_i}{\lambda_i+\lambda'} + \frac{\lambda}{\lambda_i}}\Big) :=\xi_{i}.
\end{align*}
Note that if $\lambda_i\geq\lambda'$, then $\xi_i <3$. In case $\lambda_i < \lambda'$, we write $\lambda_i =c_i\lambda_n$ for some $c_i \geq 1$. We have
\begin{align*}
    \xi_i &<  \frac{1+\frac{\lambda}{\lambda_i}}{\frac{\lambda_i}{2\lambda'} + \frac{\lambda}{\lambda_i}}= \frac{1+\frac{\lambda}{c_i\lambda_n}}{\frac{c_i\lambda_n}{2\lambda'} + \frac{\lambda}{c_i\lambda_n}}
\end{align*}
and consider the following two cases:
\begin{enumerate}
    \item \emph{Case 1:} $\frac{c_i\lambda_n}{2\lambda'} \geq \frac{\lambda}{c_i\lambda_n}$ or $c_i \geq \frac{\sqrt{2\lambda\lambda'}}{\lambda_n}$. Then
    \begin{align*}
        \xi_i &< \frac{1+\frac{\lambda}{c_i\lambda_n}}{\frac{c_i\lambda_n}{2\lambda'}}< 1+ \frac{2\lambda'}{c_i\lambda_n}\leq 1+\sqrt{\frac{2\lambda'}{\lambda}}.
    \end{align*}
    \item \emph{Case 2:}  $\frac{c_i\lambda_n}{2\lambda'} < \frac{\lambda}{c_i\lambda_n}$ or $c_i < \frac{\sqrt{2\lambda\lambda'}}{\lambda_n}$. Then
    \begin{align*}
        \xi_i &<  \frac{1+\frac{\lambda}{c_i\lambda_n}}{\frac{\lambda}{c_i\lambda_n}}< 1+ \sqrt{\frac{2\lambda'}{\lambda}}.
    \end{align*}
\end{enumerate}
Therefore  $\|\Z_i\| < 2\max\Biggr\{3, 1+ \sqrt{\frac{2\lambda'}{\lambda}}\Biggr\} < 20\sqrt{\frac{\lambda'}{\lambda}}:=R$. Using matrix Chernoff inequality, for any $\theta >0$
\begin{align*}
    \Pr\left(\lambda_{\min}\left(\frac{1}{q}\sum_{i=1}^{q}{\Z_i}\right) \leq 1-\theta/2\right) \leq n.\exp\left(-\frac{q\theta^2}{8R}\right),
\end{align*}
and,
\begin{align*}
     \Pr\left(\lambda_{\max}\left(\frac{1}{q}\sum_{i=1}^{q}{\Z_i}\right) \geq 1+\theta/2\right) \leq n.\exp\left(-\frac{q\theta^2}{(8+2\theta)R}\right).
\end{align*}
For any $\theta<1$ and $q>200\sqrt{\lambda'/\lambda}\log(2n/\delta)/\theta^2$, with probability $1-\delta$
\begin{align*}
    -\theta/2\I\preceq \frac{1}{q}\sum_{i=1}^{q}{\Z_i} -\I \preceq \theta/2\I.
\end{align*}
and finally with probability $1-\delta$
\begin{align*}
   (1-\theta/2)(\E\hat\A+\lambda\I)\preceq   \frac{1}{q}\sum_{i=1}^{q}{\hat\A_{i}+\lambda\I} \preceq (1+\theta/2)(\E\hat\A +\lambda\I).
\end{align*}
\end{proof}
We use the following result from \cite{dmy24} as a black box in our recursive preconditioning scheme for solving the Block-Nystr\"om linear system approximately. The following lemma provides an algorithm to solve the resulting linear system at the final depth of our recursive scheme.
    \begin{lemma}[Based on Lemma 4.3 from \cite{dmy24}]\label{l:dmy_Nystrom_solve}
Given matrix $\A \succ 0$, let $\hat\A = \C\W^{\dagger}\C^\top$ be its Nystr\"om approximation where $\C=\A\S^\top \in \R^{n\times m}$ and $\W=\S\A\S^\top$. For $\psi>0$, denote $\M=\hat\A + \psi\I$ as the Nystr\"om preconditioner and assume that $\M\approx_{O(\kappa)} \A+\psi\I$. Given vector $\v \in \R^n$ and $\epsilon>0$, there exists an algorithm that provides $\hat\w$: an approximate solution to the linear system $\M\w=\v$ satisfying
\begin{align*}
    \|\hat\w-\M^{-1}\v\|_{\M} \leq \epsilon\|\M^{-1}\v\|_{\M}.
\end{align*}
in time $O((nm+m^3)\log(m/\delta) + (nm+m^2)\log(\kappa/\epsilon))$, where $\kappa$ is the condition number of $\A$.

\end{lemma}
The following lemma is a computational result we use in our proof of Theorem \ref{t:linear_system_solve_2}.
\begin{lemma}\label{l:c_bound}
For any $x,\phi,\theta >0$, $c>1$ and $p=c(1+\theta)^2$
\begin{align*}
(4(1+\theta)^2)^{\frac{\log(x)}{\log(c)}} &\leq x^{\phi/2}\\
\log(20p^2)^{\frac{\log(x)}{\log(c)}} &\leq (x)^{\phi/2}
    \end{align*}
\end{lemma}
if and only if $c > \max\big((4(1+\theta)^2)^{2/\phi},\log^{2/\phi}(20p^2),1\big)$.
\begin{proof}
    \begin{align*}
(4(1+\theta)^2)^{\frac{\log(x)}{\log(c)}} = x^{\frac{\log(4(1+\theta)^2)}{\log(c)}} \leq x^{\phi/2}
    \end{align*}
    if and only if $c \geq (4(1+\theta)^2)^{2/\phi}.$
    Furthermore for $p=c(1+\theta)^2$,
    \begin{align*}
\log(20p^2)^{\frac{\log(x)}{\log(c)}} \leq (x)^{\phi/2}
    \end{align*}
    if and only if $c \geq \log^{2/\phi}(20p^2)$.
\end{proof}
The following theorem is an extended version of Theorem \ref{t:linear_system_solve}. The statement of Theorem \ref{t:linear_system_solve} can be recovered by setting $\tilde\lambda=\lambda$. We provide a recursive preconditioning scheme for solving the Block-Nystr\"om linear system having near-linear dependence on the number of blocks $q$.
\begin{theorem}[Recursive solver for Block-Nystr\"om ]\label{t:linear_system_solve_2}
Given $\lambda,\tilde\lambda$ and $\lambda'$ satisfying $\lambda \leq \tilde\lambda \leq \lambda'$, for $1\leq i \leq q$ let $\hat\A_i$  are Nystr\"om approximations of $\A$ sampled from $O(1)$-approximate $\lambda'$-ridge leverage scores of $\A$, each with $m=O(d_{\lambda'}(\A)\log(n/\delta))$ landmarks and let $q = O\big(\sqrt{\frac{\lambda'}{\tilde\lambda}}\log(n/\delta)/\theta^2\big)$. Denote $\hat\A_{[q]} =  \frac{1}{q}\sum_{i=1}^{q}{\hat\A_{i}}$. There exists an event with probability $1-\delta$ for any $\delta>0$ such that for any $\v \in \R^n$, $\epsilon>0$ and $0<\phi<1$ we can find $\u \in \R^n$ such that
\begin{align*}
    \|\u-\big(\hat\A_{[q]} +\lambda\I\big)^{-1}\v\|_{\hat\A_{[q]} +\lambda\I}^2 \leq \epsilon\cdot \|\big(\hat\A_{[q]} +\lambda\I\big)^{-1}\v\|_{\hat\A_{[q]} +\lambda\I}^2
\end{align*}
in time $O\Big(\sqrt{\tilde\lambda/\lambda}\cdot nmq^{1+\phi}\cdot cs_1s_2k\log(1/\epsilon)\Big)$, where $k=\max\Big\{1,\Big\lceil\log\big(\sqrt{\lambda'/\tilde\lambda}\big)/\log(c)\Big\rceil\Big\}$, $s_1 = \max\big(1,\log\Big(\tilde\lambda/\lambda\Big)\big)$, $s_2 = \log(m\kappa/\delta)\log^{3/2}(n/\delta)\log(20c^2(1+\theta)^4)$, and $c$ is chosen so that \\ $c \geq \lceil \max\Big((4(1+\theta)^2)^{2/\phi}, \log^{2/\phi}(20c^2(1+\theta)^4\Big) \Big\rceil.$
    \end{theorem}

\begin{proof}
Let $\epsilon>0$, $\theta>0$ be fixed and some $c>1$  (to be determined later). Let $r_k = \lambda'/(c^{2k}\tilde\lambda)$ where $k\geq 0$ is an integer. Furthermore let $q_k = O(\sqrt{r_k}\log(n/\delta)/\theta^2)$. We have $\hat\A_{[q]} +\lambda\I =  \frac{1}{q_0}\sum_{i=1}^{q_0}{\hat\A_{i} + \lambda\I}$. Let $\M_k=\frac{1}{q_k}\sum_{i=1}^{q_k}{\hat\A_{i}+\frac{\lambda'}{r_k}\I}$. Note that
\begin{align*}
  (\lambda/\tilde\lambda)\M_0\preceq \hat\A_{[q]} +\lambda\I \preceq \M_0.
\end{align*}
Using Lemma \ref{l:pcg}, for any given $\v$ we can find $\u \in \R^n$ such that $\|\u-\big(\hat\A_{[q]} +\lambda\I\big)^{-1}\v\|_{\hat\A_{[q]} +\lambda\I}^2 \leq \epsilon\|\big(\hat\A_{[q]} +\lambda\I\big)^{-1}\v\|_{\hat\A_{[q]} +\lambda\I}^2$ in time $4\sqrt{\tilde\lambda/\lambda}\big(T(\M_0) + q_0nm\big)\log(2/\epsilon) + n\sqrt{\tilde\lambda/\lambda}\log(1/\epsilon)$, where $T(\M_0)$ is time complexity to find a $\u$ given $\v$ such that $\|\u-\M_0^{-1}\v\|_{\M_0}^{2} \leq \frac{\lambda}{10\tilde\lambda}\|\M_0^{-1}\v\|_{\M_0}^2$. The total time complexity is given as
\begin{align}
O\Big(\sqrt{\tilde\lambda/\lambda}\big(T(\M_0) + q_0nm)\log(1/\epsilon)\Big) \label{e:total_time_recursion}
\end{align}
Now note that according to Theorem \ref{t:exp_nys_con} and our choices of $q_0$ and $q_1$, with probability $1-\delta/n$
\begin{align*}
    \M_0 \preceq (1+\theta)\Big(\E\hat\A + \frac{\lambda'}{r_0}\I\Big) \preceq (1+\theta)\Big(\E\hat\A + \frac{\lambda'}{r_1}\I\Big)\preceq (1+\theta)^2\M_1.
\end{align*}
Furthermore,
\begin{align*}
    \M_0 \succeq \frac{1}{1+\theta}\Big(\E\hat\A + \frac{\lambda'}{r_0}\I\Big)\succeq \frac{1}{c^2(1+\theta)}\Big(\E\hat\A + \frac{\lambda'}{r_1}\I\Big) \succeq \frac{1}{c^2(1+\theta)^2}\M_1.
\end{align*}
Again using Lemma \ref{l:pcg} we get
\begin{align}
    T(\M_0) &\leq 4c(1+\theta)^2\big(T(\M_1) + q_0nm\big)\log(20\tilde\lambda/\lambda) + nc(1+\theta)^2\log(10\tilde\lambda/\lambda) \nonumber\\
    &=O\Big((T(\M_1) + q_0nm)cs_1\Big).\label{e:tm0}
\end{align}
where $s_1 = \log(20\tilde\lambda/\lambda)$. Here $T(\M_1)$ is time complexity to find a $\u$ given $\v$ such that $\|\u-\M_1^{-1}\v\|^2_{\M_1} \leq \frac{1}{10c^2(1+\theta)^4}\|\M_1^{-1}\v\|^2_{\M_1}$. Similar as above we can show that
\begin{align*}
   \frac{1}{c^2(1+\theta)^2}\M_2 \preceq \M_1 \preceq (1+\theta)^2\M_2
\end{align*}
upper bounding $T(\M_1)$ as
\begin{align*}
    T(\M_1) \leq 4c(1+\theta)^2\big(T(\M_2) + q_1nm\big)\log(20c^2(1+\theta)^4) + nc(1+\theta)^2\log(10c^2(1+\theta)^4).
\end{align*}
Now recursively continuing in this manner by conditioning over high probability events $ \frac{1}{1+\theta}\E[\M_k]\preceq \M_k \preceq (1+\theta)\E[\M_k]$ according to Theorem \ref{t:exp_nys_con}, we get
\begin{align*}
    T(\M_k) \leq 4c(1+\theta)^2\big(T(\M_{k+1}) + q_knm\big)\log(20c^2(1+\theta)^4) + nc(1+\theta)^2\log(10c^2(1+\theta)^4).
\end{align*}
In fact, we can show that for $p=c(1+\theta)^2$
\begin{align*}
    T(\M_1) &\leq 4^kp^k\log^k(20p^2)T(\M_{k+1}) + nm\sum_{i=1}^{k}{4^{i}q_{i}p^i\log^{i}(20p^2)} + \frac{n}{4}\sum_{i=1}^{k}{4^{i}p^{i}\log^i(20p^2)} \nonumber\\
     &\leq 4^kp^k\log^k(20p^2)T(\M_{k+1}) + 2nmq_0\sum_{i=1}^{k}{\Big(\frac{4p\log(20p^2)}{c}\Big)^{i}}\\
     &\leq  4^kp^k\log^k(20p^2)T(\M_{k+1}) + 2knmq_0\cdot\big(4(1+\theta)^2\big)^k\cdot\big(\log(20p^2)\big)^k.
\end{align*}
In second to last inequality we used $q_i \geq 1$ for all $i$ and the formula $q_i = q_0/c^{i}$. Choose $k$ such that $r_{k+1}<2$ i.e., $k= \Big\lceil\frac{\log\sqrt{\lambda'/\tilde\lambda}}{\log(c)}\Big\rceil$ is sufficient. Now, let $c \geq \max\Big\{(4(1+\theta)^2)^{2/\phi}, \log^{2/\phi}(20p^2)\Big\}.$ Using Lemma \ref{l:c_bound} we get
\begin{align}
    T(\M_1) &\leq  4^kp^k\log^k(20p^2)T(\M_{k+1}) + 2knmq_0\cdot\Big(\sqrt{\frac{\lambda'}{\tilde\lambda}}\Big)^\phi \nonumber \\
    &= \frac{q_0}{q_k}\cdot\big(4(1+\theta)^2\big)^k\cdot\big(\log(20p^2)\big)^k\cdot T(\M_{k+1})   + 2knmq_0\cdot\Big(\sqrt{\frac{\lambda'}{\tilde\lambda}}\Big)^\phi \nonumber\\
    &\leq \Big(T(\M_{k+1}) + 2knm\Big)\cdot q_0^{1+\phi} \label{e:recursion}
\end{align}
where in the last inequality we used $\sqrt{\frac{\lambda'}{\tilde\lambda}} < q_0$. Now we precondition $\M_{k+1}$ with $\hat\A_1 + \frac{\lambda'}{r_{k+1}}\I$. As we have
\begin{align*}
    \frac{1}{q_{k+1}}\Big(\hat\A_1 + \frac{\lambda'}{r_{k+1}}\I\Big) \preceq \M_{k+1} \preceq \A+\frac{\lambda'}{r_{k+1}}\I \preceq \A+\lambda'\I \preceq 2(\hat\A_1+\lambda'\I) \preceq 4\Big(\hat\A_1+\frac{\lambda'}{r_{k+1}}\I\Big).
\end{align*}
where the second last inequality holds with probability $1-\delta/n$, due to Lemma \ref{l:musco-approx}. Using Lemma \ref{l:pcg} we get
\begin{align*}
    T(\M_{k+1}) \leq 8\sqrt{q_{k+1}}\big(T(\hat\A_1) + q_{k+1}nm\big)\log(20p^2) + 2n\sqrt{q_{k+1}}\log(10p^2)
\end{align*}
where $T(\hat\A_1)$ is the time complexity to find a $\u$ given $\v$ such that $\Big\|\u-\Big(\hat\A_1+\frac{\lambda'}{r_{k+1}}\I\Big)^{-1}\v\Big\|^2_{\hat\A_1+\lambda'/r_{k+1}\I} \leq \frac{1}{40q_{k+1}}\Big\|\Big(\hat\A_1+\frac{\lambda'}{r_{k+1}}\I\Big)^{-1}\v\Big\|^2_{\hat\A_1+\lambda'/r_{k+1}\I}.$ It only remains to upper bound $T(\hat\A_1)$. We apply Lemma \ref{l:dmy_Nystrom_solve} to upper bound $T(\hat\A_1)$. Let $\psi= \lambda'/r_k$ and apply Lemma \ref{l:dmy_Nystrom_solve} with $\M=\hat\A_1 + \psi\I$, we get that $\M^{-1}\x$ can be solved approximately in time $O\Big(nm\log(m\kappa/\delta)\Big)$, thus upper bounding $T(\hat\A_1)$. Substituting this in expression for $T(\M_{k+1})$ we get
\begin{align*}
    T(\M_{k+1}) &= O\Big((q_{k+1}nm)\log(m\kappa/\delta)\sqrt{q_{k+1}}\log(20p^2)\Big)\\
    &=O\Big(nm\log(m\kappa/\delta)\log^{3/2}(n/\delta)\log(20p^2)\Big)
\end{align*}
Denoting $s_2 = \log(m\kappa/\delta)\log^{3/2}(n/\delta)\log(20p^2)$ and substituting the upper bound for $T(\M_{k+1})$ in (\ref{e:recursion}) we get
\begin{align*}
    T(\M_1) =O\Big(\big(nms_2 + 2knm\big)\cdot q_0^{1+\phi}\Big).
\end{align*}
Back substituting the above in (\ref{e:tm0}) we get
\begin{align*}
    T(\M_0) = O\Big(\big(nms_2 + 2knm\big)\cdot q_0^{1+\phi}\cdot cs_1 + nmq_0\cdot cs_1\Big)
\end{align*}
Finally substituting the above in expression (\ref{e:total_time_recursion}), the overall time complexity is given as
\begin{align*}
&O\Big(\sqrt{\tilde\lambda/\lambda}\big(\big(nms_2 + 2knm\big)\cdot q_0^{1+\phi}\cdot cs_1 + nmq_0\cdot cs_1 + q_0nm\big)\log(1/\epsilon)\Big)\\
=&O\Big(\sqrt{\tilde\lambda/\lambda}\cdot nmq_0^{1+\phi}\cdot cs_1s_2k\log(1/\epsilon)).
\end{align*}
Taking the union bound over all the considered high probability events finishes the proof.
\end{proof}

\section{Statistical risk of KRR in random design setting}\label{s:appendix_krr}
Consider the Hilbert space $L^2(\calh,\rho_\calx)$ consisting of square integrable functions from $\calh$ to $\R$, i.e., $L^2(\calh,\rho_\calx) = \{f: \calh \rightarrow \R \ | \int_{\calh}{f(\x)^2d\rho_\calx(\x) < \infty}\}$. The norm on $L^2(\calh,\rho_\calx)$ will be denoted by $\|\cdot\|_\rho$, and for any $f \in  L^2(\calh,\rho_\calx)$ we have $\|f\|_\rho = \Big(f(\x)^2d\rho_\calx(\x)\Big)^{1/2}$. Let $\cals_\rho: \calh \rightarrow L^2(\calh,\rho_\calx)$ be the map $\cals_\rho\omega = \langle\cdot,\omega\rangle_\calh$ and $\cals_\rho^*: L^2(\calh,\rho_\calx) \rightarrow \calh$ be the adjoint map of $\cals_\rho$. The covariance operator $\cals_\rho^*\cals_\rho : \calh \rightarrow \calh$ will be denoted as $\calc$, whereas the integral operator $\cals_\rho\cals_\rho^* : L^2(\calh,\rho_\calx) \rightarrow L^2(\calh,\rho_\calx)$ will be denoted as $\call$. Under assumption \ref{as:1}, $\calc$ and $\call$ are positive, self-adjoint, and bounded linear operators. Let $\calz_n: \calh \rightarrow \R^n $ as $\calz_n\omega = \big(\langle\x_i,\omega\rangle\big)_{i=1}^{n}$ and $\cals_n = \calz_n/\sqrt{n}$. The operator $\cals_n^*\cals_n: \calh\rightarrow\calh$ is known as the empirical covariance operator and will be denoted by $\calc_n$. Note that $\calz_n^*\calz_n = n\calc_n$. An important observation here is that the operator $\calz_n\calz_n^* : \R^n \rightarrow \R^n$ is the linear map $\alpha \rightarrow \K\alpha$ where $\K \in \R^{n\times n}$ is the kernel matrix over the $n$ points $\x_i$ for $1\leq i \leq n$. For $\lambda>0$, the regularized operators $\calc+\lambda\mathcal{I}$, $\calc_n+\lambda\mathcal{I}$ will be denoted by $\calc_\lambda$ and $\calc_{n\lambda}$ respectively.
The following provides further intuition on the various operators considered in the analysis of statistical risk of KRR:
\begin{itemize}
    \item For any $g \in L^2(\calh,\rho_\calx)$, $\cals_\rho^* g = \int_\calh{\x g(\x)d\rho_\calx(\x)}$, $\call g = \int_\calh{\langle\cdot,\x\rangle_\calh g(\x)d\rho_\calx(\x)}$.
    \item For any $\omega \in \calh$, $\cals_\rho^*\cals_\rho\omega = \int_{\calh}{\langle\cdot,\omega\rangle_\calh\x d\rho_\calx(\x)}$, $\cals_n^*\cals_n\omega = \frac{1}{n}\sum_{i=1}^{n}{\langle\x_i,\omega\rangle_\calh\x_i}.$
    \item For any $\alpha \in \R^n$, $\calz_n^*\alpha = \sum_{i=1}^{n}{\alpha_i\x_i}$ and $\calz_n\calz_n^*\alpha = \K\alpha$.
\end{itemize}
The following lemma provide two different ways to represent the hypothesis $\hat\omega$ learned by the classical Nystr\"om KRR.
\begin{lemma}[Representations of learned hypothesis]\label{l:omega_rep}
Let $\hat\K$ be an $m$-rank Nystr\"om approximation of $\K$. Let $\hat\calp$ denote the projection operator onto the corresponding subspace $\calh_m$. Then the hypothesis learned by classical Nystr\"om KRR is given as
    \begin{align*}
        \hat\omega &= \hat\calp\calz_n^*\big(\hat\K+n\lambda\I\big)^{-1}\y\\
        &=\hat\calp\calz_n^*(\calz_n\hat\calp\calz_n^* + n\lambda\I)^{-1}\y\\
&=\hat\calp(\hat\calp\calz_n^*\calz_n\hat\calp +n\lambda\mathcal{I})^{-1}\hat\calp\calz_n^*\y.
    \end{align*}
\end{lemma}
\begin{proof}
Recall that
\begin{align*}
    \tilde{\mathcal{E}}(\omega,\lambda) = \frac{1}{n}\sum_{i=1}^{n}{(\langle\omega,\x_i\rangle_{\calh}-y_i)^2} +\lambda\|\omega\|_\calh^2.
\end{align*}
Let $\hat\omega$ be the minimizer of $  \tilde{\mathcal{E}}(\omega,\lambda)$. First note $\calz_n\hat\omega = \big(\langle\hat\omega,\x_i\rangle_{\calh}\big)_{i=1}^{n}$. Substituting $\hat\omega=\calz_n^*\S^\top\hat\w$ where $\S\in\R^{m\times n}$ is a random sketching matrix, we get $\calz_n\calz_n^*\S^\top\hat\w = \big(\langle\hat\omega,\x_i\rangle_{\calh}\big)_{i=1}^{n}$. Therefore $\sum_{i=1}^{n}{(\langle\hat\omega,\x_i\rangle_{\calh}-y_i)^2} = \|\K\S^\top\hat\w-\y\|^2$, by noting $\calz_n\calz_n^*=\K$. In particular $\hat\w$ is the solution of the system $(\S\K^2\S^\top +n\lambda\S\K\S^\top)\hat\w=\S\K\y$, implying,
    \begin{align*}
      \hat\w =  (\S\K^2\S^\top +n\lambda\S\K\S^\top)^\dagger\S\K\y.
    \end{align*}
    The learned $\hat\omega$ is given as
    \begin{align*}
        \hat\omega &= \calz_n^*\S^\top(\S\K^2\S^\top +n\lambda\S\K\S^\top)^\dagger\S\K\y\\
        &=\calz_n^*\S^\top(\S\calz_n(\calz_n^*\calz_n +n\lambda\mathcal{I})\calz_n^*\S^\top)^\dagger\S\calz_n\calz_n^*\y\\
&=\calz_n^*\S^\top(\S\calz_n(\S\calz_n^\dagger)\S\calz_n(\calz_n^*\calz_n +n\lambda\mathcal{I})\calz_n^*\S^\top(\calz_n^*\S^\top)^\dagger\calz_n^*\S^\top)^\dagger\S\calz_n\calz_n^*\y\\
&=\calz_n^*\S^\top(\S\calz_n(\hat\calp\calz_n^*\calz_n\hat\calp+n\lambda\mathcal{I})\calz_n^*\S^\top)^\dagger\S\calz_n\calz_n^*\y\\
&=\hat\calp(\hat\calp\calz_n^*\calz_n\hat\calp+n\lambda\mathcal{I})^{-1}\hat\calp\calz_n^*\y.
\end{align*}
The second last equality holds because $\calz_n^*\S^\top(\calz_n^*\S^\top)^\dagger$ and $(\S\calz_n)^\dagger\S\calz_n$ are orthogonal projections on $\calh_m$. Furthermore using the push-through identity we have $(\hat\calp\calz_n^*\calz_n\hat\calp+n\lambda\mathcal{I})^{-1}\hat\calp\calz_n^* = \hat\calp\calz_n^*(\calz_n^*\hat\calp\calz_n+n\lambda\I)^{-1}\y$ leading to
\begin{align*}
\hat\omega&=\hat\calp\calz_n^*(\calz_n\hat\calp\calz_n^*+n\lambda\I)^{-1}\y\\
&=\hat\calp\calz_n^*\big(\hat\K +n\lambda\I\big)^{-1}\y.
\end{align*}
The last equality holds because $\hat\K=\calz_n\hat\calp\calz_n^*$.
\end{proof}
A similar representation like Lemma \ref{l:omega_rep} holds for Block-Nystr\"om KRR as shown before the proof of Theorem \ref{t:main_stat_risk_2}. In the next result, we first show that for any given $\x$ in $\calh$, the output $y$ can be predicted in time linear in number of blocks, provided the Block Nystr\"om hypothesis has been precomputed.

\begin{lemma}[Prediction with Block-Nystr\"om]\label{l:prediction}
      For some $q\geq 1$, consider $\calp_{[q]} = \frac{1}{q}\sum_{i=1}^{q}{\hat\calp_i}$ where $\hat\calp_i$ denotes an orthogonal projection onto some $m$ dimensional subspace of $\calh_n$. In particular, $\hat\calp_i = \calz_n^*\S_i^\top(\S_i\K\S_i^\top)^\dagger\S_i\calz_n$ where $\S_i \in \R^{m\times n}$ is a sub-sampling matrix. Let $\hat\omega_{[q]} = \calp_{[q]}\calz_n^*(\hat\K_{[q]} +n\lambda\I)^{-1}\y$ where $\hat\K_{[q]} = \frac{1}{q}\sum_{i=1}^{q}{\hat\K_i+n\lambda\I}$ and $\hat\K_{i} = \calz_n\hat\calp_i\calz_n^*$ are iid Nystr\"om approximations of $\K$. Then for any $\x \in \calh$,  $\langle\hat\omega_{[q]},\x\rangle_\calh$ can be computed in time $O(qm)$ after a preprocessing cost of $\tilde O\Big(qm^3 + nmq^{1+o(1)}\Big)$, assuming $(\hat\K_{[q]} +n\lambda\I)^{-1}\y$ can be computed in time $\tilde O(nmq^{1+o(1)}).$
\end{lemma}
\begin{proof} Given any $\x \in \calh$, we can predict the response $y$ for $\x$ by computing $\langle\hat\omega_{[q]},\x\rangle_\calh$ as follows.
\begin{align*}
    \langle\omega_{[q]},\x\rangle_\calh &= \frac{1}{q}\sum_{i=1}^{q}{\langle\hat\calp_i\calz_n^*(\hat\K_{[q]}+n\lambda\I)^{-1}\y,\x\rangle_\calh}\\
    &=\frac{1}{q}\sum_{i=1}^{q}{\langle\calz_n^*\S_i^\top(\S_i\K\S_i^\top)^\dagger\S_i\calz_n\calz_n^*(\hat\K_{[q]}+n\lambda\I)^{-1}\y,\x\rangle_\calh}\\
    &=\frac{1}{q}\sum_{i=1}^{q}{\langle(\S_i\K\S_i^\top)^\dagger\S_i\calz_n\calz_n^*(\hat\K_{[q]}+n\lambda\I)^{-1}\y,\S_i\calz_n\x\rangle}.
\end{align*}
For any fixed $i$, $(\S_i\K\S_i^\top)^\dagger$ can be computed in time $O(m^3)$, $\S_i\calz_n\calz_n^*$ in time $O(nm)$\footnote{We are assuming that $\langle\x_i,\x_j\rangle_\calh$ takes times $O(1)$ for any $1\leq i,j \leq n$.}, and $\S_i\calz_n\calz_n^*(\hat\K_{[q]}+n\lambda\I)^{-1}\y$ in time $O(nm)$ given $\S_i\calz_n\calz_n^*$ and $(\hat\K_{[q]}+n\lambda\I)^{-1}\y$ have been precomputed. For any $\x \in \calh$, $\S_i\calz_n\x$ can be computed in time $O(m)$. The overall preprocessing cost to find $\langle\hat\omega_{[q]},\x\rangle_\calh$ is $\tilde O\Big(qm^3 + nmq^{1+o(1)}\Big)$.
\end{proof}
In Theorem \ref{t:linear_system_solve_2}, we provide a recursive algorithm to approximate $(\hat\K_{[q]}+n\lambda\I)^{-1}\y$ in time $ \tilde O(nmq^{1+o(1)})$ with high precision, for an appropriately chosen $q$ depending on $\lambda$ and sampling distribution for Nystr\"om landmarks. We now provide the proof of statistical risk of Block-Nystr\"om KRR. For $q\geq 1$ and $1\leq i \leq q$, consider $\hat\calp_{i}$ to denote orthogonal projections on $m$ dimensional subspaces of $\calh_n$ sampled in an iid manner and $\hat\K_i = \calz_n\hat\calp_i\calz_n^*$. Let $\hat\calp_{[q]}$ denote the average of $q$ projections i.e., $\hat\calp_{[q]} = \frac{1}{q}\sum_{i=1}^{q}{\hat\calp_i}$ and $\hat\K_{[q]}= \frac{1}{q}\sum_{i=1}^{q}{\hat\K_i}=\calz_n\hat\calp_{[q]}\calz_n^*$. In  Block-Nystr\"om, we consider the following hypothesis in $\calh$
\begin{align*}
    \omega_{[q]} &= \hat\calp_{[q]}\calz_n^*(\hat\K_{[q]} +n\lambda\I)^{-1}\y\\
    &=\hat\calp_{[q]}\calz_n^*(\calz_n\hat\calp_{[q]}\calz_n^* +n\lambda\I)^{-1}\y\\
&=\hat\calp_{[q]}^{1/2}\big(\hat\calp_{[q]}^{1/2}\calz_n^*\calz_n\hat\calp_{[q]}^{1/2}+n\lambda\mathcal{I}\big)^{-1}\hat\calp_{[q]}^{1/2}\calz_n^*\y.
\end{align*}
Recall $f_\rho$ denotes the regression function and $f_\calh$ denotes the projection of $f_\rho$ onto $\bar\calh_\rho$. We define $\omega = \calc_\lambda^{-1}\cals_\rho^*f_\calh$. 

The following theorem provides a more general version of Theorem \ref{t:main_stat_risk}, bounding the generalization error in terms of a range of norms parameterized by $a$, following prior works \citep{lin2020convergences,lin2020optimal}. The bounds in terms of the expected risk stated in Theorem \ref{t:main_stat_risk} can be recovered by taking $a=0$.


\begin{theorem}[Expected risk of approximate KRR, extended Theorem \ref{t:main_stat_risk}]\label{t:main_stat_risk_2}
Under assumptions  \ref{as:1}, \ref{as:2}, \ref{as:3}, \ref{as:4}, \ref{as:5},  $0\leq a \leq \zeta$, $\zeta < \frac{1}{2}$, $n \geq O(G^2\log(G^2/\delta))$ and $\frac{19G^2\log(n/\delta)}{n}\leq\lambda \leq \|\calc\|$. 
   \begin{align*}
    \big\|\call^{-a}(\cals_\rho \omega_{[q]}- f_\calh)\big\|_\rho \leq   \lambda^{-a}\cdot \tilde O\Big(R\lambda^\zeta\big\|\K_{n\lambda}^{1/2}(\hat\K_{[q]}+n\lambda\I)^{-1}\K_{n\lambda}^{1/2}\big\| + \frac{1}{n\lambda^{1-\zeta}} + \frac{1}{\sqrt{n\lambda^{\gamma}}} \Big)
\end{align*}
where $\K_{n\lambda} = \K+n\lambda\I$.
\end{theorem}
\begin{proof}
For simplicity of notation we will denote  $(\hat\K_{[q]}+n\lambda\I) = \bar\K_{n\lambda}$, $\hat\calp_{[q]} = \bar\calp$. We start with the following decomposition:
    \begin{align}
        \big\|\call^{-a}\big(\cals_\rho\omega_{[q]}-f_\calh\big)\big\|_\rho &\leq \big\|\call^{-a}\cals_\rho\big(\omega_{[q]}-\omega\big)\big\|_\rho + \underbrace{\big\|\call^{-a}\big(\cals_\rho\omega-f_\calh)\big\|_\rho}_{\text{True Bias}} \nonumber\\
        &\leq \big\|\call^{-a}\cals_\rho\big(\omega_{[q]}-\omega\big)\big\|_\rho + R\lambda^{\zeta-a} \label{e:risk_1}
    \end{align}
    where in last inequality we used Lemma \ref{l:true_bias} to upper bound the true bias term. Consider the first term now:
    \begin{align}
        \big\|\call^{-a}\cals_\rho\big(\omega_{[q]}-\omega\big)\big\|_\rho &= \big\|\call^{-a}\cals_\rho\calc^{a-1/2}\calc^{1/2-a}\big(\omega_{[q]}-\omega\big)\big\|_\rho \nonumber\\
        &\leq \big\|\call^{-a}\cals_\rho\calc^{a-1/2}\big\|\cdot\big\|\calc^{1/2-a}\big(\omega_{[q]}-\omega\big)\big\|_\calh \nonumber\\
        &\leq \big\|\calc^{1/2-a}\big(\omega_{[q]}-\omega\big)\big\|_\calh. \label{e:risk_2}
    \end{align}
The last inequality is obtained after upperbounding $\big\|\call^{-a}\cals_\rho\calc^{a-1/2}\big\|$ by $1$. Now we substitute for $\omega_{[q]}$. Continuing we have,
\begin{align}
     \big\|\calc^{1/2-a}\big(\omega_{[q]}-\omega\big)\big\|_\calh &= \big\|\calc^{1/2-a}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\y - \omega\big]\big\|_\calh \nonumber\\
     &=\big\|\calc^{1/2-a}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}(\y-\calz_n\omega +\calz_n\omega)-\omega\big]\big\|_\calh \nonumber\\
     &\leq \underbrace{\big\|\calc^{1/2-a}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}(\y-\calz_n\omega)\big]\big\|_\calh}_{\mathcal{T}_v: \text{ Variance}} + \underbrace{\big\|\calc^{1/2-a}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n\omega - \omega\big]\big\|_\calh}_{\mathcal{T}_b: \text{ Bias}}. \label{e:risk_3}
\end{align}
We upper bound the bias and variance terms separately, considering the variance term first:
\begin{align*}
    \mathcal{T}_v &=\big\|\calc^{1/2-a}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}(\y-\calz_n\omega)\big]\big\|_\calh\\
 &=\big\|\calc^{1/2-a}\calc_\lambda^{a-1/2}\calc_\lambda^{1/2-a}\calc_{n\lambda}^{a-1/2}\calc_{n\lambda}^{1/2-a}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}(\y-\calz_n\omega)\big]\big\|_\calh\\
 &\leq \big\|\calc^{1/2-a}\calc_\lambda^{a-1/2}\big\|\cdot\big\|\calc_\lambda^{1/2-a}\calc_{n\lambda}^{a-1/2}\big\|\cdot\big\|\calc_{n\lambda}^{-a}\big\|\cdot\big\|\calc_{n\lambda}^{1/2}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}(\y-\calz_n\omega)\big]\big\|_\calh.
\end{align*}
We have $\big\|\calc^{1/2-a}\calc_\lambda^{a-1/2}\big\| \leq 1$, and $\big\|\calc_\lambda^{1/2-a}\calc_{n\lambda}^{a-1/2}\big\| \leq \big\|\calc_{\lambda}^{1/2}\calc_{n\lambda}^{-1/2}\big\|^{1-2a} \leq 2$ by using Lemma \ref{l:cordes} and Lemma \ref{l:rudi_15_1}. Therefore we get,
\begin{align*}
    \mathcal{T}_v &\leq 2\lambda^{-a}\big\|\calc_{n\lambda}^{1/2}\big[\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}(\y-\calz_n\omega)\big]\big\|_\calh\\
    &=2\lambda^{-a}\big\|\calc_{n\lambda}^{1/2}\big[\bar\calp^{1/2}\bar\calp^{1/2}\calz_n^*(\calz_n\bar\calp^{1/2}\bar\calp^{1/2}\calz_n^*+n\lambda\I)^{-1}(\y-\calz_n\omega)\big]\big\|_\calh.
\end{align*}
In the last equality we substituted $\bar\K_{n\lambda}^{-1} = (\calz_n\bar\calp\calz_n^*+n\lambda\I)^{-1}$. Using push-through identity we have $\bar\calp^{1/2}\calz_n^*(\calz_n\bar\calp^{1/2}\bar\calp^{1/2}\calz_n^*+n\lambda\I)^{-1} = (\bar\calp^{1/2}\calz_n^*\calz_n\bar\calp^{1/2} +n\lambda\mathcal{I})^{-1}\bar\calp^{1/2}\calz_n^*$. Substituting this in the last equality we have,
\begin{align*}
     \mathcal{T}_v &\leq 2\lambda^{-a}\big\|\calc_{n\lambda}^{1/2}\bar\calp^{1/2}(\bar\calp^{1/2}\calz_n^*\calz_n\bar\calp^{1/2} +n\lambda\mathcal{I})^{-1}\calp^{1/2}\big[\calz_n^*\y - \calz_n^*\calz_n\omega\big]\big\|_\calh\\
     &=2\lambda^{-a}\big\|\calc_{n\lambda}^{1/2}\bar\calp^{1/2}(\bar\calp^{1/2}\calc_n\bar\calp^{1/2} +\lambda\mathcal{I})^{-1}\calp^{1/2}\big[\cals_n^*\hat\y - \cals_n\omega\big]\big\|_\calh\\
     &\leq 2\lambda^{-a}\big\|\calc_{n\lambda}^{1/2}\bar\calp^{1/2}(\bar\calp^{1/2}\calc_n\bar\calp^{1/2} +\lambda\mathcal{I})^{-1}\calp^{1/2}\calc_{n\lambda}^{1/2}\big\|\cdot\underbrace{\big\|\calc_{n\lambda}^{-1/2}\big[\cals_n^*\hat\y - \calc_n\omega\big]\big\|_\calh}_{\text{sample variance}}.
\end{align*}
The second equality holds because $\calz_n = \sqrt{n}\cals_n$ and $\cals_n^*\cals_n=\calc_n$ and $\hat\y = \y/\sqrt{n}$.
We use Lemma \ref{l:sample_variance} to upper bound the term $\big\|\calc_{n\lambda}^{-1/2}\big[\cals_n^*\hat\y - \calc_n\omega^\lambda\big]\big\|_\calh$. The remaining multiplicative term can be upper bounded by $1$ as 
\begin{align*}
    \bar\calp^{1/2}\calc_n\bar\calp^{1/2} +\lambda\mathcal{I} &\succeq  \bar\calp^{1/2}\calc_{n\lambda}\bar\calp^{1/2} = \bar\calp^{1/2}\calc_{n\lambda}^{1/2}\calc_{n\lambda}^{1/2}\bar\calp^{1/2}\\
    \Rightarrow (\bar\calp^{1/2}\calc_n\bar\calp^{1/2} +\lambda\mathcal{I})^{-1} &\preceq (\bar\calp^{1/2}\calc_{n\lambda}^{1/2}\calc_{n\lambda}^{1/2}\bar\calp^{1/2})^\dagger = (\calc_{n\lambda}^{1/2}\bar\calp^{1/2})^\dagger(\bar\calp^{1/2}\calc_{n\lambda}^{1/2})^\dagger.
\end{align*}
Therefore,
\begin{align*}
    \big\|\calc_{n\lambda}^{1/2}\bar\calp^{1/2}(\bar\calp^{1/2}\calc_n\bar\calp^{1/2} +\lambda\mathcal{I})^{-1}\bar\calp^{1/2}\calc_{n\lambda}^{1/2}\big\| \leq \|\calc_{n\lambda}^{1/2}\bar\calp^{1/2}(\calc_{n\lambda}^{1/2}\bar\calp^{1/2})^\dagger(\bar\calp^{1/2}\calc_{n\lambda}^{1/2})^\dagger\bar\calp^{1/2}\calc_{n\lambda}^{1/2}\| \leq 1.
\end{align*}
The upperbound on the variance term becomes
\begin{align}
    \mathcal{T}_v \leq \lambda^{-a}\cdot  O\Big(\lambda^\zeta + \frac{1}{n\lambda^{1-\zeta}} + \frac{1}{\sqrt{n\lambda^{\gamma}}} \Big)\log(1/\delta). \label{e:risk_4}
\end{align}
We now upper bound the bias term:
\begin{align*}
    \mathcal{T}_b&=\big\|\calc^{1/2-a}\big(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n- \mathcal{I}\big)\omega\big\|_\calh\\
    &=\big\|\calc^{1/2-a}\big(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n- \mathcal{I}\big)\calc_{\lambda}^{-1}\cals_\rho^*f_\calh\big\|_\calh\\
    &=\big\|\calc^{1/2-a}\big(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n- \mathcal{I}\big)\calc_{\lambda}^{-1}\cals_\rho^*\call^\zeta g\big\|_\calh.
\end{align*}
The last equality holds due to the source assumption \ref{as:4}. Using $\cals_\rho^*\call^\zeta = \cals_\rho^*(\cals_\rho\cals_\rho^*)^\zeta = (\cals_\rho^*\cals_\rho)^\zeta\cals_\rho^* = \calc^\zeta\cals_\rho^*g$, we get
\begin{align*}
    \mathcal{T}_b &= \big\|\calc^{1/2-a}\big(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n- \mathcal{I}\big)\calc_{\lambda}^{-1}\calc^\zeta\cals_\rho^*g \big\|_\calh\\
    &\leq  \big\|\calc^{1/2-a}\big(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n- \mathcal{I}\big)\calc_{\lambda}^{-1}\calc^\zeta\cals_\rho^*\big\|\cdot\big\|g\big\|_\rho\\
    &\leq R\big\|\calc^{1/2-a}\big(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n- \mathcal{I}\big)\calc_{\lambda}^{-1}\calc^\zeta\calc^{1/2}\big\|\\
    &\leq R\big\|\calc_\lambda^{1/2-a}\big(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n- \mathcal{I}\big)\calc_{\lambda}^{\zeta-1/2}\big\|.
\end{align*}
In the second to last inequality we used $\big\|g\big\|_\rho \leq R$ and in the last inequality we used $\calc^{\zeta+1/2} \preceq \calc_\lambda^{\zeta+1/2}$, and $\calc^{1/2-a} \preceq \calc_\lambda^{1/2-a}$ as $a \leq \zeta < \frac{1}{2}$. Continuing we get,
\begin{align*}
    \mathcal{T}_b &\leq R\big\|\calc_\lambda^{-a}\big\|\cdot\big\|\calc_\lambda^{1/2}\calc_{n\lambda}^{-1/2}\big\|\cdot\big\|\calc_{n\lambda}^{-1/2}\big\|\cdot\big\|\calc_{n\lambda}(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n-\mathcal{I})\big\|\cdot\|\calc_{\lambda}^{\zeta-1/2}\|\\
    &\leq \frac{2R\lambda^{-a}\lambda^\zeta}{\lambda}\big\|\calc_{n\lambda}(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n-\mathcal{I})\big\|\\
    &=\frac{2R\lambda^{-a}\lambda^\zeta}{n\lambda}\big\|(\calz_n^*\calz_n+n\lambda\I)(\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n-\mathcal{I})\big\|\\
    &=\frac{2R\lambda^{-a}\lambda^\zeta}{n\lambda}\big\|(\calz_n^*\calz_n+n\lambda\I)(\calz_n^\dagger\calz_n\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n-\mathcal{I})\big\|\\
    &=\frac{2R\lambda^{-a}\lambda^\zeta}{n\lambda}\big\|(\calz_n^*\calz_n+n\lambda\mathcal{I})(\calz_n^\dagger\bar\K\bar\K_{n\lambda}^{-1}\calz_n-\mathcal{I})\big\|,
\end{align*}
where we used the observation that $\calz_n^\dagger\calz_n$ is a projection on $\calh_n$, implying $\calz_n^\dagger\calz_n\bar\calp = \bar\calp$. Also we substituted $\calz_n\bar\calp\calz_n^* = \bar\K.$ Multiplying the terms we get,
\begin{align*}
    \mathcal{T}_b &\leq \frac{2R\lambda^{-a}\lambda^\zeta}{n\lambda}\big\|\calz_n^*\bar\K\bar\K_{n\lambda}^{-1}\calz_n + n\lambda\calz_n^\dagger\bar\K\bar\K_{n\lambda}^{-1}\calz_n-\calz_n^*\calz_n-n\lambda\mathcal{I}\big\|\\
    &\leq \frac{2R\lambda^{-a}\lambda^\zeta}{n\lambda}\Big(\|\calz_n^*(\bar\K\bar\K_{n\lambda}^{-1}-\I)\calz_n + n\lambda\calz_n^\dagger\bar\K\bar\K_{n\lambda}^{-1}\calz_n -n\lambda\mathcal{I}\|\Big).
\end{align*}
The terms $\big\|\calz_n^*(\bar\K\bar\K_{n\lambda}^{-1}-\I)\calz_n\big\|$ and $\big\|\calz_n^\dagger\bar\K\bar\K_{n\lambda}^{-1}\calz_n\big\|$ can be upper bounded separately as
\begin{align*}
    \big\|\calz_n^*(\bar\K\bar\K_{n\lambda}^{-1}-\I)\calz_n\big\| = n\lambda\|\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n\| =n\lambda\|\K^{1/2}\bar\K_{n\lambda}^{-1}\K^{1/2}\| &\leq n\lambda\|\K_{n\lambda}^{1/2}\bar\K_{n\lambda}^{-1}\K_{n\lambda}^{1/2}\|
\end{align*}
where we used $\calz_n\calz_n^*=\K$. In second term substitute $\bar\K=\calz_n\bar\calp\calz_n^*$ to get:
\begin{align*}
    \|n\lambda\calz_n^\dagger\bar\K\bar\K_{n\lambda}^{-1}\calz_n\| &= n\lambda\|\calz_n^\dagger\calz_n\bar\calp\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n\| \leq n\lambda\|\calz_n^\dagger\calz_n\|\cdot\|\bar\calp\|\cdot\|\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n\|\\
    &\leq n\lambda\|\calz_n^*\bar\K_{n\lambda}^{-1}\calz_n\| \leq n\lambda\|\K_{n\lambda}^{1/2}\bar\K_{n\lambda}^{-1}\bar\K_{n\lambda}^{1/2}\|.
\end{align*}
Combining these upperbounds we get,
\begin{align}
    \mathcal{T}_b \leq 2R\lambda^{-a}\lambda^\zeta\big(1 + \|\K_{n\lambda}^{1/2}\bar\K_{n\lambda}^{-1}\K_{n\lambda}^{1/2}\|\big). \label{e:risk_5}
\end{align}
Combining (\ref{e:risk_5}), (\ref{e:risk_4}), (\ref{e:risk_3}), (\ref{e:risk_2}), and $(\ref{e:risk_1})$, we conclude
\begin{align*}
    \big\|\call^{-a}(\cals_\rho\omega_{[q]}- f_\calh)\big\|_\rho \leq   \lambda^{-a}\cdot O\Big(\lambda^\zeta\big\|\bar\K_{n\lambda}^{1/2}\bar\K_{n\lambda}^{-1}\bar\K_{n\lambda}^{1/2}\big\| + \frac{1}{n\lambda^{1-\zeta}} + \frac{1}{\sqrt{n\lambda^{\gamma}}} \Big)\log(1/\delta).
\end{align*}
\end{proof}
Using Theorem \ref{t:main_stat_risk_2} we prove the following two corollaries for classical Nystr\"om and Block Nystr\"om KRR respectively, recovering the optimal generalization error up to a multiplicative factor of $\alpha$.




For the following corollary, consider $\lambda' =\alpha\lambda$ and construct a Nystr\"om approximation to $\K$ by sampling landmarks from $n\lambda'$-ridge leverage scores of $\K$, but still adding $n\lambda$ as the regularizer. We refer to this as classical Nystr\"om.
\begin{corollary}[Statistical risk of KRR with classical Nystr\"om]\label{c:single_nys_risk}
      Let $0\leq a \leq \zeta$, $\zeta < \frac{1}{2}$, $n \geq O(G^2\log(G^2/\delta))$, $\lambda^* = \tilde O(n^{-\frac{1}{2\zeta+\gamma}})$ if $2\zeta+\gamma >1$, and $\lambda^* = \tilde O(n^{-1})$ if $2\zeta+\gamma \leq 1$. Let $\lambda' = \alpha\lambda^* < 1$ for some $\alpha>1$. Then under assumptions \ref{as:1}-\ref{as:4} and for any $\delta>0$
      \begin{align*}
    \big\|\call^{-a}(\cals_\rho\hat\omega- f_\calh)\big\|_\rho \leq \begin{cases} \alpha\cdot \tilde O(n^{-\frac{\zeta-a}{2\zeta+\gamma}})  \ \text{if} \ \ 2\zeta+\gamma>1 \\
    \alpha\cdot \tilde O(n^{-(\zeta-a)}) \ \ \text{if} \ 2\zeta+\gamma \leq 1
\end{cases}
\end{align*}
with probability $1-\delta$. Here $\hat\omega$ denotes the hypothesis $\hat\calp\calz_n^*(\hat\K+n\lambda^*\I)^{-1}\y$, $\hat\calp$ is orthogonal projection onto the $m$ dimensional subspace spanned by Nystr\"om landmarks sampled using $O(1)$-approximate $n\lambda'$-ridge leverage scores of $\K$ and $\hat\K$ denotes the corresponding Nystr\"om approximation to $\K$.
\end{corollary}


\begin{proof}
    Let $\lambda^*$ be the optimal regularizer depending on the case if $2\zeta+\gamma>1$ or $2\zeta+\gamma \leq 1$. Consider $\lambda' = \alpha\lambda^*$. We have with probability $1-\delta$
    \begin{align*}
        \K+n\lambda^*\I \preceq \K+n\lambda'\I \preceq 2(\hat\K +n\lambda'\I) \preceq \frac{2\lambda'}{\lambda^*}(\hat\K+n\lambda^*\I) \preceq 2\alpha(\K+n\lambda^*\I)
    \end{align*}
    implying $\|(\K+n\lambda^*\I)^{1/2}\big(\hat\K+n\lambda^*\I\big)^{-1}(\K+n\lambda^*\I)^{1/2}\| \leq 2\alpha$. Substituting this in the statement of Theorem \ref{t:main_stat_risk_2} finishes the proof.
\end{proof}
We provide an extended version of Corollary \ref{c:avg_nys_risk}. The following extension is useful when the excess risk factor $\alpha$ is potentially quite large and the resulting linear system $(\hat\K_{[q]} +n\lambda^{*}\I)\w=\y$ is more expensive to solve than sampling Nystr\"om landmarks from $\alpha^2\lambda^*$-ridge leverage scores of $\K$, due to large number of blocks as $q=\tilde O(\alpha)$. To recover corollary \ref{c:avg_nys_risk} one can consider $\beta=\alpha$ in the following result.
\begin{corollary}[Expected risk of Block-Nystr\"om-KRR]\label{c:avg_nys_risk_2}
      Under Assumptions \ref{as:1}, \ref{as:2}, \ref{as:3} and \ref{as:4}, suppose that $\zeta<1/2$ and $n \geq \tilde O(G^2\log(G^2/\delta))$. Also, let $\lambda^* = \tilde O(n^{-\frac{1}{2\zeta+\gamma}})$ if $2\zeta+\gamma >1$ and $\lambda^* = \tilde O(n^{-1})$ if $2\zeta+\gamma \leq 1$. Consider Block-Nystr\"om-KRR, $\hat\omega_{[q]}=\calp_{[q]}\calz_n^*(\hat\K_{[q]}+n\lambda^*\I)^{-1}\y$, constructed using $q=\tilde O(\beta)$ blocks, each with $\tilde O(d_{n\lambda'}(\K))$ leverage score samples where $1\leq \beta \leq \alpha$ and $\lambda'=\beta\alpha\lambda^*$. Then,
      \begin{align*}
    \big\|\cals_\rho\hat\omega_{[q]}- f_\calh\big\|_\rho \leq \begin{cases} \alpha\cdot \tilde O(n^{-\frac{\zeta}{2\zeta+\gamma}})  &\text{if} \ \ 2\zeta+\gamma>1,\\
    \alpha\cdot \tilde O(n^{-\zeta}) &\text{if} \  \ 2\zeta+\gamma \leq 1.
\end{cases}
\end{align*}
\end{corollary}
\begin{proof}\textbf{of Corollary \ref{c:avg_nys_risk_2}.}
    Let $\lambda^*$ be the optimal regularizer depending on the case if $2\zeta+\gamma>1$ or $2\zeta+\gamma \leq 1$. Consider $\tilde\lambda= \frac{\alpha}{\beta}\lambda^*$ and $\lambda' = \beta\alpha \lambda^*$. We have with probability $1-\delta$,
    \begin{align*}
        \K+n\lambda^*\I \preceq \K+n\tilde\lambda\I \preceq 8 \sqrt{\frac{\lambda'}{\tilde\lambda}}\Big(\frac{1}{q}\sum_{i=1}^{q}{\hat\K_i +n\tilde\lambda\I}\Big) \preceq 8 \sqrt{\frac{\lambda'}{\tilde\lambda}}\cdot\frac{\tilde\lambda}{\lambda^*}\Big(\frac{1}{q}\sum_{i=1}^{q}{\hat\K_i +n\lambda^*\I}\Big) \preceq 8\alpha(\K+n\lambda^*\I)
    \end{align*}
    For $q > O(\beta\log(n/\delta))$. In the second inequality, we used Theorem \ref{t:Nys_spectral_approximation_2}. Therefore,
    \begin{align*}
       (\K+n\lambda^*\I)^{-1} \preceq \Big(\frac{1}{q}\sum_{i=1}^{q}{\hat\K_i +n\lambda^*\I}\Big)^{-1} \preceq 8\alpha(\K+n\lambda^*\I)^{-1}
    \end{align*}
    implying $\Big\|(\K+n\lambda^*\I)^{1/2}\Big(\frac{1}{q}\sum_{i=1}^{q}{\hat\K_i +n\lambda^*\I}\Big)^{-1}(\K+n\lambda^*\I)^{1/2}\Big\| < 8\alpha$. Substituting this in the statement of Theorem \ref{t:main_stat_risk_2} finishes the proof.
\end{proof}
In the following lemma, we derive explicit expressions for the time complexity of classical Nystr\"om KRR for any $\alpha \geq 1$. In particular, we sample landmarks using $n\lambda'$-ridge leverage scores of $\K$ where $\lambda'=\alpha\lambda^*$, obtaining the Nystr\"om approximation $\hat\K$. We then add $n\lambda^*\I$ to $\hat \K$, obtaining an $n\lambda^*$-regularized $\alpha$-approximation to $\K$.
For better intuition, it is helpful to think of $\alpha$ as $n^\theta$ for small $\theta>0$. In particular, the form of the exponent $\theta$ changes as the regime changes from $2\zeta+\gamma>1$ to $2\zeta+\gamma \leq 1$. We capture this regime change by considering $\theta= \mu/\max\{1,2\zeta+\gamma\}$. We consider $a=0$ to obtain the time complexity for obtaining $\alpha$ multiplicative bound for the expected risk.
\begin{lemma}[Cost analysis of KRR with classical Nystr\"om]\label{l:cost_single_Nystrom}
Let $a=0$ and $\zeta < \frac{1}{2}$. Let $\lambda' = \alpha\lambda^*$, where $\lambda^* = \tilde O(n^{-\frac{1}{2\zeta+\gamma}})$ and $\alpha = n^{\frac{\mu}{2\zeta+\gamma}}$ if $2\zeta+\gamma >1$, and $\lambda^* = \tilde O(n^{-1})$ and $\alpha = n^{\mu}$ if $2\zeta+\gamma <1$. Furthermore, let $\mu \leq \zeta$. Then the total time complexity of classical Nystr\"om KRR in regime of $2\zeta+\gamma >1$ is given as:
 \begin{align*} \mathcal{T}_{nys}=\begin{cases} 
        \tilde O\Big(n^{\frac{(1+2\gamma)(1-\mu)}{2\zeta+\gamma}}\Big)
         \ \text{ if  $\mu \leq \frac{1-2\zeta}{1+\gamma}$}\\
        \tilde O\Big(n^{\frac{2\zeta +\gamma(2-\mu)}{2\zeta+\gamma}}\Big) \ \ \ \text{ otherwise}.
    \end{cases}
    \end{align*}
and if $2\zeta+\gamma \leq 1$,
      \begin{align*}
       \mathcal{T}_{nys}=
    \begin{cases}
       \tilde O\Big(n^{(1+2\gamma)(1-\mu)}\Big) \text{if} \ \mu \leq \frac{\gamma}{1+\gamma},\\
        \tilde O\Big(n^{1+\gamma(1-\mu)}\Big) \text {otherwise.} 
    \end{cases}
    \end{align*}
\end{lemma}
\begin{proof}
    In the regime of $2\zeta+\gamma >1$, the optimal $\lambda^*$ is $\tilde O(n^{-\frac{1}{2\zeta+\gamma}})$. Let $\lambda' =\alpha\lambda^*$ where $\alpha = n^{\frac{\mu}{2\zeta+\gamma}}$. Let $m=d_{n\lambda'}(\K)$.
    The overall time complexity of classical Nystr\"om KRR is the sum of three costs as follows:
    \begin{itemize}
        \item Landmarks sampling using Lemma \ref{l:rls_bless} : $\tilde O(m^2/\lambda') = \tilde O(\frac{1}{(\lambda')^{1+2\gamma}}\big) = \tilde O(\frac{1}{\alpha^{1+2\gamma}}\cdot n^{\frac{1+2\gamma}{2\zeta+\gamma}}).$
        \item Cost of inverting $\tilde O(m)\times \tilde O(m)$  submatrix of $\K$: $\tilde O(m^3) = \tilde O(\frac{1}{\alpha^{3\gamma}}\cdot n^{\frac{3\gamma}{2\zeta+\gamma}}).$
        \item Cost of solving linear system $(\hat\K+n\lambda^*\I)\w=\y$  using preconditioned conjugate gradient: $ \tilde O(nm) = \tilde O(\frac{1}{\alpha^\gamma}\cdot n^{\frac{2\zeta+2\gamma}{2\zeta+\gamma}})$.
    \end{itemize}
    Under the assumption that $\mu \leq\zeta$, it is easy to show that cost of sampling landmarks is larger than the cost of inverting the principal submatrix. Now comparing the first and third costs it is easy to see that cost of landmarks sampling dominates the cost of solving the linear system as long as $\mu < \frac{1-2\zeta}{1+\gamma}.$
    Therefore overall time complexity is given as
    \begin{align*}\begin{cases} 
        \tilde O\Big(n^{\frac{(1+2\gamma)(1-\mu)}{2\zeta+\gamma}}\Big)
         \ \text{ if  $\mu \leq \frac{1-2\zeta}{1+\gamma}$}\\
        \tilde O\Big(n^{\frac{2\zeta +\gamma(2-\mu)}{2\zeta+\gamma}}\Big) \ \ \ \text{ otherwise}.
    \end{cases}
    \end{align*}
    Note that we always assume $\mu \leq \zeta$.
    Now consider the regime $2\zeta+\gamma <1$, the optimal $\lambda^* = \tilde O(1/n)$ and the corresponding learning rate $\tilde O(n^{-\zeta})$. Let $\lambda' = \alpha\lambda^*$ where now $\alpha = n^{\mu}$ for $0 \leq \mu \leq \zeta$. We have
    \begin{itemize}
        \item Nystr\"om landmarks sampling using Lemma \ref{l:rls_bless}: $\tilde O(m^2/\lambda') = \tilde O\Big(n^{(1+2\gamma)(1-\mu)}\Big).$
        \item  Cost of inverting $\tilde O(m)\times \tilde O(m)$ matrix : $\tilde O(m^3) = \tilde O(n^{3\gamma(1-\mu)})$
        \item Cost of solving linear system $(\hat\K+n\lambda^*\I)\w=\y$  using preconditioned conjugate gradient: $\tilde O(n^{1+\gamma(1-\mu)})$
    \end{itemize}
    The overall cost is then given as
    \begin{align*}
    \begin{cases}
        \tilde O\Big(n^{(1+2\gamma)(1-\mu)}\Big) \text{if} \ \mu \leq \frac{\gamma}{1+\gamma},\\
        \tilde O\Big(n^{1+\gamma(1-\mu)}\Big) \text {otherwise.} 
    \end{cases}
    \end{align*}
    Here also additional constraint is $\mu \leq \zeta$.
\end{proof}
We now provide explicit expressions for the time complexity of Block-Nystr\"om KRR. 
\begin{lemma}[Cost analysis of KRR with Block-Nystr\"om]\label{l:cost_avg_Nystrom}
Let $a=0$, $\zeta<\frac{1}{2}$ and $\lambda^*$ be the optimal regularizer depending on the regime if $2\zeta+\gamma>1$ or $2\zeta+\gamma\leq 1$. Let $\lambda' = \beta\alpha\lambda^*$ for some $1\leq \beta\leq \alpha$ and define $q$ as follows
    \begin{align*}
        q=\begin{cases}
            \lceil200\beta\log(n)/\delta\rceil \ \text{if} \ \beta>1\\
            1 \ \text{if} \ \beta=1.
        \end{cases}
    \end{align*}
If $2\zeta+\gamma>1$, let $\lambda^* = \tilde O(n^{-\frac{1}{2\zeta+\gamma}})$, $\alpha = n^{\frac{\mu}{2\zeta+\gamma}}$ and $\beta=n^{\frac{\nu}{2\zeta+\gamma}}$  where $0\leq \mu \leq \zeta$ and $\nu = \max\Big\{0,\min\big\{\mu,\frac{1-2\zeta-\mu(1.5+\gamma)}{\gamma+\phi+0.5}\big\}\Big\}$. 
Then the total time complexity of Block-Nystr\"om KRR is given as:
   \begin{align*}\mathcal{T}_{Blk}=
        \begin{cases}
            \tilde O\Big(n^{\frac{(1+2\gamma)(1-\mu)-2\gamma\nu}{2\zeta+\gamma}}\Big) \ \text{if} \ \mu < \frac{1-2\zeta}{\gamma+1.5}, \\
         \tilde O\Big(n^{\frac{(1+2\gamma)(1-\mu)}{2\zeta+\gamma}}\Big) \ \ \ \text{if} \ \frac{1-2\zeta}{\gamma+1.5} \leq \mu \leq \frac{1-2\zeta}{\gamma+1},\\
         \tilde O\Big(n^{\frac{2\zeta+\gamma(2-\mu)}{2\zeta+\gamma}}\Big) \text{otherwise}.
        \end{cases}
    \end{align*}
    If $2\zeta+\gamma \leq 1$, let $\lambda^* = \tilde O(n^{-1})$, $\alpha = n^{\mu}$, $\beta=n^{\nu}$ where $0 \leq \mu\leq \zeta$ and  $\nu = \max\Big\{0,\min\big\{\mu, \frac{\gamma-\mu(\gamma+1.5)}{\gamma+\phi+0.5}\big\}\Big\}$. Then the overall cost of Block-Nystr\"om is given as
    \begin{align*}
    \mathcal{T}_{Blk}=
        \begin{cases}
            \tilde O\Big(n^{(1+2\gamma)(1-\mu)-2\gamma\nu}\Big) \ \text{if} \ \mu < \frac{\gamma}{\gamma+1.5} \\
         \tilde O\Big(n^{(1+2\gamma)(1-\mu)}\Big) \ \ \ \text{if} \ \frac{\gamma}{\gamma+1.5} \leq \mu \leq \frac{\gamma}{1+\gamma}\\
         \tilde O\Big(n^{1+\gamma(1-\mu)}\Big) \text{otherwise}
        \end{cases}
    \end{align*}
\end{lemma}
\begin{proof}
We consider $\tilde\lambda= \frac{\alpha}{\beta}\lambda^*$ and $\lambda'=\beta\alpha\lambda^*$. For sampling Nystr\"om landmarks we use Lemma \ref{l:rls_bless} $q$ times leading to cost of $\tilde O(q\cdot m^2/\lambda')$, where $m=d_{n\lambda'}(\K)$. First consider the regime $2\zeta+\gamma>1$. Similar to Lemma \ref{l:cost_single_Nystrom} we break down the cost in three components:
    \begin{itemize}
        \item Nystr\"om landmarks sampling : $\tilde O(q m^2/\lambda') = \tilde O(\beta^{-2\gamma}\alpha^{-(1+2\gamma)} n^{\frac{1+2\gamma}{2\zeta+\gamma}}).$
     \item  Cost of inverting $q$ $\tilde O(m)\times \tilde O(m)$ principal submatrices of $\K$: $\tilde O(qm^3) =\tilde O\Big(\beta^{1-3\gamma}\alpha^{-3\gamma} n^{\frac{3\gamma}{2\zeta+\gamma}}\Big).$
          \item Cost of solving linear system $(\hat\K_{[q]}+n\lambda^*\I)\w=\y$ using techniques from Lemma \ref{t:linear_system_solve_2}: $\tilde O\Big(\sqrt{\tilde\lambda/\lambda^*}\cdot q^{1+\phi}nm\Big) = \tilde O\Big(\sqrt{\alpha/\beta}\cdot\beta^{1+\phi-\gamma}\alpha^{-\gamma}n^{\frac{2\zeta+2\gamma}{2\zeta+\gamma}}\Big) = \tilde O \Big(\beta^{1/2+\phi-\gamma}\alpha^{1/2-\gamma}n^{\frac{2\zeta+2\gamma}{2\zeta+\gamma}}\Big).$
    \end{itemize}
 Under the assumption that $\mu \leq \zeta$, one can show that the cost of landmarks sampling is larger than the cost of inverting the principal submatrices. Comparing the first and the third costs we get
    \begin{align*}
        &\beta^{-2\gamma}\alpha^{-(1+2\gamma)} n^{\frac{1+2\gamma}{2\zeta+\gamma}} \geq \beta^{1/2+\phi-\gamma}\alpha^{1/2-\gamma}n^{\frac{2\zeta+2\gamma}{2\zeta+\gamma}}\\
        \Rightarrow&  n^{\frac{1-2\zeta}{2\zeta+\gamma}} \geq \beta^{1/2+\phi+\gamma}\alpha^{3/2+\gamma}\\
         \Rightarrow& 1-2\zeta \geq \mu(1.5+\gamma) + \nu(0.5+\phi+\gamma)\\
         \Rightarrow& \nu \leq \frac{1-2\zeta-\mu(1.5+\gamma)}{\gamma+\phi+0.5}.
    \end{align*}
     We set $\nu = \max\Big\{0,\min\big\{\mu,\frac{1-2\zeta-\mu(1.5+\gamma)}{\gamma+\phi+0.5}\big\}\Big\}$. If $\nu >0$, then we run  Block-Nystr\"om KRR and if $\nu=0$ i.e. $\beta=1$ and consequently $q=1$, we run classical Nystr\"om KRR. The overall time complexity is given as
 \begin{align*}
        \begin{cases}
            \tilde O\Big(n^{\frac{(1+2\gamma)(1-\mu)-2\gamma\nu}{2\zeta+\gamma}}\Big) \ \text{if} \ \mu < \frac{1-2\zeta}{\gamma+1.5}, \\
         \tilde O\Big(n^{\frac{(1+2\gamma)(1-\mu)}{2\zeta+\gamma}}\Big) \ \ \ \text{if} \ \frac{1-2\zeta}{\gamma+1.5} \leq \mu \leq \frac{1-2\zeta}{\gamma+1},\\
         \tilde O\Big(n^{\frac{2\zeta+\gamma(2-\mu)}{2\zeta+\gamma}}\Big) \ \text{otherwise}.
        \end{cases}
    \end{align*}
    Now let $2\zeta+\gamma \leq 1$. The cost of  Block-Nystr\"om KRR is given as
   \begin{itemize}
       \item Landmarks sampling: $\tilde O(qm^2/\lambda') = \tilde O\Big(\beta^{-2\gamma}\alpha^{-(1+2\gamma)}n^{1+2\gamma}\Big).$
        \item  Cost of inverting $q$ $\tilde O(m)\times \tilde O(m)$ principal submatrices of $\K$: $\tilde O(qm^3) : \tilde O\Big(\beta^{1-3\gamma}\alpha^{-3\gamma}n^{3\gamma}\Big)$
        \item Cost of solving linear system $(\hat\K_{[q]}+n\lambda^*\I)\w=\y$ using techniques from Lemma \ref{t:linear_system_solve_2}: $\tilde O\Big(\sqrt{\tilde\lambda/\lambda^*}\cdot q^{1+\phi}nm\Big) = \tilde O\Big(\sqrt{\alpha/\beta}\cdot\beta^{1+\phi-\gamma}\alpha^{-\gamma}n^{1+\gamma}\Big) = \tilde O\Big(\beta^{1/2+\phi-\gamma}\alpha^{1/2-\gamma}n^{1+\gamma}\Big)$
   \end{itemize}
    Again, one can show that the cost of landmarks sampling is larger than the cost of inverting the principal submatrices. Comparing the first and third costs we get
    \begin{align*}
        \beta^{-2\gamma}\alpha^{-(1+2\gamma)}n^{1+2\gamma} &\geq \beta^{1/2+\phi-\gamma}\alpha^{1/2-\gamma}n^{1+\gamma}\\
        \Rightarrow n^\gamma &\geq \beta^{1/2+\phi+\gamma}\alpha^{3/2+\gamma}\\
        \Rightarrow \gamma &\geq \mu(\gamma+3/2) + \nu(\gamma+\phi+1/2)\\
        \Rightarrow \nu &\leq \frac{\gamma-\mu(\gamma+1.5)}{\gamma+\phi+0.5}
    \end{align*}
    As $0\leq\nu \leq \mu$ we set $\nu = \max\Big\{0,\min\big\{\mu, \frac{\gamma-\mu(\gamma+1.5)}{\gamma+\phi+0.5}\big\}\Big\}$. Again, $\nu >0$ corresponds to Block-Nystr\"om and if $\nu=0$ we run classical Nystr\"om KRR. The overall cost is therefore given as
    \begin{align*}
        \begin{cases}
            \tilde O\Big(n^{(1+2\gamma)(1-\mu)-2\gamma\nu}\Big) \ \text{if} \ \mu < \frac{\gamma}{\gamma+1.5} \\
         \tilde O\Big(n^{(1+2\gamma)(1-\mu)}\Big) \ \ \ \text{if} \ \frac{\gamma}{\gamma+1.5} \leq \mu \leq \frac{\gamma}{1+\gamma}\\
         \tilde O\Big(n^{1+\gamma(1-\mu)}\Big) \ \ \text{otherwise}.
        \end{cases}
    \end{align*}
\end{proof}
\paragraph{Detailed cost comparison between classical Nystr\"om and Block Nystr\"om KRR.}
As shown in Lemma \ref{l:cost_avg_Nystrom} there is a regime in which Block-Nystr\"om provides computational gains over classical Nystr\"om KRR. In particular, we have proven that as long as $\alpha=n^\theta$ for $\theta < \frac{1}{\gamma+1.5}\cdot\frac{\min\{\gamma,1-2\zeta\}}{\max\{1,2\zeta+\gamma\}}$, Block-Nystr\"om enjoys faster time complexity and achieves the same excess risk factor of $\alpha$ as obtained by classical Nystr\"om. Furthermore, within this range of values for $\theta$, the computational gains enjoyed by Block-Nystr\"om change their trend. As $\theta$ increases from $0$ to $\frac{1}{2\gamma+2+o(1)}\cdot\frac{\min\{\gamma,1-2\zeta\}}{\max\{1,2\zeta+\gamma\}}$, the ratio of time complexity of two methods, $\mathcal{T}_{Blk}/\mathcal{T}_{nys}$, scales as $1/n^{2\theta\gamma}$, whereas when $\theta$ increases from $\frac{1}{2\gamma+2+o(1)}\cdot\frac{\min\{\gamma,1-2\zeta\}}{\max\{1,2\zeta+\gamma\}}$ to $\frac{1}{\gamma+1.5}\cdot\frac{\min\{\gamma,1-2\zeta\}}{\max\{1,2\zeta+\gamma\}}$, we use a slightly different averaging scheme where we reduce the number of blocks to avoid computational overhead resulting due to potentially having to solve the linear system $(\hat\K_{[q]}+n\lambda^*\I)\w=\y$ with $q=\tilde O(\alpha)$ number of blocks. In this case we consider $q=\tilde O(\beta)$ with $\beta$ diminishing from $\alpha$ to $1$ as $\theta$ increases in this later regime. This idea of reduced averaging leads $\mathcal{T}_{Blk}/\mathcal{T}_{nys}$ to scale as $\frac{1}{n^{\xi}}$ where $\xi=\frac{1}{\gamma+o(1)+0.5}\Big(\frac{\min\{\gamma,1-2\zeta\}}{\max\{1,2\zeta+\gamma\}}-(\gamma+1.5)\theta\Big)$, meaning larger $\theta$ has diminishing computational gains. At the critical point of $\theta = \frac{1}{\gamma+1.5}\frac{\min\{\gamma,1-2\zeta\}}{\max\{1,2\zeta+\gamma\}}$, Block Nystr\"om KRR reduces to classical Nystr\"om KRR as $\beta$ becomes $1$. 
\section{Proof of Lemma \ref{l:rls-square-main}}
\label{a:preconditioner}
In this section we provide proof of Lemma \ref{l:rls-square-main}. We start by restating the lemma, replacing the notation $\bar\lambda$ with $\lambda$ for notational convenience. For psd matrices, we use $\A\approx_c\B$ to denote $c^{-1}\B\preceq\A\preceq c\B$, and $\omega \approx 2.372$ denotes the fast matrix multiplication exponent.



\begin{lemma}\label{l:rls-square}
    Given an $n\times n$ psd matrix $\A$ with at most $k$ eigenvalues larger than $O(1)$ times its smallest eigenvalue, consider $\lambda=\frac1k\sum_{i>k}\lambda_i(\A)$. Then, $d_\lambda(\A)\leq 2k$, and we can compute $O(1)$-approximations of all $\lambda$-ridge leverage scores of $\A$ in time $\tilde O(\nnz(\A) + k^\omega)$.
\end{lemma}


\begin{proof}
    The fact that $d_\lambda(\A)\leq 2k$ is shown in Lemma 2.1 of \cite{dmy24}. Next, let $\lambda_1\geq\lambda_2\geq ...\geq\lambda_n$ be the eigenvalues of $\A$. We will show that it suffices to approximate the ridge leverage scores of $\A^2$ instead of $\A$. Let $\tilde\lambda = \frac1k\sum_{i>k}\lambda_i^2$, so that $d_{\tilde\lambda}(\A^2)\leq 2k$. Also, define $\bar\kappa_k(\A)=\frac1{n-k}\sum_{i>k}\frac{\lambda_i}{\lambda_n}$. We're going to show that:
   \begin{align}
     \bar\kappa_k(\A)\cdot \A(\A+\lambda\I)^{-1}\preceq \bar\kappa_k(\A^2)\cdot \A^2(\A^2+\tilde\lambda\I)^{-1}.
     \label{eq:lev-1}
   \end{align}
    Since the matrices commute, it is enough to show this for each
eigenvalue. Observe that we have:
\begin{align*}
  \frac{\bar\kappa_k(\A^2)}{\bar\kappa_k(\A)} =
  \frac{\sum_{j>k}\lambda_j^2}{\sum_{j>k}\lambda_n\lambda_j}\in [1,\lambda_{k+1}/\lambda_n].
\end{align*}
This means that
\begin{align*}
  \frac{\lambda_i}{\lambda_i+\frac1k\sum_{j>k}\lambda_j}
  &=\frac{\lambda_i^2}{\lambda_i^2+\frac1k\sum_{j>k}\lambda_i\lambda_j}
    \leq\frac{\lambda_i^2}{\lambda_i^2+\frac1k\sum_{j>k}\lambda_n\lambda_j}
  \\
  &=\frac{\lambda_i^2}{\lambda_i^2+\frac{\bar\kappa_k(\A)}{\bar\kappa_k(\A^2)}\frac1k\sum_{j>k}\lambda_j^2}
  \leq \frac{\bar\kappa_k(\A^2)}{\bar\kappa_k(\A)}\frac{\lambda_i^2}{\lambda_i^2+\frac1k\sum_{j>k}\lambda_j^2},
\end{align*}
which implies \eqref{eq:lev-1}. Since $\lambda$-ridge leverage scores of $\A$ are the diagonal entries of $\A(\A+\lambda\I)^{-1}$, this shows that for any $i$:
\begin{align*}
    \ell_{i}(\A,\lambda) 
    &= \e_i^\top\A(\A+\lambda\I)^{-1}\e_i
    \\
    &\leq \frac{\bar\kappa_k(\A^2)}{\bar\kappa_k(\A)}\e_i^\top\A^2(\A^2+\tilde\lambda\I)^{-1}\e_i
    \\
    &=O(1)\cdot \ell_{i}(\A^2,\tilde\lambda),
\end{align*}
where in the last step we used that $\bar\kappa_k(\A^2) = O(1)$ because all of the tail eigenvalues are within a constant of each other. This, together with the fact that $\sum_i\ell_{i}(\A^2,\tilde\lambda) = O(k)$, implies that it suffices to perform approximate ridge leverage score sampling with respect to $\ell_{i}(\A^2,\tilde\lambda)$. 

Next, we show how to construct approximations of $\ell_{i}(\A^2,\tilde\lambda)$ in $\tilde O(\nnz(\A)+k^\omega)$ time. First, notice that
\begin{align*}
    \ell_{i}(\A^2,\tilde\lambda) = \a_i^\top(\A^2+\tilde\lambda\I)^{-1}\a_i,
\end{align*}
where $\a_i$ is the $i$th row of $\A$. Next, we approximate the inner matrix by using a $\tilde O(k)\times n$ sparse sketching matrix $\Pi$ \citep{cohen2016optimal}, computing $\M=\Pi\A$ in $\tilde O(\nnz(\A))$ time, so that with high probability $\M^\top\M+\tilde\lambda\I\approx_2 \A^2+\tilde\lambda\I$. Thus, it suffices to approximate:
\begin{align*}
\a_i^\top(\M^\top\M+\tilde\lambda\I)^{-1}\a_i
&= \|(\M^\top\M+\tilde\lambda\I)^{-1/2}\a_i\|^2
\\
&= \|\B_{\tilde\lambda}(\M^\top\M+\tilde\lambda\I)^{-1}\a_i\|^2,\qquad\text{where}
    \quad\B_{\tilde\lambda} = \begin{bmatrix}\M\\\sqrt{\tilde\lambda}\I\end{bmatrix}.
\end{align*}
Note that if $\S$ is an $O(\log n)\times 2n$ Johnson-Lindenstrauss embedding, then we can approximate the above norms to within a constant factor with $\tilde\ell_i = \|\S\B_{\tilde\lambda}(\M^\top\M+\tilde\lambda\I)^{-1}\a_i\|^2$. In order to compute these estimates, we first pre-compute the $O(\log n)\times d$ matrix $\S\B_{\tilde\lambda}$, and then compute $\mathbf{R}=\S\B_{\tilde\lambda}\cdot(\M^\top\M+\tilde\lambda\I)^{-1}$ by solving $O(\log n)$ linear systems with $\M^\top\M+\tilde\lambda\I$. The linear systems can be solved by following the preconditioning strategy of \cite{dmy24}, observing that: 
  \begin{align*}
    (\M^\top\M+\tilde\lambda\I)^{-1}
    = \frac1{\tilde\lambda}\Big(\I -
    \M^\top(\M\M^\top+\tilde\lambda\I)^{-1}\M\Big).
  \end{align*}
Thus, it suffices to solve a linear system with $\M\M^\top+\tilde\lambda\I$. To do this, we construct a $k\times \tilde O(k)$ sketch $\tilde\M = \M\S_2^\top$ such that $\tilde\M\tilde\M^\top \approx_{O(1)} \M\M^\top$ via a subspace embedding \citep{cohen2016optimal}, and precondition that linear system with $\B^{-1}=(\tilde\M\tilde\M^\top+\tilde\lambda\I)^{-1}\approx_{O(1)}(\M\M^\top+\tilde\lambda\I)^{-1}$. Thus, after precomputing
$\B^{-1}$ at the cost of
$\tilde O(\nnz(\M)+k^\omega)$, we can solve
the linear system $(\M^\top\M+\tilde\lambda\I)^{-1}\v$ in time $\tilde O(\nnz(\A)+k^2)$.

Finally, we compute the $O(\log n)\times n$ matrix $\mathbf{R}\A$ and then let $\tilde\ell_i$ be the squared row norms of this matrix. The overall costs are $\tilde O(\nnz(\A)+k^\omega)$ for precomputing $\mathbf{R}$ and then $\tilde O(\nnz(\A))$ for computing the squared row norms. 


\end{proof}


