\talkno{
\begin{proposition}\label{p:winsim} Число оборотов 

    (a) любого контура выпуклого многоугольника; 

    (b) любой замкнутой ломаной без самопересечений

    вокруг любой точки из внешности (внутренности) равно $0$ ($\pm 1$).
    См. рисунок \ref{f:wn_examples}.
\end{proposition} 

\begin{proof}[Доказательство пункта (a)] 
    Обозначим через $\Omega$ данный выпуклый многоугольник, а через $\partial\Omega$ " --- его контур. 

    Если точка $O$ лежит вне $\Omega$, то проведeм через $O$ две опорные прямые к $\Omega$. 
    Возьмeм две точки $A, B$ из пересечений этих опорных прямых с контуром $\partial\Omega$ многоугольника. 
    Имеем $w(\partial \Omega) = \frac{1}{2\pi} (\angle AOB+\angle BOA) = 0$. 

    Если точка $O$ лежит внутри $\Omega$, то нарисуем правильный треугольник $ABC$ с центром в $O$.
    Возьмeм три точки $A', B', C'$ пересечения  лучей $OA, OB, OC$ с контуром $\partial\Omega$ многоугольника.
    Они разбивают контур $\partial\Omega$ на три ломаные.
    Имеем
    $$w(\partial \Omega) = \frac{1}{2\pi} (\angle A'OB' + \angle B'OC' + \angle C'OA') = \frac{3}{2\pi} \angle A'OB' = \frac{3}{2\pi} \angle AOB = \pm 1.$$
\end{proof}

Пункт (b) в зависимости от изложения является либо следствием \emph{теоремы Жордана} \cite[\S1.4]{Sk20}, либо леммой в ее доказательстве.

}

\begin{example}\label{p:ex} Для любых целого числа $n$ и точки $O$ существует замкнутая ломаная, число оборотов которой вокруг $O$ равно $n$.
\end{example}

\talkno{

\begin{proof}[Построение]
    Если $n=0$, то примером является замкнутая ломаная, состоящая из одной точки.
    Если $n\ne 0$, то возьмем правильный треугольник $ABC$ с центром $O$, ориентированный против часовой стрелки при $n>0$ и по часовой стрелке иначе.
    Определим замкнутую ломаную $l$ формулой $l := \underbrace{ABC\ldots ABC}_{|n| \text{ раз}}$.
    По утверждению \ref{p:winsim}.a, имеем $w(l) = |n| \cdot w(ABC) = n$.
\end{proof}

}

\begin{proposition}\label{p:noncl} 
    Число оборотов $w(A_1\ldots A_m)$ является целым числом. 
\end{proposition}

\talkno{

\begin{proof}[Доказательство]  
    Для $j=1,\ldots,m$ обозначим $t_j:=\angle A_jOA_{j+1}$, где $A_{m+1}=A_1$.  
    Тогда 
    $$\overrightarrow{OA_1} \upuparrows e^{it_m}\overrightarrow{OA_m} \upuparrows e^{i(t_m+t_{m-1})}\overrightarrow{OA_{m-1}} \upuparrows \ldots \upuparrows e^{i(t_m+t_{m-1}+\cdots+t_1)}\overrightarrow{OA_1}.$$
    Следовательно, $(t_m+t_{m-1}+\cdots+t_1)/2\pi$ является целым числом.
\end{proof}

\begin{figure}[ht] \centering
    \includegraphics[scale=0.65]{borsuk_black.eps}
    \caption{Замкнутая ломаная $l$, симметричная относительно точки $O$; $w(l)=3$} 
\end{figure}

\begin{theorem}[Борсук-Улам]\label{borul-pl} 
    Пусть замкнутая ломаная $A_1\ldots A_{2k}$ не проходит через точку $O$ и симметрична относительно $O$ (т.~е. $O$ "--- середина отрезка $A_jA_{k+j}$ для каждого $j=1,\ldots,k$).
    Тогда число оборотов ломаной вокруг точки $O$ нечетно.
\end{theorem}

}

\talkonly{\newpage}

Следующие обозначение и результаты будут полезны.

Пусть $l=A_1\ldots A_m$ "--- ломаная, не проходящая через точку $O$. 
Определим действительное число $w'(l)=w'(l,O)$ формулой
$$2\pi \cdot w'(l) = 2\pi \cdot w'(l,O):= \talkonly{$$ 
$$}\angle A_1OA_2+\angle A_2OA_3+\ldots+\angle A_{m-1}OA_m.$$
Очевидно, что

$\bullet$ $w'(A_1\ldots A_mA_1) = w(A_1\ldots A_m)$;

$\bullet$ $w'(A_1\ldots A_m) = w'(A_1\ldots A_j) + w'(A_j\ldots A_m)$ для каждого $j=1,\ldots,m$; 

$\bullet$ если точки $A_2,\ldots, A_{m-1}$ лежат внутри угла $\angle A_1 O A_m$, то  
$2\pi w'(A_1\ldots A_m) = \angle A_1 O A_m$.

\begin{proposition}\label{p:w'}
    Имеем \talkonly{\newline} $\angle A_1OA_m = 2\pi w'(A_1\ldots A_m)+2\pi n$ для некоторого целого $n$. 
\end{proposition}

\talkno{

\begin{proof}
    Очевидно, что $2\pi w(A_1\ldots A_m) = 2\pi w'(A_1\ldots A_m)+\angle A_mOA_1$.
    По утверждению \ref{p:noncl} получаем требуемое.
\end{proof}

\begin{proof} [Доказательство теоремы \ref{borul-pl}]
    Ввиду симметричности, имеем
    $$w'(A_1 \ldots A_{k+1}) = w'(A_{k+1} \ldots A_{2k}A_1).$$
    Тогда
    $$w(A_1\ldots A_{2k}) = w'(A_1\ldots A_{2k}A_1) = w'(A_1\ldots A_{k+1}) + w'(A_{k+1}\ldots A_{2k}A_1) =$$
    $$= 2w'(A_1 \ldots A_{k+1}) \stackrel{(1)}{=} 2 \left( \frac{\angle A_1OA_{k+1}}{2\pi} + n \right) = 1 + 2n$$
    для некоторого целого $n$. 
    Здесь равенство $(1)$ следует из утверждения~\ref{p:w'}.
\end{proof}
}

Обозначим через $l^{-1}$ ломаную, полученную из ломаной $l$ прохождением в противоположном порядке.
Очевидно, что $w'(l) = -w'(l^{-1})$ для любой точки $O\not\in l$. 
%и ломаной $l$, не проходящей через $O$.

\talkonly{\newpage}

\emph{Конкатенацией} ломаных $l_1 = A_1 \ldots A_m C$ и $l_2 = C B_1\ldots B_k$ называется  ломаная 
$$l_1l_2 := A_1 \ldots A_m C B_1 \ldots B_k.$$
\emph{Конкатенацией} замкнутых ломаных 
\talkonly{\linebreak}
$l_1 = A_1 \ldots A_m C$ и $l_2 = B_1\ldots B_k C$ называется замкнутая ломаная 
$$l_1l_2 := A_1 \ldots A_m C B_1 \ldots B_k C.$$
В этих обозначениях $w'(l_1l_2) = w'(l_1) + w'(l_2)$ для любых точки $O$ и ломаных $l_1, l_2$, не проходящих через $O$.

\talkno{

\begin{proposition} \label{k23}
    Пусть $O$, $A$, $B$ "--- три попарно различные точки.
    Пусть $l_1$, $l_2$, $l_3$ "--- ломаные, соединяющие точку $A$ с точкой $B$, и не проходящие через точку $O$.
    Тогда 
    \linebreak
    $w(l_1 l_2^{-1}) + w(l_2 l_3^{-1}) = w(l_1 l_3^{-1})$.
\end{proposition}

\begin{proof}
    Имеем
    $$w(l_1 l_2^{-1}) + w(l_2 l_3^{-1}) = w'(l_1) + w'(l_2^{-1}) + w'(l_2) + w'(l_3^{-1}) = w'(l_1) + w'(l_3^{-1}) = w(l_1 l_3^{-1}).$$  
\end{proof}

\begin{example}[см. построение в \S\ref{s:wind}.A] \label{k23-ex}
    Пусть $O$, $A$, $B$ "--- три попарно различных точки.
    Для любых трех целых чисел $n_1, n_2, n_3$, таких что $n_1 + n_2 = n_3$, существуют три ломаные $l_1, l_2, l_3$, соединяющие точку $A$ с точкой $B$, не проходящие через точку $O$, и такие, что
$$w(l_1l_2^{-1}) = n_1, \qquad w(l_2l_3^{-1}) = n_2 \quad\text{и}\quad w(l_1l_3^{-1}) = n_3.$$
\end{example}

\begin{proposition}\label{p:3rays} 
    Пусть $A_0A_1A_2$ "--- правильный треугольник, а точка $O$ "--- его центр.
    Для $j=0,1,2$ обозначим через $l_j$ ломаную, не пересекающую луч $OA_j$ и соединяющую $A_{j+1}$ с $A_{j+2}$, где нумерация берется по модулю 3.
    Тогда $w(l_0l_1l_2) = \pm 1$.  
\end{proposition}

\begin{proof}[Набросок доказательства]
    Можно считать, что вершины треугольника пронумерованы против часовой стрелки.
    По утверждению \ref{p:w'} имеем $w'(l_0) = \frac{1}{3} + k$ для некоторого целого $k$.
    В следующем абзаце мы докажем, что $k = 0$.
    Равенства  $w'(l_1) = w'(l_2) = \frac{1}{3}$ доказываются аналогично.
    Тогда $w(l_0l_1l_2) = w'(l_0) + w'(l_1) + w'(l_2) = 1$. 

    Обозначим через $B_1 \ldots B_m$ последовательные вершины ломаной $l_0$. 
    Для $j = 1, \ldots, m-1$ положим $t_j := \angle B_jOB_{j+1} \in (-\pi, \pi)$.
    Пусть найдется такое наименьшее $j$, что $T_j := t_1 + \ldots + t_j \not \in \left(-\frac{2\pi}{3}, \frac{4\pi}{3}\right)$.
    Тогда отрезок $B_jB_{j+1}$ пересекается с лучом $OA_0$. 
    Значит, $T_j \in \left(-\frac{2\pi}{3}, \frac{4\pi}{3}\right)$ для любого $j = 1, \ldots, m-1$.
    В частности, $T_{m-1} \in \left(-\frac{2\pi}{3}, \frac{4\pi}{3}\right)$.
    При этом $T_{m-1} = 2\pi w'(l_0) = \frac{2\pi}{3} + 2\pi k$ для некоторого целого $k$.
    Следовательно, $k = 0$.
\end{proof}

Подробнее о числе оборотов и связанных с ним понятиях см. \cite{Wn, Va81, To84, Ta88},  \cite[теорема 2]{KK18}, \cite[\S2]{Sk18}, \cite[\S3.2]{Sk20}. 


