\end{proof}

Приведем 
%более аккуратное
другое построение примера \ref{p:maps}, полезное для обобщений.
%которые в этой статье не обсуждаются

Для вершины $v$ и ориентированного ребра $\tau$ в графе $K$, таких что $f(v) \not\in f(\tau)$, положим
$$w'_f(\tau,v):=w'(f|_\tau,f(v)).$$

\begin{lemma}[ср. {\cite[Lemma 2.1]{KS20}}]\label{l:f-move}
    Для любых графа $K$, его ориентированного ребра $ab$, его вершины $j \not \in ab$, знака $s \in \{-1, +1\}$ и слабого почти вложения $g : K \to \R^2$ существует слабое почти вложение $f : K \to \R^2$, такое что

    (1) $w'_f(ab, j) = w'_g(ab, j)  + s$  и 

    (2) $w'_f(\sigma, v) = w'_g(\sigma, v)$ для любых ориентированного ребра $\sigma\ne ab,ba$ и вершины $v\ne j$, $v \not \in \sigma$. 
\end{lemma}

\begin{proof}[Набросок доказательства]
    Пусть имеется ломаная $l = A_1 \ldots A_m$ и треугольник с вершинами $X$, $Y$, $Z$, обозначенными против часовой стрелки.
    Точка $O$ лежит внутри треугольника $XYZ$.

   \begin{figure}[ht]\centering
        \includegraphics[scale=.9]{f-move.eps}
        \caption{Положительное пальцевое движение ломаной $l$ вокруг точки $O$}
        \label{f:fingermove-strict}
    \end{figure}

    Будем говорить, что ломаная $l_+$ получена из ломаной $l$ \emph{положительным пальцевым движением} вокруг точки $O$, если $l_+ = A_1 \ldots A_m XYZX A_m$.
    Аналогично $l_-$ получена из ломаной $l$ \emph{отрицательным пальцевым движением} вокруг точки $O$, если $l_- = A_1 \ldots A_m XZYX A_m$.

    Легко видеть, что $w'(l) = w'(l_+) - 1 = w'(l_-) + 1$.

    \smallskip
    Сделаем пальцевое движение ломаной $g|_{ab}$ вокруг $g(j)$ так, что 

    (i) $g(j)$ единственный образ вершины графа внутри треугольника $XYZ$,

    (ii) отрезок $g(b)X$ не содержит образов вершин графа $K$, отличных от $a$ и $b$,

    (iii) движение положительное, если $s = +1$, иначе отрицательное.

    Отображение $f$, полученное в результате этого пальцевого движения, является искомым.
    Условия (i,~iii) влекут условия (1,~2).
    Отображение $f$ является слабым почти вложением ввиду условия (ii).
\end{proof}

\begin{proof}[Набросок построения примера \ref{p:maps}]
    Квадрат с диагоналями образует слабое почти вложение $g:K_4\to\R^2$; пусть вершины $g(j),~ j \in [4]$ пронумерованы против часовой стрелки.
    Тогда $w_g(C_j,j) = 0$ для каждого $j \in [4]$.

    Многократным применением леммы \ref{l:f-move} к отображению $g$ получим слабое почти вложение $f : K_4 \to \R^2$, такое что
    $$\begin{array}{l}
        w'_f(23, 1) = w'_g(23, 1) + n_1, \quad w'_f(34, 2) = w'_g(34, 2) + n_2,\\
        w'_f(41, 3) = w'_g(41, 3) + n_3, \quad w'_f(12, 4) = w'_g(12 ,4) + n_4
    \end{array}\quad \text{ и }$$
    $$w'_f(\sigma, v) = w'_g(\sigma, v) \text{ для каждой пары } (\sigma, v),~ v \not \in \sigma, \text{ отличной от перечисленных}.$$
    Ввиду равенства $w_f(ijk,v)=w'_f(ij,v)+w'_f(jk,v)+w'_f(ki,v)$ для любого отображения $f$, цикла $ijk$ и вершины $v \not \in ijk$, отображение $f$ является искомым.
\end{proof}

