\begin{definition}[{\cite[Definition 2.2]{PU:1999}}]
\label{def:gmo}
	Let $(T_i)_{i \in I}$ be a conic decomposition of $\LaurentMonoid$.
	A generalized monomial order (or g.m.o) on $\LaurentMonoid$ for the decomposition $(T_i)_{i \in I}$ is a total order $<$ on $\LaurentMonoid$ such that
	\begin{enumerate}[(1)]
		\item $\forall t \in \LaurentMonoid, 1 \le t$
		\item $\forall r \in \LaurentMonoid, \forall i \in I$, $(s,t \in  T_i \ \textnormal{and}\ r < s) \implies rt < st$ \label{item:compatibilite_multiplication_dans_Ti}
	\end{enumerate}
\end{definition}

\begin{remark}
	For each $i \in I$, the restriction of $<$ to $T_i$ is a monomial order (take $r$ in $T_i$ in 2. of Definition \ref{def:gmo}).
\end{remark}

Given a conic decomposition, Lemma \ref{lemma:construct_gto} provides a method for constructing a g.m.o by employing an auxiliary function, $\phi: \LaurentMonoid \to \mathbb{Q}_{\ge 0}$, which exhibits favorable behavior in relation to the decomposition.

\begin{lemma}[{\cite[Lemma 2.1]{PU:1999}}]
\label{lemma:construct_gto}
Let $(T_i)_{i \in I}$ be a conic decomposition of $\LaurentMonoid$ and $E$ be either $\{1\}$ or one of the $T_i$.
Let $<_G$ be a total group order on $\LaurentMonoid$ (e.g. the lexicographical order). 
Let $\phi : \LaurentMonoid \to \mathbb{Q}_{\ge 0}$ be a function fulfilling the following conditions:
\begin{enumerate}[(1)]
	\item $\forall t \in \LaurentMonoid\setminus E$, $\phi(t) > 0$
	\item $\forall s,t \in \LaurentMonoid$, $\phi(st) \le \phi(s) + \phi(t)$
	\item $\forall i \in I$, $\phi|_{T_i}$ is a monoid homomorphism.
\end{enumerate}
\noindent Then the order $<$ defined by
\[ r < s \iff \phi(r) < \phi(s) \textnormal{ or } (\phi(r) = \phi(s) \textnormal{ and } r <_G s)\]
is a g.m.o on $\LaurentMonoid$ for the decomposition $(T_i)_{i \in I}$.
\end{lemma}

The notions of leading monomial, leading coefficient and leading term are defined for a Laurent polynomial as in the polynomial case.
\begin{definition}
\label{def:leadings}
Fix a g.m.o on $T$ and let $f \in \LaurentRing$. 
The leading monomial $\lm(f)$ of $f$ is defined as $\max(\X^j,\ j \in \textnormal{supp(f)})$.
The leading coefficient $\lc(f)$ of $f$ is the coefficient of $\lm(f)$ in $f$. 
The leading term $\lt(f)$ of $f$ is the product $\lc(f)\lm(f)$.
\end{definition}

Examples \ref{ex:standard_gmo_1} to \ref{ex:second_gmo} illustrate Lemma \ref{lemma:construct_gto} and Definition \ref{def:leadings}.
In each case, the group order on $\LaurentMonoid$ is taken to be the lexicographical order, and we show in the case $n=2$ how the monomials of $f = 2xy^{-2} + x^{-2}y^{-2} + 3x^{-1}y^{-2} + y^2 \in K[x^{\pm 1},y^{\pm 1}]$ are ordered.

\begin{example}
\label{ex:standard_gmo_1}
Take the standard decomposition $(T_0,T_1,\dots,T_n)$ of Example \ref{ex:standard_conic_decomposition}.
Let $E = \{1\}$ and define $\phi : \LaurentMonoid \to \mathbb{Q}_{\ge 0}$ by $\phi(i_1,\dots,i_n) = i_1 + \dots + i_n - (n+1)\min(0,i_1,\dots,i_n)$.
We have $xy^{-2} > x^{-1}y^{-2} > y^2 > x^{-2}y^{-2}$, $\lm(f)= xy^{-2}$, $\lc(f) = 2$ and $\lt(f) = 2xy^{-2}$.
\end{example}

\begin{example}
\label{ex:standard_gmo_2}
Take the standard decomposition $(T_0,T_1,\dots,T_n)$ of Example \ref{ex:standard_conic_decomposition}. 
Let $E = T_0$ and define $\phi : \LaurentMonoid \to \mathbb{Q}_{\ge 0}$ by $\phi(i_1,\dots,i_n) = -\min(0,i_1,\dots,i_n)$. 
We have $xy^{-2} > x^{-1}y^{-2} > x^{-2}y^{-2} > y^2$, $\lm(f) = xy^{-2}$, $\lc(f) = 2$ and $\lt(f) = 2xy^{-2}$.
\end{example}

\begin{example}
\label{ex:second_gmo}
Take the conic decomposition $(T_d)_{d \in D_n}$ of Example \ref{ex:second_conic_decomposition}. 
Let $E = \{1\}$  and define $\phi: \LaurentMonoid	\to \mathbb{Q}_{\ge 0}$ by $\phi(i_1,\dots,i_n) = \lvert i_1 \rvert + \dots + \lvert i_n \rvert $. 
We have $x^{-2}y^{-2} > xy^{-2} > x^{-1}y^{-2} > y^2$, $\lm(f) = x^{-2}y^{-2}$, $\lc(f) = 3$ and $\lt(f) = 3x^{-2}y^{-2}$.
\end{example}

In Example \ref{ex:problem_leading_term}, we illustrate the fact that for $t \in \LaurentMonoid$ and $f \in \LaurentRing$, the leading monomial of $tf$ is generally not equal to the product of $t$ by $\lm(f)$.

\begin{example}
\label{ex:problem_leading_term}
Take the g.m.o of Example \ref{ex:standard_conic_decomposition} in the case $n=2$ and $f = xy + y^{-1} \in K[x^{\pm 1}, y^{\pm 1}]$.
We have $\lm(yf) = xy^2$ but $y\lm(f) = 1 \neq xy^2$.
\end{example}

However, thanks to the compatibility condition (2) of Definition \ref{def:gmo}, if two monomials $t_1$, $t_2$ are such that $\lm(t_1f)$ and $\lm(t_2f)$ lies in the same cone $T_i$, then the monomials $a_1, a_2$ of $f$ such that $\lm(t_1f) = t_1a_1$ and $\lm(t_2f) = t_2a_2$ are equal. 
This is proven in Lemma \ref{lemma:lmi_independent} and leads naturally to the definition of "one leading monomial per cone" in Definition \ref{def:lmi}.
For the rest of this section, we fix a g.m.o for a conic decomposition $(T_i)_{i \in I}$ of $T$.
\begin{definition}
	\label{def:T_i(f)}
	For $i \in  I$ and $f \in \LaurentRing$, define \[T_i(f) := \{ t \in \LaurentMonoid,\ \lm(tf) \in T_i\}\].
\end{definition}

\begin{lemma}[{\cite[Lemma 2.3]{PU:1999}}]
	\label{lemma:lmi_independent}
	Let $i \in I$, $f \in \LaurentRing$, $u,v \in T_i(f)$. 
	Write $\lm(uf) = ut_u \in T_i$ and $\lm(vf) = vt_v \in T_i$ for some monomials $t_u,t_v$ of $f$. 
	Then $t_u = t_v$. 
\end{lemma}

\begin{definition}
	\label{def:lmi}
	Let $i \in  I$, $f \in  \LaurentRing$ and $t \in T_i(f)$. 
	We define $\lm_i(f) := \lm(tf)t^{-1}$. 
	This is well defined by Lemma \ref{lemma:lmi_independent} (i.e it does not depend on a particular $t \in T_i(f)$).
	We also define $\lc_i(f)$ as the coefficient of $\lm_i(f)$ in $f$, and $\lt_i(f) = \lc_i(f)\lm_i(f)$.
\end{definition}

\begin{remark}
   Before giving some examples, we explain how to compute $\lm_i(f)$. 
By Lemma \ref{lemma:lmi_independent}, we have $\lm_i(f) = \lm(tf)t^{-1}$ whenever $t \in T_i(f)$. 
So we just need to find a $t \in T_i(f)$, which can be done as follows.
Recall that $T_i$ is finitely generated and generates $T$ as a group. 
This implies that for each monomial $s$ of $f$, we can find $u_s, v_s \in T_i$ such that $s = u_sv_s^{-1}$. 
Define $t$ as the product of the monomials $v_s$ for $s$ a monomial of $f$.
Then $\textnormal{supp}(tf) \subset  T_i$, and $\lm(tf) \in T_i$. 
The latter means that $t \in T_i(f)$ and we are done. \label{rem:how_to_compute_the_Tis}
\end{remark}

%Examples \ref{ex:standard_gmo_1_2} to \ref{ex:second_gmo_2}  continue Examples \ref{ex:standard_gmo_1} to \ref{ex:standard_gmo_2}.

\begin{example}[Example \ref{ex:standard_gmo_1} continued.]
\label{ex:standard_gmo_1_2}
 We have $\lm_0(f) = \lm_1(f) = y^2$, $\lm_2(f) = \lm(f) = xy^{-2}$, $T_0(f) = y^2T_0$, $T_1(f) = y^2T_1$ and $T_2(f) = yT_2$.
\end{example}

\begin{example}[Example \ref{ex:standard_gmo_2} continued.]
\label{ex:standard_gmo_2_2}
 We have $\lm_0(f) = \lm_2(f) = \lm(f) = xy^{-2}$, $\lm_1(f) = x^{-2}y^{-2}$, $T_0(f) = x^2y^2T_0$, $T_1(f) = xy^2T_1$ and $T_2(f) = x^2y^2T_2$.
\end{example}

\begin{example}[Example \ref{ex:second_gmo} continued.]
\label{ex:second_gmo_2}
We index the 4 cones as in b) of Figure \ref{schema:conic_decompositions}.
We have $\lm_0(f) = \lm_1(f)= y^2$, $\lm_2(f) = \lm(f) = x^{-2}y^{-2}$ and $\lm_3(f)  = xy^{-2}$.
\end{example}

\begin{remark}
	We have $\lm(f)$ = $\lm_i(f)$ for at least one index $i \in I$. 
	For a fixed $f$, the $\lm_i(f)$'s are not necessarily distincts, and $\lm_i(f)$ is generally not an element of $T_i$.
\end{remark}

The following lemma states that a g.m.o shares with monomial orders the crucial property of being a well-order.
\begin{lemma}[{\cite[Lemma 2.2]{PU:1999}}]
\label{lemma:stric_descending_seq}
Let $<$ be a g.m.o on $\LaurentMonoid$ (for a conic decomposition $(T_i)_{i \in I}$ of $\LaurentMonoid$). 
Then every strictly descending sequence in $\LaurentMonoid$ is finite. 
In particular, any subset of $\LaurentMonoid$ contains a smallest element.
\end{lemma}

\section{Multivariate division in $K\{\X;r\} $}
\label{sec:MultiVarDivision}
In this section, we demonstrate the adaptability of the division algorithm, originally presented in the Tate algebras setting in \cite[Proposition 3.1]{CVV:2019}, to the polytopal setting in the case $ P = \{r\}  $ is a single point. The general case will be studied in Section \ref{sec:gb_valP}.

The novelty lies in the method employed to eliminate the leading term of an element $f \in \LaurentPolytopalRingForR$ by $g \in  \LaurentPolytopalRingForR$.
We can not solely rely on the leading terms of $f$ and $g$ (see Example \ref{ex:division_failure}), but have to consider also the terms $\lt_i(g)$ and the sets $T_i(g)$ for $i \in I$.

\subsection{The monoid of terms $ \MonoidOfTermsForR $}
\label{subsec:monoid_of_terms}

\begin{definition}
	\label{def:order}
Let $\le_\omega$ be a g.m.o on $\LaurentMonoid$. 
We define the monoid of terms $\MonoidOfTermsWithGMO$ (or simply $\MonoidOfTerms$) as the multiplicative monoid $\{a\mathbf{X}^u:\ a \in K^\times, u \in \Z^n\}$.
We define a preorder $\le_{r}$ on $\MonoidOfTerms$ by
\begin{align*}
	a\X^u \le_r b\X^v \iff &(\valr{r}(a\X^u) > \valr{r}(b\X^v)) \textnormal{ or }\\ &(\valr{r}(a\X^u) = \valr{r}(b\X^v) \textnormal{ and } \X^u \le_{\omega} \X^v) 
\end{align*}
 \end{definition}

\begin{remark}
The preorder $\le_r$ is not antisymmetric (and so not an order).
For terms $t_1,t_2$, the fact that $t_1 \le_r t_2$ and $t_2 \le_r t_1$ is equivalent to the existence of $a \in (\Kz)^\times$ such that $t_1 = at_2$.
\end{remark}
\begin{remark}
The preorder $\le_r$ is compatible with multiplication by elements of $K^\times$ but is not compatible with multiplication
by monomials (because $\le_\omega$ itself is not).
It is also not a well-order (there exists infinite strictly decreasing sequences). 
\end{remark}

However, Lemma \ref{lemma:topological_order} shows that the preorder $\le_r$ is a \textit{topological} well-order as in \cite[Lemma 2.14]{CVV:2019}.

\begin{lemma}
	\label{lemma:topological_order}
	Let $(t_j)_{j \in \N}$ be a strictly decreasing sequence for $ \le_r $ in $\MonoidOfTerms$. 
	Then $\lim_{j \to \infty}\valr{r}(t_j) = +\infty$, or equivalently $\sum_{j \in \N}t_j \in\LaurentPolytopalRingForR\}$ .
\end{lemma}

\begin{proof}
	By definition of the preorder $\le_r$, the sequence $(\valr{r}(t_j))_{j \in \N}$ 
is nondecreasing and takes its values in a discret subset $\frac{1}{D}\Z$ of $\R$ 
for some integer $D$ (taking into account the image group of $\val$ and 
the product of the denominators of $ r $). 
Since $\le_\omega$ is a well-order, there can be for a fixed 
$v \in \frac{1}{D}\Z$ only a finite number of indices $j$ for which $\valr{r}(t_j) = v$. 
Combining these two facts, $\valr{r}(t_j)$ must tend to $+\infty$.
\end{proof}

\begin{remark}
	\label{remark:leading_term}
	If $i \neq j \in \Z^n$, the terms $a_i\X^i$ and $b_j\X^j$  are never "equal"
	(that is $a_i\X^i \le_r b_j\X^j$ and $b_j\X^j \le_r a_i\X^i$) for $\le_r$. 
	Therefore, any nonzero $f \in \LaurentPolytopalRingForR$ has a unique leading term for $\le_r$.
\end{remark}

\begin{definition}
Let $f=\sum_{\alpha \in \Z^n} c_\alpha \X^\alpha \in \LaurentPolytopalRingForR$.
We define
\begin{equation}
	\textnormal{in}_r(f) := \sum_{\alpha \in \Z^n \textrm{ s.t. } \valr{r}(c_\alpha \X^\alpha)= \valr{r}(f)}  c_\alpha \X^\alpha  \in \LaurentRing.
\end{equation}

Using the map $\textnormal{in}_r: \LaurentPolytopalRingForR \to \LaurentRing$,
we extend to $f \in \LaurentPolytopalRingForR$ the definitions of 
$\lm(f)$, $\lc(f)$, $\lt(f)$, $\lm_i(f)$, $\lc_i(f)$, $\lt_i(f)$ and $T_i(f)$. 
\end{definition}

The leading term for the term order on $\MonoidOfTerms$ (as in Remark \ref{remark:leading_term})
equals $\lt(f) = \lt(\textnormal{in}_r(f))$, and same for $\lt_i(f), \, T_i(f)$ and so on.

\subsection{Multivariate division algorithm}
\label{subsec:division}

In Example \ref{ex:division_failure}, we illustrate how the classical procedure to cancel
the leading term of a polynomial can fail in the Laurent polynomial setting equipped with a g.m.o.
\begin{example}
	\label{ex:division_failure}
	Take the g.m.o of Example \ref{ex:standard_gmo_1} in the case $n=2$ and $ f = x + y$, $g = x^{-1}y + y^{-1} \in K[x^{\pm 1},y^{\pm1}]$.
	We have $\lt(f) = x$ and $\lt(g) = x^{-1}y$. 
	To cancel out $\lt(f)$ in $f$ the classical way, we substract $\frac{\lt(f)}{\lt(g)}g$ from $f$ and obtain $y - x^2y^{-2}$.
	But then we have $\lm(y - x^2y^{-2} ) = x^2y^{-2} > x = \lm(f)$, that is the leading monomial after cancellation is strictly superior to the leading monomial of $f$!
\end{example}

The issue in Example \ref{ex:division_failure} arises from assuming that $\lt(tg) = t\lt(g)$.
For a g.m.o, this equality does not necessarily hold (e.g Example \ref{ex:problem_leading_term}),
and it becomes possible for the leading term of $tg$ to exceed the leading term of $f$. 
While the leading term of $f$ is successfully canceled out, a larger term originating from $tg$ emerges after the cancellation.
To properly eliminate the leading term of $f$ by a multiple of $g$, we need instead to identify a term $t$ such that $\lt(tg) = \lt(f)$. 
According to Lemma \ref{lemma:lmi_independent}, depending on the specific cone $T_i$ in
which $\lm(f)$ is contained, this equality can be expressed again as $\lt(f) = \lt(tg) = t\lt_i(g)$.
This shows that the potential candidates for $t$ are the terms $\frac{\lt(f)}{\lt_i(g)}$
for varying indices $i$ for which $\lm(f) \in T_i$.
Summarizing the process:
\begin{enumerate}[(1)]
	\item Find an index $i$ such that $\lm(f) \in T_i$ (there exists at least one).
	\item Check if $\lm \left(\frac{\lm(f)}{\lm_i(g)}g\right) = \lm(f)$. 
		If this condition is satisfied, the leading term of $f$ can be effectively canceled out by subtracting $\frac{\lt(f)}{\lt_i(g)}g$ from $f$, and $\frac{\lm(f)}{\lm_i(g)} \in  T_i(g)$; otherwise, it cannot.
\end{enumerate}

\begin{remark}
	The monomial $\lm(f)$ can be contained in more than one cone, but it suffices to test the condition for cancellation within any one of those cones.
\end{remark}

The preceding discussion is applied in Proposition \ref{prop:multi_div} and Algorithm \ref{alg:multi_div}
to formulate a multivariate division algorithm in the ring $\LaurentPolytopalRingForR$ using $ \le_r $ to order terms.
Same as \cite[Algo 1]{CVV:2019}, Algorithm \ref{alg:multi_div} needs a countable amount of steps to terminate,
but only a finite amount of steps to reach  a given finite precision in $\valr{r}.$
\begin{proposition}
	\label{prop:multi_div}
	Let $f \in \LaurentPolytopalRingForR$ and $G$ be a finite subset of $\LaurentPolytopalRingForR$. 
	Algorithm \ref{alg:multi_div} produces a family $(q_g)_{g \in  G}$ and $s$ in $\LaurentPolytopalRingForR$ such that:
	\begin{enumerate}[(1)]
		\item $f = \sum_{g \in  G}q_gg + s$
		\item for all monomial $t$ in $s$, $t \notin \bigcup_{i \in I, g \in G}T_i(g)\lm_i(g)$
		\item for all $g \in  G$ and all monomial $t$ in $q_g$, $\lt(tg) \le_r \lt(f)$.
	\end{enumerate}
\end{proposition}

\begin{proof}
We construct by induction sequences $(f_j)_{j\ge 0}$, $(q_{g,j})_{j \ge 0}$ for $g \in G$ and 
$(s_j)_{j\ge 0}$ such that for all $j \ge 0$:
\[ f = f_j + \sum_{g \in G}q_{g,j}g + s_j,\]
and $\lt(f_j)_{j\ge 0}$ is strictly decreasing for $ \le_r$.
We first set $f_0 = f$, $s_0 = 0$ and $q_{g,0} = 0$ for all $g \in G$.
If there exists $i \in I$ and $g \in G$ such that
\[\lm \left( \frac{\lm(f_j)}{\lm_i(g)}g \right) = \lm(f_j) \in T_i, \]
we set $f_{j+1} = f_j - tg$ and $q_{g,j+1} = q_{g,j} + tg$ where $t = \frac{\lt(f_j)}{\lt_i(g)}$,
and leave unchanged $s_j$ and the other $q_{g,j}$'s. 
Otherwise, we set $f_{j+1} = f_j - lt(f_j)$ and $s_{j+1} = s_j + lt(f_j)$ and leave unchanged the $q_{g,j}$'s. 
By construction, the sequence $(\lt(f_j))_{j \ge 0}$ is strictly decreasing for $ \le_r $.
By Lemma \ref{lemma:topological_order}, we deduce that 
$\valr{r}(s_{j+1}-s_j)$ and the $\valr{r}(q_{g,j+1}-q_{g,j})$'s tend to $+\infty$ when $j \to +\infty$.
Thus $s_j$ and the $q_{g,j}$'s converge in $K\{\mathbf{X};\{r\} \}$.
Their limits % elements $q_g=\lim_{j \to +\infty}q_{g,j}$ for $g \in G$ and $r = \lim_{j \to +\infty}r_j$ 
satisfy the requirements of the proposition.
\end{proof}

\begin{definition}
    The output $s$ obtained from Algo \ref{alg:multi_div} with entries $f$ and $G=(g_1,\dots,g_m)$ is denoted $\rem(f,G).$
\end{definition}

\begin{algorithm}
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
	\caption{Multivariate division algorithm in $\LaurentPolytopalRingForR$ for $ \le_r $}
	\label{alg:multi_div}
	\Input{$f,g_1,\dots,g_m \in \LaurentPolytopalRingForR$}
	\Output{$q_1,\dots,q_m,s \in \LaurentPolytopalRingForR$ satisfying Prop \ref{prop:multi_div}}
	\BlankLine
	$q_1,\dots,q_m,s\gets 0$\;
	\While{ $f \neq 0$}{
		%$i \gets$ index in $I$ such that $\textnormal{lm}(f) \in T_i$\;
		\While{ $\exists (i,j) \in I \times \llbracket 1,m \rrbracket$ such that $\lm\left(\frac{\lm(f)}{\lm_i(g_j)}g_j\right) = \lm(f)$}{
			$t \gets \frac{\lt(f)}{\lt_i(g_j)}$\;
			$q_j \gets q_j + t $\;
			$f \gets f - tg_j $\;
		}
		$s \gets s + \lt(f)$

		$f \gets f - \lt(f)$;
	}
	\Return $q_1,\dots,q_m,s$
\end{algorithm}

\section{Gröbner bases for ideals in $ \LaurentPolytopalRingForR $}
\label{sec:GBpolytopal}

Let $\le$ be a g.m.o for a conic decomposition $(T_i)_{i \in I}$. 
For an ideal $J$ in $\LaurentPolytopalRingForR$, define $\lm(J) := \left\{ \lm(f),\ f \in J,\ f \neq 0 \right\}$.
Notice that 

\begin{equation}
	\label{eq:lmJ}
\lm(J) = \bigcup_{f \in  J, i \in I}T_i(f)\lm_i(f).
\end{equation}

A finite subset $G$ of $J$ is then a Gröbner basis when equation \eqref{eq:lmJ} still holds while considering in the set union only elements from $G$ instead of all members of $J.$ 

\subsection{Gröbner bases}

\begin{definition}
	Let $J$ be an ideal in $\LaurentPolytopalRingForR$ and $G$ be a finite subset of $J\setminus\{0\}$. 
	We say that $G$ is a Gröbner basis of $J$ (with respect to the g.m.o $\le$ and the conic decomposition $(T_i)_{i \in I}$) when:
	\[ \lm(J) = \bigcup_{g \in G,i \in I}T_i(g)\lm_i(g).\]
\end{definition}

In Proposition \ref{prop:has_gb}, we prove that every ideal $J$ within $\LaurentPolytopalRingForR$ contains a Gröbner basis. 
The demonstration relies on the fact that the set $T_i(f)$ is a finitely generated $T_i$-module, as proved in the following lemma:

\begin{lemma}
\label{lemma:fin_gen}
For all $i \in I$, there is a finite subset $E_i \subseteq \lm(J)\cap T_i$ such that $\lm(J)\cap T_i = T_i\cdot E_i$.
In case $J = \langle f \rangle$ is principal, we have $\lm(\langle f \rangle)\cap T_i = T_i(f)\lm_i(f) = T_i\cdot E_i$, and so $T_i(f) = T_i\cdot  \Bigl\{\frac{t}{\lm_i(f)},\ t \in E_i\Bigr\}$ is finitely generated over $T_i.$
\end{lemma}
\begin{proof}
	By Dickson's lemma, there exists a finite subset $E_i$ of $\lm(J)\cap T_i$ which generates the ideal $\langle \lm(J)\cap T_i \rangle_{K[T_i]}$ of $K[T_i]$.
	Then $\lm(J)\cap T_i =  T_i\cdot E_i$. 
	If $(J) = \langle f \rangle$ is principal, then $\lm(\langle f \rangle)\cap T_i = T_i(f)\lm_i(f)$ and we can conclude with Def. \ref{def:lmi}.
\end{proof}

\begin{proposition}
\label{prop:has_gb}
Let $J$ be an ideal of $\LaurentPolytopalRingForR$. Then $J$ contains a Gröbner basis.
\end{proposition}

\begin{proof}
 By Lemma \ref{lemma:fin_gen}, there are finite subsets $E_i \subset T_i$ such that $\lm(J) = \bigcup_{i \in I}T_i\cdot E_i$. 
 For all $t \in \bigcup_{i \in I}E_i$ choose an element $f_t \in J$ such that $\lm(f_t) = t$. Thanks to Def \ref{def:lmi}, $\lm_i(f_t)=\lm(f_t)=t.$
 We prove that the finite set $G=\{f_t \ |\ t \in \bigcup_{i \in I}E_i\}$ is a Gröbner basis of $J$.
 Let $u \in \lm(J).$ Let $i$ be such that $u \in T_i.$ Then there is some $(v,t) \in T_i \times E_i$ such that 
 $u=vt.$
 Let $c_t = \lc(f_t)$ and $c_\alpha \X^\alpha$ be a term of $f_t.$
 Then $c_\alpha \X^\alpha <_r c_t t$. 
 We remark that on the one hand $\valr{r} (c_\alpha \X^\alpha ) > \valr{r} (c_t t)$ 
 if and only if $ \valr{r} (c_\alpha v \X^\alpha ) > \valr{r} (c_t vt)$,
 and on the other hand, if $\valr{a} (c_\alpha \X^\alpha ) = \valr{r} (c_t t)$ ,
 then by item \ref{item:compatibilite_multiplication_dans_Ti} of Def \ref{def:gmo}
 and the fact that $v$ and $t$ are in $T_i$, we can remark that
 $\X^\alpha <_\omega t$ implies $\X^\alpha v <_\omega tv.$
 In any case, $c_\alpha \X^\alpha v <_r c_t vt$.
 Thus, $\lm(v f_t)=vt=u \in T_i.$
 Consequently, $v \in T_i(f_t)$ and $u \in T_i(f_t) \lm_i(f_t).$
We can then conclude that $G$ is a GB of $J.$
\end{proof}

\begin{proposition}
\label{prop:classical_easy}
Let $G$ be a Gröbner basis for an ideal $J$ of $\LaurentPolytopalRingForR$. We have
\begin{enumerate}[(1)]
	\item   $\forall f \in \LaurentPolytopalRingForR$, $f \in J \iff \rem(f,G) = 0$
	\item  $G$ generates the ideal $J$
\end{enumerate}
\end{proposition}

\begin{proof}
For the first part, if $\rem(f,G) = 0$, then the multivariate division algorithm gives $f \in J$. 
	Reciprocally, if $f \in J$ and $G$ is a Gröbner basis of $J$, then by (2) of Prop \ref{prop:multi_div} the remainder of the division of $f$ by $J$ is necessarily $0$.
For the second part, if $f \in J$,then, thanks to the above first part, $\rem(f,G) = 0$, and so $f \in J$.
\end{proof} 

\subsection{S-pairs and Buchberger criterion}

In the polynomial case, the S-pair of two polynomials $f$ and $g$ is formed to eliminate the minimal multiple of their leading terms, relying on the concept of least common multiple in $\PolynomialMonoid$.

However, in the Laurent setting, where $\LaurentMonoid$ is a group and the notions of lcm and gcd of two monomials in $T$ are useless, the replacement for the lcm of $f$ and $g$ is the finite set introduced in Proposition \ref{prop:Uifg}.
Notice that this set now depends on the cone in which the cancellation occurs.

By the same argument as in Lemma \ref{lemma:fin_gen}, we have:
\begin{proposition}
	\label{prop:Uifg}
	For $i \in I$ and $f,g \in \LaurentPolytopalRingForR$,
	$\lm_i(f)T_i(f) \cap \lm_i(g)T_i(g) \subset T_i$ is a finitely generated $T_i$-module.
\end{proposition}


\begin{definition}[S-pair]
	\label{def:Spair}
	Let $f,g \in \LaurentPolytopalRingForR$ and $i \in I$. 
	For $v \in \lm_i(f)T_i(f) \cap \lm_i(g)T_i(g)$, we define:
	\[ S(i,f,g,v) := \lc_i(g)\frac{v}{\lm_i(f)}f - \lc_i(f)\frac{v}{\lm_i(g)}g.\]
\end{definition}

\begin{lemma}
	\label{lemma:Spair}
	For $f,g \in \LaurentPolytopalRingForR$, $i \in I$ and $v \in \lm_i(f)T_i(f) \cap \lm_i(g)T_i(g)$, we have
    $\lt(S(i,f,g,v)) <_r \lc_i(f)\lc_i(g)v$.
\end{lemma}
\begin{proof}
Since $v \in T_i(f)\lm_i(f)\cap T_i(g)\lm_i(g)$, there exists $m_f \in T_i(f)$ and
$m_g \in T_i(g)$ such that $v = \lm(m_ff) = \lm(m_gg) = m_f\lm_i(f) = m_g\lm_i(g)$. 
Then the leading terms of $\lc_i(g)\frac{v}{\lm_i(f)}f$ and  $\lc_i(f)\frac{v}{\lm_i(g)}g$
both equal $\lc_i(f)\lc_i(g)v$. They cancel out leaving $\lt(S(i,f,g,v)) <_r \lc_i(f)\lc_i(g)v$.
\end{proof}

Since it involves all objects introduced so far, we give a detailed proof of the following adaptation of the classical cancellation lemma (see also \textit{e.g.} \cite[Lemma 5.1]{CVV:2022}).
\begin{lemma}
	\label{lemma:sumSpair}
Let $h_1,\dots,h_m \in \LaurentPolytopalRingForR$ and $i \in I$. 
For $1\le j \le m-1$, let $U(i,h_j,h_{j+1})$ be a finite system of generators of  $\lm_i(h_j)T_i(h_j) \cap \lm_i(h_{j+1})T_i(h_{j+1})$ which exists by Proposition \ref{prop:Uifg}.
Suppose that there are $t_1,\dots, t_m \in \MonoidOfTerms$, $u \in T_i$ and $c \in \val{}(K^\times)$ such that
\begin{itemize}
	\item for all $j \in \{1,\dots,m\}$, $\lt(t_jh_j) = c_ju$ with $\textnormal{val}(c_j) = c$
	\item  $\lt(\sum_{i=1}^{m}t_jh_j) <_r c_1u$.
\end{itemize}

Then there are elements $d_j \in K$, $v_j \in U(i,h_j,h_{j+1})$ for $1 \le j \le m-1$ and $t_m^\prime \in \LaurentPolytopalRingForR$ such that:
\begin{enumerate}[(1)]
	\item $\sum_{j=1}^{m}t_jh_j = \sum_{j=1}^{m-1}d_j\frac{u}{v_j}S(i,h_j,h_{j+1},v_j) + t_{m}^\prime h_m$. \label{enum:1}
	\item $\valr{r}(t^\prime_mh_m) > \valr{r}(uc_1)$. \label{enum:2}
	\item $\frac{u}{v_j} \in T_i$ for all $j <m$. \label{enum:3}
	\item For all $j <m$, $\val \left( d_j \lc_i(h_j) \lc_i(h_{j+1}) \right) \geq c.$ \label{enum:4}
	% \item $\val{P}(d_j\frac{u}{r_j}) + \max(\val{P}(h_j),\val{P}(h_{j+1})) \ge \val{P}(uc_1)$ for $j < m$.
\end{enumerate}

\end{lemma}
\begin{proof}
	Write $p_j = \frac{t_jh_j}{c_j}$, $e_j = \sum_{k=1}^{j}c_k$ and $t_j=\gamma_j \tilde{t}_j$ for some $\gamma_j \in K$
	and some monomial $\tilde{t}_j$.
	By hypothesis $u$ is in $T_i$ and $u = \tilde{t_j}\lm_i(h_j) \in T_i(h_j)\lm_i(h_j)$ for all $j$. 
	This implies that for all $j <m$ we have:
	\[u \in  T_i(h_j)\lm_i(h_j) \cap T_i(h_{j+1})\lm_i(h_{j+1}) = T_i\cdot U(i,h_j,h_{j+1})\]
	We deduce that for all $j<m$, there exist $k_j \in T_i$ and $v_j \in  U(i,h_j, h_{j+1}$) such that $u = k_jv_j$.
	Now write
	\begin{align}
	\sum_{j=1}^{m}t_jh_j &= e_1(p_1 - p_2) + \dots + e_{m-1}(p_{m-1}- p_m) + e_mp_m \label{eqn:somme_telescopique}
	\end{align}
	For all $j<m$, we have $\lt(t_j h_j)=c_j u= \gamma_j \lc_i (h_j)\tilde{t}_j \lm_i(h_j), $
	hence $\frac{t_j}{c_j \tilde{t}_j}=\frac{1}{\lc_i(h_j)}$.
	For any $j<m$, put $P_j = p_j - p_{j+1}$. We can then write:
	\begin{align*}
		P_j &= \frac{u}{v_j}\left(\frac{v_j}{u}p_j - \frac{v_j}{u}p_{j+1}\right) = \frac{u}{v_j}\left(\frac{t_jv_jh_j}{c_j\tilde{t}_j\lm_i(h_j)} - \frac{t_{j+1}v_jh_{j+1}}{c_{j+1}\tilde{t}_{j+1}\lm_i(h_{j+1})} \right)  \\
					  &= \frac{u}{v_j}\left(\frac{1}{\lc_i(h_j)}\frac{v_j}{\lm_i(h_j)}h_j - \frac{1}{\lc_i(h_{j+1})}\frac{v_j}{\lm_i(h_{j+1})}h_{j+1}\right)	\\
					  &= \frac{1}{\lc_i(h_j)\lc_i(h_{j+1})}\frac{u}{v_j}\left(\lc_i(h_{j+1})\frac{v_j}{\lm_i(h_j)}h_j - \lc_i(h_j)\frac{v_j}{\lm_i(h_{j+1})}h_{j+1}\right) \\
					  &= \frac{1}{\lc_i(h_j)\lc_i(h_{j+1})}\frac{u}{v_j}S(i,h_j,h_{j+1}).
	\end{align*}
	Plugging in the last expression back into equation \eqref{eqn:somme_telescopique} gives the desired equality with $d_j = \frac{e_j}{\lc_i(h_j)\lc_i(h_{j+1})}$ and $t^{\prime}_m = \frac{e_m}{c_m}t_m$.
	It satisfies \ref{enum:1}.
	The hypothesis forces $\val{}(e_m) > \val{}(c_m)$. Then we have $\valP(t^\prime_mh_m) = \val{}(e_m) + \valP(u) > \val{}(c_m) + \valP(u) = \valP(c_1u)$, which proves \ref{enum:2}.
	In addition, $\frac{u}{v_j} = k_j \in T_i$, which proves \ref{enum:3}.
	Finally, using that $\val (e_j) \geq c$ and $d_j = \frac{e_j}{\lc_i(h_j)\lc_i(h_{j+1})}$, one gets \ref{enum:4}.
\end{proof}

To prove the final Buchberger criterion in Proposition \ref{prop:buch_criterion}, we need the following lemma:
\begin{lemma}
	\label{lemma:inequality}
%	For $F$ a finite family in $\LaurentPolytopalRingForR$ and $(t_f)_{f \in  F}$ a family of terms, define $m((t_f)_{f \in F}) := \max(t_fd,\ d \in \textnormal{terms}(f),\ f \in  F)$.

%	Let $u \in T_i$ be such that $m((t_f)_{f \in  F}) < u$. 
%	Then for all $v \in T_i$, we have $m((vt_f)_{f \in  F}) < vu$.

If $f \in \LaurentPolytopalRingForR$ and $i \in \llbracket 1 , m \rrbracket$ are such that $\lt (f) <_r u$ for some $u \in T_i$,
then for any $v \in T_i,$ $ \lt (vf) <_r vu.$

\end{lemma}

\begin{proof}
%By hypothesis, we have $t_fd \le m((t_f)_{f \in F}) < u \in T_i$ for every term $t_fd$.
%Since $v \in T_i$, we have by (2) of Definition \ref{def:gmo} that $vt_fd < vu$ for every term $vt_f$, thus $m((vt_f)_{f \in F}) < vu$.  
Take $t$ a term of $f$. Then $t <_r u$ and $u,v \in T_i$ so 2. of Definition \ref{def:gmo} implies
$vt <_r vu.$ Taking the maximum on the $vt$'s, we conclude.
\end{proof}

\begin{proposition}[Buchberger criterion]
	\label{prop:buch_criterion}
Let $H = (h_1,\dots,h_m)$ be a family in $\LaurentPolytopalRingForR$ and $J$ the ideal generated by $H$.
For each $i \in I$ and $h_j \neq h_k \in H$, let $U(i,h_j,h_k)$ be a finite system of generators of the $T_i$-module $\lm_i(h_j)T_i(h_j) \cap \lm_i(h_k)T_i(h_k)$.
The following are equivalent:
\begin{enumerate}[(1)]
	\item $H$ is a Gröbner basis of $J$
	\item For all $i \in I$, $h_j \neq h_k$, $v \in U(i,h_j,h_k)$, $\rem(S(i,h_j,h_k,v),H) = 0$.
	\end{enumerate}
\end{proposition}
\begin{proof}
The fact that	(1) implies (2) is immediate from Prop \ref{prop:classical_easy}.

We now prove that (2) implies (1). 
By contradiction, assume that (2) is true and that $H$ is not a Gröbner basis of $J$. 
Then there exists $f \in  J$ such that $\lm(f) \notin \bigcup_{i \in I, 1\le j \le m}T_i(h_j)\lm_i(h_j)$.
Since, $f \in J = (h_1,\dots,h_m)$, we can write $f = \sum_{j=1}^{m}q_jh_j$ for some $q_j$ in $\LaurentPolytopalRingForR$. 
%By summing for each $j$ over the terms of $q_j$, we can rewrite $f$ as $\sum_{j=1}^{m}\sum_{\alpha \in \Delta(j)}t_{j,\alpha}h_j$ where for each $j$, $(t_{j,\alpha})_{\alpha \in \Delta(j)}$ is a finite family of terms. 
Write $\Delta(j)$ to be the set of terms of $q_j$. We can rewrite $f$ as $\sum_{j=1}^{m}\sum_{\alpha \in \Delta(j)}t_{j,\alpha}h_j$.
For such a writing of $f$, define $u = \max\{\lt(t_{j,\alpha}h_j), 1 \le j \le m, \alpha \in \Delta(j)\}$ and write the term $u$ as $u=c\tilde{u}$
for some $c \in K$ and some monomial $\tilde{u}.$
We have $\lt(f) <_r u$ because $\lm(f) \notin \cup_{i,j}T_i(h_j)\lm_i(h_j)$ and a cancellation has to appear.

Thus, $\valr{r}(u)$ is upper-bounded. Since $\val$ is discrete, there is a maximal $\valr{r}(u)$ among all
possible expressions of $f=\sum_{j=1}^{m}q_jh_j$. Among the expressions reaching this valuation, Lemma \ref{lemma:stric_descending_seq} ensure 
there is one such that $u$ is minimal. Let $i$ be such that $u \in T_i.$
Define $Z = \{(j,\alpha) \in \llbracket 1,m\rrbracket \times \Delta(j),\ \textrm{s.t. } \lt(t_{j,\alpha}h_j) = \gamma u,\ \gamma \in K, \ \val(\gamma)=0\}$
and $Z^\prime = \{(j, \alpha) \in \llbracket 1,m\rrbracket \times \Delta(j),\ \textrm{s.t. } \lt(t_{j,\alpha}h_j) <_r u\}$. 
We can then write:
\begin{equation}
 f = \sum_{(j,\alpha) \in Z}t_{j,\alpha}h_j + \sum_{(j,\alpha) \in Z^\prime}t_{j,\alpha}h_j \label{eq:ecriture_f_in_Buchberger}
\end{equation}
Let $g := \sum_{(j,\alpha) \in Z}t_{j,\alpha}h_j$.
We have $\lt(g) \le_r \max(\lt(f),\lt(\sum_{(j,\alpha) \in Z^\prime}t_{j,\alpha}h_j )) <_r u$ and $\lt(t_{j,\alpha}h_j) = c_{j,\alpha}\tilde{u}$ for all $(j,\alpha) \in Z$, where the $c_{j,\alpha}$ all have the same valuation.
So $g$ satisfies the conditions of Lemma \ref{lemma:sumSpair} and we can write
\begin{equation}
	g = \sum_{j=1}^{m-1}d_j\frac{\tilde{u}}{v_j}S(i,h_j,h_{j+1},v_j) + t^\prime_mh_m \label{eq:def_g_in_Buchberger}
\end{equation}
for some $d_j \in K$, $v_j \in U(i,h_j,h_{j+1})$, $\val \left( d_j \lc_i(h_j) \lc_i(h_{j+1}) \right) \geq \val (c)$ and $\tilde{u}/v_j \in T_i$ for $j<m$, and with $\lt(t^\prime_mh_m) < u$.
Now we use the hypothesis that all the S-pairs of elements of $H$ reduce to zero. 
For each $j<m$ we can write
\begin{equation}
S(i,h_j,h_{j+1},v_j) = \sum_{l=1}^{m} q^{(j)}_l  h_l,
\end{equation}
for some $q^{(j)}_l $'s in $\LaurentPolytopalRingForR$
satisfying 
\begin{align*}
\lt (q^{(j)}_l  h_l) & \leq_r \lt \left( S(i,h_j,h_{j+1},v_j) \right), \\
                    & <_r \lc_i(h_j)\lc_i(h_{j+1})v_j,
\end{align*}
where the last inequality comes from Lemma \ref{lemma:Spair}.
Since $v_j \in T_i$ and $\tilde{u}/v_j \in T_i$, we can apply
Lemma \ref{lemma:inequality}:

\begin{align*}
  \lt \left(\frac{\tilde{u}}{v_j}q^{(j)}_l  h_l\right) & <_r \lc_i(h_j)\lc_i(h_{j+1})v_j\frac{\tilde{u}}{v_j}  \\
 & = \lc_i(h_j)\lc_i(h_{j+1})\tilde{u}.
\end{align*}
Finally, using that $\val \left( d_j \lc_i(h_j) \lc_i(h_{j+1}) \right) \geq \val (c)$,
we deduce that for all $l \in \llbracket 1, m \rrbracket$ and
$j \in \llbracket1,m-1 \rrbracket$;
\[\lt \left(d_j \frac{\tilde{u}}{v_j}q^{(j)}_l  h_l\right)<_r u.\]
Inserting the expressions of $d_j \frac{\tilde{u}}{v_j}S(i,h_j,h_{j+1},v_j)$ as $\sum_{l=1}^{m} d_j \frac{\tilde{u}}{v_j}q^{(j)}_l  h_l$
in Equations \eqref{eq:def_g_in_Buchberger} and then \eqref{eq:ecriture_f_in_Buchberger},
we get an expression of $f$ in terms of the $h_j$'s with strictly smaller $u$, contradicting its minimality.
\end{proof}

