\begin{proposition}
Algorithm \ref{alg:buchberger} on page \pageref{alg:buchberger} is correct and terminates, in the sense that it 
calls the multivariate $\textrm{division}$ a finite number of times.
\end{proposition}
\begin{proof}
    Correctness of the output is clear thanks to the Buchberger criterion of Proposition \ref{prop:buch_criterion}.
    For the termination, we prove that the addition of a new $s$ to $H$ (on Line 10) can only happen a finite amount of times.
    Indeed, let us assume that there is some input $J$ such that there is an infinite amount of non-zero $r$ happening on Line 8.
    Let $i \in I$ be an index such that there is an infinite amount of $\lt(s)$ in $T_i$ and let $H_j$ be an indexation
    of all the states of the set $H$ throughout Algo. \ref{alg:buchberger}.
    Using the second property of multivariate division in Prop. \ref{prop:multi_div}, 
    we can extract from the non-decreasing sequence $(<\lm_i(g)T_i(g),\ g \in H_j>_{K[T_i]})_{j \in  \N}$ of $K[T_i]$-ideals a strictly increasing one. 
	This is not possible since $K[T_i]$ is noetherian.
\end{proof}

%We provide explicit applications of Algorithm \ref{alg:buchberger} in the Annex.
We refer to the Appendix for a \sage demo and explicit examples over $\LaurentRing$.

\begin{algorithm}
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
	\caption{Buchberger algorithm in $\LaurentPolytopalRingForR$}
	\label{alg:buchberger}
	\Input{$J = (h_1,\dots,h_m)$ an ideal of $\LaurentPolytopalRingForR$}
	\Output{a Gröbner basis of $J$}
	\BlankLine
	$H \gets \{h_1,\dots,h_m\}$; $B \gets \{(h_i,h_j),\ 1 \le i < j\le m$\}

	\While{ $ B \neq \emptyset $}{
		$(f,g) \gets$ element of $B$; $B \gets B \setminus \{(f,g)\}$\;
		\For{ $ i \in I$ }{
			$U(i,f,g) \gets$ finite set of generators of $\lm_i(f)T_i(f)\cap  \lm_i(g)T_i(g)$ \tcp*{See Sec. \ref{sec:implem}} 
			\For{ $v \in U(i,f,g)$}{
				$\_,s \gets \textnormal{division}(S(i,f,g,v),H)$  \tcp*{Algo \ref{alg:multi_div}}
				\If{ $s \neq 0$}{
					$B \gets B \cup \{(h,s),\  h \in H\}$\;
					$H \gets H \cup \{s\}$
				}
			}
		}
	}
	\Return $H$
\end{algorithm}


\section{Implementation}
\label{sec:implem}
\subsection{Computation of the $T_i(f)$'s}
\label{subsec:computation_Ti}
To make our Buchberger algorithm fully explicit, we need a method to compute the finite set of generators $U(i, f, g)$ in line 5 of Algorithm \ref{alg:buchberger}. 
This problem was not addressed when g.m.o.'s for Laurent polynomials were introduced in \cite{PU:1999}.
Our idea is to compute the $T_i(f)$'s, for which we provide a general formula in Theorem \ref{th:compute_Tif}.

The following definitions are motivated by the fact that for particular g.m.o's (such as those of Examples \ref{ex:standard_gmo_1} to \ref{ex:second_gmo}),
the sets $A_i(f)$'s, $\Delta_{i,j}$'s and $U_i(f)$'s can be obtained by classical computations in polyhedral geometry.

\begin{definition}
    We define:
	\begin{enumerate}[(1)]
        \item $A_i(f):= \{t \in T,\ t\lm_i(f) \in T_i\}.$
        \item $\Delta_{i,j}(f):=\{t \in A_i(f) \cap A_j(f), \ t\lm_i(f) > t \lm_j(f)  \}.$
        \item $U_i(f):=A_i(f) \cap \bigcap_{j \in  I, \ \lm_i(f) \neq \lm_j(f)} \left( A_j(f)^c \cup \Delta_{i,j}(f) \right).$
    \end{enumerate}
\end{definition}

\begin{thm}
	\label{th:compute_Tif}
For any $i \in I,$ 
\begin{equation}
	\label{eqn:Ti_equal_Ui}
    T_i(f)=U_i(f) 
\end{equation}
\end{thm}
\begin{proof}
    We first prove that $T_i(f) \subset U_i(f).$
    Let $t  \in T_i(f).$ Then $\lm(tf) \in T_i$ so $t \lm_i(f)=\lm(tf) \in T_i $, hence $t \in A_i(f).$
    Let $j \in I$ be such that $\lm_i(f) \neq \lm_j(f)$.
    We can write that $t \lm_i(f)=\lm(tf) \geq t \lm_j(f)$ and since  $\lm_i(f) \neq \lm_j(f)$, this inequality becomes strict:  $t \lm_i(f)> t \lm_j(f)$. 
	Depending on whether $t \lm_j(f) \in T_j$ or not, $t$ is then in $A_j^c$ or $\Delta_{i,j}$.
    In conclusion, $t \in U_i(f)$ and $T_i(f) \subset U_i(f).$

    We prove the converse inclusion. 
    Let \[t \in U_i(f)=A_i \cap \bigcap_{j \in  I, \ \lm_i(f) \neq \lm_j(f)} \left( A_j^c \cup \Delta_{i,j} \right).\]
    From $t \in A_i,$ we get that $t \lm_i(f) \in T_i.$
    Let $j \in I$ be such that $\lm(tf) \in T_j$. Then $\lm(tf)=t\lm_j(f)\in T_j$ and $t \in  A_j(f).$
    If $j$ is such that $\lm_i(f)=\lm_j(f)$ then $t\lm_i(f)=t\lm_j(f)$, hence $\lm(tf)=t\lm_i(f)$ and  $\lm(tf) \in T_i$.
    Otherwise, our assumptions provide that $t \in U_i$ but not in $A_j(f),$ hence $t \in \Delta_{i,j}(f)$.
    Consequently, $ t\lm_i(f) > t \lm_j(f) =\lm(tf)$ which is in contradiction with the definition of $\lm(tf).$
    In conclusion, $\lm(tf)=t\lm_i(f) \in T_i$, hence $t \in T_i(f)$ and $T_i(f) = U_i(f).$
\end{proof}


