\begin{thm}
	\label{th:monogenous}
Let $\le$ be a g.m.o such that the underlying conic decomposition is $(T_0, T_1, \dots, T_n)$ as defined in Example \ref{ex:standard_conic_decomposition}. For all $f \in \LaurentRing$ and $0 \leq i \leq n$, $T_i(f)$ is a monogenous $T_i$-module.
\end{thm}

\begin{proof}
Assume, for the sake of contradiction, that there exists an index $i$ and $f \in \LaurentRing$ such that the set of minimal generators of $T_i(f)$ contains at least two elements $a \neq b \in \Z^n$.
We will focus on the case where $i=0$; the proof for $i \neq 0$ is essentially the same. 
We have $a + T_0 = \bigcap_j\{x \in \Z^n \mid x_j \geq a_j\}$ and $b + T_0 = \bigcap_j\{x \in \Z^n \mid x_j \geq b_j\}$.
Let $p \in \Z^n$ be the vector such that $p_j = \min(a_j, b_j)$ for $1 \le j \le n$, which is necessarily different from $a$ and $b$. By definition of $p$, we have $a + T_0 \cup b + T_0 \subset p + T_0$.
Therefore, $p \notin T_0(f)$; otherwise, $\{a, b\}$ wouldn't be contained in a minimal set of generators of $T_0(f)$.
Since the $T_i(f)$'s cover $\Z^n$, there exists $k \neq 0$ such that $p \in T_k(f)$.
We have $T_0 \cap T_k =\{x_k = 0\} \cap \left(\bigcap_{j \neq k}\{ x_j \geq 0\}\right)$. Consequently, the set $p + T_0 \cap T_k $ contains either $a$ or $b$, depending on whether $\min(a_k, b_k) = a_k$ or $b_k$. Without loss of generality, assume it contains $a$.
From $a \in p + T_0 \cap T_k,$ we deduce that $a-p \in T_0 \cap T_k.$
Also, from $a \in p + T_0 \cap T_k \subset p+T_k$ and  $p \in T_k(f)$, we get that $a \in T_k(f)$ and thus $a \in T_k(f) \cap T_0(f)$.
Consequently we can write $(a-p)+p=a$ with $(a-p) \in T_k \cap T_0$, $p \in T_k(f)$ and $a \in T_k(f) \cap T_0(f)$. According to Lemma \ref{lemma:conic_group}, this implies $p \in T_0(f)$, contradicting $p \notin T_0(f)$.
\end{proof}

Altogether, Proposition \ref{th:minimal_number_cones} and Theorem \ref{th:monogenous} assert that, for a g.m.o defined over the decomposition of Example \ref{ex:standard_conic_decomposition}, the number of S-pairs to be reduced in Algorithm \ref{alg:buchberger} is minimized to the greatest extent possible.
For g.m.o's of this nature,  we can determine the generator $g_i$ of $T_i(f)$ using a straightforward descent algorithm.
Recall that $T_i$ is the monoid generated by $H_i = \{e_1,\dots,\hat{e_i},\dots,e_n\} \cup \{-(e_1+\dots+e_n)\}$, where $(e_1,\dots,e_n)$ denote the canonical basis of $\R^n$.
We first find a $t \in T_i(f)$ so that $T_i(f)=g_i + T_i \subset t + T_i$. Then, for each generator $h \in H_i$ of $T_i$, we compute $t = t - h$ until $t + T_i \not\subset T_i(f)$, for then we set $t = t +h$. At the end, $t = g_i$. The procedure is detailed in Algorithm \ref{alg:generator}.

\begin{remark}
	For a g.m.o as in Theorem \ref{th:monogenous}, it can easily be shown that if $g_j, g_k$ are the generators of $T_j(f), T_k(f)$ respectively, then $\lVert g_j - g_k \rVert_\infty \le 1$ (with $\Vert \cdot \Vert_\infty$ the maximum norm on $\R^n$). 
	To speed up the computation of the $T_i(f)$'s, we can first determine $g_0$ using Algorithm \ref{alg:generator}.
	Then the generators of the $T_i(f)$'s for $ i \in \llbracket1,n\rrbracket$ are contained within the (small) set $\{y \in \Z^n,\ \lVert y - g_0 \rVert_\infty \le 1\}$.
\end{remark}

\begin{remark}

   If in addition the g.m.o is defined by a function as outlined in Lemma \ref{lemma:construct_gto}, and this function restricts to an integral linear function on each cone (as illustrated in Examples \ref{ex:standard_gmo_1} and \ref{ex:standard_gmo_2}), then the generator of $T_i(f)$ can be expressed directly as the intersection of $n$ affine hyperplanes defined by integral equalities.
\end{remark}

We emphasize that the time spent computing the generators of the $T_i(f)$'s is negligible compared to the time spent reducing S-pairs in Algorithm \ref{alg:buchberger}.


\begin{algorithm}
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
	\caption{Generator of $T_i(f)$}
	\label{alg:generator}
	\Input{ $0 \le i \le n$, $f \in  \LaurentPolytopalRingForR$, $H_i = \{h_1,\dots,h_n\}$ generators of $T_i$, and the g.m.o. of Example \ref{ex:standard_conic_decomposition}}
	\Output{ $g \in \LaurentMonoid$ such that $T_i(f) = g + T_i$ }
	$t \gets$ a monomial such that all monomials of $t \times in_r(f)$ are in $T_i$ \tcp*{Use Remark \ref{rem:how_to_compute_the_Tis}}
	\For{ $h \in H_i$}{
		\While{ $t \in  T_i(f)$}{
			$t \gets t -h$\;
		}
		$t \gets t + h$\;
	}
	\Return{t}
	\BlankLine
\end{algorithm}

