\subsection{New definitions}

Let us assign an (arbitrary) indexing to the vertices of $P$: $\textnormal{vert}(P) = \{r_1, \dots, r_t\}$, 
and let $I_P$ represent the set of indexing indices: $I_P := \{1, \dots, t\}$. 
This indexing will be used to resolve ties in Definition \ref{def:new_order} when $\val_P(f) = \val_{r_i}(f)$ 
for more than one $r_i$.

\begin{definition}
\label{def:I_P(X)}
For $ f \in \MonoidOfTerms $, we define
\[ I_P(f) := \{ i \in I_P ,\ \val_P(f) = \val_{r_i}(f)\} \subseteq I_P.  \]
\end{definition}
Thus, $I_P(f) \subseteq I_P$ is the subset of indices at which $\val_P(f)$ is attained.

\begin{example}
	\label{ex:I_Pf}
	Set $ r_1 = (1,2), r_2 = (2,1), r_3 = (0,0) $.
Take $ P = \textnormal{Conv}(\{r_1,r_2,r_3\})$, $K =  \Q_2 $ and 
	$ f = \frac{1}{2}x + y^{2} + xy \in K \{x^{\pm 1}, y^{\pm 1}; P\}$.
	We have $ \val_P(f) = \min_{i \in I_P}\val_{r_i}(f) = \val_{r_1}(f) = \val_{r_2}(f) = -3$, so $ I_P(f) = \{1,2\}  $.
	This common minimum is reached at $ xy $ for $ \val_{r_1} $ and at $ \frac{1}{2}x $ and $xy$ for $ \val_{r_2} $.
\end{example}

\begin{example}
\label{ex:I_Pmonomial}
	Set $ r_1 = (0,0,3), r_2 = (1,0,0), r_3 = (-1,1,2), r_4 = (0,1,1) $.
Take $ P = \textnormal{Conv}(\{r_1,r_2,r_3,r_4\})$, $K =  \Q_2 $ and 
$ t = 2xyz^{-1} \in K \{x^{\pm 1}, y^{\pm 1}, z^{\pm 1}; P\}$.
	We have $ \val_P(t) = \min_{i \in I_P}\val_{r_i}(t) = \val_{r_2}(t) = \val_{r_4}(t) = 0$, so $ I_P(t) = \{2,4\}  $.
	Since $ t $ is a single term, this common minimum is necessarily reached at $ t $.
\end{example}


\begin{definition}
\label{def:Uibar}
For each $i \in I_P$, we define:
\begin{itemize}
    \item The monoid $V_i \subseteq T$ by: 
    \begin{align*}
		V_i &=\{ \X^\alpha \in T,\ i \in I_P(\X^{\alpha})\} \\
		    &=\{ \X^\alpha \in T,\ \val_{P}(\X^\alpha) = \min_{j \in I_P}(\val_{r_j}(\X^{\alpha})) = \val_{r_i}(\X^{\alpha})\} \\
			&=\{ \X^\alpha \in T,\ r_i \cdot \alpha \leq r_j \cdot \alpha ,\ \forall j \in I_P \}.
    \end{align*}
		% $V_i := \{ \X^{\alpha} \in T ,\ i \in I_p(\X^{\alpha})\}.$ 

	\item The subset $ V_{i,<} \subseteq  V_i $ by:
	\begin{align*}
		V_{i,<} &= \{ \X^\alpha \in T ,\  \min(I_P(\X^\alpha ) = i \} \\
				&= \left\{ \X^{\alpha} \in T,\ 
				\begin{cases}
					r_i \cdot \alpha < r_j \cdot \alpha \textnormal{ if }  j < i  \\ 
					r_i \cdot \alpha \le r_j \cdot \alpha \textnormal{ if } i \le j  
				\end{cases}, \forall j \in I_P \right\}.
	\end{align*}
	$V_{i,<}$ is obtained from $V_i$ by replacing each inequality involving $j < i$ with a strict inequality, hence the sign $ < $ in the notation.
\end{itemize}
\end{definition}

By construction, we have $ \cup_{i \in I_P} V_i = T $, 
the sets $ V_{i,<} $ are pairwise disjoint, and $ \coprod_{i \in I_P} V_{i,<} = T $. 
To aid in visualizing $ V_i $ and $ V_{i,<} $, 
we introduce their equivalents in $ \R^n $, $ C_i $ and $ C_{i,<} $:
\[
	\begin{split}
	C_{i} := \{ \alpha \in \R^n ,\ i \in I_P(\X^{\alpha})\} &\quad \quad C_{i,<} := \{ \alpha \in \R^n ,\ i= \min(I_P(\X^{\alpha})) \} 
	\end{split}
\]

That way, we have $ V_i = \{ \X^{\alpha},\ \alpha \in C_{i}\cap \Z^n\}$,
$ V_{i,<} = \{ \X^{\alpha} ,\ \alpha \in C_{i,<}\cap\Z^n\}$, and so
the monoid $ V_i $ (resp. the set $ V_{i,<} $) can be identified with the monoid of 
integer-coordinate points in $C_i$ (resp. the set of integer-coordinate points in $ C_{i,<}$). 

\bigbreak


Now consider a conic decomposition such that each cone is contained within a single \( V_i \).
For each \( i \in I_P \), let \( D_i \) be the indexing set containing the indices of all cones contained in \( V_i \). 
Hence for each \( V_i \), the cones contained in $ V_i $, noted \( (T_{i,j})_{j \in D_i} \), is a conic decomposition of the monoid \( V_i \).
and the collection 
\[
\{T_{i,j} \mid i \in I_P, j \in D_i\}
\] 
forms a conic decomposition of \( T \).
An alternative method to construct such a conic decomposition is to take the union of the traces of a conic decomposition of \( T \) on each \( V_i \). 
We provide four visual examples in Figures~\ref{fig:decompo_point}--\ref{ex:decompo_full_bad} on page \pageref{fig:decompo_point}-\pageref{ex:decompo_full_bad}. 
In each case:
\begin{itemize}
    \item The left figure represents the polytope $P$,  
    \item The middle figure illustrates the cones $C_i$ (and thus $V_i$), and  
    \item The right figure shows the decomposition of each $V_i$ into the various $T_{i,j}$ (dashed lines).
	\item The sets $ C_{i,<} $ (and thus $ V_{i,<} $) are not directly shown on Figures ~\ref{fig:decompo_point}--\ref{ex:decompo_full_bad}, but
	can be obtained by removing from $ C_i $ all the facets $ C_i \cap C_j $ for $ j < i $.
\end{itemize}

\begin{remark}
    \label{re:different_breakings}
    We make a few remarks on Figures~\ref{fig:decompo_point}--\ref{ex:decompo_full_bad}.
    \begin{itemize}
        \item In Figure \ref{fig:decompo_point}, $C_1 \cap \Z^n = \Z^n$, thus $V_1 \cap T = T$, and $\{T_{1,1}, T_{1,2}, T_{1,3}\}$ is simply a conic decomposition of $T$. This corresponds to the case studied in the first part of the paper.  
        \item In Figure \ref{fig:decompo_segment}, the monoids $V_1$ and $V_2$ are not conic decompositions of themselves (each contains non-trivial invertible elements), so we must break each of them into smaller pieces (two in this case).
        \item In Figure \ref{ex:decompo_full}, all the $V_i$ are already conic decompositions of themselves, so we can simply set $T_{i,1} = V_i$ for each $i$.  
        \item In Figure \ref{ex:decompo_full_bad}, we reuse the polytope from Figure 4 but further decompose the monoids $V_1$ and $V_3$ into two pieces each. While this is possible, it is not necessary.  
        In general, we aim to minimize the number of cones in our conic decomposition. 
        Thus, we decompose each $V_i$ into smaller pieces only if $V_i$ is not already a conic decomposition of itself, 
        as in Figures \ref{fig:decompo_point} and \ref{fig:decompo_segment}, and avoid unnecessary decompositions like those shown in Figure \ref{ex:decompo_full_bad}.
    \end{itemize}
\end{remark}


