Let $ \le_{\omega} $ be a generalized order with respect to the conic decompositon $ \{ T_{i,j} ,\  i \in I_P, j \in D_i \} $.
\begin{definition}
\label{def:new_order}
We define a preorder $\le_{P}$ on $\MonoidOfTerms$ by:
\[ a\X^u \le_{P} b\X^v \iff  \begin{cases}
		\valP(b\X^v) < \val_P(a\X^u) &(1)\\
		\textnormal{\textbf{or}} \\
		\textnormal{equality in (1)} \textnormal{\textbf{ and }} \min(I_P(b\X^v)) < \min(I_P(a\X^u)  &(2) \\
		\textnormal{\textbf{or}} \\ 
		\textnormal{equality in (2)} \textnormal{\textbf{ and }} \X^v \ge_{\omega} \X^u 

	\end{cases} \]

For $ f \in \LaurentPolytopalRing $, $ i \in I_P $, $ j \in D_i $ we define:
\begin{enumerate}
	\item  $\lm(f), \lc(f) $ and $ \lt(f) $, the leading monomial,
coefficient and term of $ f$ for this preorder. 
	\item $ \textnormal{in}_{P}(f) := 
		   \textnormal{in}_{r_k}(f) $ where $ k = \min(I_P(\lm(f))) $.

	   \item \nopagebreak[4] $ \lm_{i,j}(f), \lc_{i,j}(f)$ and $\lt_{i,j}(f) $ the
		   leading monomial, coefficient and term of $ \textnormal{in}_{r_i}(f) $ for the cone $ T_{i,j} $
		   in the sense of Definition \ref{def:leadings}.

	\item $ T_{i,j}(f) := \{ t \in T ,\ \lm(tf) \in T_{i,j}\cap V_{i,<}\} $
\end{enumerate}
\end{definition}


\begin{remark}
\label{rem:convergence_new}
Lemma \ref{lemma:topological_order} remains true for $ \le_P $ since 
the additional tie-breaking step happens after comparing the $ \val_P $'s.
\end{remark}



The following Lemma will be used in the proof of Proposition \ref{prop:lmij_unicity}  below.
\begin{lemma}
\label{lem:tij_module}
	Suppose $ f \in \LaurentPolytopalRing $ satisfies $ \lm(f) \in V_{i,<} $ and let $ t \in V_i $.
	Then $ \lm(tf) \in V_{_i,<} $.
\end{lemma}

\begin{proof}
\label{pr:tij_module}

	We have:
	\begin{align}
		\label{eq:proof_tij_module}
	\val_P(tf) = \min_{j \in I_P}(\val_{r_{j}}(tf))
					= \min_{j \in I_P}(\val_{r_{j}}(t) + \val_{r_j}(f)).
	\end{align}

	Since $t \in V_i$, we have $i \in I_P(t)$, that is $ \min_{j \in I_P}(\val_{r_j}(t)) = \val_{r_i}(t) $.
	Similarly, $\lm(f) \in V_{i,<} \subseteq  V_i $, so $i \in I_P(f)$ and $ \min_{j \in I_p}(\val_{r_j}(f)) = \val_{r_i}(f) $.  
	Thus for any $ (j,k) \in I_P^2 $, we have $\val_{r_i}(t) + \val_{r_i}(f) \le \val_{r_j}(t) + \val_{r_k}(f)$.
	This is true in particular when $j = k$, so the minimum in (\ref{eq:proof_tij_module}) is reached at $ i$, that is $i \in I_P(tf)$.  

	Now we show that if $ j \in I_P(tf) $, then $ i \le j $.
	Suppose that $ j \in I_P(tf) $.
	Then $\val_{r_j}(t) + \val_{r_j}(f) = \val_{r_i}(t) + \val_{r_i}(f)$.
	Since $t \in V_i$, $\val_{r_j}(t) \geq \val_{r_i}(t)$,
	so $\val_{r_j}(f) \leq \val_{r_i}(f)=\val_P(f).$
	Thus $\val_{r_j}(f)=\val_P(f)$ and $ j \in I_P(f) $. 
%	We have $ j \in I_P(f) $, otherwise if $ j \notin I_P(f) $, we get:
%\[ \val_{r_j}(t) + \val_{r_j}(f) > \val_{r_j}(t) + \val_{r_i}(f) \ge \val_{r_i}(t) + \val_{r_i}(f), \]
%	and so $ j \notin I_P(tf) $, contradiction.
	In addition $ \lm(f) \in V_{i,<} $, thus $ i = \min(I_P(f))$, and then $ i \le j $.

	Finally $ i = \min(I_P(tf)) $, that is $ \lm(tf) \in V_{i,<} $.
\end{proof}


\begin{proposition}
\label{prop:lmij_unicity}
Let $f, g \in \LaurentPolytopalRing$ and $a \in T_{i,j}(f)$. Then:
\begin{enumerate}
    \item $\lm(af) = a \lm_{i,j}(f)$.
    \item $ \lm_{i,j}(f) T_{i,j}(f) \cap \lm_{i,j}(g) T_{i,j}(g) \subseteq T_{i,j} \cap V_{i,<}$ is a finitely generated $T_{i,j}$-module.
\end{enumerate}
\end{proposition}

\begin{proof}
\label{proof:lmij_unicity}
\begin{enumerate}
	\item By definition, $a \in T_{i,j}(f)$ means that $\lm(af) \in T_{i,j} \cap V_{i,<} \subseteq V_{i,<}$.
The elements of $V_{i,<}$ are precisely the monomials $t$ in $T$ such that $\min(I_P(t)) = i$, so
$\min(I_P(\lm(af))) = i$.  
By ($2$) of Definition \ref{def:new_order}, it follows that $\textnormal{in}_{P}(af) = \textnormal{in}_{r_i}(af)$, 
and the latter is equal to $a \times \textnormal{in}_{r_i}(f)$, since $\val_{r_i}$, unlike $\val_P$,
satisfies $\val_{r_i}(af) = \val_{r_i}(a) + \val_{r_i}(f)$.  

Now by Definition \ref{def:new_order}, $\lm(af)$ is the greatest term under the generalized order
$\le_{\omega}$ of $\textnormal{in}_{P}(af) = a \times \textnormal{in}_{r_i}(f)$.  
Since $a \in  T_{i,j}(f)$, this greatest term is equal to
$a \times \lm_{i,j}(f)$ by (3) of Definition \ref{def:new_order}.
\item Let $A(i,j,f,g) := \lm_{i,j}(f) T_{i,j}(f) \cap \lm_{i,j}(g) T_{i,j}(g)$.  
	We first show that $ A(i,j,f,g) $ is a $ T_{i,j} $-module. 
	For this, it is sufficient to show that if $h \in \LaurentPolytopalRing$, then $T_{i,j}(h)$ is a $T_{i,j}$-module.  
	Indeed, if this holds, then $\lm_{i,j}(f)T_{i,j}(f)$ and $\lm_{i,j}(g)T_{i,j}(g)$ are also $T_{i,j}$-modules,  
	and so is their intersection $ A(i,j,f,g) $.

	Let $ a \in T_{i,j}(h)$ and $ t \in T_{i,j} $. We aim to show
	that $ at \in T_{i,j}(h) $, that is $ \lm(tah) \in T_{i,j}\cap V_{i,<} $.

	% Since $ t \in T_{i,j} \subseteq V_i $ and $ \lm(ah) \in V_{i,<} $, we can apply Lemma \ref{lem:tij_module} to $ t $
	% and $ ah $ to get $ \lm(tah) \in V_{i,<} $. We then get by item ($ 2 $) of Definition \ref{def:new_order}
	% $ \textnormal{in}_P(tah) = \textnormal{in}_{r_i}(tah) = ta\times \textnormal{in}_{r_i}(h) $,
	% and $  \lm(taf) $ equals the maximum under $ \le_{\omega} $ of the terms of $ t\times\a \textnormal{in}_{r_i}(h) $.
	% But $ a \in T_{i,j}(h) $, so the greatest term of $ a \times \textnormal{in}_{r_i(f)} $ is $ a \times \lm_{i,j}(f) $
	% and is in $ T_{i,j} $. Now $ t $ is in $ T_{i,j} $, so by item 2. of Definition \ref{def:gmo}, $ \lm(taf) \in T_{i,j} $ also.
	% This conclude the proof that $ A(i,j,f,g) $ is a $ T_{i,j} $-module.



Since $ t \in T_{i,j} \subseteq V_i $ and $ \lm(ah) \in V_{i,<} $, 
we can apply Lemma \ref{lem:tij_module} to $ t $ and $ ah $, 
yielding $ \lm(tah) \in V_{i,<} $. 
By item (2) of Definition \ref{def:new_order}, we then have:
\[
\textnormal{in}_P(tah) = \textnormal{in}_{r_i}(tah) = ta \times \textnormal{in}_{r_i}(h).
\]
So $ \lm(tah) $ equals the maximum, under $ \le_{\omega} $, of the terms of $ t \times a \times \textnormal{in}_{r_i}(h) $. 
Since $ a \in T_{i,j}(h) $, the greatest term of $ a \times \textnormal{in}_{r_i}(h) $ 
is $ a \times \lm_{i,j}(h) $, and this term belongs to $ T_{i,j} $.

Now, since $ t \in T_{i,j} $, by item (2) of Definition \ref{def:gmo}, 
the maximum on the terms of $ t \times a \times \textnormal{in}_{r_i}(h) $, which equals $ \lm(tah) $, 
is in $ T_{i,j} $.

% Since \( t \in T_{i,j} \subseteq V_i \) and \( \lm(ah) \in V_{i,<} \),
% we can apply Lemma \ref{lem:tij_module} to \( t \) and \( ah \), 
% yielding \( \lm(tah) \in V_{i,<} \).
% By item (2) of Definition \ref{def:new_order}, we then have:
%
% \[
% \textnormal{in}_P(tah) = \textnormal{in}_{r_i}(tah) = ta \times \textnormal{in}_{r_i}(h).
% \]
%
% So \( \lm(tah) \) equals the maximum, under \( \le_{\omega} \), of the terms of \( t \times a \times \textnormal{in}_{r_i}(h) \).
% Since \( a \in T_{i,j}(h) \), the greatest term of \( a \times \textnormal{in}_{r_i}(h) \)
% is \( a \times \lm_{i,j}(h) \), and this term belongs to \( T_{i,j} \).
%
% Now, since \( t \in  T_{i,j} \), by item (2) of Definition \ref{def:gmo},
% the maximum on the terms of $ t \times a \times \textnormal{in}_{r_i}(h) $, whih equals $ \lm(ath) $,
% is in $ T_{i,j} $.
So $ \lm(tah) \in V_{i,<}\cap T_{i,j} $, and 
this completes the proof that \( A(i,j,f,g) \) is a \( T_{i,j} \)-module.

	Now we prove that any subset $X \subseteq T_{i,j}$ is finitely generated as a $T_{i,j}$-module.  
This is equivalent to showing that the following partial order on $X$:
\[
a \preceq b \iff \exists u \in T_{i,j},\ b = au,
\]
is a well partial order.
Let $v_1, \dots, v_k$ be a finite generating set of $T_{i,j}$. For every $t \in X \subseteq T_{i,j}$, 
there exists non-negative integers $ n_1, \dots, n_k $ (depending on $ t $) such that $t = v_{1}^{n_1} \dots v_{k}^{n_k}$.
We embed $X$ into $\N^k$ via the map $\phi: t = v_{1}^{n_1} \dots v_{k}^{n_k} \mapsto (n_1, \dots, n_k) \in \N^k.$
Under this embedding, the partial order $\preceq$ on $X$ corresponds to the component-wise order $\leq$ on $\phi(X)$ in $\N^k$:  
\[
a \preceq b \text{ in } X \iff \phi(a) \leq \phi(b) \text{ in } \N^k,
\]
so we have that $\preceq$ is a well partial order on $X$ if and only if $\leq$ is a well partial order on $\phi(X)$.  
By Dickson's Lemma, the component-wise order on any subset of $\N^k$ is a well partial order, so $\preceq$ is a well partial order on $X$.

Applying this result to $X = A(i,j,f,g)$, we conclude that $A(i,j,f,g)$ is finitely generated as a $T_{i,j}$-module.
\end{enumerate}
\end{proof}



With these adapted definitions, the definition of Gröbner basis becomes:

\begin{definition}
    Let $J$ be an ideal in $\LaurentPolytopalRing$ and $G$ be a finite subset of $J \setminus \{0\}$.  
    We say that $G$ is a Gröbner basis of $J$ (with respect to the g.m.o $\le_{\omega}$ for the conic decomposition $\{T_{i,j}, i \in I_P, j \in D_i\}$) when:
    \[
    \lm(J) = \bigcup_{g \in G, i \in I_P, j \in D_i} T_{i,j}(g) \lm_{i,j}(g).
    \]
\end{definition}

\subsection{Buchberger algorithm in $ \LaurentPolytopalRing $ }

We now adapt the multivariate division algorithm (Algorithm \ref{alg:multi_div}),
the Buchberger criterion (Proposition \ref{prop:buch_criterion}),
and the Buchberger algorithm (Algorithm \ref{alg:buchberger}) from Sections 
\ref{sec:MultiVarDivision} and \ref{sec:GBpolytopal} to our new setting.

This process involves substituting \( \lm_i(f) \) and \( T_i(f) \) with their
newly defined counterparts, \( \lm_{i,j}(f) \) and \( T_{i,j}(f) \), respectively, and substituing $ \le_r $
with $ \le_P $.
Any additional changes beyond these substitutions are also noted where applicable. 
Full proofs can be found in the Appendices.

To simplify notation when indexing the cones in the conic decomposition
\( \{T_{i,j},\ i \in I_P,\ j \in D_i\} \), we define \( L := \{(i,j) \mid i \in I_P,\ j \in D_i \} \).

\subsubsection{Division algorithm}

In Proposition \ref{prop:multi_div_new}, the only difference from 
Proposition \ref{prop:multi_div} is the replacement of $ \le_r $ with $ \le_P $ in (3).

\begin{proposition}
	\label{prop:multi_div_new}
	Let $f \in \LaurentPolytopalRing$ and $G$ be a finite subset of $\LaurentPolytopalRing$. 
	Algorithm \ref{alg:multi_div} produces a family $(q_g)_{g \in  G}$ and $r$ in $\LaurentPolytopalRing$ such that:
	\begin{enumerate}[(1)]
		\item $f = \sum_{g \in  G}q_gg + r$
