% By construction, the sequence $(\lt(f_j))_{j \ge 0}$ is strictly decreasing.
% By Lemma \ref{lemma:topological_order}, we deduce that 
% $\valP(r_{j+1}-r_j)$ and the $\valP(q_{g,j+1}-q_{g,j})$'s tend to $+\infty$ when $j \to +\infty$.
% Thus $r_j$ and the $q_{g,j}$'s converge in $K\{\mathbf{X};P\}$.
% Their limits % elements $q_g=\lim_{j \to +\infty}q_{g,j}$ for $g \in G$ and $r = \lim_{j \to +\infty}r_j$ 
% satisfy the requirements of the proposition.
% \end{proof}

\begin{algorithm}
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
	\caption{Multivariate division algorithm in $K\{\mathbf{X};P\}$} 
	\label{alg:multi_div_new}
	\Input{$f,g_1,\dots,g_m \in K\{\mathbf{X};P\}$}
	\Output{$q_1,\dots,q_m,r$ satisfying Prop \ref{prop:multi_div_new}}
	\BlankLine
	$q_1,\dots,q_m,r\gets 0$\;
	\While{ $f \neq 0$}{
		%$i \gets$ index in $I$ such that $\textnormal{lm}(f) \in T_i$\;
		\While{ $\exists (i,j) \in L$ and $k \in  \llbracket 1,m \rrbracket$ such that $\lm\left(\frac{\lm(f)}{\lm_{i,j}(g_k)}g_k\right) = \lm(f)$}{
			$t \gets \frac{\lt(f)}{\lt_{i,j}(g_k)}$\;
			$q_k \gets q_k + t $\;
			$f \gets f - tg_k $\;
		}
		$r \gets r + \lt(f)$

		$f \gets f - \lt(f)$;
	}
	\Return $q_1,\dots,q_m,r$
\end{algorithm}

\subsubsection{S-pairs and Buchberger criterion}

% The Definition \ref{def:Spair_new} of $S$-pair  is exactly the Same as Definition $\ref{def:Spair}  $.
% In Lemma \ref{lemma:sumSpair_new}, the monomial $ u $
% in which the colliding occurs needs to be in $ T_{i,j}\cap V_{i,<} $ (instead of just $ T_{i,j} $ in Lemma \ref{lemma:sumSpair})
% to accomodate the new definition of $ T_{i,j}(f) $ ((4) of Definition \ref{def:new_order}).
% In the proof of Proposition \ref{prop:buch_criterion_new} (Appendix \ref{app:proof_criterion}),
% the Lemma \ref{lemma:inequality} is replaced by a refined version \ref{lemma:inequality_new}
% taking into account the intermediate tie-breaking involving the indices $ I_P $.
% Otherwise, the statments are the same.


The definition of \( S \)-pair in Definition \ref{def:Spair_new} is identical to that in Definition \ref{def:Spair}. 
In Lemma \ref{lemma:sumSpair_new}, the monomial \( u \) where the collision occurs must belong to \( T_{i,j} \cap V_{i,<} \) (instead of just \( T_{i,j} \) as in Lemma \ref{lemma:sumSpair}) to accommodate the new definition of \( T_{i,j}(f) \) (item (4) of Definition \ref{def:new_order}). 

In the proof of the Buchberger criterion of Proposition \ref{prop:buch_criterion_new} (Appendix \ref{app:proof_criterion}), Lemma \ref{lemma:inequality} is replaced by a refined version, Lemma \ref{lemma:inequality_new}, which accounts for the intermediate tie-breaking involving the indices \( I_P \). 

Otherwise, the statements remain the same.

\begin{definition}[S-pair]
	\label{def:Spair_new}
	Let $f,g \in \LaurentPolytopalRing$ and $(i,j) \in L$. 
	For $v \in \lm_{i,j}(f)T_{i,j(}(f) \cap \lm_{i,j}(g)T_{i,j}(g)$, we define:
	\[ S((i,j),f,g,v) := \lc_{i,j}(g)\frac{v}{\lm_{i,j}(f)}f - \lc_{i,j}(f)\frac{v}{\lm_{i,j}(g)}g.\]
\end{definition}

\begin{lemma}
	\label{lemma:sumSpair_new}
Let $h_1,\dots,h_m \in \LaurentPolytopalRing$ and $(i,j) \in L$. 
For $1\le k \le m-1$, let $U((i,j),h_k,h_{k+1})$ be a finite system of generators of  $\lm_{i,j}(h_k)T_{i,j}(h_k) 
\cap \lm_{i,j}(h_{k+1})T_i(h_{k+1})$ which exists by Proposition \ref{prop:lmij_unicity}.
%\TVshort{J'ai changé la référence}
%\ref{prop:Uifg}.
Suppose that there are $t_1,\dots, t_m \in \MonoidOfTerms$, $u \in T_{i,j} \cap V_{i,<}$ and $c \in \val{}(K^\times)$ such that
\begin{itemize}
	\item for all $k \in \{1,\dots,m\}$, $\lt(t_kh_k) = c_ku$ with $\textnormal{val}(c_k) = c$
	\item  $\lt(\sum_{k=1}^{m}t_kh_k) <_P c_1u$.
\end{itemize}

Then there are elements $d_k \in K$, $v_k \in U((i,j),h_k,h_{k+1})$ for $1 \le k \le m-1$ and $t_m^\prime \in \LaurentPolytopalRing$ such that:
\begin{enumerate}[(1)]
	\item $\sum_{j=k}^{m}t_kh_k = \sum_{k=1}^{m-1}d_j\frac{u}{v_k}S((i,j),h_k,h_{k+1},v_k) + t_{m}^\prime h_m$. \label{enum:1_new}
	\item $\valP(t^\prime_mh_m) > \valP(uc_1)$. \label{enum:2_new}
	\item $\frac{u}{v_k} \in T_{i,j}$ for all $k <m$. \label{enum:3_new}
	\item For all $k <m$, $\val \left( d_k \lc_{i,j}(h_k) \lc_{i,j}(h_{k+1}) \right) \geq c.$ \label{enum:4_new}
	% \item $\val{P}(d_j\frac{u}{r_j}) + \max(\val{P}(h_j),\val{P}(h_{j+1})) \ge \val{P}(uc_1)$ for $j < m$.
\end{enumerate}

\end{lemma}

\begin{proposition}[Buchberger criterion]
	\label{prop:buch_criterion_new}
Let $H = (h_1,\dots,h_m)$ be a family in $\LaurentPolytopalRing$ and $J$ the ideal generated by $H$.
For each $(i,j) \in I$ and $h_k \neq h_s \in H$, let $U((i,j),h_k,h_s)$ be a finite system of generators of 
the $T_{i,j}$-module $\lm_{i,j}(h_s)T_{i,j}(h_s) \cap \lm_{i,j}(h_k)T_{i,j}(h_k)$.
The following are equivalent:
\begin{enumerate}[(1)]
	\item $H$ is a Gröbner basis of $J$
	\item For all $(i,j)  \in L$, $h_k \neq h_s$, $v \in U((i,j),h_s,h_k)$:
		\begin{equation}
			\rem(S((i,j),h_s,h_k,v),H) = 0
		\end{equation}
		.
	\end{enumerate}
\end{proposition}
\subsubsection{Buchberger algorithm}

In the Buchberger algorithm (Algorithm \ref{alg:buchberger_new}), we just update line $ 7 $ to use
Algorithm \ref{alg:multi_div_new} when reducing an $ S $-pair.
% \begin{proposition}
% 	\label{prop:buchberger_new}
% Algorithm \ref{alg:buchberger_new} on page \pageref{alg:buchberger_new} is correct and terminates, in the sense that it 
% calls the multivariate $\textrm{division}$ a finite number of times.
% \end{proposition}
\begin{algorithm}
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
	\caption{Buchberger algorithm in $\LaurentPolytopalRing$}
	\label{alg:buchberger_new}
	\Input{$J = (h_1,\dots,h_m)$ an ideal of $\LaurentPolytopalRing$}
	\Output{a Gröbner basis of $J$}
	\BlankLine
	$H \gets \{h_1,\dots,h_m\}$; $B \gets \{(h_s,h_k),\ 1 \le s < k\le m$\}

	\While{ $ B \neq \emptyset $}{
		$(f,g) \gets$ element of $B$; $B \gets B \setminus \{(f,g)\}$\;
		\For{ $ (i,j) \in L$ }{
			$U((i,j),f,g) \gets$ finite set of generators of $\lm_{i,j}(f)T_{i,j}(f)\cap  \lm_{i,j}(g)T_{i,j}(g)$\; 
			\For{ $v \in U((i,j),f,g)$}{
				$\_,r \gets \textnormal{division}(S((i,j),f,g,v),H)$  \tcp*{Algo \ref{alg:multi_div_new}}
				\If{ $r \neq 0$}{
					$B \gets B \cup \{(h,r),\  h \in H\}$\;
					$H \gets H \cup \{r\}$
				}
			}
		}
	}
	\Return $H$
\end{algorithm}

