\section{Proof of Proposition \ref{prop:multi_div_new}}
\begin{proof}
\label{proof:multi_div_new}
We construct by induction sequences $(f_k)_{k\ge 0}$, $(q_{g,k})_{k \ge 0}$ for $g \in G$ and $(r_k)_{k\ge 0}$ such that for all $k \ge 0$:
\[ f = f_k + \sum_{g \in G}q_{g,k}g + r_k,\]
and $\lt(f_k)_{k\ge 0}$ is strictly decreasing for $ \le_{P} $.

We first set $f_0 = f$, $r_0 = 0$ and $q_{g,0} = 0$ for all $g \in G$. 

If there exists $(i,j) \in L$ and $g \in G$ such that \[\lm \left( \frac{\lm(f_k)}{\lm_{i,j}(g)}g \right) = \lm(f_k) \in T_{i,j} \cap V_{i,<}, \] we set $f_{k+1} = f_k - tg$ and $q_{g,k+1} = q_{g,k} + tg$ where $t = \frac{\lt(f_k)}{\lt_{i,j}(g)}$, and leave unchanged $r_k$ and the other $q_{g,k}$'s. 

Otherwise, we set $f_{k+1} = f_k - lt(f_k)$ and $r_{k+1} = r_k + lt(f_k)$ and leave unchanged the $q_{g,k}$'s. 

By construction, the sequence $(\lt(f_k))_{k \ge 0}$ is strictly decreasing for $ \le_{P} $.
By Remark \ref{rem:convergence_new}, we deduce that 
$\valP(r_{k+1}-r_k)$ and the $\valP(q_{g,k+1}-q_{g,k})$'s tend to $+\infty$ when $k \to +\infty$.
Thus $r_k$ and the $q_{g,k}$'s converge in $K\{\mathbf{X};P\}$.
\end{proof}

\section{Proof of Lemma \ref{lemma:sumSpair_new}}
\begin{proof}
\label{proof:sumSpair_new}

	Write $p_k = \frac{t_kh_k}{c_k}$, $e_k = \sum_{s=1}^{k}c_s$ and $t_k=\gamma_k \tilde{t}_k$ for some $\gamma_k \in K$
	and some monomial $\tilde{t}_k$.
	By hypothesis $u$ is in $T_{i,j}\cap V_{i,<}$ and $u = \tilde{t_k}\lm_{i,j}(h_k) \in T_{i,j}(h_k)\lm_{i,j}(h_k)$ for all $k$. 
	This implies that for all $k <m$ we have:
	\[u \in  T_{i,j}(h_k)\lm_{i,j}(h_k) \cap T_{i,j}(h_{k+1})\lm_{i,j}(h_{k+1}) = T_{i,j}\cdot U((i,j),h_k,h_{k+1})\]
	We deduce that for all $k<m$, there exist $s_k \in T_{i,j}$ and $v_k \in  U((i,j),h_k, h_{k+1}$) such that $u = s_kv_k$.
	Now write
	\begin{align}
	\sum_{k=1}^{m}t_kh_k &= e_1(p_1 - p_2) + \dots + e_{m-1}(p_{m-1}- p_m) + e_mp_m \label{eqn:somme_telescopique_new}
	\end{align}
	For all $k<m$, we have $\lt(t_k h_k)=c_k u= \gamma_k \lc_{i,j}(h_k)\tilde{t}_k \lm_{i,j}(h_k), $
	hence $\frac{t_k}{c_k \tilde{t}_k}=\frac{1}{\lc_{i,j}(h_k)}$.
	For any $k<m$, put $P_k = p_k - p_{k+1}$. We can then write:
	\begin{align*}
		P_k &= \frac{u}{v_k}\left(\frac{v_k}{u}p_k - \frac{v_k}{u}p_{k+1}\right) = \frac{u}{v_k}\left(\frac{t_kv_kh_k}{c_k\tilde{t}_k\lm_{i,j}(h_k)} - \frac{t_{k+1}v_kh_{k+1}}{c_{k+1}\tilde{t}_{k+1}\lm_{i,j}(h_{k+1})} \right)  \\
					  &= \frac{u}{v_k}\left(\frac{1}{\lc_{i,j}(h_k)}\frac{v_k}{\lm_{i,j}(h_k)}h_k - \frac{1}{\lc_{i,j}(h_{k+1})}\frac{v_k}{\lm_{i,j}(h_{k+1})}h_{k+1}\right)	\\
					  &= \frac{1}{\lc_{i,j}(h_k)\lc_{i,j}(h_{k+1})}\frac{u}{v_k}\left(\lc_{i,j}(h_{k+1})\frac{v_k}{\lm_{i,j}(h_k)}h_k - \lc_{i,j}(h_k)\frac{v_k}{\lm_{i,j}(h_{k+1})}h_{k+1}\right) \\
					  &= \frac{1}{\lc_{i,j}(h_k)\lc_{i,j}(h_{k+1})}\frac{u}{v_k}S((i,j),h_k,h_{k+1}).
	\end{align*}
	Plugging in the last expression back into equation \eqref{eqn:somme_telescopique_new} gives the desired equality
	with $d_k = \frac{e_k}{\lc_{i,j}(h_k)\lc_{i,j}(h_{k+1})}$ and $t^{\prime}_m = \frac{e_m}{c_m}t_m$.
	It satisfies \ref{enum:1_new}.
	The hypothesis forces $\val{}(e_m) > \val{}(c_m)$. Then we have $\valP(t^\prime_mh_m) = \val{}(e_m) + \valP(u) > \val{}(c_m) + \valP(u) = \valP(c_1u)$, which proves \ref{enum:2}.
	In addition, $\frac{u}{v_k} = s_k \in T_{i,j}$, which proves \ref{enum:3_new}.
	Finally, using that $\val (e_k) \geq c$ and $d_k = \frac{e_k}{\lc_{i,j}(h_k)\lc_{i,j}(h_{k+1})}$, one gets \ref{enum:4_new}.
\end{proof}

\section{Proof of Proposition \ref{prop:buch_criterion_new}}
\label{app:proof_criterion}
Before presenting the proof, we establish two lemmas that are adaptations of 
Lemma \ref{lemma:Spair} and Lemma \ref{lemma:inequality}, respectively.

\begin{lemma}
\label{lemma:Spair_new}
For $f,g \in \LaurentPolytopalRing$, $(i,j) \in L$ and $v \in \lm_{i,j}(f)T_{i,j}(f) \cap \lm_{i,j}(g)T_{i,j}(g)$, we have
$\lt(S((i,j),f,g,v)) <_{P} \lc_{i,j}(f)\lc_{i,j}(g)v$.
\end{lemma}

\begin{proof}
Since $v \in T_{i,j}(f)\lm_{i,j}(f)\cap T_{i,j}(g)\lm_{i,j}(g)$, there exists $m_f \in T_{i,j}(f)$
and $m_g \in T_{i,j}(g)$ such that $v = \lm(m_ff) = \lm(m_gg) = m_f\lm_{i,j}(f) = m_g\lm_{i,j}(g)$. 
Then the leading terms of $\lc_{i,j}(g)\frac{v}{\lm_{i,j}(f)}f$ and  $\lc_{i,j}(f)\frac{v}{\lm_{i,j}(g)}g$
are both equal to $\lc_{i,j}(f)\lc_{i,j}(g)v$.
They cancel out leaving $\lt(S((i,j),f,g,v)) <_{P} \lc_{i,j}(f)\lc_{i,j}(g)v$.
\end{proof}

\begin{lemma}
\label{lemma:inequality_new}
If $f \in \LaurentPolytopalRing$ and $(i,j) \in L$ are such that $\lt (f) <_{P} u$ for some term $ u $ 
satisfying $\lm(u) \in T_{i,j}\cap V_{i,<}$,
then for any $v \in T_{i,j}$ we have $ \lt(vf) <_P vu.$
\end{lemma}

\begin{proof}
The coefficient of $ u $ play no role in the proof, so we can
assume that $ u = \lm(u) $.
Take $t$ a term of $f$. Then $t <_{P} u$. Since $ u, v \in V_i$,
we have by Lemma \ref{lem:tij_module} that $ \val_{P}(uv) = \val_{r_i}(u) + \val_{r_i}(v) = \val_P(u) + \val_P(v) $.
We separate in 3 cases following Definition \ref{def:new_order}:
\begin{itemize}
\item Case $ \val_P(u) < \val_P(t) $.

Then $ \val_P(uv) = \val_P(u) + \val_P(v) < \val_P(t)
+ \val_P(v) \le \val_P(tv)$. Thus $ tv <_{P} uv $.

\item Case $ \val_P(u) = \val_P(t) $ and $ \min(I_P(u)) < \min(I_P(t))$.

Then $ \val_P(uv) = \val_P(u) + \val_P(v) = \val_P(t) + \val_P(v) \le \val_P(tv) $.
If $ \val_P(uv) < \val_P(tv)$, then $ tv <_p uv$ and we are done, so let's suppose
$ \val_P(uv) = \val_P(tv) $. Then we have
\begin{equation}
	\label{eq:item_2}
	\val_P(uv) = \val_{r_i}(u) + \val_{r_i}(v) = \val_P(tv) = \min_{k \in I_P}(\val_{r_k}(t) + \val_{r_k}(v))
\end{equation}

We have $ u \in V_{i,<} $, so $ i = \min(I_P(u))$.
Now since $ \val_P(u) = \val_P(t) $ and $ i = \min(I_P(u)) < \min(I_P(t))$,
we have $ \val_{r_k}(t) > \val_{r_i}(u)$ for $ k \le i $.
Also, since $ v \in T_{i,j} \subseteq V_{i}$, we have
$ \val_{r_k}(v) \ge \val_{r_i}(v) $ for any $ k \in I_P $.
Thus for $ k \le i $, we have
$ \val_{r_k}(t) + \val_{r_k}(v) > \val_{r_i}(u) + \val_{r_i}(v) $. It follows that
the minimum in (\ref{eq:item_2})
can be reached only for a $ k > i $. This shows $ \min(I_P(tv)) > \min(I_P(uv)) $ and so $ tv <_P vu $.

\item Case $ \val_P(u) = \val_P(t) $ and $ \min(I_P(u)) = \min(I_P(t))$ and $ u >_{\omega} t $

Reasoning like in case 2 with $ \min(I_P(u)) = \min(I_P(t)) $ this time, one
gets that the minimum in (\ref{eq:item_2}) can only be reached
for indices $ k \ge i $, so $ \min(I_P(tv)) \ge \min(I_P(uv)) $.
If the inequality is strict, we get $ tv <_P uv$ and we are done, otherwise
this is $ \le_{\omega} $ who breaks ties between $ uv $ and $ tv $.
We can then just use item 2. of Definition \ref{def:gmo} like in the proof of Lemma \ref{lemma:inequality} to get
$ tv <_{\omega} uv $, and so $ tv <_P uv $.

\end{itemize}

Now since the maximum on the $vt$'s for $ \le_P $ equals $ \lt(vf) $, we conclude
$ \lt(vf) <_P vu $.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:buch_criterion_new} ]
\label{proof:buch_criterion_new}
By contradiction, assume that (2) is true and that $H$ is not a Gröbner basis of $J$. 
Then there exists $f \in  J$ such that $\lm(f) \notin \bigcup_{(i,j) \in L, 1\le k \le m}T_{i,j}(h_k)\lm_{i,j}(h_k)$.
Since, $f \in J = (h_1,\dots,h_m)$, we can write $f = \sum_{k=1}^{m}q_kh_k$ for some $q_k$ in $\LaurentPolytopalRing$. 
%By summing for each $j$ over the terms of $q_k$, we can rewrite $f$ as $\sum_{j=1}^{m}\sum_{\alpha \in \Delta(j)}t_{j,\alpha}h_k$ where for each $j$, $(t_{j,\alpha})_{\alpha \in \Delta(j)}$ is a finite family of terms. 
Write $\Delta(k)$ to be the set of terms of $q_k$.
We can rewrite $f$ as $\sum_{k=1}^{m}\sum_{\alpha \in \Delta(k)}t_{k,\alpha}h_k$.
For such a writing of $f$, define $u = \max\{\lt(t_{k,\alpha}h_k), 1 \le k \le m, \alpha \in \Delta(k)\}$
and write the term $u$ as $u=c\tilde{u}$
for some $c \in K$ and some monomial $\tilde{u}.$
We have $\lt(f) <_P u$ because $\lm(f) \notin \cup_{i,j}T_{i,j}(h_k)\lm_{i,j}(h_k)$.
Thus, $\val_P(u)$ is upper-bounded.

Since $\val$ is discrete, there is a maximal $\val_P(u)$ among all
possible expressions of $f=\sum_{k=1}^{m}q_kh_k$.
Among the expressions reaching this valuation, Lemma \ref{lemma:stric_descending_seq} ensure 
there is one such that $u$ is minimal. Let $(i,j) \in L$ be such that $u \in T_{i,j} \cap V_{i,<}$.
Define $Z = \{(k,\alpha) \in \llbracket 1,m\rrbracket \times \Delta(k),\ \textrm{s.t. }
\lt(t_{k,\alpha}h_k) =_P u\}$ and
$Z^\prime = \{(k, \alpha) \in \llbracket 1,m\rrbracket \times \Delta(k),\ \textrm{s.t. } \lt(t_{k,\alpha}h_k) <_P u\}$. 
We can then write:
\begin{equation}
 f = \sum_{(k,\alpha) \in Z}t_{k,\alpha}h_k + \sum_{(k,\alpha) \in Z^\prime}t_{k,\alpha}h_k \label{eq:ecriture_f_ij_new}
\end{equation}
Let $g := \sum_{(k,\alpha) \in Z}t_{k,\alpha}h_k$.
We have $\lt(g) \le_P \max(\lt(f),\lt(\sum_{(k,\alpha) \in Z^\prime}t_{k,\alpha}h_k )) <_{P} u$ and
$\lt(t_{k,\alpha}h_k) = c_{k,\alpha}\tilde{u}$ for all $(k,\alpha) \in Z$, where the $c_{k,\alpha}$ all have the same valuation.
So $g$ satisfies the conditions of Lemma \ref{lemma:sumSpair_new} and we can write
\begin{equation}
	g = \sum_{k=1}^{m-1}d_k\frac{\tilde{u}}{v_k}S((i,j),h_k,h_{k+1},v_k) + t^\prime_mh_m \label{eq:def_g_ijn_Buchberger}
\end{equation}
for some $d_k \in K$, $v_k \in U((i,j),h_k,h_{k+1})$, $\val \left( d_k \lc_{i,j}(h_k) \lc_{i,j}(h_{k+1}) \right) \geq \val (c)$
and $\tilde{u}/v_k \in T_{i,j}$ for $k<m$, and with $\lt(t^\prime_mh_m) <_P u$.
Now we use the hypothesis that all the S-pairs of elements of $H$ reduce to zero. 
For each $k<m$ we can write
\begin{equation}
S((i,j),h_k,h_{k+1},v_k) = \sum_{l=1}^{m} q^{(k)}_l  h_l,
\end{equation}
for some $q^{(k)}_l $'s in $\LaurentPolytopalRing$
satisfying 
\begin{align*}
\lt (q^{(k)}_l  h_l) & \leq_P \lt \left( S((i,j),h_k,h_{k+1},v_k) \right), \\
                    & <_P \lc_{i,j}(h_k)\lc_{i,j}(h_{k+1})v_k,
\end{align*}
where the last inequality comes from Lemma \ref{lemma:Spair_new}.
Since $v_k \in T_{i,j} \cap V_{i,<}$ and $\tilde{u}/v_k \in T_{i,j}$, we can apply
Lemma \ref{lemma:inequality_new}:

\begin{align*}
  \lt \left(\frac{\tilde{u}}{v_k}q^{(k)}_l  h_l\right) & <_P \lc_{i,j}(h_k)\lc_{i,j}(h_{k+1})v_k\frac{\tilde{u}}{v_k},  \\
 & = \lc_{i,j}(h_k)\lc_{i,j}(h_{k+1})\tilde{u}.
\end{align*}
Finally, using that $\val \left( d_k \lc_{i,j}(h_k) \lc_{i,j}(h_{k+1}) \right) \geq \val (c)$,
we deduce that for all $l \in \llbracket 1, m \rrbracket$ and $k \in \llbracket1,m-1 \rrbracket$; \[\lt \left(d_k \frac{\tilde{u}}{v_k}q^{(k)}_l  h_l\right)<_P u.\]
Inserting the expressions of $d_k \frac{\tilde{u}}{v_k}S((i,j),h_k,h_{k+1},v_k)$ as $\sum_{l=1}^{m} d_k \frac{\tilde{u}}{v_k}q^{(k)}_l  h_l$
in Equations \eqref{eq:def_g_ijn_Buchberger} and then \eqref{eq:ecriture_f_ij_new},
we get an expression of $f$ in terms of the $h_k$'s with strictly smaller $u$ for $ \le_P $, contradicting its minimality.
\end{proof}



