\REQUIRE Audioset dataset $\mathcal{D}=\{(V^k,C_{\text{audio}}^k)\}_{k=1}^{|D|}$, VLM $\mathcal{VLM}$, LLM $\mathcal{LLM}$, video caption prompt template $\mathcal{P}_{vc}^{user}$, CoT information acquisition prompt template $\mathcal{P}_{reason}^{user}$
\ENSURE Visual to Video Object dataset: $\mathcal{D}_{v2o}$, Video Object to Sound Event dataset: $\mathcal{D}_{o2e}$, Sound Event to Audio Caption dataset $\mathcal{D}_{e2c}$
\FOR{each ($V$, $C_{\text{audio}}$) $\in \mathcal{D}$}
    % Add your algorithm steps here
    \STATE $C_{\text{video}} = \mathcal{VLM}(\mathcal{P}_{vc}^{user}(V))$
    \STATE $<V_{\text{object}}, S_{\text{event}}>=\mathcal{LLM}(\mathcal{P}_{reason}^{user}(C_{\text{video}}, C_{audio}))$
    \STATE $\mathcal{D}_{v2o} +=\{(V/C_{\text{video}}),(V_{\text{object}})\}$
    \STATE $\mathcal{D}_{o2e} +=\{(V/C_{\text{video}},V_{\text{object}}),(S_{\text{event}})\}$
    \STATE $\mathcal{D}_{e2c} +=\{(V/C_{\text{video}},S_{\text{event}}),(C_{\text{audio}})\}$
\ENDFOR
\end{algorithmic}
\end{algorithm}

