\title{Descriptive Complexity of Sensitivity of Cellular Automata}


\author{Tom Favereau \inst{1}(\Envelope) \orcidID{0009-0008-5876-8676} \and Ville Salo \inst{2} \orcidID{0000-0002-2059-194X}}
