\title{A Cautionary Note on Quantum Oracles}
\date{}

\author{Avantika Agarwal\\
    \small Institute for Quantum Computing\\
    \small University of Waterloo\\
    \small \texttt{avantika.agarwal@uwaterloo.ca}
    \and Srijita Kundu\\
    \small Institute for Quantum Computing\\
