\section{Definitions and Preliminaries}

\subsection{Complexity Classes}\label{sec:defs}

\begin{definition}[True Quantified Boolean Formula ($\TQBF$)]
    The language $\TQBF$ is defined as the set of quantified Boolean formula which are true, where a quantified Boolean formula $\psi$ is the following:
    \begin{align*}
        \psi = Q_1x_1Q_2x_2\ldots Q_nx_n \phi(x_1,x_2,\ldots x_n)
    \end{align*}
    where $Q_i$ are the quantifiers $\exists$ or $\forall$, and $\phi$ is a Boolean formula of size $m$. The size of $\psi$ is then defined to be $n+m$.
\end{definition}

\begin{definition}[Quantum Turing Machine \cite{Wat09}]\label{def:qtm}
    A quantum Turing machine (QTM) consists of three tapes: a read-only input tape, a classical work tape and a quantum work tape with qubits initialized to the $\ket{0}$ state. It has five tape heads, one each for the input and classical work tape, and three for the quantum tape. In every step of the computation, the Turing machine can read an input bit or perform one step on the classical tape, or apply one quantum gate (from Toffoli, Hadamard or phase-shift gates) on the quantum tape or perform a single-qubit measurement on the quantum tape.\\
    The runtime of the QTM is the number of steps taken by the machine, and the space used by the QTM is the number of squares used on the classical work tape plus the number of qubits used on the quantum work tape.
\end{definition}

\begin{definition}[$\BQPSPACE$ \cite{Wat09}]
    A promise problem $L = (L_{yes}, L_{no})$ is in $\BQPSPACE$ if there is a quantum Turing machine $T$ (as per Definition \ref{def:qtm}) and a polynomial $p: \N \rightarrow \N$ such that $T$ decides $L$ using $p(n)$ space on inputs of length $n$, with bounded error. That is,
    \begin{align*}
        x \in L_{yes} &\Rightarrow \Pr[T(x) = 1] \geq \frac{2}{3} \\
        x \in L_{no} &\Rightarrow \Pr[T(x) = 1] \leq \frac{1}{3}
    \end{align*}
\end{definition}
\noindent The classical analogue of $\BQPSPACE$ is $\PSPACE$ where the Turing machines described above do not have a quantum tape. It follows from definition that $\PSPACE^O \subseteq \BQPSPACE^O$ for every classical and distributional oracle. It is known that $\PSPACE = \BQPSPACE$ (shown in \cite{Wat03}). However, the proof of this result might not relativize for classical oracles according to our understanding.

\begin{definition}[$\PQP$]
    A promise problem $L = (L_{yes}, L_{no})$ is in $\PQP$ if there is a polynomial time uniform family of quantum circuits $\{V_n\}_{n \in \N}$ and polynomials $p,q: \N \rightarrow \N$ such that $V_n$ decides inputs of length $n$ using $p(n)$ time, with probability of error at most $1/2$. That is,
    \begin{align*}
        x \in L_{yes} &\Rightarrow \Pr[V_n(x) = 1] \geq \frac{1}{2} + \frac{1}{2^{q(n)}} \\
        x \in L_{no} &\Rightarrow \Pr[V_n(x) = 1] \leq \frac{1}{2}
    \end{align*}
\end{definition}
\noindent It is known (shown in \cite{Wat09}) that $\PQP = \PP$, where $\PP$ is the class of problems which can be solved by a classical polynomial time randomized algorithm with probability of error at most $1/2$. It can be verified that this result relativizes with respect to classical and distributional oracles.

\begin{definition}[$\QMA$]
    A promise problem $L = (L_{yes}, L_{no})$ is in $\QMA$ if there exists a poly-bounded function $p:\mathbb{N}\mapsto\mathbb{N}$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \mathbb{N}}$ such that for every $n$-bit input $x$, $V_n$ takes in a quantum proof $\ket{\psi}$ of $p(n)$ qubits and outputs a single bit, such that:
    \begin{align*}
        x \in L_{yes} &\Rightarrow \exists \ket{\psi}~~~~~\Pr[V_n(x, \ket{\psi}) = 1] \geq \frac{2}{3} \\
        x \in L_{no} &\Rightarrow \forall \ket{\psi}~~~~~\Pr[V_n(x,\ket{\psi}) = 1] \leq \frac{1}{3}
    \end{align*}
\end{definition}

\begin{definition}[$\QCSigma_i$]\label{def:QCSigmam}
  Let $L=(L_{yes},L_{no})$ be a promise problem. We say that $L$ is in $\QCSigma_i$ if there exists a poly-bounded function $p:\mathbb{N}\mapsto\mathbb{N}$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \mathbb{N}}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proofs ${y_1}\in \set{0,1}^{p(n)}, \ldots, {y_i}\in \set{0,1}^{p(n)}$ and outputs a single bit, such that:
  \begin{itemize}
    \item Completeness: $x\in L_{yes}$ $\Rightarrow$ $\exists y_1 \forall y_2 \ldots Q_i y_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \geq \frac{2}{3}$.
    \item Soundness: $x\in L_{no}$ $\Rightarrow$ $\forall y_1 \exists y_2 \ldots \overline{Q}_i y_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \leq \frac{1}{3}$.
  \end{itemize}
  Here, $Q_i$ equals $\exists$ when $m$ is odd and equals $\forall$ otherwise and $\overline{Q}_i$ is the complementary quantifier to $Q_i$.
\end{definition}

\noindent Note that the first level of this hierarchy corresponds to $\QCMA$. The complement of the $i^{\mathrm{th}}$ level of the hierarchy, $\QCSigma_i$, is the class $\QCPi_i$ defined next.

\begin{definition}[$\QCPi_i$]\label{def:QCPim}
  Let $L=(L_{yes},L_{no})$ be a promise problem. We say that $L \in \QCPi_i$ if there exists a polynomially bounded function $p:\mathbb{N}\mapsto\mathbb{N}$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \mathbb{N}}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proofs ${y_1}\in \set{0,1}^{p(n)}, \ldots, {y_i}\in \set{0,1}^{p(n)}$ and outputs a single bit, such that:
  \begin{itemize}
    \item Completeness: $x\in L_{yes}$ $\Rightarrow$ $\forall y_1 \exists y_2 \ldots Q_i y_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \geq \frac{2}{3}$.
    \item Soundness: $x\in L_{no}$ $\Rightarrow$ $\exists y_1 \forall y_2 \ldots \overline{Q}_i y_i$ s.t. s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \leq \frac{1}{3}$.
  \end{itemize}
  Here, $Q_i$ equals $\forall$ when $m$ is odd and equals $\exists$ otherwise, and $\overline{Q}_i$ is the complementary quantifier to $Q_i$.
\end{definition}

\noindent Now the corresponding quantum-classical polynomial hierarchy is defined as follows.

\begin{definition}[Quantum-Classical Polynomial Hierarchy ($\QCPH$)]\label{def:QCPH}
  \begin{align*}
        \QCPH = \bigcup_{m \in \mathbb{N}} \; \QCSigma_i = \bigcup_{m \in \mathbb{N}} \; \QCPi_i.
    \end{align*}
\end{definition}

\noindent Note that $\QCPH$ is the quantum-classical analogue of the classical complexity class $\PH$, where the verifier is a classical deterministic algorithm. The first level of $\PH$ is the well-known complexity class $\NP$. It follows from definition that $\PH \subseteq \QCPH$ and this is true relative to all classical and distributional oracles. See \cite{GSSSY22}, \cite{AGKR24} and \cite{AB24} for other properties of $\QCPH$. Note also that $\QCPH$ ($\PH$) consist of problems which can be decided by a quantum (classical) verifier receiving a constant number of alternatively quantified proofs. In particular, the number of proofs that the verifier receives is not allowed to increase with increase in the input length (though the size of the proofs is allowed to increase). If we do allow the number of proofs to grow, say, polynomially with the length of the input, then we get a different complexity class, which we will call $\polyQCPH$. We will call the analogous classical deterministic complexity class as $\polyPH$, though we don't define it formally. Later we show that $\polyPH = \polyQCPH$ with respect to all classical oracles.

\begin{definition}[$\polyQCSigma_i$]\label{def:polyQCSigmam}
  Let $L=(L_{yes},L_{no})$ be a promise problem. We say that $L$ is in $\polyQCSigma_i$ if there exists a poly-bounded function $p:\mathbb{N}\mapsto\mathbb{N}$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \mathbb{N}}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proofs ${y_1}\in \set{0,1}^{p(n)}, \ldots, {y_{n^i}}\in \set{0,1}^{p(n)}$ and outputs a single bit, such that:
  \begin{itemize}
    \item Completeness: $x\in L_{yes}$ $\Rightarrow$ $\exists y_1 \forall y_2 \ldots Q_{n^i} y_{n^i}$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_{n^i})] \geq \frac{2}{3}$.
    \item Soundness: $x\in L_{no}$ $\Rightarrow$ $\forall y_1 \exists y_2 \ldots \overline{Q}_{n^i} y_{n^i}$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_{n^i})] \leq \frac{1}{3}$.
  \end{itemize}
  Here, $Q_{n^i}$ equals $\exists$ when ${n^i}$ is odd and equals $\forall$ otherwise and $\overline{Q}_{n^i}$ is the complementary quantifier to $Q_{n^i}$.
\end{definition}

\begin{definition}[$\polyQCPi_i$]\label{def:polyQCPim}
  Let $L=(L_{yes},L_{no})$ be a promise problem. We say that $L \in \polyQCPi_i$ if there exists a polynomially bounded function $p:\mathbb{N}\mapsto\mathbb{N}$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \mathbb{N}}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proofs ${y_1}\in \set{0,1}^{p(n)}, \ldots, {y_{n^i}}\in \set{0,1}^{p(n)}$ and outputs a single bit, such that:
  \begin{itemize}
    \item Completeness: $x\in L_{yes}$ $\Rightarrow$ $\forall y_1 \exists y_2 \ldots Q_{n^i} y_{n^i}$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_{n^i})] \geq \frac{2}{3}$.
    \item Soundness: $x\in L_{no}$ $\Rightarrow$ $\exists y_1 \forall y_2 \ldots \overline{Q}_{n^i} y_{n^i}$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_{n^i})] \leq \frac{1}{3}$.
  \end{itemize}
  Here, $Q_{n^i}$ equals $\forall$ when ${n^i}$ is odd and equals $\exists$ otherwise, and $\overline{Q}_{n^i}$ is the complementary quantifier to $Q_{n^i}$.
\end{definition}

\begin{definition}[$\polyQCPH$]\label{def:polyQCPH}
  \begin{align*}
        \polyQCPH = \bigcup_{i \in \mathbb{N}} \; \polyQCSigma_i = \bigcup_{i \in \mathbb{N}} \; \polyQCPi_i.
    \end{align*}
\end{definition}

\subsection{Other Preliminaries}

\begin{definition}[$p$-uniform probability measure]
    Let $\mu$ be the uniform probability over $N$-dimensional pure states. For a given $p \in [0,1]$, a probability measure $\sigma$ is a $p$-uniform measure if it can be obtained from $\mu$ by conditioning on some event occurring with probability at least $p$.
\end{definition}

\begin{lemma}[Geometric Lemma \cite{AK07}]\label{lem:geometriclemma}
    Given a $p$-uniform probability measure $\sigma$ over $N$-dimensional pure states, and a density matrix $\rho$,
    \begin{align*}
        \E_{\ket{\psi} \sim \sigma}[\bra{\psi}\rho\ket{\psi}] = O\left(\frac{1+\log(1/p)}{N}\right)
    \end{align*}
\end{lemma}

\begin{proposition}[Chernoff Bound]\label{prop:chernoff}
    Let $\mathbf{X_1}, \cdots, \mathbf{X_n}$ be $n$ independent random variables between $0$ and $1$. If $\mathbf{X} = \sum_{i=1}^n \mathbf{X_i}$ and $\mu = \E[\mathbf{X}]$, then for any $\delta > 0$
    \begin{align*}
        \Pr[\mathbf{X} \geq \mu + t] &\leq e^{-\frac{2t^2}{n}} \\
        \Pr[\mathbf{X} \leq \mu - t] &\leq e^{-\frac{2t^2}{n}}
    \end{align*}
\end{proposition}

\section{Classical Oracles}
In this section, we show that $\PSPACE = \polyQCPH = \polyPH$ with respect to every classical oracle $O$. We start by describing the proof of $\TQBF$-completeness for $\PSPACE$, from \cite{AB09}.

\begin{lemma}[Theorem 4.11 of \cite{AB09}]\label{lem:tqbfpspacecomp}
    The problem $\TQBF$ is complete for $\PSPACE$. This holds relative to all classical oracles $O$.
\end{lemma}
\begin{proof}
    Consider $L \in \PSPACE$ and let $M$ be the corresponding Turing Machine. Let $G_{M,x}$ be the configuration graph of $M$ on input $x$. Then $M$ accepts $x$ iff there is a path from $C_{init}$ to $C_{acc}$ in the configuration graph $G_{M,x}$. Suppose $M$ uses space $m = p(|x|)$ on input $x$, where $p: \N \rightarrow \N$ is a polynomial. We will convert this problem of finding a path between $C_{init}$ and $C_{acc}$ to a quantified Boolean formula $\psi$ which is true iff such a path exists. This construction is done inductively, and we define $\psi_i(C_1, C_2)$ to be the quantified Boolean formula which is true iff there is a path of length at most $2^i$ between vertices $C_1$ and $C_2$ of $G_{M,x}$. Then we want to set $\psi = \psi_m(C_{init}, C_{acc})$. We know that $\psi_0$ can be written as a Boolean formula of size $O(m)$, using a construction similar to Cook-Levin theorem. Then we can define $\psi_i$ as follows:
    \begin{align*}
        \psi_i(C_1, C_2) := \exists C \forall D_1 \forall D_2 [(D_1 = C_1 \wedge D_2 = C) \vee (D_1 = C \wedge D_2 = C_2)] \Rightarrow \psi_{i-1}(D_1, D_2)
    \end{align*}
    The formula above encodes the fact that there is a path of length at most $2^i$ between $C_1$ and $C_2$ iff there is a vertex $C$ such that there is a path of length at most $2^{i-1}$ between $C_1$ and $C$ and between $C$ and $C_2$. Then the formula $\psi_m$ has size $O(m^2)$. We can also check that each of these steps will work in the presence of an arbitrary classical oracle, where note it is important that the quantified variables $C, D_1, D_2$ and the Boolean formulas $\psi_i$ are allowed to depend on the oracle $O$.
\end{proof}

\begin{lemma}
    For every classical oracle $O$, $\PSPACE^O = \polyPH^O = \polyQCPH^O$.
\end{lemma}
\begin{proof}
    It is clear from definition that $\polyPH^O \subseteq \polyQCPH^O \subseteq \PSPACE^O$ where for the second cotainment we use the fact that a $\PSPACE^O$ machine can iterate over all possible settings of alternatively quantified proofs and estimate the acceptance probability of the resulting verifier, similar to Lemma \ref{lem:pqpinpspacedist}. From Lemma \ref{lem:tqbfpspacecomp}, we know that $\PSPACE^O \subseteq \polyPH^O$ since a $\polyPH^O$ machine can clearly decide a $\TQBF$ predicate (dependent on the oracle $O$). Hence the claim follows.
\end{proof}


