\section{Quantum Oracles}

\subsection{\texorpdfstring{$\QMA$}{QMA} is contained in \texorpdfstring{$\PQP$}{PQP}}
In this section we show that relative to every quantum oracle $U$, $\QMA^U \subseteq \PQP^U$. This proof is the same as the proof by \cite{MW05}.

\begin{lemma}[Theorem 3.4 of \cite{MW05}]\label{lem:qmainpqp}
    For every quantum oracle $U$, $\QMA^U \subseteq \PQP^U$.
\end{lemma}
\begin{proof}
    Let $L \in \QMA^U$ and $V^U$ be the corresponding verifier. Suppose $V^U$ takes a quantum proof of length $p(n)$ on inputs of length $n$. Using strong error-reduction for $V^U$ from \cite{MW05}, we will assume that $V^U$ makes an error of at most $1/2^{r(n)}$, where $r(n) = p^2(n)$. Define the verifier $W^U$, which runs the verifier $V^U$ by fixing the proof to be the maximally mixed state on $p(n)$ qubits. That is, on input $x$ of length $n$, $W^U(x) = V^U\left(x, \frac{I_{2^{p(n)}}}{2^{p(n)}}\right)$. Then using the assumption on $V^U$, we have the following:
    \begin{align*}
        x \in L_{yes} &\Rightarrow \Pr[W^U(x) = 1] \geq \frac{1}{2^{p(n)}}\left(1-\frac{1}{2^{r(n)}}\right) \\
        x \in L_{no} &\Rightarrow \Pr[W^U(x) = 1] \leq \frac{1}{2^{r(n)}}
    \end{align*}
    Thus $W^U$ is a $\PQP^U$ verifier for $L$ for the given choice of $r(n)$. Therefore, $L \in \PQP^U$.
\end{proof}


\begin{lemma}\label{lem:pqpinbqpspace}
    For every quantum oracle $U$, $\PQP^U \subseteq \BQPSPACE^U$.
\end{lemma}
\begin{proof}
    Let $L \in \PQP^U$ and $V^U$ be the corresponding verifier. Suppose the verifier $V^U$ accepts with probability at least $\frac{1}{2} + \frac{1}{2^{p(n)}}$ on an input $x$ of length $n$ if $x \in L_{yes}$ and with probability at most $\frac{1}{2}$ otherwise. Then define a verifier $W^U$ which on input $x$ repeats $V^U(x)$ independently for $c2^{4p(n)}$ for a sufficiently large constant $c$ and accepts iff the fraction of accepting iterations is at least $\frac{1}{2} + \frac{1}{2^{p(n)}} - \frac{1}{2^{2p(n)}}$. Using Chernoff bound (Proposition \ref{prop:chernoff}), $W^U$ makes an error with probability at most $1/3$ if $c$ is a sufficiently large constant. Further, $W^U$ can be run in polynomial space, since it can reuse the same qubits for each iteration of running $V^U(x)$ (which takes polynomially many qubits) and store a counter for the number of accepting iterations on the classical tape, which take $O(p(n))$ classical bits. Hence, $L \in \BQPSPACE^U$.
\end{proof}

\paragraph{$\TQBF$ completeness fails for quantum oracles.}In the classical setting, it is known that if we allow the number of alternating proofs in $\PH$ to grow polynomially with the length of the input, then we get the same class as $\PSPACE$. This follows from Lemma \ref{lem:tqbfpspacecomp}. However, in the case of quantum oracles, $\PSPACE$ and $\TQBF$ do not make sense anymore (note that $\TQBF$ may not be complete for $\BQPSPACE$ even for classical oracles). If we try to do a similar proof as the classical one, but now for $\BQPSPACE$ and $\polyQCPH$, it also does not seem to work. In particular, suppose the classical alternatively quantified proofs are supposed to capture a path in the configuration graph of the classical tape of a $\BQPSPACE$ machine $Q$. Since $Q$ is a $\BQPSPACE$ machine, it can potentially run for an exponential amount of time, provided it does not use more than polynomial space. Therefore, we can't defer measurements in $Q$ by adding ancilla qubits. In particular, the future steps of the classical tape can depend on these intermediate measurement outcomes. Therefore, a $\polyQCPH$ predicate may not capture this possibility, since all the quantum measurements in $\polyQCPH$ happen after all the classical proofs have been specified. Therefore, while $\polyQCPH^U \subseteq \BQPSPACE^U$, the reverse containment does not seem to hold.


\subsection{Oracle Separation between \texorpdfstring{$\QMA$}{QMA} and \texorpdfstring{$\polyQCPH$}{polyQCPH}}
In this section we show that the quantum oracle separation between $\QMA$ and $\QCMA$ established in \cite{AK07} extends to an oracle separation between $\QMA$ and $\QCPH$. More strongly, it extends to a separation between $\QMA$ and $\polyQCPH$, thus also giving a quantum oracle separation between $\PQP$ and $\polyQCPH$.
\paragraph{\cite{AK07} Quantum oracle problem.} Given either the oracle $U_\psi = I - 2\ket{\psi}\bra{\psi}$ for some $n$-qubit Haar-random state $\ket{\psi}$ (yes case), or the identity operator $I$ on qubits (no case), distinguish between the two cases. \\
\\
\noindent Given a query algorithm $A$, \cite{AK07} consider for every $n$-qubit pure state $\ket{\psi}$, the classical witness $w$ which maximizes the acceptance probability of $A$ on $U_\psi$. They use the witnesses to partition the space of $n$-qubit pure states, say the partition for witness $w$ is called $S(w)$, and they pick the witness $w$ with the partition of the largest size. Then they show that if $A$ makes a small number of queries, then $A(\cdot, w)$ can not distinguish between $U_\psi$ and $U = I$ with high probability over the choice of a uniformly random state $\ket{\psi}$ from $S(w)$. We present a slightly different formulation of the proof from \cite{AK07}, by considering for every $n$-qubit pure state $\ket{\psi}$, the classical witness $w$ which maximizes the gap between the acceptance probability of $A$ for $U_\psi$ and $U = I$.

\begin{theorem}[Modification of Theorem 3.3 of \cite{AK07}]\label{thm:lowerbound}
    Suppose we have a query algorithm $A$ with oracle access to an $n$-qubit unitary $U$, which is chosen from one of the two cases below:
    \begin{enumerate}
        \item $U = U_\psi$
        %There exists a state $\ket{\psi}$ such that $U\ket{\psi} = -\ket{\psi}$ and $U\ket{\phi} = \ket{\phi}$ for every state $\ket{\phi}$ that is orthogonal to $\ket{\psi}$
        \item $U = I$. 
    \end{enumerate}
    For a particular oracle $U_\psi$, let $w$ be the witness of length $m$ which maximizes the distinguishing advantage of $A$ between $U_\psi$ and $I$ (we call this good witness). For a given witness $w$, define $S(w)$ to be the set of states $\ket{\psi}$ such that $w$ is the good witness for $U_\psi$. Then there exists a witness $w^{\ast}$ such that with high probability over choice of states $\ket{\psi} \in S(w^{\ast})$, the algorithm $A$ (given any witness of length $m$) needs $\Omega\left(\sqrt{\frac{2^n}{m+1}}\right)$ queries to distinguish between $U_\psi$ and $I$ with bounded error.
\end{theorem}
\begin{proof}
    Suppose $A$ makes at most $T$ queries. We know by definition that $\{S(w)\}_w$ forms a partition of the set of $n$-qubit pure states, and we can pick a witness $w^{\ast}$ such that
    \begin{align*}
        \Pr_{\ket{\psi}\sim \mu}[\ket{\psi} \in S(w^{\ast})] \geq \frac{1}{2^m}
    \end{align*}
    For every state $\ket{\psi} \in S(w^{\ast})$, let $\ket{\Phi^\psi}$ be the final state of $A$ when $U = U_\psi$, and $\ket{\Phi^I}$ be the final state of $A$ when $U = I$. Then \cite{AK07} show, using Lemma \ref{lem:geometriclemma}, that
    \begin{align*}
        \E_{\ket{\psi}\sim S(w^{\ast})}[||\ket{\Phi^\psi} - \ket{\Phi^I}||_2] \leq O\left(T \sqrt{\frac{m+1}{2^n}}\right).
    \end{align*}
    Therefore, using Markov's inequality, for every query algorithm $A$ we have,
    \begin{align}
        \Pr_{\ket{\psi}\sim S(w^{\ast})}\left[||\ket{\Phi^\psi} - \ket{\Phi^I}||_2 \geq \omega\left(T \sqrt{\frac{m+1}{2^n}}\right)\right] \leq o(1).  \label{eq:p-uniform}
    \end{align}
    In particular, with probability at least $2/3$ over choice of states $\ket{\psi} \in S(w^{\ast})$, $A$ needs $T = \Omega\left(\sqrt{\frac{2^n}{m+1}}\right)$ queries to distinguish between $U_\psi$ and $U = I$ with constant bias.
\end{proof}

