\subsection{Properties of the ROSTER algorithm}

\begin{theorem}
\label{Lemma: Roster Congestion Bounds}
The network congestion resulting from the ROSTER algorithm is given by
\begin{equation*}
    \psi_S(\mathcal{G} | r_i^\circledast) \leq \psi_S(\mathcal{G} | r_i^*) \leq \sum_{e \in \mathcal{E}} t_e(f_e + 1),
\end{equation*}
where $r_i^*$ is the optimal selfish route for the driver, and $r_i^\circledast$ is the route that minimizes network congestion.
\end{theorem}

\begin{proof}
In the worst-case routing scenario, the driver rejects all recommendations and selects $r_i^*$, leading to a maximum congestion: 
\begin{equation*}
    \psi_S(\mathcal{G} | r_i^*) = \sum_{e \in \mathcal{E}_{r_i^*}} t_e(f_e + 1) + \sum_{e \notin \mathcal{E}_{r_i^*}} t_e(f_e).
\end{equation*}
In the best-case scenario, the driver follows the system's optimal recommendation $r_i^\circledast$, leading to a minimum congestion:
\begin{equation*}
    \psi_S(\mathcal{G}| r_i^\circledast) = \min_{r \in \mathcal{R}} \sum_{e \in \mathcal{E}_r} t_e(f_e + 1) + \sum_{e \notin \mathcal{E}_r} t_e(f_e).
\end{equation*}
Thus, the network congestion falls between the worst-case and best-case congestion.
\end{proof}


\subsection{Trust Dynamics \label{Sect: Trust Dynamics}}
\subsubsection{Driver Trust Updating}
Since humans are known to deviate from Bayesian updating \cite{ortoleva2022alternatives} but have been shown to follow a recency-based weighted average update model \cite{sutton2018reinforcement, strickland2024humans} when updating their trust values, the driver is assumed to update its trust in the system as follows:
\vspace{-0.1in}
\begin{equation}
\label{Eqn: Intermediate Trust Update}
\alpha_{m} = 
\begin{cases}
\alpha_{m-1} \ \text{if} \ \hat{B}^m_D(a_D^t) = 0,
\\
(1 - \eta_{D,m})^{m} \alpha_0 + \displaystyle \sum_{i = 0}^{m- 1}\eta_D(1 - \eta_{D,m})^i C_i \ \text{otherwise,}
\end{cases}
\end{equation}
where $C_i = 1$ if the driver accepts recommendation at stage $i$, and $0$ otherwise. Here, $\eta_{D,m}$ is the driver's adaptive learning rate at stage $m$, which is influenced by the change in the driver's discomfort, and is computed as follows
\vspace{-0.09in}
\begin{equation*}
\label{Eqn: Driver Discomfort}
\eta_{D,m} = \varepsilon_D \cdot \nabla B_D^m(a_D^t),
\vspace{-0.08in}
\end{equation*}
where $\varepsilon_D$ is a constant used to scale the gradient of the regret incurred by the driver. At intermediate interaction stages (i.e., $m \not = m^*$), the driver's regret is given by
\begin{equation*}
B_D^m(a_D^t) = \mathbb{E}_p(T(r_i)) - \mu_{m,D},
\label{Eqn: driver Counterfactual Regret}
\end{equation*}
where $r_i$ denotes the route recommended by the system. On the other hand, when $m = m^*$, the driver's regret is based on true observed outcomes and computed as
\begin{equation*}
B_D^m(a_D^t) = 
\begin{cases}
T(r_i) - \mu_{m,D}, & \text{if}\ a_D^t = r_i\\
\mathbb{E}_{q^\prime}(T(r_i)) - T(r_i) & \text{otherwise}.
\end{cases}
\label{Eqn: driver True Regret}
\end{equation*}

