\begin{lemma}\label{rootn}
  For any $i>0$, there exists a constant $a_i>0$ such that the following relations hold between the length $n$ of any string  $s\in RL_i$ and the length of the leftmost block $s_0$ of $s$:
  \begin{enumerate}
      \item $|s_0|<n^{1/2^i}$.
      \item  $|s_0|>a_i n^{1/2^i}$.
  \end{enumerate}
\end{lemma}
\begin{proof}
%It is useful to express the length of the leftmost block $s_0$ in terms of the length $n$ of the overall string $s_i$. 
We use Equation \ref{eqn:srel}.
Since $|s_j|>|s_{j-1}|^2$ for all $j$, we have  $n=|s_i|>|s_0|^{2^i}$, yielding the upper bound $|s_0|<n^{1/2^i}$.


To obtain a lower bound, note that 
%$\lceil \log(j+1)\rceil <|s_{j-1}|$  for all $j>0$. Therefore,
 there exists a constant $c>0$  such that  $|s_j|<c|s_{j-1}|^2$ for all $j$.
 Since it is easy to prove that  $|s_j|<c^{2^{j}-1}|s_0|^{2^j}$ for all $j$,
 we conclude that $|s_0|>a_i n^{1/2^i}$, where $a_i=\frac{1}{c^{1-\frac{1}{2^{i}}}}$.
\end{proof}
