\section{Preliminaries}\label{sec:prel}

\paragraph{\textbf{Basics}}
For a set $e=\{x,y\}$ of two points $x,y\in\mathbb{R}^2$, we denote by
$s[e]$ the straight line segment between $x$ and $y$, i.e.,
$s[e]\coloneqq\big\{(1-\lambda)\cdot x+\lambda\cdot y\mid \lambda\in
[0,1]\subseteq \mathbb{R}\big\}$.
By definition, $x,y\in s[x,y]$. Moreover, the interior of straight line
segment is denoted by $s(e)\coloneqq s[e]\setminus\{x,y\}$.  For
simplicity, we write $s(x,y)$ and $s[x,y]$ instead of $s[\{x,y\}]$ and
$s(\{x,y\})$, respectively.  Two sets $A$ and $B$ \emph{overlap},
whenever $A\cap B\not\in \{A,B,\emptyset\}$.  A collection $\mc{S}$ of sets
is \emph{overlap-free} if no two elements in $\mc{S}$ overlap.

\paragraph{\textbf{Graphs}}
We consider (undirected) graphs $G=(V,E)$ with finite vertex set $V(G)=V$
and edge set $E(G)=E\subseteq {V\choose 2}$, i.e., without loops and
multiple edges.  A tree $T$ is an acyclic connected graph, and it is rooted
if there is distinguished vertex $\rho_T$, called the root of $T$. A rooted
forest is a graph whose connected components are rooted trees. Note a tree
is a forest consisting of a single connected component. Given a rooted
forest $F$, we can define a partial order $\preceq_F$ on $V(F)$ by putting
$v\preceq_F w$ whenever there is a connected component $T$ of $F$ that
contains $v$ and $w$ and where $v$ lies one the unique path connecting
$\rho_T$ and $w$.  In this case, we say that $v$ is an ancestor of $w$.
Note that $\rho_T$ is always $\preceq_F$-minimal for all connected
components $T$ of $F$. A vertex $v$ is a \emph{child} of $w$ (or,
equivalently, $w$ is a \emph{parent} of $v$) in $F$ if $\{v,w\}\in F$ and
$w\preceq_F v$. Two vertices are \emph{siblings} if they have a common
parent or if they are the roots of two distinct connected components of
$F$.

Given a collection of sets $\mc S$, the \emph{Hasse diagram}
$\Hasse\coloneqq \Hasse{}[\mc{S}]$ \emph{of} $\mc{S}$ \emph{(w.r.t.\ set
inclusion)} is a graph whose vertices are the elements in
$\mc{S}$. Inclusion-maximal elements in $\Hasse$ are called \emph{roots},
and there is an edge $\{A_1,A_2\}\in E(\Hasse)$ if and only if,
$A_i\subsetneq A_j$ with $\{i,j\}=\{1,2\}$ and there is no $C\in\mc{S}$
with $A_i\subsetneq C\subsetneq A_j$.  In this context, it is well-known
that the Hasse diagram of an overlap-free set $\mathcal{S}$ must be a
rooted forest. For instance, this is a direct consequence of
\cite[Thm.~3.5.2]{Semple:03}.

\paragraph{\textbf{Planarity and Polygons}}
In the following, $\varphi\colon V\to \mathbb{R}^2$ denotes an injective
map of the vertices of $G=(V,E)$ into the Euclidean plane. Given such a map
$\varphi$, a \emph{(straight-line) embedding $\PS(G)$} of a graph $G=(V,E)$
is defined as $\PS(G)\coloneqq \big\{\varphi(v)\mid v\in V\big\}\cup
\big\{s[\varphi(u),\varphi(v)] \mid \{u,v\}\in E\big\}$. In simple words,
an embedding $\PS(G)$ associates each vertex with a unique point in the
plane and every edge by a straight-line connecting its endpoints. Given a
subgraph $H$ of $G$ with embedding $\PS(G)$, we denote with
$V(\PS(H))\coloneqq \{\varphi(v)\mid v\in V(H)\}$ the set of vertices and
with $E(\PS(H))\coloneqq \left\{\{\varphi(v),\varphi(u)\} \mid \{u,v\}\in
E(H) \right\}$ the set of edges of $\PS(H)$. The latter, in particular,
allows us to treat $\PS(H)$ as a graph theoretical object to which all the
standard terminology of graphs applies.
%
In the following, $v_x$ and $v_y$ (or, $u_x$ and $u_y$) denote the $x$- and
$y$-coordinate of the image $\varphi(v) = u \in \mathbb{R}^2$ of a vertex
$v$. 
For $W\subseteq V(G)$, we defined the following real-valued intervals:
\begin{align*}
  \Ih{W}\coloneqq [\min_{v\in W} v_x,\max_{x\in W} v_x),\hspace{.5cm}
  \Io{W}\coloneqq (\min_{v\in W} v_x,\max_{x\in W} v_x),\, and \hspace{.5cm}
  \Ic{W}\coloneqq [\min_{v\in W} v_x,\max_{x\in W} v_x].
\end{align*} 
In particular, since for an edge $e\in E(G)$ we have $e\subseteq V(G)$, the
intervals $\Ih{e}$, $\Io{e}$ and $\Ic{e}$ are well-defined.  In case $W=
V(G)$, we write $\Ih{G}$, $\Io{G}$ and $\Ic{G}$ instead of $\Ih{W}$,
$\Io{W}$ and $\Ic{W}$, respectively.

An edge $e =\{u,v\} \in E$ of $G$ is \emph{vertical} if $u_x=v_x$.  If $e$
is non-vertical, then $\min(e)$ denotes the (unique) vertex $w\in
e=\{u,v\}$ with $w_x = \min\{u_x,v_x\}$, and $\max(e)$ is the (unique)
vertex $w\in e=\{u,v\}$ with $w_x = \max\{u_x,v_x\}$. Note that
$\min(e)_x<\max(e)$ for non-vertical edges and thus, $\Ih{e}$, $\Io{e}$,
$\Ic{e}$ are non-empty in this case.  For vertical edges, we leave
$\min(e)$ and $\max(e)$ undefined, and we have $\Ih{e}=\emptyset$. By the
latter arguments, $\Ih{e}=\emptyset$ if and only if $e$ is a vertical edge.

An embedding $\PS(G)$ of $G$ is \emph{planar} if $s(\varphi(u),\varphi(v))$
for every edge $\{u,v\}\in E$ does not contain any point of the straight
line $s[\varphi(u'),\varphi(v')]$ for every edge $\{u',v'\}\in E\setminus
\{u,v\}$ \cite{fary1948straight}. A graph is \emph{planar} if it admits a
planar embedding. Due to F{\'a}ry's Theorem \cite{fary1948straight}
definition of planarity is equivalent to the ``usual'' definition of planar
graphs, where the planar embedding is defined in terms of so-called Jordan
curves, see e.g.\ \cite{Diestel2010}.


\begin{remark}
  From here on, all embeddings of all graphs are considered to be planar.
\end{remark}

A \emph{polygon} $P$ refers to the embedding of an cycle $C_P$ of $G$,
i.e., $P=\PS(C_P)$, where $C_P$ is a connected subgraph of $G$ such that
all vertices have degree two in $C_P$. This type of polygons is usually
called ``simple'' polygon. A \emph{corner} of a polygon $P$ refers to a
point $p\in V(P)$.  Note that corners may have the same $x$- or
$y$-coordinate as other corners, e.g., we may have corners with coordinates
$(v_x,v_y)$, $(v'_x,v_y)$ and $(v''_x,v_y)$. Thus, corners may lie on the
same straight line.  We refer to the bounded region enclosed by a polygon
$P$ as its \emph{interior} $\Int(P)$ and assume that $P \cap \Int(P) =
\emptyset$. The \emph{exterior} of $P$ is the unbounded region
$\Ext(P)\coloneqq \mathbb{R}^2\setminus(P\cup\Int(P))$.

\paragraph{\textbf{Sets of Polygons and Nesting Forest}}
In the following,  $\P$ denotes a set of polygons and put
$\Int(\P) \coloneqq \{\Int(P)\mid P\in \P\}$. 
We say that $\P$ is \emph{overlap-free} if
$\Int(\P)$ is overlap-free.  The Hasse diagram
$\Hasse[\Int(\P)]$ of $\Int(\P)$ with respect to inclusion thus is a rooted
forest $\NF{\P}$, which we call the \emph{nesting forest} of $\P$. For
simplicity, we identify vertices $\Int(P)$ in $\mc{F}(\P)$ by the
corresponding polygons $P\in \P$ and thus, by slight abuse of notation,
assume that $V(\NF{\P})=\P$.  Moreover, we say that a polygon $P$ is inside
of a polygon $P'$ if $\Int(P)\subseteq\Int(P')$, and the two polygons
\emph{touch} if $\Int(P)\cap\Int(P')=\emptyset$ but $P\cap P'\neq
\emptyset$.

\section{Outstretched Segments and Polygons}
\label{sec:osp} %oustretched-segments-polygon

Given a subgraph $H$ of $G$ with embedding $\PS(G)$, a \emph{segment $S$
(of $\PS(H)$)} refers to the embedding of some subpath $Q_S$ of $H$, i.e.,
$S=\PS(Q_S)$. We say that a vertex $v\in V(S)$ is \emph{terminal (in $S$)}
if $v$ has degree one in $S$. Analogously, an edge $e =\{u,v\}\in E(S)$ is
\emph{terminal (in $S$)} if one of its vertices $u$ or $v$ is terminal in
$S$. For a segment $S$, we define $\MIN(S)$ (resp., $\MAX(S)$) as the set
of vertices $v$ for which $v_x$ is minimal (resp., maximal) among all
vertices in $S$. If $|\MIN(S)|=1$ or $|\MAX(S)|=1$, then we write $\min(S)$
or $\max(S)$ for the unique minimal or maximal element. Note that
$\min_{v\in S} v_x = v'_x$ for all $v'\in\MIN(S)$ and $\max_{v\in S} v_x =
v'_x$ for all $v'\in\MAX(S)$. 

\begin{definition} \label{def:prop-O}
  A segment $S$ satisfies Property~(O) if for all distinct 
  edges $e,f\in E(S)$ it holds that $\Ih{e}\cap \Ih{f}=\emptyset$.
\end{definition}
Note, for all edges $e\in E(S)$, we have $\Ih{e}\subseteq \Ih{S}$.
Moreover, $\Ih{S}=\emptyset$ implies that $\Ih{e}=\emptyset$ for all $e\in
E(S)$.  Since $\Ih{e} = \emptyset$ precisely if $e$ is vertical, the
intervals $\Ih{e}$ of non-vertical edges $e$ of $S$ partition the interval
$\Ih{S}$ whenever $S$ satisfies (O).

\begin{lemma}\label{lem:O}
  For a segment $S$, the following three conditions are equivalent:
  \begin{description}[nolistsep,leftmargin=!,labelwidth=.7cm]
  \item[(O)] $S$ satisfies Property~(O).
  \item[(O')]  
  \begin{enumerate}[nolistsep,noitemsep]
    \item[(a)] $\min_{v\in S}v_x$  and
      $\max_{v\in S}v_x$ correspond to the
      x-coordinates of the terminal vertices of $S$, and
    \item[(b)] $u_x\leq v_x$ for all vertices $u,v \in V(S)$ 
      with $u\preceq_S v$, where  $\preceq_S$ is 
      defined on $V(S)$ by choosing a vertex $v\in\MIN(S)$ 
      as the root of $S$.
  \end{enumerate}
  \item[(O'')]For all $\xi\in \Ih{S}$, there is exactly
    one edge $e \in E(S)$ with $\xi\in \Ih{e}$.
  \end{description}
\end{lemma}
\begin{proof}
First, assume that the segment $S$ consists of a single vertex or of
vertical edges only and thus $\MIN(S)=\MAX(S)$, i.e., $\min_{v\in
  S}v_x=\max_{v\in S}v_x$. Thus, $\Ih{e}=\emptyset$ for all $e\in E(S)$,
and there is no $\xi\in \Ih{S}$.  Now, it is easy to see that (O), (O') and
(O'') are always satisfied and, in particular, trivially equivalent. Thus,
assume that $S$ contains at least one non-vertical edge. In this case,
$\min_{v\in S}v_x\neq\max_{v\in S}v_x$ and thus, there is a $\xi\in
\Ih{S}$.  One easily verifies that (O) and (O'') are equivalent.

Next, suppose that $S$ satisfies (O'). Assume, for contradiction, that (O'') is
violated. Since $S$ is connected, for all $\xi\in \Ih{S}\subseteq\mathbb{R}$
there is at least one edge $e$ with $\xi\in \Ih{e}\subseteq \Ih{S}$. Since (O'')
is violated, there are two edges $e = \{u,v\},f=\{a,b\}\in E(S)$ with
$\xi\in \Ih{e}\cap \Ih{f}$.  Now, assume w.l.o.g.\ that $u\prec_S v \preceq_S
a\prec_S b$. By (O'.b) and the fact that $e$ and $f$ are non-vertical,
$u_x< v_x \leq a_x < b_x$ and thus, $\xi < v_x\leq a_x\le \xi$; a
contradiction.
Hence, if $S$ satisfies (O'), then $S$ satisfies (O'') as well.

Now, suppose that $S$ satisfies (O''). As argued above, we can assume that $S$
contains at least one non-vertical edge and thus, $\min_{v\in S} v_x\neq
\max_{v\in S} v_x$. We continue with showing that (O') is satisfied by
induction on the number of edges of $S$. Let $t$ and $t'$ be the terminal
vertices of $S$. As base case, assume that $S$ contains only one edge $e
=\{t,t'\}$. Since $e$ must be non-vertical, we have $\{\min_{v\in
  S}v_x,\max_{v\in S} v_x\} =\{t_x,t'_x\}$, and it is easy to see that (O')
holds.  Assume that (O') is satisfied for all segments $S$ of $P$ having
$m$ edges. Let $S$ be a segment of $P$ that consists of $m+1$ edges. Now,
remove the terminal edge $e=\{u,t\}$ and vertex $t$ from $S$ to obtain the
segment $S_1$ of $P$ with $m$ edges and with terminal vertices $t'$ and
$u$. Similarly, remove the terminal edge $\{u',t'\}$ and vertex $t'$ from
$S$ to obtain the segment $S_2$ of $P$ with $m$ edges and terminal vertices
$t$ and $u'$. By assumption, both $S_1$ and $S_2$ satisfy (O'). We can
assume w.l.o.g.\ that $t'\in\MIN(S_1)$.  In this case, $\preceq_{S_1}$ can
be defined on $V(S_1)$ by choosing $t'$ as the root of $S_1$. Hence, the
other terminal vertex $u$ of $S_1$ is a $\preceq_{S_1}$-maximal element and
thus, by (O'.b), must satisfy $u\in\MAX(S_1)$.  In addition, we have
$t'_x\leq u'_x \leq u_x$, since $t'\preceq_{S_1} u' \preceq_{S_1} u $.

Then, assume for contradiction that $u'\notin\MIN(S_2)$ and, therefore,
$\min_{v\in S_2} v_x \neq u'_x$. Since $S_1$ satisfies (O'.b) and since
$\{t,u\}$ is a terminal edge of $S$, we have $\min_{w\in S_1}w_x = t'_x\leq
u'_x \leq v_x$ for all vertices $v\in V(S_2)\setminus \{t\}\subseteq
V(S_1)$.  This and $\min_{u\in S_2}u_x \neq u'_x$ implies that $t_x<u'_x$
and, in particular, $\min_{v\in S_2} v_x=t_x$. If all edges of $S_1$ are
vertical, it is easy to see that $S$ satisfies (O').  Assume that $S_1$
contains a non-vertical edge. In this case, there is an edge $f=\{a,b\}$ in
$S_1$ such that $a\preceq_{S_1} b$ and $t'_x\leq a_x<b_x\le u_x$. Moreover,
$t_x<u'_x\leq u_x$ implies that there is a $\xi\in \mathbb{R}$ for which
$\min_{v\in f}v_x = a_x\leq \xi <b_x = \max_{v\in f} v_x$ and $\min_{v\in
  e} v_x = t_x \le a_x\leq \xi < b_x \le u_x =\max_{v\in e}v_x$; a
contradiction since $S$ satisfies (O''). Hence, $u'\in\MIN(S_2)$. In this
case, $\min_{v\in S_1} v_x = t'_x\leq u'_x = \min_{u\in S_2} u_x$ implies
that $t'_x\leq v_x$ for all $v\in V(S)$ and thus, $\min_{v\in S}v_x =t'_x$
corresponds to the $x$-coordinates of one of its terminal
vertices. Moreover, since both $S_1$ and $S_2$ satisfy (O'.b) and $t'_x
=\min_{v\in S}v_x$, one easily verifies that (O'.b) must hold for $S$.
%
This immediately implies that $\max_{v\in S}v_x = t_x$ corresponds to the
$x$-coordinate of the other terminal vertex. Note, however, that $t'_x=t_x$
could be possible.  In either case, $S$ satisfies (O'.a).  Hence, if $S$
satisfies (O), then $S$ satisfies (O') as well. In summary, therefore,
Conditions~(O), (O') and~(O'') are equivalent.
\end{proof}

It is easy to see that Property~(O) is hereditary, that is:
\begin{obs}
  If $S$ is a segment that satisfies (O), then every segment $S'\subseteq
  S$ satisfies (O).
\end{obs}

\begin{definition}
  A segment $S$ is \emph{outstretched} if it satisfies (O) and its terminal
  edges are non-vertical. Moreover, an outstretched segment $S$ of a polygon 
  $P$ is \emph{maximally} outstretched (w.r.t.\ $P$) if there is no outstretched
  segment $S'$ in $P$ with $S\subsetneq S'$.
\end{definition}
Note that outstretched segments $S$ may have empty edge set in which case
$S$ can contain only a single vertex $t=\max(S)=\min(S)$. Moreover,
although terminal edges of $S$ cannot be vertical, $S$ can contain vertical
edges in its interior. In this case, it is even possible that $S$ contains
incident, i.e., consecutive, vertical edges.

\begin{lemma}\label{lem:minmaxS}
  For an outstretched segment $S$ with $E(S)\neq \emptyset$  it always holds
  that $\MIN(S)\cap \MAX(S)=\emptyset$.  In particular, 
  $\MIN(S) = \{t\}$ and $\MAX(S) = \{t'\}$ are singletons consisting
  of the terminal vertices $t$ and $t'$ of $S$ only, i.e., 
  $\min(S)=t$ and $\max(S)=t'$ are well-defined and distinct.
\end{lemma}
\begin{proof}
  By Lemma \ref{lem:O}, $\min_{v\in S}v_x$ and $\max_{v\in S}v_x$
  correspond to the $x$-coordinates of terminal vertices of $S$. Let $t$
  and $t'$ be the terminal vertices and $e=\{u,t\}$ and $f=\{u',t'\}$ be
  the terminal edges of $S$. Note, $e=f$ is possible. Assume w.l.o.g.\ that
  $t\in\MIN(S)$.  Since terminal edges of $S$ are non-vertical, we have
  $\max_{v\in e}v_x\neq \min_{v\in e}v_x$ which implies that $\MIN(S)\neq
  \MAX(S)$ and, in particular, $t'\in \MAX(S)$.  Moreover, by (O'.b) and
  because $e$ and $f$ are non-vertical, it holds that $t_x< u_x\le v_x \leq
  u'_x < t'_x$ for all vertices $v \in V(S)$ with $u\preceq_S v\preceq_{S}
  u'$, where $\preceq_S$ is defined on $V(S)$ by choosing $t$ as the root.
  Thus, $\MIN(S)=\{t\}$ and $\MAX(S)=\{t'\}$, i.e., $\min(S)=t$ and
  $\max(S)=t'$. Moreover, $\MIN(S)\cap\MAX(S)=\emptyset$.
\end{proof}

For later reference, we provide here the following simple result:
\begin{lemma}\label{lem:snf} 
  Let $S,S'$ be two outstretched segments of a polygon $P$ such that
  $E(S)\cap E(S')\ne \emptyset$.  Then, $S^* = S\cup S'$ is an outstretched
  segment of $P$.  
\end{lemma}
\begin{proof} 
  Since $S$ and $S'$ are paths in $P$, $S^* = S\cup S'$ is a connected
  subgraph of $P$ and thus, either $S^*\subsetneq P$ is a path or $S^* = P$
  is a polygon, i.e., a ``graph-theoretical'' cycle. In either case, every
  vertex of $S^*$ must have degree at most two in $S^*$ and $E(S)\cap
  E(S')$ must contain at least one of the terminal edges of $S$ as well as
  of $S'$.  By Lemma \ref{lem:minmaxS}, the terminal vertices
  $t\coloneqq\min(S)$ and $\max(S)$ of $S$ as well as $t'\coloneqq\min(S')$
  and $\max(S')$ are uniquely defined and distinct.

  Assume, for contradiction, that $S^*=P$.  In this case, it holds for the
  terminal vertices that $t,t',\max(S),\max(S')\in V(S)\cap V(S')$ since
  $S$ and $S'$ are are paths of a cycle $P$ whose union coincides with
  $P$. But then $t_x = t'_x$ and $\max(S)_x = \max(S')_x$ and thus, $t=t'$
  and $\max(S) = \max(S')$. This and $\MIN(P)\subseteq \MIN(S)\cup\MIN(S')$
  implies that $\min(P) = t$.  Since $S$ and $S'$ are outstretched segments
  and $t=t'$ refers to the unique vertex with minimum $x$-coordinate in $S$
  and $S'$, for the terminal edge $e = \{t,u\}$ of $S$ and $f=\{t,u'\}$ of
  $S'$ it must hold $u\neq u'$; otherwise $t$ would have degree one in
  $S^*=P$; a contradiction to $P$ being a cycle). But then $E(S)\cap E(S')$
  does not contain the terminal edges $e$ and $f$.  By similar arguments,
  $E(S)\cap E(S')$ does not contain the terminal edges $\{\max(S),w\}$ and
  $\{\max(S'),w'\}$.  Hence, $E(S)\cap E(S')$ does not contain any of the
  terminal edges of $S$ and $S'$; a contradiction.

  Therefore, $S^*$ is a path. If $S'\subseteq S$ or $S\subseteq S'$, then
  $S^*=S$ or $S^*=S'$, and thus $S^*$ is an outstretched segment of
  $P$. Otherwise $S'\cap S$ is a path that contain exactly one terminal
  vertex $S$ and $S'$ and $E(S\cap S')\ne\emptyset$ contain at least one
  terminal, and therefore non-vertical edge.  We use the partial orders
  $\preceq_{S}$ and $\preceq_{S'}$ as defined Lemma \ref{lem:O} by using
  $t$ and $t'$ as the root of $S$ and $S'$, respectively.

  Assume, for contradiction, that $S^*$ does not satisfy (O). Hence, there
  are two distinct edges $f$ and $g$ in $S^*$ and a $\xi\in \Ih{S^*}$ with
  $\xi\in \Ih{f}\cap \Ih{g}$. Since $S$ and $S'$ satisfy (O), we can
  w.l.o.g.\ assume that $f\in E(S)\setminus E(S')$ and $g\in E(S')\setminus
  E(S)$. Note, both edges $f$ and $g$ are non-vertical since neither $\Ih{f} =
  \emptyset$ nor $\Ih{g} = \emptyset$. Since $e,f\in E(S)$, we have
  $e\preceq_S f$ or $f\preceq_S e$, and we can assume w.l.o.g.\ that
  $e\preceq_S f$. Moreover, since $e,g\in E(S')$, we have either
  $e\preceq_{S'} g$ or $g\prec_{S'}e$. However, $g\prec_{S'}e$ together
  with $e\preceq_S f$, implies $\xi<\max(g)_x\le \max(e)_x\le \min(f)_x\le
  \xi$; a contradiction. Hence, $e\prec_{S'} g$ must hold. Since $S$ and
  $S'$ are paths and $f\in E(S)\setminus E(S')$ and $g\in E(S')\setminus
  E(S)$, there is a unique vertex $w\in V(S)\cap V(S') \subseteq V(S^*)$
  that satisfies the following property: $w$ is adjacent to $v\in
  V(S)\setminus V(S')$ and satisfies $w\preceq_S \max(f)$ and $w$ is
  adjacent to $v'\in V(S')\setminus V(S)$ and satisfies $w\preceq_S
  \max(g)$.  Since $S\cap S'$ is a path with $e\in E(S\cap S')$ and $w\in
  V(S\cap S')$, there is a vertex $v'''\in V(S\cap S')$ adjacent to $w$.
  The latter two observations together imply $\deg_{S^*}(w)\ge 3$; a
  contradiction.

  Hence, $S^*$ satisfies (O). Since, in addition, the terminal edges of
  $S^*$ are terminal edges of $S$ or $S'$ and are, thus, non-vertical, it
  follows that $S^*$ is an outstretched segment.
\end{proof}

Note that a similar result as in \Cref{lem:snf} does not hold if we only
claim $V(S)\cap V(S')\ne \emptyset$ instead of $E(S)\cap E(S')\ne
\emptyset$. To see this, consider the two maximal outstretched segments
$S_1$ and $S_2$ in the polygon $P$ as shown in
\Cref{fig:consecutive}(right). Here $S_1$ and $S_2$ intersect in a single
vertex but not in their edges. It is easy to verify that $S_1\cup S_2$ is
not an outstretched segment since Property (O) is violated.

\begin{definition}
  An outstretched segment $S$ of $P$ is maximal if there is no outstretched
  segment $S'$ of $P$ with $S\subsetneq S'$.
\end{definition}
The following properties of maximal outstretched segments will be useful:
\begin{proposition}\label{lem:bSPp} %bas-SP-prop
  For two distinct maximal outstretched segments $S$ and $S'$ of a polygon
  $P$ the following conditions are satisfied:
  \begin{enumerate}[noitemsep,nolistsep]
  \item $E(S)\cap E(S')=\emptyset$, i.e.\ they are edge-disjoint;
  \item $S\cap S'= \{\min(S),\max(S)\}\cap \{\min(S'),\max(S')\}$
  i.e.\ they can intersect at most in their terminal vertices;
  \item If $S\cap S'\ne \emptyset$, then 
  $\min(S)=\min(S')$ or
    $\max(S)=\max(S')$.
  \item If $|V(S)\cap V(S')|=2$ then $S\cup S'=P$.  
  \end{enumerate}
\end{proposition}
\begin{proof}
  Let $S, S'$ be two distinct maximal outstretched segments of a
  polygon $P$.

  1. If there is an edge $e\in E(S)\cap E(S')$, then \cref{lem:snf} implies
  that $S^*\coloneqq S\cup S'$ is an outstretched segment of $P$ and
  $S,S'\subseteq S^*$. Maximality implies $S=S'=S^*$; a contradiction.

  2. Let $p \in S\cap S'$.  By Statement~(1), $E(S)\cap E(S')=\emptyset$.
  Since $S,S'\subseteq P$ and $P$ is planar we can conclude that $S$ and
  $S'$ can only intersect in a common vertex, i.e., $p\in S\cap S'\subseteq
  V(S)\cap V(S')$.  Now, assume for contradiction that $p \in
  V(S)\setminus\{\min(S),\max(S)\}$ or $p \in
  V(S')\setminus\{\min(S'),\max(S')\}$.  Then, we may assume w.l.o.g.\ $p
  \in V(S)\setminus\{\min(S),\max(S)\}$.  Since $S,S'\subseteq P$ and $P$
  is a graph-theoretical cycle, and since $p\in
  V(S)\setminus\{\min(S),\min(S)\}$, where $\min(S)$ and $\max(S)$ are
  terminal vertices of $S$, we conclude that $\deg_{S}(p)=2=\deg_{P}(p)$.
  This, together with $\deg_{S'}(p)\ge 1$, implies that there is an
  incident edge $\{p,p'\}\in E(S')\subseteq E(P)$ for which we have
  $\{p,p'\}\in E(S)$. In particular, $\{p,p'\}\in E(S)\cap E(S')\ne
  \emptyset$, contradicting Statement~1.

  3. Assume that $S\cap S'\ne \emptyset$
  By Statement~2, $S\cap S'= \{\min(S),\max(S)\}\cap \{\min(S'),\max(S')\}$.
  Moreover, $S,S'\subsetneq S\cup S'$. However, $S\cup S'$ cannot be a
  maximal outstretched segment since, otherwise, we would contradict
  maximality of $S$ and $S'$.  Hence, only $S\cup S' = P$ is
  possible. Since $S$ and $S'$ are edge-disjoint, they must therefore
  intersect in precisely two vertices, i.e.,
  $\{\min(S),\max(S)\} = \{\min(S'),\max(S')\}$. This, together with
  $S\cup S' = P$, implies that $\min(S)=\min(S')$ or $\max(S)=\max(S')$ must
  hold.

  4. If $|V(S)\cap V(S')|=2$, then Statement~3 implies that
  $\min(S)=\min(S')$ and $\max(S)=\max(S')$. Since by Statement 1., $S$ and
  $S'$ are edge disjoint and thus internally vertex disjoint in $P$, we
  conclude that $S\cup S'$ is a graph theoretic cycle, and thus coincides
  with $P$.
\end{proof}

\begin{corollary}\label{cor:edge-uniqueS}
  Let $P$ be a polygon. Then, for every non-vertical edge $e\in E(P)$,
  there is a unique maximal outstretched segment $S$ of $P$ such that
  $e\in E(S)$. %Let $e =\{u,v\} \in E(P)$
\end{corollary}
\begin{proof}
  Let $e\in E(P)$ be a non-vertical edge. Since $s[e]\subset P$ is an
  outstretched segment of $P$, there is a maximal outstretched segment $S$
  containing $e$. Since maximal outstretched segments are edge-disjoint by
  \Cref{lem:bSPp}~(1), $S$ is uniquely determined.
\end{proof}

\begin{definition}\label{def:consecutive}
  A path (segment) in $P$ that consists of vertical edges only is called
  \emph{vertical} path (segment).  Two maximal outstretched segments $S$
  and $S'$ are \emph{consecutive (along $P$)} if they are distinct and (i)
  $V(S)\cap V(S')\neq \emptyset$ or (ii) there is a vertical path $W$ that
  does not share edges with $S$ and $S'$ and such that $S\cup S'\cup W$ is
  a segment of $P$.
\end{definition} 

