\begin{definition} \label{def:parity}
  Let $S$ be a maximal outstretched segment of a polygon $P$.  Then, the
  \emph{parity $\varpi$ of $S$} is
  \begin{equation*}
    \varpi(S)\coloneqq \begin{cases}
      0, \text{\ if } |\mc{N}_{\xi,S}| \text{ is even for all }	
      \xi\in \Io{S}\\
      1, \text{\ otherwise, i.e., }|\mc{N}_{\xi,S}| \text{ is odd for all }
      \xi\in \Io{S}\\
    \end{cases}
  \end{equation*}
\end{definition}
Note that, by \Cref{lem:eol}, $|\mc{N}_{\xi,S}|$ is either always even or
always odd for any $\xi\in\Io{S}$. Therefore, the parity
$\varpi(S)\in \{0,1\}$ is well-defined for every maximal outstretched
segment $S$ of $P$. Hence, the choice of $\xi\in \Io{S}$ in
the definition is arbitrary. 
%
Intuitively, the parity $\varpi(S)$ determines whether $\Int(P)$ is above
or below the outstretched segment $S$: if $\varpi(S)=0$, then $\Int(P)$ is
``above'' the segment $S$, and if $\varpi(S)=1$, then $\Int(P)$ is
``below'' the segment $S$. Therefore, for a given point $p$, it suffices to
determine the parity $\varpi(S)$ of the segment ``immediately above'' $p$
to determine whether or not $p\in\Int(P)$, see \cref{fig:pari}.
%
The next result, which is a
simple consequence of \Cref{lem:inside<->odd} and the definition of the
parity function $\varpi$, states this observation more formally:
\begin{proposition} \label{prop:ibp} %prop:inside<->blw-pair
  Let $P$ be a polygon and $p=(\xi,y)\in \mathbb{R}^2\setminus P$.  Then,
  $p\in \Int(P)$ if and only if there is a maximal outstretched segment $S$
  of $P$ such that
  \begin{enumerate}[noitemsep,nolistsep]
  \item $\xi\in \Ih{S}$ and $y<\yVal{S}{\xi}$,
  \item there is no maximal outstretched segment $S'$ of $P$ with $\xi\in
    \Ih{S'}$ such that that $y< \yVal{S'}{\xi}< \yVal{S}{\xi}$,
  \item $\varpi(S)=1$.
  \end{enumerate} 
\end{proposition}
\begin{proof}
  Let $P$ be a polygon and $p=(\xi,y)\in \mathbb{R}^2\setminus P$.  By
  \Cref{lem:inside<->odd}, $p\in \Int(P)$ if and only if the number of
  maximal outstretched segments $S$ of $P$ that satisfies Statement~(1) is
  odd.  In particular, if $p\in \Int(P)$, then there is a maximal
  outstretched segment $S$ of $P$ satisfying Statement~(1).  Moreover, we
  may choose the maximal outstretched segment $S$ of $P$ that satisfies
  Statements~(1) and~(2). Thus, is remains to show that, in the presence of
  Statements~(1) and~(2), $p\in\Int(P)$ and $\varpi(S)=1$ are equivalent.
  By assumption, $p$ is not contained in the boundary of $P$, i.e.,
  {$p\notin P$}. Since $\Int(P)$ is an open set, $p\in\Int(P)$ if and only
  if $p'\in\Int(P)$ for all $p'\in\mathbb{R}^2$ that satisfy $\Vert
  p-p'\Vert<\delta$ for sufficiently small $\delta>0$. In particular, we
  have $p=(\xi,y)\in \Int(P)$ if and only if $p'\coloneqq(\xi+\delta,y)\in
  \Int(P)$. In this case, we have $p'\in \mathbb{R}^2\setminus P$.  Hence,
  by assumption, there is a maximal outstretched segment $S'$ of $P$ that
  satisfies Statement~(1) and~(2) for $(\xi+\delta, y)=p'\in
  \mathbb{R}^2\setminus P$.  Since $\delta>0$ was sufficiently small, we
  can assume that $\min(S')_x\le \xi<\xi+\delta<\min(S')_x$, i.e.,
  $\xi+\delta\in (\min(S')_x,\max(S')_x)$.  Then, by definition of
  $\varpi(S)$, the number of segments that satisfy Statement~(1) is odd
  (i.e., $p'\in\Int(P)$) if and only if $\varpi(S)=1$ (i.e., Statement~(3)
  holds), see \Cref{lem:inside<->odd}.  This, together with $p \in \Int(P)$
  iff $p'\in \Int(P)$, implies $p\in\Int(P)$ if and only if Statement~(3)
  holds.
\end{proof}

Inverting the direction of the $y$-axis immediately implies the following
``mirror image'' of \Cref{prop:ibp}:
\begin{corollary} \label{cor:ibp-} 
  Let $P$ be a polygon and $p=(\xi,y)\in \mathbb{R}^2\setminus P$.  Then,
  $p\in \Int(P)$ if and only if there is a maximal outstretched segment $S$
  of $P$ such that
  \begin{enumerate}[noitemsep,nolistsep]
  \item $\xi\in \Ih{S}$ and $y>\yVal{S}{\xi}$,
  \item there is no maximal outstretched segment $S'$ of $P$ with $\xi\in
    \Ih{S'}$ such that $y> \yVal{S'}{\xi}> \yVal{S}{\xi}$,
  \item $\varpi(S)=0$.
  \end{enumerate} 
\end{corollary}

The following simple consequence of \Cref{prop:L24} and the definition of
consecutive maximal outstretched segments will be useful later on.
\begin{corollary} \label{cor:maxpar=1}
  Let $P$ be a polygon, let $\mc{S}$ be the set of all maximal outstretched
  segments of $P$, and let $S\in \mc{S}$.  If there is a $\xi\in \Io{S}$
  such that $\yVal{S}{\xi}\ge \yVal{S'}{\xi}$ for each $S'\in \mc{S}$ with
  $\xi\in \Ih{S'}$, then $\varpi(S)=1$.  Moreover, if $S$ and $S'\in
  \mc{S}$ are consecutive, then $\varpi(S)\ne\varpi(S')$.
\end{corollary}
\begin{proof}
  Let $P$ be a polygon, let $\mc{S}$ be the set of all maximal outstretched
  segments of $P$, and let $S\in \mc{S}$.  If there is a $\xi\in \Io{S}$
  such that $\yVal{S}{\xi}\ge \yVal{S'}{\xi}$ for each $S'\in \mc{S}$ with
  $\xi\in \Ih{S'}$, then $\mc{N}_{\xi,S}=\{S\}$ and, therefore,
  $\varpi(S)=1$.  Moreover, if $S$ and $S'$ are consecutive, then, by
  \Cref{lem:consec-x}, $\min(S)_x=\min(S)_x$ or $\max(S)_x=\max(S)_x$. In
  the first case, we assume w.l.o.g.\ that $\yVal{S}{\xi}<\yVal{S'}{\xi}$
  for $\xi\coloneqq\min(S)_x+\delta$ with $\delta>0$ sufficiently
  small. Since $P$ is simple, no other segment $S''\in \mc{S}$ contains a
  point $(\xi,\yVal{S''}{\xi})$ with
  $\yVal{S}{\xi}\le\yVal{S''}{\xi}\le\yVal{S'}{\xi}$.  Hence, since
  $\xi\notin \{\max(S)_x,\max(S')_x\}$, we conclude
  $|\mc{N}_{\xi,S'}|-|\mc{N}_{\xi,S}|=1$. Thus, we can assume
  w.l.o.g.\ that $|\mc{N}_{\xi,S'}|$ is odd and $|\mc{N}_{\xi,S}|$ is even.
  Hence, we can apply \Cref{lem:eol} and conclude that $|\mc{N}_{\xi',S'}|$
  is odd for all $\xi'\in \Io{S}$, and $|\mc{N}_{\xi',S}|$ is even for all
  $\xi'\in \Io{S}$.  By definition, $\varpi(S)\ne\varpi(S')$.  The same
  conclusion follows by an analogous argument for $\max(S)_x=\max(S')_x$.
\end{proof}

