\section{Investigating the Set of Maximally Outstretched Segments}
\label{sec:invest}

So far, we have considered a single polygon.  From here on, we focus on a
set $\P$ of polygons and the corresponding set $\Int(\P) = \{\Int(P)\mid
P\in \P\}$. Since $\Ih{P}$ is the
projection of $P$ onto the $x$-axis, we observe the following:
\begin{obs} \label{obs:I-P-sub}
  Let $\P$ be a set of polygons, and $P,P' \in \P$.  Then,
  $\Int(P)\subseteq \Int(P')$ implies $\Ih{P}\subseteq \Ih{P'}$.
  Conversely, $\Ih{P}\cap \Ih{P'}=\emptyset$ implies
  $\Int(P)\cap\Int(P')=\emptyset$.
\end{obs}
Note that, in general, neither $\Ih{P}\subseteq \Ih{P'}$ implies
$\Int(P)\subseteq \Int(P')$ nor $\Int(P)\cap\Int(P')=\emptyset$ implies
$\Ih{P}\cap \Ih{P'}=\emptyset$; see \cref{fig:non-sweep} for an
example.
%
Moreover, we will make use of the following three simple result
regarding the boundaries of overlap-free polygons, see
\cref{fig:overlapping} for an illustrative example:
\begin{lemma} \label{lem:s-o-r} 
  Let $P$ and $P'$ be two overlap-free polygons.  Then,
  $P\cap\Int(P')\ne\emptyset$ implies $\Int(P)\subsetneq \Int(P')$ and
  $P\subseteq \Int(P')\cup P'$.  Moreover, $\Ext(P')\cap P\ne\emptyset$
  implies $\Int(P)\nsubseteq \Int(P')$.  In particular, there are no
  $p,p'\in P$ such that $p\in \Int(P')$ and $p'\in \Ext(P')$.
\end{lemma}
\begin{proof}
  Let $P$ and $P'$ be two overlap-free polygons. First, assume that $p\in
  P\cap\Int(P')$. Hence, $p\in \Int(P')\setminus \Int(P)\ne
  \emptyset$. Since $p\in P$ is on the ``boundary'' of $P$ and since $p\in
  \Int(P')$ is \emph{not} on the ``boundary'' of $P'$, for every
  $\varepsilon>0$, there is a $p'\in \mathbb{R}^2$ with $||p-p'|| \le
  \varepsilon$ such that $p'\in \Int(P)\cap \Int(P')$. Hence, $\Int(P)\cap
  \Int(P')\ne\emptyset$.  This, together with $\Int(P')\setminus \Int(P)\ne
  \emptyset$ and the assumption that $P$ and $P'$ are overlap-free implies
  $\Int(P)\subsetneq \Int(P')$.  Now, assume that $p\in P\cap\Ext(P')$. By
  similar reasoning, there is a $p' \in \mathbb{R}^2$ such that $p' \in
  \Int(P)\cap\Ext(P')$.  This together with the assumption that $P$ and
  $P'$ are overlap-free implies $\Int(P)\nsubseteq\Int(P')$.  In summary,
  $P\cap\Int(P')\ne\emptyset$ and $P\cap\Ext(P')\ne\emptyset$ can never
  occur.
\end{proof}

\begin{lemma} \label{lem:area}
  Let $P$ and $P'$ be two overlap-free polygons
  such that $\Int(P)\cap\Int(P')\ne\emptyset$.  Then,
  $\Int(P)\subsetneq\Int(P')$ if and only if $\area{P}<\area{P'}$. In
  particular, $P=P'$ if and only if $\area{P}=\area{P'}$.
\end{lemma}
\begin{proof}
  Since polygons are overlap-free, $\Int(P)\cap\Int(P')\ne\emptyset$
  implies $P=P'$, $\Int(P)\subsetneq\Int(P')$ or
  $\Int(P')\subsetneq\Int(P)$. Clearly, $\Int(P)\subseteq \Int(P')$ implies
  $\area{P}\le\area{P'}$. Since two polygons are different only if their
  vertex sets differ, $P\ne P'$ and $\Int(P)\subseteq\Int(P')$ implies that
  there is vertex $v\in V(P)$ such that $v\in\Int(P')$, and thus
  $\area{P}<\area{P'}$. Thus, $\Int(P)\subseteq\Int(P')$ and
  $\area{P}=\area{P'}$ implies $P=P'$.
\end{proof}

