\begin{lemma}\label{lem:mos-le-1}
  Let $\P$ be a set of overlap-free polygons and $P,P'\in \P$. 
  Moreover, let $S$ and $S'$ be maximal
  outstretched segments of $P$ and $P'$, respectively.  Then, 
  we have $\yVal{S}{\xi}\le\yVal{S'}{\xi}$ for all 
  $\xi\in \Ic{S}\cap \Ic{S'}$, or
  $\yVal{S'}{\xi}\le\yVal{S}{\xi}$ for all 
  $\xi\in \Ic{S}\cap \Ic{S'}$.
\end{lemma}
\begin{proof}
  Let $(S,P),(S',P') \in \SP{\P}$.  If $P=P'$, the statement follows from
  \cref{lem:asa}.  Hence, suppose that $P\neq P'$.  Now, assume for
  contradiction that there are two $\xi_1,\xi_2\in \Ic{S}\cap \Ic{S'}$ such
  that $\yVal{S'}{\xi_1}>\yVal{S}{\xi_1}$ and
  $\yVal{S'}{\xi_2}<\yVal{S}{\xi_2}$.
  %
  We may assume w.l.o.g.\ that $\xi_1<\xi_2$.  By similar arguments as in
  the proof of \Cref{lem:asa}, the intermediate-value-theorem implies that
  the intersection $\widehat{S^*}\coloneqq \widehat{S}\cap\widehat{S'}$
  with $\widehat{S}\coloneqq \{ p\in S\mid \xi_1\le p_x\le \xi_2 \}$ and
  $\widehat{S'}\coloneqq \{ p\in S'\mid \xi_1\le p_x\le \xi_2 \}$ is
  non-empty.  In particular, it is easy to verify that $\xi_1$ and $\xi_2$
  can be chosen such that the intersection $\widehat{S^*}$ is connected.
  Note that $\widehat{S^*}$ is not necessarily an isolated point and may
  involve vertical edges.  Moreover, $\widehat{S'}\setminus \widehat{S^*}$
  decomposes into exactly two segments $\widehat{S'_1}$ and
  $\widehat{S'_2}$, where w.l.o.g.\ $p_1\coloneqq
  (\xi_1,\yVal{S}{\xi_1})\in \widehat{S'_1}$ and $p_2\coloneqq
  (\xi_2,\yVal{S}{\xi_2})\in \widehat{S'_2}$.  Moreover,
  \cref{lem:bSPp}~(2) implies that any sufficiently small open neighborhood
  $U$ of $\widehat{S^*}$ does not intersect with other maximal outstretched
  segment of $P$ and $P'$, i.e., for a sufficiently small $\delta>0$, we
  have $U\coloneqq\{p\in \mathbb{R}^2\mid \Vert p-p'\Vert < \delta
  \textnormal{ for some }p'\in \widehat{S^*}\}$.  Since
  $\widehat{S'}=\widehat{S'_1}\cupdot \widehat{S^*} \cupdot
  \widehat{S'_2}$, it is straightforward to verify that there is a $p'_1\in
  \widehat{S'_1}\cap U$ and $p'_2\in \widehat{S'_2}\cap U$.  In particular,
  $p'_1,p'_2\notin S$, and thus, $(p'_1)_y\ne \yVal{S}{(p'_1)_x}$ and
  $(p'_2)_y\ne \yVal{S}{(p'_2)_x}$.  Moreover, $p'_1,p'_2\notin S$,
  together with $p'_1,p'_2 \in U$, implies $p'_1,p'_2\notin P$.

  Now, assume for contradiction that $(p'_1)_y<\yVal{S}{(p'_1)_x}$, and
  thus, $(p'_1)_y<\yVal{S}{(p'_1)_x}=\yVal{\widehat{S}}{(p'_1)_x}$.  This,
  together with $p'_1\in \widehat{S'_1}$ and
  $\yVal{\widehat{S'_1}}{\xi_1}=\yVal{S'}{\xi_1}>\yVal{S}{\xi_1}=
  \yVal{\widehat{S}}{\xi_1}$, implies $\widehat{S'_1}\cap
  \widehat{S}\ne\emptyset$.  In particular, there is a $p \in
  \widehat{S}\cap\widehat{S'_1} \subseteq \widehat{S}\cap \widehat{S'}$
  with $p\notin \widehat{S^*}$; a contradiction to
  $\widehat{S^*}=\widehat{S}\cap\widehat{S'}$.  Hence,
  $(p'_1)_y>\yVal{S}{(p'_1)_x}$, i.e., Statement~(1) of \cref{cor:ibp-} is
  satisfied; and since $p'_1\in U$, Statement~(2) of \cref{cor:ibp-} is
  satisfied.  This, together with \cref{cor:ibp-}, implies $p'_1\in
  \Int(P)$ if and only if $\pari{S}{P}=0$. By analogous arguments, we
  conclude that $(p'_2)_y<\yVal{S}{(p'_2)_x}$, i.e., Statement~(1) of
  \cref{prop:ibp} is satisfied; and since $p'_2\in U$, Statement~(2) of
  \cref{prop:ibp} is satisfied.  Hence, \cref{prop:ibp} implies $p'_2\in
  \Int(P)$ if and only if $\pari{S}{P}=1$.  Since $p'_1,p'_2\notin P$, we
  have $p'_1,p'_2\in \Int(P)\cup \Ext(P)$.  Thus, $p'_2\in\Int(P)$ and
  $p'_1\in\Ext(P)$ if $\pari{S}{P}=1$, and $p'_1\in\Int(P)$ and
  $p'_2\in\Ext(P)$, otherwise (i.e., $\pari{S}{P}=0$).

  Independent of $\pari{S}{P}$, therefore there are $p,p'\in
  \widehat{S'}\cap U\subseteq S'\subseteq P'$ with $p\in \Int(P)$ and
  $p'\in\Ext(P)$.  This, \cref{lem:s-o-r} and the fact that $P$ and $P'$
  are overlap-free implies a contradiction.  Hence, we have
  $\yVal{S}{\xi}\le\yVal{S'}{\xi}$ for all $\xi\in \Ih{S}\cap \Ih{S'}$, or
  $\yVal{S'}{\xi}\le\yVal{S}{\xi}$ for all $\xi\in \Ih{S}\cap \Ih{S'}$.
\end{proof}


\begin{remark}
\emph{From here on, all sets $\P$ of polygons are considered to be
overlap-free.}
\end{remark}  

Since a segment $S$ may be part of two or more polygons, we now use pairs
$(S,P)$ in order identify the polygon $P$ of which $S$ is considered to be
a maximal outstretched segment. We write $\SP{\P}$ for the set of all pairs
$(S,P)$ of maximal outstretched segments $S\in \mc{S}$ and their polygons
$P\in \mathcal{P}$.  Moreover, we set 
\[\SPx{\P}{\xi}\coloneqq \big\{(S,P)\in \SP{\P} \mid \xi\in \Ih{S}\big\}.\] 
A segment $S$ that is contained in two polygons
$P$ and $P'$ might be maximal outstretched in $P$ but not in $P'$. Hence,
$(S,P)\in \SP{\P}$ does not necessarily imply $(S,P')\in \SP{\P}$ even if
$S$ is a segment of $P'$ as well. Thus, in general, $\SP{\P} \neq
\mathcal{S}\times \mathcal{P}$. Furthermore, note that the parity of
$S$ depends on $P$, hence we write $\pari{S}{P}$ form here on.

