In this section, we are interested of the ``relative position'' of two
polygons $P$ and $P'$, i.e. $\Int(P)\subseteq \Int(P')$, $\Int(P)\subseteq
\Int(P')$ or $\Int(P)\cap\Int(P')=\emptyset$.  To this end, we introduce
the concept of ``sweep-adjacency'', which is illustrated in
\cref{fig:sweep-xample}.
\begin{definition}\label{def:adjacent}
  Let $\P$ be a set of polygons and $(S,P),(S',P')\in\SP{\P}$ with $P\ne
  P'$.  Then, we call $(S,P)$ and $(S',P')$ \emph{sweep-adjacent} if there
  is a $\xi\in \Io{S}\cap \Io{S'}$ such that there is no $(S'',P'')\in
  \SPx{\P}{\xi}$ with $P''\in \{P,P'\}$, and
  \begin{equation*}
  \yVal{S}{\xi}<\yVal{S''}{\xi}<\yVal{S'}{\xi}\textnormal{ or }
  \yVal{S}{\xi}>\yVal{S''}{\xi}>\yVal{S'}{\xi}.
  \end{equation*}
  In this case, we say that $\xi$ is a \emph{witness} for the
  sweep-adjacency of $(S,P)$ and $(S',P')$.
\end{definition}
Note that $\min(S)_x$ and $\min(S')_x$ need to be excluded from
$\Io{S}\cap\Io{S'}$, since there is another segment $(S'',P)\in\SP{\P}$
with $\min(S'')=\min(S)$ (resp., $(S'',P')\in\SP{\P}$ with
$\min(S'')=\min(S')$), which would lead to ambiguities.
%
Moreover, in order to get some intuition, we observe the following:

\begin{obs} \label{obs:alwaysone}
  Let $\P$ be a set of polygons, $P,P'\in\P$ with $P\ne P'$, and
  $(S,P),(S',P')\in \SP{\P}$.  Then, the existence of a $\xi\in \Io{S}\cap
  \Io{S'}$ with $\yVal{S}{\xi}=\yVal{S'}{\xi}$ implies (a) that
  $p\coloneqq(\xi,\yVal{S}{\xi})=(\xi,\yVal{S'}{\xi})\in S\cap S'$, and (b)
  that $(S,P)$ and $(S',P')$ are sweep-adjacent.  However, $p\in S\cap S'$
  with $p_x\in\Io{S}\cap\Io{S'}$ does \emph{not} imply that $(S,P)$ and
  $(S',P')$ are sweep-adjacent; see \cref{fig:non-sweep} for an
  illustrative example.
\end{obs}

\begin{lemma}\label{lem:sweep-adja-pair}
  Let $\P$ be a set of polygons and $P,P'\in\P$. Then, there is a
  sweep-adjacent pair $(S,P),(S',P')\in \SP{\P}$ if and only if $\Ih{P}\cap
  \Ih{P'}\ne\emptyset$ and $P\neq P'$.
\end{lemma}
\begin{proof}
  Let $\P$ be a set of polygons, $P,P'\in\P$ with $P\ne P'$.  If
  $\Ih{P}\cap \Ih{P'}=\emptyset$, then there is no $\xi$ such that
  $(S,P),(S'P')\in \SPx{\P}{\xi}$, and thus, in particular, no
  sweep-adjacent pair of segments exists. Conversely, we assume $\Ih{P}\cap
  \Ih{P'}\ne\emptyset$. Since $\Ih{P}$ and $\Ih{P'}$ are semi-open to the
  right, so is their intersection, and thus there is an open interval
  $J\subseteq \Ih{P}\cap \Ih{P'}\ne\emptyset$. Moreover, $J'\coloneqq
  J\setminus\{v_x\mid v\in V(P)\cup V(P')\}\ne\emptyset$, and for every
  $\xi\in J'$, we have $\mc{S}\coloneqq\{S\mid (S,P)\in \SPx{\P}{\xi}\}$
  and $\mc{S'}\coloneqq\{S'\mid (S',P')\in \SPx{\P}{\xi}\}$ are non-empty.
  Now, choose $S\in \mc{S}$ and $S'\in \mc{S'}$ such that
  $|\yVal{S}{\xi}-\yVal{S'}{\xi}|$ is minimal.  It follows immediately that
  $(S,P)$ and $(S',P')$ are sweep-adjacent.
\end{proof}
\begin{lemma}\label{lem:sw+delta}
  Let $\P$ be a set of polygons, and let $(S,P),(S',P')\in \SP{\P}$ be
  sweep-adjacent witnessed by $\xi$.  Then, there exists a sufficiently
  small $\delta>0$ such that sweep-adjacency is also witnessed by 
  $\xi+\delta$ and $\xi-\delta$.
  In particular, there is always a witness $\xi'\in
  \Io{S}\cap\Io{S'}$ with $\xi \ne v_x$ for all $v \in V(P)\cup V(P')$.
\end{lemma}
\begin{proof}
  Let $\P$ be a set of polygons, and let $(S,P),(S',P')\in \SP{\P}$ be a
  sweep-adjacent pair witnessed by $\xi$ and we assume
  w.l.o.g.\ $\yVal{S}{\xi}\le\yVal{S'}{\xi}$.  Hence, \cref{def:adjacent}
  implies $\xi\in \Io{S}\cap\Io{S'}$. This, together with
  $\Io{S}\cap\Io{S'}$ being an open interval, implies that there is a
  sufficiently small open neighborhood $U$ of $\xi$ such that $U\subseteq
  \Io{S}\cap\Io{S'}$ and $\SPx{\P}{\xi}=\SPx{\P}{\xi'}$ for all $\xi'\in
  U$.  In particular, there is a $\delta>0$ such that (a) $\xi\pm\delta\in
  U$ and b $\xi\pm\delta\ne v_x$ for all $v\in V(P)\cup V(P')$.  Moreover,
  by \cref{def:adjacent}, there is no $(S'',P'')\in\SP{\P}$ with $P''\in
  \{P,P'\}$ and $\yVal{S}{\xi}<\yVal{S''}{\xi}<\yVal{S'}{\xi}$.  This,
  together with $\SPx{\P}{\xi}=\SPx{\P}{\xi\pm\delta}$ and
  \cref{lem:mos-le-1}, implies that there is no $(S'',P'')\in\SP{\P}$ with
  $P''\in \{P,P'\}$ and $\yVal{S}{\xi'}<\yVal{S''}{\xi'}<\yVal{S'}{\xi'}$.
  Hence, $\xi\pm\delta$ is also a witness for the sweep-adjacency of
  $(S,P)$ and $(S',P')$.
\end{proof}


