\notag
\\
&\leq  \frac{2 B \tau_{\mix}(c)t}{\tau(c)}.    \label{eqn:t_1_term_bound}
\end{align}
% \Neil{We can get away with $B$ rather than $2B$ above if we want.}\\
Now for \eqref{eqn:inter_2}, we use the time-scale separation to show it vanishes as $c\to\infty$. By leveraging the assumption of policy $\pi^\star(\tau(c))$ that during each time segment $\cbrac{i\tau(c),\dots,(i+1)\tau(c)}$, the schedules $(\bm{\sigma}(\bm{n}(j)), \bm{n}(j))$ for all $j\in\cbrac{i\tau(c),\dots,(i+1)\tau(c)-1}$ are determined based on the request queue lengths at the beginning of the segment that is $\bar{\bm Q}^c(i\tau(c))$, even though request queue lengths evolve during this time segment. Using this, we can rewrite and upper bound~\eqref{eqn:inter_2} as follows:
\begin{align}
\eqref{eqn:inter_2}&\leq \frac{1}{c}
\sum_{i:i\tau(c) \leq ct} 
\sum_{s=i\tau(c)+\tau_{\mix}(c)}^{(i+1)\tau(c)-1}
    \Bigg| 
        \mu'_{\bm Q(i\tau(c))} \sbrac{P^{\bm Q(i\tau(c))}}^s \hat{n}^\star_r\brac{\bm Z(s),\bar{\bm Q}^c\Big(\frac{i\tau(c)}{c}\Big)}\\
        & \qquad \qquad \qquad \qquad \qquad \qquad-\mu^{\pi^\star(\bm Q(i\tau(c))} \sbrac{P^{\bm Q(i\tau(c))}}^s \hat{n}^\star_r\brac{\bm Z(s),\bar{\bm Q}^c\Big(\frac{i\tau(c)}{c}\Big)} 
    \Bigg| \nonumber\\
& \leq\frac{1}{c}\sum_{i:i\tau(c) \leq ct} \sum_{s=i\tau(c)+\tau_{\mix}(c)}^{(i+1)\tau(c)-1} 2B \norm{\mu'_{\bm Q(i\tau(c))} \sbrac{P^{\bm Q(i\tau(c))}}^s -\mu^{\pi^\star(\bm Q(i\tau(c))} \sbrac{P^{\bm Q(i\tau(c))}}^s}_{\TV}\label{eqn:inter_3}\\
% &\leq \frac{1}{c}\sum_{i:i\tau(c) \leq ct} \sum_{s=i\tau(c)+\tau_{\mix}(c)}^{(i+1)\tau(c)-1} 2B \norm{\mu'_{\bm Q(i\tau(c))}  -\mu^{\pi^\star(\bm Q(i\tau(c))} }_{\TV} \rho\brac{P^{\bm Q(i\tau(c))}}^s \nonumber\\
&\leq \frac{1}{c}\sum_{i:i\tau(c) \leq ct} \sum_{s=i\tau(c)+\tau_{\mix}(c)}^{(i+1)\tau(c)-1} 2B \norm{\mu'_{\bm Q(i\tau(c))}  -\mu^{\pi^\star(\bm Q(i\tau(c))} }_{\TV} \rho^s \label{eqn:inter_4}\\
&\leq \frac{4B\rho^{\tau_{\mix}(c)}t}{(1-\rho)\tau(c)}\label{eqn:inter_5}.
\end{align}
%\Neil{We still need to define $\rho$, and prove $\rho$ is independent of $Q$. I've added a subsubsection to populate on this.}\\
% \Neil{Have we defined $\pi$ and potential clash if we wish to use $\pi$ for policy as well.}
% \Neil{$\pi$ for policy, $\pi^\star$, and $\mu$ for stationary distribution.}
% \Neil{Should this be $ \delta_{\bm{Z}(i\tau(c))}$, assuming this is a Dirac delta function?}
In the first inequality, $ \mu'_{\bm{Q}(i\tau(c))}$ represents the initial distribution of the $\bm{Z}$ process which may not be stationary.
Furthermore, \eqref{eqn:inter_3} is derived from: 
\begin{multline*}
 \left| \mu'_{\bm Q} \sbrac{P^{\bm Q}}^s \hat{n}^\star_r(i\tau(c))-\mu^{\pi^\star(\bm Q)}\sbrac{P^{\bm Q}}^s \hat{n}^\star_r(i\tau(c)) \right| 
 \leq B     \sum_{\bm z\in \mathcal{Z}} \left|\sum_{\bm z'\in \mathcal{Z}}\brac{\mu'_{\bm Q}(\bm z') -\mu^{\pi^\star(\bm Q)}}\sbrac{P^{\bm Q}}^s_{\bm z' \bm z}\right|
 \\= 2B     \frac{1}{2}\sum_{\bm z\in \mathcal{Z}} \left|\mu'_{\bm Q}(\bm z)\sbrac{P^{\bm Q}}^s_{ \bm z} -\mu^{\pi^\star(\bm Q)}(\bm z)\sbrac{P^{\bm Q}}^s_{ \bm z}\right|=2B \norm{\mu'_{\bm Q}\sbrac{P^{\bm Q}}^s-\mu^{\pi^\star(\bm Q)}\sbrac{P^{\bm Q}}^s}_{\TV},
\end{multline*}
(For brevity, we suppress the dependence of $\bm{Q}$ on $ i\tau(c)$). In~\eqref{eqn:inter_4}, we have used our mixing time lemma, Lemma~\ref{lem:lemrho}. Finally, in the last inequality~\eqref{eqn:inter_5}, we used the bound $\norm{\mu'_{\bm{Q}(i\tau(c))} - \mu^{\pi^\star(\bm Q(i\tau(c))}}_{\TV} \leq 2$.

Therefore, applying~\eqref{eqn:t_1_term_bound} and~\eqref{eqn:inter_5} to \eqref{eqn:term2}, we have 
\begin{equation*}
\left|\eqref{eqn:term2}\right|\leq \frac{2 B \tau_{\mix}(c)t}{\tau(c)}+ \frac{4B\rho^{\tau_{\mix}(c)}t}{(1-\rho)\tau(c)}.
\end{equation*}
Hence, by selecting $\tau_{\mix}(c) =\left|\frac{\alpha\log(c)}{\log(\rho)}\right|$ for $\alpha>0$ and choosing $\tau(c) = (\log(c))^2$, the upper bound in the above expression approaches $0$ as $c \to \infty$. This proves that~\eqref{eqn:term2} converges to $0$ as $c\to \infty$. 


Finally we turn to the limit of~\eqref{eqn:term3}. Since we are staring $Z(i\tau(c))\sim \mu^{\pi^\star(\bm Q(i\tau(c))}$, we can write
\begin{multline*}
\frac{1}{c} \sum_{i:i\tau(c) \leq ct} \sum_{s=i\tau(c)}^{(i+1)\tau(c)-1} \E \sbrac{\hat{n}^\star_r\brac{\bm Z(s),\bar{\bm Q}^c(i\tau(c)/c)}\mid \bm Z(i\tau(c))\sim \mu^{\pi^\star(\bm Q(i\tau(c))} ,\bm Q(i\tau(c))}=\\\frac{1}{c} \sum_{i:i\tau(c) \leq ct} \sum_{s=i\tau(c)}^{(i+1)\tau(c)-1} \E_{z\sim \mu^{\pi^\star(\bm Q(i\tau(c))}} \sbrac{\gamma_r {n}^\star_r}.
\end{multline*}
%which, by the Functional Strong Law of Large Numbers, converges to~\eqref{eqn:fl_3} as $c \to \infty$. 

%Thus far, it has been shown that $\bar{A}_r^c(t)$ in term~\eqref{eqn:term0} converges to~\eqref{eqn:fl_2} as $c \to \infty$. 
So we have established that Term~\eqref{eqn:term1} tends to zero as $c \to \infty$ by applying the Azuma-Hoeffding inequality, and leveraging time-scale separation, term~\eqref{eqn:term2} also vanishes as $c \to \infty$. So term~\eqref{eqn:term3} is the only term remaining. %This completes the proof that the limit satisfies~\eqref{eqn:fl_1}-\eqref{eqn:fl_3}.
Thus we see that
\begin{equation}
\bar{D}_r(t) = \lim_{c\rightarrow \infty} \frac{1}{c} \sum_{i:i\tau(c) \leq ct} \sum_{s=i\tau(c)}^{(i+1)\tau(c)-1} \E_{z\sim \mu^{\pi^\star(\bm Q(i\tau(c))}} \sbrac{\gamma_r {n}^\star_r}\,.
\label{eq:Dlim2}    
\end{equation}
Thus, we see that \eqref{eq:Dlim} holds as required.  
\end{proof}

Here, we see that due to timescale separation, the departure process on the fluid scale is ultimately determined by the stationary distribution of LLEs. This observation is critical both in characterizing the non-standard capacity region of these system and for finding throughput optimal policies.

