\section{Proof of Theorem \ref{thrm:stabilityRegion}}
\label{append:stabilityregion}

We now restate and prove Theorem \ref{thrm:stabilityRegion}.

\ThrmStabilityRegion* 



\begin{proof}
We first prove \eqref{eq:Cbar} holds. To do this, we take any stabilizable policy. We then use the long-run service process of that policy to design an LLE scheduling scheme with the correct stationary service rate to satisfy \eqref{eq:Cbar}.

First, if $\bm \lambda \in \mathcal C$, then let $\bm X(\infty)=(\bm Z(\infty),\bm Q(\infty))$ denote the stationary distribution of the Markov chain that is positive recurrent under $\bm \lambda$. Also, we let $ d_r(\infty)$ denote the stationary number type $r$ requests that depart. Thus we have for $r \in \mathcal R$,
\begin{align}
 \lambda_r &\leq\mathbb{E}\sbrac{ d_r(\infty)}\notag \\
&=\sum_{\bm z,\bm q}\mb{P}(\bm X(\infty)=(\bm z,\bm q))\sum_{(\bm{\sigma},\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z, \bm q)  n_r \gamma_r \, . \label{eq:expand}
\end{align}
Above, \eqref{eq:expand} the expanded expression for the stationary departure rate.
Here $p(\bm{\sigma},\bm{n} | \bm z, \bm q) $ denotes the stationary probability the schedule $(\bm{\sigma},\bm{n})$ is selected given the system state $(\bm z, \bm q)$. 

Conditioning on $\bm Z(\infty)$, we can further write
\begin{align}
 \lambda_r
&\leq\sum_{\bm z}
    \mb{P}(\bm Z(\infty)=\bm z) 
    \sum_{\bm q}
        \mb{P}(\bm Q(\infty)=\bm q | \bm Z(\infty) =  \bm z)
    \sum_{(\bm{\sigma},\bm{n})\in\mathcal{S}}
            p(\bm{\sigma},\bm{n} | \bm z, \bm q)
             n_r \gamma_r ,
            \notag \\
 & =\sum_{\bm z}\mb{P}(\bm Z(\infty)=\bm z)\sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z)   n_r \gamma_r \label{eq:lle_stationary}
\end{align}
where 
\begin{equation}\label{eq:pidef}
p(\bm{\sigma} ,\bm{n} | \bm z)
:=
\sum_{\bm q}
    \mb{P}(\bm Q(\infty)=\bm q\mid \bm Z(\infty)=\bm z)
    p(\bm{\sigma} ,\bm{n} | \bm z, \bm q) 
\end{equation}
 denotes the probability that schedule $(\bm{\sigma} ,\bm{n})$ is selected in stationary regime given that $\bm Z(\infty)=\bm{z}$. 

We can now use it to define an entanglement matching policy that is agnostic to request queues. In particular, we define the request agnostic policy $\hat \pi$ where whenever the left side queues are in state $\bm z$, we choose the schedule $(\bm \sigma, \bm n)$ with probability $p(\bm{\sigma},\bm{n} | \bm z)$ as given by \eqref{eq:pidef}. We let $\hat{\bm Z}(\infty)$ denote the stationary number of LLEs under this policy. 

We now show that $\hat{\bm Z}(\infty)$ and $\bm Z(\infty)$ are equal in distribution.\footnote{For a standard switching model these are immediately equal as they are both independent of the queue size process $\bm Q(\infty)$; however, in our case this property that must be verified. The following calculations are not standard in prior analysis on Maximal Stability.} We prove this by verifying both distributions satisfy identical balance equations.

First the balance equations for $\hat{\bm Z}(\infty)$  are
\begin{equation}
\mathbb P (\hat{\bm Z}(\infty) = \bm z) 
=
\sum_{\bm z'} \sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}} \mathbb P 
( \bm Z(1) = \bm z | \bm Z(0) =\bm z', \bm n(0) = \bm n, \bm \sigma(0)= \bm \sigma  ) p(\bm{\sigma} ,\bm{n} | \bm z')
\mathbb P( \hat {\bm Z}(\infty) = \bm z' ) \, .
\label{eq:hatbalance}    
\end{equation}
Here, $\bm z'$ indicates the initial state of the stationary distribution, and $\bm z$ represents the next state reached after one transition.
Next, the balance equations for $\bm X(\infty) = (\bm Z(\infty), \bm Q(\infty))$ are 
:
\begin{align}
    &
    \mathbb P (  \bm Z( \infty) = \bm z, \bm Q(\infty) = \bm q )
    \notag
\\
&
= 
    \sum_{\bm z' \bm q'} \sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}} 
    \Big[
    \mathbb P ( \bm Z(1) =\bm z  , \bm Q(1) = \bm q  | \bm Z(0) =\bm z ' , \bm Q(0) = \bm q', \bm n(0)= \bm n, \bm \sigma(0)= \bm \sigma )
    \notag
    \\
    &\qquad \qquad \qquad \qquad
    \times 
    p(\bm{\sigma} ,\bm{n} | \bm z', \bm q')
    \notag
    \\
    &\qquad \qquad \qquad  \qquad\qquad
    \times
    \mathbb P (\bm Z(\infty) =\bm z ' , \bm Q(\infty ) = \bm q' )  
    \Big]\, .
     \label{eq:Zlong0}
\end{align}
Thus, summing over $\bm q$ gives
\begin{align}
  &
  \mathbb P (  \bm Z( \infty) = \bm z)
  \notag
  \\
&
  = \sum_{\bm q} \mathbb P (  \bm Z( \infty) = \bm z, \bm Q(\infty) = \bm q ) 
  \notag
  \\
  &
= 
    \sum_{\bm q\, \bm z' \bm q'} \sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}} 
    \Big[ 
    \mathbb P ( \bm Z(1) =\bm z  , \bm Q(1) = \bm q  | \bm Z(0) =\bm z ' , \bm Q(0) = \bm q' , \bm n(0)= \bm n, , \bm \sigma(0)= \bm \sigma)  
    \notag
    \\
    &
    \qquad \qquad \qquad \qquad 
    \times
    p(\bm{\sigma} ,\bm{n} | \bm z', \bm q')
    \notag
    \\
    &\qquad \qquad \qquad \qquad\quad \times
    \mathbb P (\bm Z(\infty) =\bm z ' , \bm Q(\infty ) = \bm q' )  \Big]
    \label{eq:Zlong1}
\\
&
=
    \sum_{\, \bm z' \bm q'} \sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}} 
   \Big[ 
    \mathbb P ( \bm Z(1) =\bm z  | \bm Z(0) =\bm z ' , \bm Q(0) = \bm q' , \bm n(0)= \bm n, \bm \sigma(0)= \bm \sigma)  
    \notag
    \\
    &
    \qquad \qquad \qquad \qquad 
    \times
    p(\bm{\sigma} ,\bm{n} | \bm z', \bm q')
    \notag
    \\
    &\qquad \qquad \qquad \qquad\quad \times
    \mathbb P (\bm Z(\infty) =\bm z ' , \bm Q(\infty ) = \bm q' )  \Big]
    \label{eq:Zlong2}
\\
&
=
    \sum_{\, \bm z' \bm q'} \sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}} 
   \Big[ 
    \mathbb P ( \bm Z(1) =\bm z  | \bm Z(0) =\bm z ' ,  \bm n(0)= \bm n, \bm \sigma(0)= \bm \sigma) 
    \notag
    \\
    &
    \qquad \qquad \qquad \qquad 
    \times
    p(\bm{\sigma} ,\bm{n} | \bm z', \bm q')
    \notag
    \\
    &\qquad \qquad \qquad \qquad\quad \times
    \mathbb P ( \bm Q(\infty ) = \bm q' 
 | \bm Z(\infty) =\bm z '  ) 
     \mathbb P (\bm Z(\infty) =\bm z ' ) \Big]  
     \label{eq:Zlong3}
\\
&
=
    \sum_{\, \bm z' }
    \sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}} 
    \mathbb P ( \bm Z(1) =\bm z  | \bm Z(0) =\bm z ' ,  \bm n(0)= \bm n, \bm \sigma(0)= \bm \sigma) 
    \notag
    \\
    &
    \qquad \qquad \qquad  
    \times
    \Big[  
    \sum_{\, \bm q' }
   p(\bm{\sigma} ,\bm{n} | \bm z', \bm q')
    \mathbb P ( \bm Q(\infty ) = \bm q' 
 | \bm Z(\infty) =\bm z '  ) 
 \Big]
     \mathbb P (\bm Z(\infty) =\bm z ' )   
      \label{eq:Zlong4}
\\
&
=
    \sum_{\, \bm z' }
    \sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}} 
    \mathbb P ( \bm Z(1) =\bm z  | \bm Z(0) =\bm z ' ,  \bm n(0)= \bm n, \bm \sigma(0)= \bm \sigma)
    p(\bm{\sigma} ,\bm{n} | \bm z')
         \mathbb P (\bm Z(\infty) =\bm z ' )   \, .
          \label{eq:Zlong5}
\end{align}
Above in \eqref{eq:Zlong1}, we apply \eqref{eq:Zlong0}. In \eqref{eq:Zlong2} we sum over $\bm q$. In \eqref{eq:Zlong3}, we note that the transition from $\bm z'$ to $\bm z$ does not depend on $\bm q'$ once we condition on the schedule $\bm n$, and we also condition on $\bm z'$. In \eqref{eq:Zlong4} we notice we can bring sum over $\bm q'$ inside. In \eqref{eq:Zlong5} we note by our definition \eqref{eq:pidef} that this inner sum is $p(\bm{\sigma} ,\bm{n} | \bm z')$. From \eqref{eq:Zlong5} and \eqref{eq:hatbalance} we see that both $\bm Z(\infty)$, $\hat {\bm Z}(\infty)$ satisfy the same balance equation (on the same irreducible set of states). Thus by uniqueness of stationary distributions $\bm Z(\infty)$, $\hat {\bm Z}(\infty)$ are equal in distribution.

We can now see that \eqref{eq:Cbar} holds. In particular, we let $\mu (\bm z) = \mathbb P(\hat {\bm Z}(\infty) = \bm z) = \mathbb P(\bm Z(\infty) = \bm z)$ then, from \eqref{eq:expand}, we see that our request agnostic policy $\hat \pi$ is such that 
\[
\lambda_r
 \leq \sum_{\bm z}\mu(\bm z)\sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z)   n_r \gamma_r  \,. 
\]
This verifies \eqref{eq:Cbar} and completes the first part of the theorem.

For the second part, we apply Foster's Lemma.\footnote{Again, there are some complications when compared to more traditional maximal stability proofs due to the random evolution of the service process.} Consider an agnostic policy such that 
\[
\lambda_r
 < \sum_{\bm z}\mu(\bm z)\sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z)   n_r \gamma_r  \, 
\]
holds.
Notice that if the LLE process is stationary, then we have for all $\bm q$ sufficiently large
\begin{align*}
& \mathbb E \Big[ \sum_r Q_r(t+1) -\sum_r Q_r(t) | \bm Q(t)=\bm q, \bm Z(t)\sim \mu \Big]
\\
& = 
\sum_r \Big( \lambda_r  - \sum_{\bm z}\mu(\bm z)\sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z)   n_r \gamma_r  \Big) <0 \, .
\end{align*}
Thus, in principle, if it were not for Markov evolution of the $\bm Z(t)$ process, then we could directly apply Foster's Lemma. In order to deal with this issue, we simply need to give the process sufficient time to approach equilibrium and then we can apply Lyapunov arguments. We start by proving stability for one queue, since $(\bm Z(t),  Q_r(t))$ is a Markov chain for agnostic policies. We then use our queue size bound to prove stability for $(\bm Z(t),  \bm Q(t))$. We apply the Lyapunov argument of Bertsimas et al. \cite{bertsimas1998geometric}. This is the plan for the remainder of the proof. \footnote{We note that an alternative approach is to Apply Foster-Lyapunov over renewal cycles of the process $\bm Z$ and apply Theorem 8.13 of Robert \cite{robert2013stochastic}. Another approach would be to consider a quadratic Lyapunov function and then apply a similar argument to \cite{georgiadis2006resource}.}



We let 
\[
\epsilon_r :=  \Big( \sum_{\bm z}\mu(\bm z)\sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z)   n_r \gamma_r \Big)   -\lambda_r  \, .
\]
We note that under this policy the lefthand process $\bm Z(t)$ is an ergodic Markov chain thus there exists a $t_0$ such for all $t\geq t_0$ 
\[
\left|\sum_{\bm z}\mu(\bm z)\sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z)   n_r \gamma_r  -
\sum_{\bm z}\mathbb P (\bm Z(t) = \bm z)\sum_{(\bm{\sigma} ,\bm{n})\in\mathcal{S}}p(\bm{\sigma},\bm{n} | \bm z)   n_r \gamma_r  \right| < \frac{\epsilon_r}{2}\, .
\] 
Thus for $t \geq t_0$, we have 
\[
 \mathbb E [ Q_r(t+1) - Q_r(t)  | Q_r(t)=q_r ] \leq -\frac{\epsilon_r}{2} \, ,
\]
for any $q_r >B$. We can apply Foster-Lyapunov to the above expression to prove that  $(\bm Z(t), Q_r(t))$ is a positive recurrent Markov chain. Further by \cite{bertsimas1998geometric}, we have that $\mathbb E [ Q_r(\infty) ] < \infty$ and thus $\mathbb E [ \sum_r Q_r(\infty) ] < \infty$ and thus we see that the Markov chain $(\bm Z(t), \bm Q(t))$ is positive recurrent.

