\section{Azuma-Hoeffding Lemma}
We analyze a sequence of nested Martingale difference sequences with the following Azzuma-Hoeffding Lemma. Arguments of this type are regularly used for mixing bounds in reinforcement learning \cite{qu2020finite}. 

\begin{lem}
\label{lem:azzuma_hoeffding}
Let $$m_r(i,s)= \sbrac{\hat{n}^\star_r\brac{\bm Z(i\tau(c)+s),\bar{\bm Q}^c(i\tau(c)/c)}-\E \sbrac{\hat{n}^\star_r\brac{\bm Z(i\tau(c)+s),\bar{\bm Q}^c(i\tau(c)/c)} \mid \mathcal{F}_{i\tau(c)} }}, \ r\in \mathcal{R},$$ 
where $\mathcal{F}_{i\tau(c)} = \sigma\left(\bm{X}(s) : 0 \leq s \leq i\tau(c)\right)$ is the filtration\footnote{From the Markov property it implies that we can condition on filtration rather the process $\bm X$.} and $\left|m_r(i,s)\right|\leq B$ for all $i>0$, $s>0$. Then for any $\delta>0$ we have following bound
\begin{equation} \label{eq:lem1}
\mathbb{P}\brac{\sup_{u\leq t}\left| \frac{1}{c}\sum_{s=1}^{\tau(c)-1}\sum_{i:i\tau(c) \leq c u} m_r(i,s)\right|\geq \delta}\leq 2\tau(c) \exp{\frac{-c\delta^2}{2\tau(c) B^2 t}}.
\end{equation}
Thus for $\tau(c) = O(c^{1-\epsilon})$ for some $\epsilon$ we have, with probability 1, uniformly on compact time intervals
\[
\left| \frac{1}{c}\sum_{s=1}^{\tau(c)-1}\sum_{i:i\tau(c) \leq c u} m_r(i,s)\right|
\xrightarrow[c \rightarrow \infty]{} 0.
\]
\end{lem}

\begin{proof}
Using a union bound, we can write 
\begin{align*}
 \mathbb{P}\brac{\sup_{u\leq t}\left| \sum_{s=1}^{\tau(c)-1}\sum_{i:i\tau(c) \leq cu} m_r(i,s)\right|
 \geq c\delta}
 &
 \leq\mathbb{P}\brac{\exists s\leq \tau(c)-1:\sup_{u\leq t} \left|\sum_{i:i\tau(c) \leq c u} m_r(i,s)\right|\geq \frac{c\delta}{\tau(c)}}\\
 &
\leq \sum_{s=1}^{\tau(c)-1} \mathbb{P}\brac{\sup_{u\leq t}\left|\sum_{i:i\tau(c) \leq ct} m_r(i,s)\right|\geq \frac{c\delta}{\tau(c)}}.   
\end{align*}
 Note that $\sum_{i:i\tau(c) \leq ct} m_r(i,s)$ is a martingale difference sequence. Hence, the result follows by applying the Azuma-Hoeffding Inequality~\cite{hoeffding1994probability} to the last term in the above inequality. This can be applied to the maximum of the process by combining Azuma-Hoeffding with Doob's maximal inequality. 

For almost sure convergence, we note that the summation of the \eqref{eq:lem1} if finite for all $\delta>0$. By the Borel-Cantelli Lemma this implies almost convergence below $\delta$ and since this holds for all $\delta >0$ this implies almost sure convergence to zero as required.
 % \Neil{}
\end{proof}

\section{Mixing Time Lemmas}\label{sec:mix}

We state two lemma on the coefficient of ergodicity. The proof of these can be found in the references  \cite{seneta1988perturbation,seneta2006non}.

The following lemma can be applied to show that the coefficient of ergodicity can be used to establish the mixing properties of a Markov chain.

 \begin{lem}\label{prop:ergprop}
\[
\rho(P P') \leq \rho(P)\rho(P')
\qquad
\text{and}
\qquad
|| \lambda P - \mu P ||_{\TV} \leq \rho(P) || \lambda - \mu ||_{\TV} \,.
\]
\end{lem}
The following lemma is due to Dobrushin \cite{dobrushin1956central}, and we apply this to prove Lemma \ref{lem:lemrho}.

\begin{lem}[Dobrushin's Lemma]
\begin{align*}
\rho(P)
&
=
1 -
\min_{z_1,z_2} \sum_{z \in \mathcal Z} \min \left\{ P_{z_1,z} , P_{z_2,z} \right\}	\, .
\end{align*}
\end{lem}

We can now prove Lemma \ref{lem:lemrho}, which ensures uniform fast mixing of LLEs.

\lemrho*
\begin{proof}
We apply Dobrushin's Lemma. Specifically, we note that for all $\bm Q$
\[
\mathbb P ( \bm Z(t+1) = \bm 0 | \bm Z(t) =\bm z , \bm Q(t) = \bm Q) \geq \delta^{B|\mathcal Z|}\, .
\] 
Note this corresponds to the event where the left-hand queue empties due to the decoherence of all LLEs.
Thus, it holds that
\[
\min_{z_1,z_2} \sum_{z \in \mathcal Z} \min \left\{ P^{\bm Q}_{z_1,z} , P^{\bm Q}_{z_2,z} \right\} \geq \min_{z_1,z_2}  \min \left\{ P^{\bm Q}_{z_1,\bm 0} , P^{\bm Q}_{z_2,\bm 0} \right\}  \geq \delta^{B|\mathcal Z|}\, .
\]
Thus, applying Dobrushin's Lemma:
\[
\rho(P^{\bm Q} )= 1-\min_{z_1,z_2} \sum_{z \in \mathcal Z} \min \left\{ P^{\bm Q}_{z_1,z} , P^{\bm Q}_{z_2,z} \right\} \leq 1-\delta^{B|\mathcal Z|} =: \rho <1\, ,
\]
as required.
\end{proof}


