This way, $\bm{\Gamma}^+$ is easily seen to be isomorphic to $\bGS_\Ical$ via the homomorphism $(m_1, m_2, m_3)\mapsto (m_1, m_2, m_3, 1- m_1 - m_2- m_3)$. \par
Now we define a description $\Dcal\subseteq 2^{\Mscr_\AIP}$ so that $\Ical$ is internal at arity $5$ w.r.t. $\Dcal$. The description $\Dcal$ consists of the properties
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{equation*}
  D_<= \{ (m_1, m_2, m_3)\in \Mscr_\AIP \, \vert \, m_1 < m_2 \},  \quad  \quad
D_1=\{ (1,0) \}. 
\end{empheq} 
}
\par

The following claims show that $\Ical$ is internal at arity $5$ (w.r.t. $\Dcal$):
\begin{description}
    \item[Claim 1:] \textbf{$R^\Ical$ is $\Dcal$-stable for each $R\in \Sigma_{\Gamma^+}$.} This follows by a direct application of the definitions. 
    \item[Claim 2: $D_1$ is internal at arity $5$.]
    Indeed, the minor condition $\phi_1(x)\equiv
    x= x^{(1,1)}$ is an internal definition of $D_1$.
    \item[Claim 3:] \textbf{$O^\Ical$ is internal at arity $5$.} The following is an internal definition of $O^\Ical$:
    \[
    \phi_O(x)\equiv  
    \phi_1(x^{(1,2,2,2)}) \wedge
    \phi_1(x^{(2,1,2,2)}) \wedge
    \phi_1(x^{(2,2,1,2)}) 
    \]
    \item[Claim 4:] \textbf{$E_i^\Ical$ is internal at arity $5$ for all $i\in [3]$.} The following is an internal definition of $E_i^\Ical$:
    \[
    \phi_{E_i}(x) \equiv \phi_1(x^{(2,2,2,1,2)}).
    \]
    \item[Claim 5:]  \textbf{$\Ebb_i^\Ical$ is internal at arity $5$ for all $i\in [3]$.}
    The following is an internal definition of $\Ebb_i^\Ical$:
    \[
    \phi_{E_i}(x) \equiv x^{\sigma}= x^{\tau},
    \]
    where $\sigma\in [3]^{[5]}$ is the map sending $i$ to $1$, $4$ to $2$, and the other elements to $3$,
    and $\tau\in [3]^{[5]}$ sends $i$ to $2$, $4$ to $1$, and the other elements to $3$. The key insight is that if $f^\sigma \sim_\Dcal f^\tau$ for some element $f\in \Mscr_\AIP(5)$, then it cannot be that $f(i)< f(4)$ or $f(i)> f(4)$, so it must be that $f(i) = f(4)$. 
    \item[Claim 6:] \textbf{Let $i\in [3]$. Suppose that $\phi(x)$ is an internal reference to $U^\Ical$. Then the following formula is also an internal reference to $U^\Ical:$}
    \[
    \phi^\prime(x) \equiv
    \exists y \exists z \left(  
    \phi_{E_i}(z) \wedge \phi(y)  \wedge
    y = z^{(1,2,3,4,4)} \wedge
    x = z^{(1,2,3,i,4)}
    \right).
    \]
    \textbf{Moreover, if $f$ satisfies $\phi$ on $\Mscr_\AIP$, then
    $g$ satisfies $\phi^\prime$ on $\Mscr_\AIP$,
    where $g(i)= f(i)+1$, $g(4)= f(4) - 1$, and
    $g(j)=f(j)$ for $j\neq i,4$.}
    Let us show that $\phi(x)$ is indeed an internal reference to $U^\Ical$.
    Suppose that $\Mscr_\AIP/\Dcal \models \phi(\qclass{f_x})$  with
    $\qclass{f_y}, 
    \qclass{f_z}$ as existential witnesses for $y,z$. The formula $\phi$ is an internal reference to $U^\Ical$, so
    $f_y\in U^\Ical$.
    By a similar reasoning we also obtain that $f_z\in E_i^\Ical$. It must hold that $f_z^{(1,2,3,4,4)}\sim_\Dcal f_y$, so $f_z^{(1,2,3,4,4)}\in U^\Ical$ (by Claim 1).
    Let $f_z=(m_1, m_2, m_3, 1, m_4)$. The fact that $f^{(1,2,3,4,4)}\in U^\Ical$ means that $m_1,m_2, m_3>0$. Hence, the fist three elements in $f^{(1,2,3,i,4)}$ must also be positive, so this tuple belongs to $U^\Ical$ as well. Using the fact that $f_z^{(1,2,3,i,4)}\sim_\Dcal f_x$ we conclude that $f_x\in U^\Ical$, proving that
    $\phi$ is an internal reference to $U^\Ical$. \par
    Finally, suppose that $\Mscr_\AIP\models\phi(f)$ for some element $f$, and let $g$ be defined as in the statement. Then $g$ satisfies $\phi^\prime(x)$
    on $\Mscr_\AIP$ with $f$ as an existential witness for $y$ and the tuple
    $(f(1), f(2), f(3), 1, f(4)-1)$ as 
    an existential witness for $z$.
   \item[Claim 7:] \textbf{Let $i\in [3]$. Suppose that $\phi(x)$ is an internal reference to $U^\Ical$. Then the following formula is also an internal reference to $U^\Ical:$}
    \[
    \phi^\prime(x) \equiv
    \exists y \exists z \left(  
    \phi_{\Ebb_i}(z) \wedge \phi(y)  \wedge
    y = z^{(1,2,3,4,4)} \wedge
    x = z^{(1,2,3,i,4)}
    \right).
    \]
    \textbf{Moreover, if $f$ satisfies $\phi$ on $\Mscr_\AIP$, then
    $g$ satisfies $\phi^\prime$ on $\Mscr_\AIP$,
    where $g(i)= 2f(i)$, $g(4)= f(4) - f(i)$, and
    $g(j)=f(j)$ for $j\neq i,4$.} This follows analogously to the previous claim.     

    \item[Claim 8:] \textbf{$U^\Ical$ is internal at arity $5$.} We prove this claim using \Cref{le:internal_criterion}. We define an internal reference $\phi_{n_1,n_2,n_3}(x)$ to $U^\Ical$ inductively for each $(n_1,n_2,n_3)\in \NN^3$ following the lexicographical order, satisfying that $\Mscr_\AIP \models \phi_{n_1,n_2,n_3}( (n_1,n_2,n_3, 1- n_1 - n_2 - n_3))$. We define $\phi_{1,1,1}(x) \equiv \phi_O(x)$. Now let $(n_1, n_2, n_3)\in \NN^3$ be different from $(1,1,1)$, $i\in [3]$ be the largest index for which $n_i>1$. We have two cases. Suppose that $n_i$ is odd. Then we let $m_i=n_i-1$, and $m_j=n_j$ for $j\in [3]$, $j\neq i$, and define
    \[
    \phi_{n_1, n_2, n_3}(x) \equiv
    \exists y \exists z \left(
    \phi_{m_1, m_2, m_3}(y) \wedge
    \phi_{E_i}(z) \wedge 
    z^{(1,2,3,4,4)}= y \wedge 
    z^{(1,2,3,i,4)}= x
    \right).
    \]
    Otherwise, if $n_i$ is even, we 
    let $m_i=n_i/2$, and $m_j=n_j$ for $j\in [3]$, $j\neq i$, and define
    \[
    \phi_{n_1, n_2, n_3}(x) \equiv
    \exists y \exists z \left(
    \phi_{m_1, m_2, m_3}(y) \wedge
    \phi_{\Ebb_i}(z) \wedge 
    z^{(1,2,3,4,4)}= y \wedge 
    z^{(1,2,3,i,4)}= x
    \right).
    \]
    Now Claims 6 and 7 prove the statement. 
    \end{description}

\begin{proof}[Proof of item (1) in \Cref{th:AIP_main}]
The claims in this section show that $\Ical$ is $\Dcal$-stable. We also have that $\bGS_\Ical$ is isomorphic to $\bm\Gamma^+$. Hence, the result will follow from applying \Cref{th:reduction_hardness}
after defining a $5$-ary pattern $\Psi$ of internal references to $\Ical$ w.r.t. $\Dcal$.
Given a structure $\I$ satisfying $\I\rightarrow \bm{
\Gamma}^+$, we find a homomorphism $v\mapsto (m_v, n_v, o_v)$ from $\I$ to  $\bm{
\Gamma}^+$ in polynomial time. Moreover, we can assume that $\max_v \log_2(m_v n_v o_v) \leq |I|$.
Observe that the map 
$v\mapsto (m_v, n_v, o_v, 
 1- m_v - n_v - o_v)$ is a homomorphism from $\I$ to $\bGS_\Ical$. We define
\[
\Psi_\I\equiv 
\bigexists_{v\in I}
x_v 
\bigexists_{R\in \Sigma_{\Gamma^+
}, r\in R^I} x_r 
\left(
\bigwedge_{v\in I}
\phi_{m_v,n_v,o_v}(x_v) \right) \bigwedge
\left(
\bigwedge_{R\in \Sigma_\Gamma, r\in R^I}
\phi_R(x_r)  \bigwedge_{i\in [\arty(R)]}
x_r^{\Pi^\Ical_{R,i}} = x_{r(i)}
\right).
\]
Here, the minor conditions $\phi_{m,n,o}(x)$, and $\phi_R(x)$ for $R\in \Sigma_{\Gamma^+}$, are the internal references defined in the previous claims.
To see that $\Psi_\I$ can be computed in polynomial time, observe that the formula $\phi_{m, n, o}(x_v)$ can be constructed inductively in time $O(\log_2(mno))$, and
the maximum of $\log_2(m_v,n_v, o_v)$  is at most $|I|$ for $v\in I$. Now we only need to show that
$\Mscr_\AIP \models \Psi_\I$ in order to prove that
$(\Ical, \Dcal, \Psi)$ is a valid pattern.
We give existential witnesses for the variables in $\Psi_\I$ to show that $\Mscr_\AIP\models \Psi_\I$.
For each $v\in I$, we choose \[
f_v=(m_v, n_v, o_v, 1 - m_v - n_v - o_v)
\] 
as the existential witness for $x_v$. 
By Claim 6, we know that $f_v$ satisfies $\phi_{m_v, n_v, o_v}(x)$ on $\Mscr_\AIP$. The fact that the map $v\mapsto f_v$ is a homomorphism from $\I$ to $\bGS_\Ical$ means that for each $R\in \Sigma_{\Gamma^+}, r\in R^I$ there is some $f_r\in R^\Ical$ satisfying that 
\[f_r^{\Pi_{R,i}^\Ical}= f_{r(i)} \quad \quad \text{for each $i\in \arty(R)$}. \] 
The element $f_r$ must also satisfy $\phi_R(x)$ on $\Mscr_\AIP$, because $\phi_R(x)$ is an internal definition of $R$. Hence, $f_r$ is a valid existential witness for $x_r$. This shows that $\Mscr_\AIP\models \Psi_\I$, and completes the proof that $(\Ical, \Dcal, \Psi, 5)$ is a $\Sigma$-pattern over $\Mscr_\AIP$. \par
Now item 1 of \Cref{th:AIP_main} follows from \Cref{th:reduction_hardness} together with \Cref{prop:3-grid}-(1). Observe that $3\geq \arty(U^\Ical)$ and $3\geq \arty(P)$ for all $P\in \Dcal$, so it is enough to consider templates of the form $(\bK_3^5, \B)$ in 
item (1) of \Cref{th:AIP_main}.
\end{proof}


\subsubsection{AIP: Interpreting the Grid}
\label{sec:grid_AIP}

We define a $\Sigma_\Gamma$-interpretation $\Ical$ over $\Mscr_\AIP$
such that $\bGS_\Ical$ is finitely equivalent to $\bm{\Gamma}$. This interpretation is given by 


{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{flalign*}
& U^\Ical=\left\{
\left( 2^m3^n, y\right)\in \Mscr_\AIP(2) \, \vert \, m, n \text{ non-negative integers}\right\} & \\
&
& \\ &
O^\Ical= \{(1,0)\}, \quad \quad \Pi^\Ical_{O,1}=\id, & \\
& &\\& 
E_1^\Ical= \{ 
(m, m, n, o) \in \Mscr_\AIP(4)
\, \vert \, m+n=1 \}, \quad \text{ and } & \\&
\Pi^\Ical_{E_1,1} = (1,2,2,2), \quad  
\Pi^\Ical_{E_1,2}=(1,1,2,2),  & \\ &  & \\ &
E_2^\Ical = \{
(m, m, m, n, o) \in \Mscr_\AIP(5) \, \vert
\, m + n= 1\},  \quad \text{ and } & \\ &
\Pi^\Ical_{E_2,1}=(1,2,2,2,2), \quad 
\Pi^\Ical_{E_2,2}=(1,1,1,2,2). &
\end{empheq} 
}

Observe the grid structure 
$\bm{\Gamma}$ is isomorphic to 
$\bGS_\Ical$ via the bijection 
\[
(m,n) \mapsto (2^{m-1}3^{n-1}, 1 - 2^{m-1}3^{n-1} ). \]
Moreover, this map is computable under the plain encoding for $\bm{\Gamma}$ and $\Mscr_\AIP$. \par
Next, we define a description $\Dcal\subseteq 2^{\Mscr_\AIP}$
so that
$\Ical$ is internal w.r.t. $\Dcal$ at arity $5$. The description $\Dcal$
consists of the binary properties: 
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{equation*}
U^\Ical, \quad \quad O^\Ical.
\end{empheq} 
}
Let us show that $\Ical$ is indeed internal at arity $5$ (w.r.t. $\Dcal$). This follows from the following claims.
\begin{description}
    \item[Claim 1: The properties $U^\Ical$, 
$O^\Ical$, $E_1^\Ical$, and $E_2^\Ical$ are all $\Dcal$-stable.] This follows directly from the definitions.
    \item[Claim 2: The property $O^\Ical$ is internal at arity $5$.] Indeed, the minor condition $\phi_O(x)\equiv x = x^{(1,1)}$ is an internal definition of $O^\Ical$.
 \item[Claim 3: The properties $E_1^\Ical$ and $E_2^\Ical$ are internal at arity $5$.] 
 Consider the following internal definitions for $E_1^\Ical$ and $E_2^\Ical$:
\[
\phi_{E_1}(x) \equiv \phi_{O}(x^{(1,2,1,2)}) \wedge
\phi_{O}(x^{(2,1,1,2)})
, 
\]
\[
\phi_{E_2}(x) \equiv \phi_{O}(x^{(1,2,2,1,2)}) \wedge
\phi_{O}(x^{(2,1,2,1,2)})
\wedge \phi_{O}(x^{(2,2,1,1,2)}).
\]
\item[Claim 4: The following implications hold. ]
\[
f^{(1,2,2,2)}\in U^\Ical \implies
f^{(1,1,2,2)} \in U^\Ical \quad \quad
\textbf{for all } f\in E_1^\Ical
\]
\[
f^{(1,2,2,2,2)}\in U^\Ical \implies
f^{(1,1,1,2,2)} \in U^\Ical \quad \quad
\textbf{for all } f\in E_2^\Ical.
\]
We prove the statement for $f\in E_1^\Ical$. The case where $f\in E_2^\Ical$ follows analogously. Let $(m,n)= f^{(1,2,2,2)}$. By the definition of $E_1^\Ical$, it must hold that
$f^{(1,1,2,2)}= (2m, n-m)$. Now, observe that $(m,n)\in U^\Ical$ implies that $(2m, m - n)\in U^\Ical$ as well, following the definition of $U^\Ical$. 

\item[Claim 5:] \textbf{Let $\phi(x)$ be an internal reference to $U^\Ical$ then the following formulas are also internal references to $U^\Ical$:}
\[
\phi_1(x) =  \exists y \exists z \left(
\phi(y) \wedge \phi_{E_1}(z) \wedge
y = z^{(1,2,2,2)} \wedge x = z^{(1,1,2,2)}
\right), \textbf{ and }
\]
\[
\phi_2(x) = \exists y \exists z \left(
\phi(y) \wedge \phi_{E_2}(z) \wedge
y = z^{(1,2,2,2,2)} \wedge x = z^{(1,1,1,2,2)}
\right).
\]
Indeed, let us argue the statement for $\phi_1$. The case of $\phi_2$ follows similarly. Suppose that 
$\Mscr_\AIP/\Dcal \models \phi_1(\qclass{f_x})$ for some $f\in \Qcal(2)$, and let $\qclass{f_y}$ and $\qclass{f_z}$ be existential witnesses for $y$ and $z$ respectively. In particular, 
\[
\Mscr_\AIP/\Dcal \models \phi(\qclass{f_y}), \quad \text{ and }
\Mscr_\AIP/\Dcal \models \phi_{E_1}(\qclass{f_z}).\]
The fact that $U^\Ical$, and $E_1^\Ical$ are $\Dcal$-stable and $\phi(x)$, $\phi_{E_1}(x)$ are internal references to those properties implies that $f_y\in U^\Ical$ and $f_z\in E_1^\Ical$. It must also hold that $f_y \sim_\Dcal f_z^{(1,2,2,2)}$, so we can conclude that $f_z^{(1,2,2,2)}\in U^\Ical$. By Claim 5 this implies that $f_z^{(1,1,2,2)}\in U^\Ical$ as well.
Using that $f_z^{(1,1,2,2)}\sim_\Dcal f_x$ we finally obtain that $f_x\in U^\Ical$, proving that $\phi_1(x)$ is an internal reference to $U^\Ical$.

\item[ Claim 7: The property $U^\Ical$ is internal at arity $5$.] We use~\Cref{le:internal_criterion} to prove the claim. 
We define an internal reference  $\phi_{m,n}(x)$ to $U^\Ical$ inductively for each $m,n\in \NN$. Additionally, we keep the invariant that 
$\Mscr_\AIP\models \phi_{m,n}(f)$, 
for each $m,n \in \NN$
where $f= ({2^{m-1}2^{n-1}}, 1-{2^{m-1}3^{n-1}})$. 
We define $\phi_{1,1}$ as the minor condition $\phi_O$. Now, given $m>1$, we define
\[
\phi_{m,1}(x) \equiv
\exists y \exists z \left(
\phi_{m-1,1}(y) \wedge \phi_{E_1}(z) \wedge
y = z^{(1,2,2,2)} \wedge x = z^{(1,1,2,2)}
\right).
\]
By the previous Claim, the fact that 
$\phi_{m-1,1}$ is an internal reference to $U^\Ical$, means that so is $\phi_{m,1}$ as well. Moreover, the fact that $({2^{m-2}}, 1-{2^{m-2}})$ satisfies $\phi_{m-1,1}(x)$ on $\Mscr_\AIP$, means that
$({2^{m-1}}, 1-{2^{m-1}})$ satisfies $\phi_{m,1}(x)$ on $\Mscr_\AIP$ by taking
$({2^{m-2}}, 1-{2^{m-2}})$ as an existential witness for $y$
and 
\[
\left({2^{m-2}}, 
{2^{m-2}},
1 - {2^{m-2}},
 -{2^{m-2}}\right)
\]
as an existential witness for $z$. Arguing in a similar way, if $n>1$, we define 
\[
\phi_{m,n}(x) = \exists y \exists z \left(
\phi_{m,n-1}(y) \wedge \phi_{E_2}(z) \wedge
y = z^{(1,2,2,2,2)} \wedge x = z^{(1,1,1,2,2)}
\right).
\]
Again, using the previous claim we obtain that $\phi_{m,n}$ is an internal reference to $U^\Ical$. One can also see that
$({2^{m-1}3^{n-1}}, 1-{2^{m-1}3^{n-1}})$
satisfies $\phi_{m,n}(x)$ on $\Mscr_\AIP$. This shows the clam. 
\end{description}

\begin{proof}[Proof of items (2), (3), (4) of \Cref{th:AIP_main}]
In this section we have shown that
$\bGS_\Ical$ is isomorphic to $\bm \Gamma$ through a computable homomorphism, and that $\Ical$ is
internal at arity $5$ w.r.t. $\Dcal$. Additionally, $\arty(U^\Ical)=2$, and $\arty(Q)=2$ for all $Q\in \Dcal$. Then items (3), (4) of \Cref{th:AIP_main} follow from
 \Cref{prop:grid} together via \Cref{th:reduction_undecidability} and \Cref{th:reduction_non_computability}. \par
Finally, to prove item (2) of \Cref{th:AIP_main} we define a $5$-ary 
pattern $\Psi$ of internal references to $\Ical$ w.r.t. $\Dcal$.
We map each $\I\in \Hom(\bm \Gamma, \cdot)$ to a minor condition $\Psi_\I$ defined as follows. First, we find in polynomial time a homomorphism $v\mapsto (m_v, n_v)$ from $\I$ to $\bm{\Gamma}$. Moreover,
this can be done in such a way that $\max_{v\in I} m_v + n_v \leq |I| + 1$.
Then
\[
\Psi_\I \equiv
\bigexists_{v\in I} x_v
\bigexists_{R\in \Sigma_\Gamma, r\in R^{I}} x_r  \left(
\bigwedge_{v\in I}
\phi_{m_v,n_v}(x_v) \right) \bigwedge
\left(
\bigwedge_{R\in \Sigma_\Gamma, r\in R^I}
\phi_R(x_r)  \bigwedge_{i\in [\arty(R)]}
x_r^{\Pi^\Ical_{R,i}} = x_{r(i)}
\right).
\]
Here, for each $R\in \Sigma_R$, $\phi_R(x)$ is the internal definition of $R^\Ical$ given in the previous claims, and $\phi_{m,n}(x)$ is the internal reference to $U^\Ical$ defined in Claim 7. To see that $\Psi_\I$ can be constructed in polynomial time, observe that $\phi_{m,n}$ takes $O(n+m)$ time to construct inductively, and we have that $\max_{v\in I} n_v + m_v \leq |I| +1$.
To prove that $(\Ical, \Dcal, \Psi, 5)$ is a valid pattern we need to show that $\Psi_\I$ is satisfiable over $\Mscr_\AIP$. Recall that $\Mscr_\AIP \models \phi_{m,n}(f_{m,n})$, where $f_{m,n}=({2^{m-1} 3^{n-1}}, 1 - {2^{m-1} 3^{n-1}})$, and observe that the map $v \mapsto f_{m_v, n_v}$ is a homomorphism from $\I$ to $\bGS_\Ical$. Using this fact, $\Mscr_\AIP \models \Psi_\I$ can be proven following the same reasoning as in the proof of item (1) of \Cref{th:AIP_main}, in \Cref{sec:3-dim_grid_AIP}.
\end{proof}


\subsection{The BLP Algorithm}
\label{sec:BLP}

We prove \Cref{th:BLP_main} in this section. 
To prove item (1) we give an interpretation of the super-grid $\bm{\Gamma}^+$ over $\Mscr_\BLP$, shown in \Cref{sec:3-dim_grid_BLP}. 
Items (2),(3), and (4) are proven similarly, by showing in  \Cref{sec:grid_BLP} a suitable interpretation of the grid $\bm{\Gamma}$ over $\Mscr_\BLP$. 

\subsubsection{BLP: Interpreting the Super-Grid}
\label{sec:3-dim_grid_BLP}
We define a $\Sigma_{\Gamma^+}$-interpretation $\Ical$ over $\Mscr_\BLP$
such that $\bGS_\Ical$ is finitely equivalent to $\bm{\Gamma}^+$.
This interpretation is given by
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{flalign*}
& U^\Ical=
\left\{ (m s, n s, o s, s, t) \in \Mscr_\BLP(5) \, \middle\vert \, s= \frac{1}{2^j} \text{ for some } j\in \NN, \, 
\text{and } m,n,o\in \NN
\right\}, & \\
&
& \\ &
O^\Ical = \{ (s,s,s,s,t) \in \Mscr_\BLP(5) \vert
s= 2^{-i} \text{ for some } i\in\NN \}, \quad \quad \Pi^\Ical_{O,1} =\id, & \\
& &\\& 
E_i =
\{
(s_1, s_2, s_3, s, s, t) \in \Mscr_\BLP(6) \} \quad \text{ and } & \\&
\Pi^\Ical_{E_i, 1} = (1,2,3,4,5,5), \quad \quad \Pi^\Ical_{E_i, 2}  =
(1,2,3,i,4,5) \text{ for all $i\in [3]$,} & \\ &  & \\ &
\Ebb_i^\Ical =
\{
(s_1, s_2, s_3, s_i, s, t) \in \Mscr_\BLP(6) \} & \\ &
 \Pi^\Ical_{\Ebb_i,1} =
(1,2,3,4,5,5). \quad \quad
\Pi^\Ical_{\Ebb_i, 2}  =
(1,2,3,i,4,5)  \text{ for each $i\in [3]$. } &
\end{empheq} 
}

\begin{description}
    \item[Claim 1:]\textbf{ The structure $\bGS=\bGS_\Ical$ induced by $\Ical$ is finitely equivalent to $\bm{\Gamma}^+$.}
    Let us describe  $\bGS$. 
    For each integer $i\geq 2$ we define $\bGS$ as the connected component of $\bGS_i$ containing the element 
    \[
\left(\frac{1}{2^i},\frac{1}{2^i},
\frac{1}{2^i},\frac{1}{2^i}
1 - \frac{1}{2^{i-2}}\right) \in U_\Ical.
    \]
    Observe that $\bGS$ is the disjoint union $\bigsqcup_{i\geq 2} \bGS_i$.
Given $i \geq 2$, we define $\bm{\Gamma}^+_i$
as the substructure of 
$\bm{\Gamma}^+$ induced on the set of elements $(m,n,o)\in \NN^3$ with $m+n+o+1\leq 2^i$. The structure $\bm{\Gamma}_i^+$ is isomorphic to $\bGS_i$
through the bijection
\[
(m,n,o) \mapsto \left(
\frac{m}{2^i}, \frac{n}{2^i},
\frac{o}{2^i}, \frac{1}{2^i},
1- \frac{m+n+o+1}{2^i}
\right).
\]
Finally, observe that $\bm{\Gamma}^+$ is finitely equivalent to the disjoint union $\bigsqcup_{i>2} 
\bm{\Gamma}_i^+$. Indeed, if $\I\rightarrow \bm{\Gamma}^+$,
for some finite $\I$, then it must be that $\I\rightarrow \bm{\Gamma}^+_i$ for some $i>2$, and we also have that $\bm{\Gamma}^+_i \rightarrow \bm{\Gamma}^+$ for all $i$.  This proves the claim. 
\end{description}


Now let us define a description $\Dcal\subseteq 2^{\Mscr_\BLP}$ so that $\Ical$ is internal at arity $6$ w.r.t. $\Dcal$. The description $\Dcal$ consists of the properties 
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{equation*}
D_p=\{ (\frac{1}{2^i}, 1 - \frac{1}{2^i})
\, \vert  \, i\geq 0 \},  \quad
D_<= \{ (s_1, s_2, s_3)\in \Mscr_\BLP \, \vert \, s_1 < s_2 \}, \quad
U_\Ical.
\end{empheq} 
}
The following claims establish that $\Ical$ is internal at arity $6$ (w.r.t. $\Dcal$).
\begin{description}
    \item[Claim 2:] \textbf{The properties $U^\Ical$, and $R^\Ical$
    for $R\in \Sigma_{\Gamma^+}$ are all $\Dcal$-stable.} This follows from the definitions. 
    \item[Claim 3:] \textbf{The properties $E_i^\Ical$ are internal at arity $6$.} The following is an internal definition of $E_i^\Ical$:
    \[
    \phi_{E_i}(x) \equiv
    x^{(3,3,3,1,2,3)}= 
    x^{(3,3,3,2,1,3)}.
    \]
    \item[Claim 4:] \textbf{The properties $\Ebb_i^\Ical$ are internal at arity $6$.} The following is an internal definition of $E_i^\Ical$:
    \[
    \phi_{\Ebb_i}(x) \equiv
    x^{\sigma}= 
    x^{\tau},
    \]
    where $\sigma: [6]\rightarrow [3]$ maps $i$ to $1$, 
    $4$ to $2$ and the other elements to $3$, and $\tau: [6] \rightarrow [3]$ maps $i$ to $2$, $4$ to $1$ and
    the other elements to $3$.
    \item[Claim 5:] \textbf{If $\phi(x)$ is an internal reference to $D_p$, then the following formula is also an internal reference to $D_p$:}
    \[
    \phi^\prime(x) = 
    \exists y \exists^3 z 
    \left(
    \phi(y)  \wedge 
    z = z^{(2,1,3)} 
    \wedge
    y = z^{(1,1,2)}
    \wedge 
    x = z^{(1,2,2)}
    \right).
    \]
    \textbf{Moreover, if $(1/2^i, - 1/2^i)$ satisfies $\phi(x)$ (over $\Mscr_\BLP$), then
    $(1/2^{i+1}, 1 - 1/2^{i+1})$ 
    satisfies $\phi^\prime(x)$.} Let us begin with the second part of the statement. To see that $(1/2^{i+1}, 1- 1/2^{i+1})$ satisfies $\phi^\prime(x)$, observe that $(1/2^i, 1 - 1/2^i)$ and
    $(1/2^{i+1}, 1/2^{i+1}, 1- 1/2^i)$
    are valid existential witnesses for $y$ and $z$.\par
    Now  let us show that $\phi^\prime$ is an internal reference to $\Dcal_{1/2}$. Suppose $\Mscr_\BLP/\Dcal
    \models \phi^\prime(\qclass{f_x})$
    and $\qclass{f_y},\qclass{f_z}$
    are existential witnesses for $y$ and $z$. As $\phi$ is an internal reference to $D_p$, we have $f_y\in D_p$. Hence, the fact that
    $f_y \sim_\Dcal f_z^{(1,1,2)}$
    means that $f_z^{(1,1,2)}\in D_p$,
    so $f_z(1) + f_z(2) = 1/2^i$ for some $i\geq 0$. 
    Also, observe that the fact that
    $f_z \sim_\Dcal f_z^{(2,1,3)}$
    implies $f_z(1) = f_z(2)$. Indeed, otherwise exactly one of $f_z$
    or $f_z^{(2,3,1)}$ would belong to 
    $D_<$. Hence $f_z(1)= 1/2^{i+1}$, and $f_z^{(1,2,2)}\in D_p$. Finally, because $f_x \sim_\Dcal f_z^{(1,2,2)}$, we must have $f_x\in D_p$, proving the claim. 
\item[Claim 6:] \textbf{The property $D_p$ is internal at arity $6$.} 
We use \Cref{le:internal_criterion} to prove the claim. We define an internal reference $\phi_i(x)$ to $D_p$ inductively for each $i\geq 0$ in such a way that $(1/2^i, 1- 1/2^i)$ satisfies $\phi_i(x)$ on $\Mscr_\BLP$.
We define
\[
\phi_0(x) \equiv x = x^{(1,1)}.
\]
Given $i>0$, we define
\[
\phi_i(x) \equiv \exists y \exists^3 z
 \left(
    \phi_{i-1}(y)  \wedge 
    z = z^{(2,1,3)} 
    \wedge
    y = z^{(1,1,2)}
    \wedge 
    x = z^{(1,2,2)}
    \right).
\]
Now the previous claim proves that
$\phi_i(x)$ is an internal reference to $D_p$ and $(1/2^i,1- 1/2^i)$ satisfies it. This proves the statement.
\item[Claim 7:] \textbf{The property $O^\Ical$ is internal at arity $6$.}
Let $i\geq 2$. Then, by last claim, the following formula is an internal reference to $O^\Ical$:
\begin{align*}
\phi_{O,i}(x) \equiv
\phi_i(x^{(1,2,2,2,2)}) &\wedge 
x^{(1,2,3,3,3)} = x^{(2,1,3,3,3)} \\ &\wedge
x^{(1,3,2,3,3)} = x^{(2,3,1,3,3)} \\
&\wedge
x^{(1,3,3,2,3)} = x^{(2,3,3,1,3)}.
\end{align*}
Additionally, $\phi_{O,i}(x)$ is satisfied on $\Mscr_\BLP$ by the element
