\begin{proof}[Proof of item (1) of \Cref{th:AIP_main}.]
We define a $6$-ary pattern $\Psi$ of internal references to $\Ical$ w.r.t. $\Dcal$. Then the result will frollow from \Cref{th:reduction_hardness}. 
Given $\I\in \Hom(\bm \Gamma^+, \cdot)$, we first compute a homomorphism 
$v\mapsto (m_v, n_v, o_v)$ from $\I$ to
$\bm{\Gamma}^+$ in polynomial time in such a way that $\max_{v\in I} \log_2( m_v n_v o_v) \leq |I|$. Let $M= \max_{v\in I} m_v + n_v + o_v + 1 $, and let $j= \lceil \log_2 M \rceil$. Then $F$ is actually a homomorphism from $\I$ to $\bm{\Gamma}_j^+$, where $\bm{\Gamma}_j^+\subseteq \bm{\Gamma}^+$ is the substructure defined in Claim 1. Then the minor condition $\Psi_\I$ is defined as
\begin{align*}
\bigexists_{v\in I}
x_v
\bigexists_{
R \in \Sigma_{\Gamma^+},
r\in R^I} x_r
&
\left(
\bigwedge_{v\in I}
\phi_{j,m_v, n_v, o_v}(x_v)
\right)
\bigwedge
\left(
\bigwedge_{r\in O^I}
\phi_{O,j}(x_r) \wedge
x_r = x_{r(1)}
\right) \\ 
&\bigwedge 
\left(
\bigwedge_{
R\in \Sigma_{\Gamma^+}, R\neq O,
r\in R^I}
\phi_{R}(x_r) \bigwedge_{i\in \arty(R)}
x_r^{\Pi^\Ical_{R,i}}
= x_{r(i)}
\right).
\end{align*}
To see that $\Psi_\I$ can be computed in polynomial time, observe that
$\phi_{(m_1, \dots, m_4)}$ can be constructed inductively in time $O(m_1 + \log_2(m_2 m_3 m_4))$,
$j\leq 1 + \log_2 4|I|$, and 
$\max_{v\in I} \log_2(m_v n_v o_v) \leq |I|$.
In order to prove that $(\Ical,\Dcal, \Psi, 6)$ is a valid pattern, we only need to show that $\Mscr_\BLP \models \Psi_\I$. To do this, observe that the map
\[
v\mapsto
f_v = \left(
\frac{m_v}{2^j},
\frac{n_v}{2^j},
\frac{o_v}{2^j},
\frac{1}{2^j},
1- \frac{m_v + n_v + o_v +1}{2^j}
\right),
\]
is a homomorphism from $\I$ to the connected component of
\[\left(
\frac{1}{2^j},
\frac{1}{2^j},
\frac{1}{2^j},
\frac{1}{2^j},
1- \frac{1}{2^{j-2}}
\right) \]
in $\bGS_\Ical$ (recall the isomorphisms from Claim 1). Now $\Mscr\models \Psi_\I$ can be proven analogously to item (1) of \Cref{th:AIP_main} in 
\Cref{sec:3-dim_grid_AIP}.
Observe that $5\geq \arty(U^\Ical)$ and $5\geq \arty(P)$ for all $P\in \Dcal$. Hence, we only need to consider templates of the form $(\bK_5^6, \B)$ to achieve the TFNP-hardness result. 
\end{proof}

\subsubsection{BLP: Interpreting the Grid}
\label{sec:grid_BLP}

We define a $\Sigma_\Gamma$-interpretation $\Ical$ over $\Mscr_\BLP$
such that $\bGS_\Ical$ is finitely equivalent to $\bm{\Gamma}$. This interpretation is given by
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{flalign*}
& 
U^\Ical=\left\{
\left(\frac{1}{2^m3^n},  y\right)\in \Mscr_\BLP(2) \, \vert \, m, n \text{ non-negative integers}\right\} & \\
&
& \\ &
O^\Ical= \{(1,0)\}, \quad \quad \Pi^\Ical_{O,1}=\id, & \\
& &\\& 
E_1^\Ical= \{ 
(x, x, y, y) \in \Mscr_\BLP(4)
\}, \quad \text{ and } & \\&
\Pi^\Ical_{E_1,1}=(1,1,2,2), \quad
\Pi^\Ical_{E_1,2}=(1,2,2,2), & \\ &  & \\ &
E_2^\Ical = \{
(x,x,x, y, z) \in \Mscr_\BLP(4) \, \vert
\, x+ y= 1/3\},  \quad \text{ and } & \\ &
\Pi^\Ical_{E_2,1}=(1,1,1,2,2), \quad
\Pi^\Ical_{E_2,2}=(1,2,2,2,2). &
\end{empheq} 
}
This way, the grid structure 
$\bm{\Gamma}$ is isomorphic to 
$\bS$ via the bijection 
\[
(m,n) \mapsto \left(\frac{1}{2^{m-1}3^{n-1}}, 1 -\frac{1}{2^{m-1}3^{n-1}}\right). \] 
Moreover, this map is computable under the plain encoding for $\bm{\Gamma}$ and $\Mscr_\BLP$. \par

Next, we define a description $\Dcal\subseteq 2^{\Mscr_\BLP}$
so that
$\Ical$ is internal w.r.t. $\Dcal$ at arity $5$. The description $\Dcal$
consists of the following binary properties: 
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{equation*}
U^\Ical, \quad O^\Ical, \quad D_{1/2}=\{ (1/2,1/2)\}, \quad D_{1/3}=\{(1/3, 2/3)\}.
\end{empheq} 
}

Let us show that $\Ical$ is indeed internal at arity $5$ w.r.t. $\Dcal$. This is a consequence of the following claims.
\begin{description}
    \item[Claim 1: The properties $U^\Ical$, 
$O^\Ical$, $E_1^\Ical$, and $E_2^\Ical$ are all $\Dcal$-stable.] This is a routine check.
    \item[Claim 2: The property $O^\Ical$ is internal at arity $5$ (w.r.t. $\Dcal$).] Indeed, the minor condition $\phi_O(x)\equiv x = x^{(1,1)}$ is an internal definition of $O^\Ical$.
    \item[Claim 3: The properties $D_{1/2}$ and $D_{1/3}$ are internal at arity $5$.]  The following are internal definitions for $D_{1/2}$ and $D_{1/3}$ w.r.t. $\Dcal$:
\[
\phi_{1/2}(x) \equiv x = x^{(2,1)}, \quad
\phi_{1/3}(x) \equiv 
\exists^3y \left(
y
= y^{(3,1,2)} \wedge y = y^{(2,3,1)} \wedge x = y^{(1,2,2)} \right). 
\]
 \item[Claim 4: The properties $E_1^\Ical$ and $E_2^\Ical$ are internal at arity $5$.] 
 Consider the following internal definitions for $E_1^\Ical$ and $E_2^\Ical$:
\[
\phi_{E_1}(x) \equiv \phi_{1/2}(x^{(1,2,1,2)}) \wedge
\phi_{1/2}(x^{(2,1,1,2)})
, 
\]
\[
\phi_{E_2}(x) \equiv \phi_{1/3}(x^{(1,2,2,1,2)}) \wedge
\phi_{1/3}(x^{(2,1,2,1,2)})
\wedge \phi_{1/3}(x^{(2,2,1,1,2)}).
\]
\item[Claim 5: The following implications hold. ]
\[
f^{(1,1,2,2)}\in U^\Ical \implies
f^{(1,2,2,2)} \in U^\Ical \quad \quad
\textbf{for all } f\in E_1^\Ical
\]
\[
f^{(1,1,1,2,2)}\in U^\Ical \implies
f^{(1,2,2,2,2)} \in U^\Ical \quad \quad
\textbf{for all } f\in E_2^\Ical.
\]
We prove the statement for $f\in E_1^\Ical$. The case where $f\in E_2^\Ical$ follows analogously. Let $(m,n)= f^{(1,2,2,2)}$. By the definition of $E_1^\Ical$, it must hold that
$f^{(1,1,2,2)}= (2m, n - m)$. Now, observe that $(m, n)\in U^\Ical$ implies that $(2m, n - m)\in U^\Ical$ as well, following the definition of $U^\Ical$. 

\item[Claim 6:] \textbf{Let $\phi(x)$ be an internal reference to $U^\Ical$ then the following formulas are also internal references to $U^\Ical$:}
\[
\phi_1(x) =  \exists y \exists z \left(
\phi(y) \wedge \phi_{E_1}(z) \wedge
y = z^{(1,1,2,2)} \wedge x = z^{(1,2,2,2)}
\right), \textbf{ and }
\]
\[
\phi_2(x) = \exists y \exists z \left(
\phi(y) \wedge \phi_{E_2}(z) \wedge
y = z^{(1,1,1,2,2)} \wedge x = z^{(1,2,2,2,2)}
\right).
\]
Indeed, let us argue the statement for $\phi_1$. The case of $\phi_2$ follows similarly. Suppose that 
$\Mscr_\BLP/\Dcal \models \phi_1(\qclass{f_x})$ for some $f\in \Qcal(2)$, and let $\qclass{f_y}$ and $\qclass{f_z}$ be existential witnesses for $y$ and $z$ respectively. In particular, 
\[
\Mscr_\BLP/\Dcal \models \phi(\qclass{f_y}), \quad \text{ and }
\Mscr_\BLP/\Dcal \models \phi_{E_1}(\qclass{f_z}).\]
The fact that $U^\Ical$, and $E_1^\Ical$ are $\Dcal$-stable and $\phi(x)$, $\phi_{E_1}(x)$ are internal references to those properties implies that $f_y\in U^\Ical$ and $f_z\in E_1^\Ical$. It must also hold that $f_y \sim_\Dcal f_z^{(1,1,2,2)}$, so we can conclude that $f_z^{(1,1,2,2)}\in U^\Ical$. By Claim 5 this implies that $f_z^{(1,2,2,2)}\in U^\Ical$ as well.
Using that $f_z^{(1,2,2,2)}\sim_\Dcal f_x$ we finally obtain that $f_x\in U^\Ical$, proving that $\phi_1(x)$ is an internal reference to $U^\Ical$.

\item[ Claim 7: The property $U^\Ical$ is internal at arity $5$.] We use~\Cref{le:internal_criterion} to prove the claim. 
We define an internal reference  $\phi_{m,n}(x)$ to $U^\Ical$ inductively for each $m,n\in \NN$. Additionally, we keep the invariant that 
$\Mscr_\BLP\models \phi_{m,n}(f)$, 
for each $m,n \in \NN$
where $f= (\frac{1}{2^{m-1}2^{n-1}}, 1-\frac{1}{2^{m-1}3^{n-1}})$. 
We define $\phi_{1,1}$ as the minor condition $\phi_O$. Now, given $m>1$, we define
\[
\phi_{m,1}(x) \equiv
\exists y \exists z \left(
\phi_{m-1,1}(y) \wedge \phi_{E_1}(z) \wedge
y = z^{(1,1,2,2)} \wedge x = z^{(1,2,2,2)}
\right).
\]
By the previous Claim, the fact that 
$\phi_{m-1,1}$ is an internal reference to $U^\Ical$, means that so is $\phi_{m,1}$ as well. Moreover, the fact that $(\frac{1}{2^{m-2}}, 1-\frac{1}{2^{m-2}})$ satisfies $\phi_{m-1,1}(x)$ on $\Mscr_\BLP$, means that
$(\frac{1}{2^{m-1}}, 1-\frac{1}{2^{m-1}})$ satisfies $\phi_{m,1}(x)$ on $\Mscr_\BLP$ by taking
$(\frac{1}{2^{m-2}}, 1-\frac{1}{2^{m-2}})$ as an existential witness for $y$
and 
\[
\left(\frac{1}{2^{m-2}}, 
\frac{1}{2^{m-2}},
\frac{1}{2} - \frac{1}{2^{m-2}},
\frac{1}{2} -\frac{1}{2^{m-2}}\right)
\]
as an existential witness for $z$. Arguing in a similar way, if $n>1$, we define 
\[
\phi_{m,n}(x) = \exists y \exists z \left(
\phi_{m,n-1}(y) \wedge \phi_{E_2}(z) \wedge
y = z^{(1,1,1,2,2)} \wedge x = z^{(1,2,2,2,2)}
\right).
\]
Again, using the previous claim we obtain that $\phi_{m,n}$ is an internal reference to $U^\Ical$. One can also see that
$(\frac{1}{2^{m-1}3^{n-1}}, 1-\frac{1}{2^{m-1}3^{n-1}})$
satisfies $\phi_{m,n}(x)$ on $\Mscr_\BLP$. This shows the clam. 
\end{description}

\begin{proof}[Proof of 
items (2),(3), and (4) of 
\Cref{th:BLP_main}]
Observe that $\arty(U^\Ical)=2$, and $\arty(Q)=2$ for all $Q\in \Dcal$. 
Thus items (3) (4) of \Cref{th:BLP_main} follows from
\Cref{prop:grid} together with \Cref{th:reduction_undecidability} and \Cref{th:reduction_non_computability} using the interpretation $\Ical$ and the description $\Dcal$ in this section. \par
Finally, to prove item (2) of \Cref{th:BLP_main} we define a $5$-ary pattern
$\Psi$ of internal references to $\Ical$ w.r.t. $\Dcal$.
Given  $\I\in \Hom(\bm \Gamma, \cdot)$ we construct the minor condition $\Psi_\I$ as follows. First, we find in polynomial time a homomorphism $v\mapsto (m_v, n_v)$ from $\I$ to $\bm{\Gamma}$ such that
$\max_{v\in I} m_v + n_v \leq |I| +1 $. Then
\[
\Psi_\I \equiv
\bigexists_{v\in I} x_v
\bigexists_{R\in \Sigma_\Gamma, r\in R^{I}} x_r  \left(
\bigwedge_{v\in I}
\phi_{m_v,n_v}(x_v) \right) \bigwedge
\left(
\bigwedge_{R\in \Sigma_\Gamma, r\in R^I}
\phi_R(x_r)  \bigwedge_{i\in [\arty(R)]}
x_r^{\Pi^\Ical_{R,i}} = x_{r(i)}
\right).
\]
Here, for each $R\in \Sigma_R$, $\phi_R(x)$ is the internal definition of $R^\Ical$ given in the previous claims, and $\phi_{m,n}(x)$ is the internal reference to $U^\Ical$ defined in Claim 7. To see that $\Psi_\I$ can be computed in polynomial time, observe that $\phi_{m,n}(x)$ takes $O(m+n)$ time to be constructed inductively, and $\max_{v\in I} m_v + n_v \leq |I| +1$. 
The fact that $\Mscr_\BLP \models \Psi_\I$
can be proven similarly to item (1) of \Cref{th:AIP_main} in \Cref{sec:3-dim_grid_AIP}, using that the map $v \mapsto (\frac{1}{2^{m-1} 3^{n-1}}, 1 - \frac{1}{2^{m-1} 3^{n-1}})$ is a homomorphism from $\Ical$ to $\bm{\Gamma}$.
\end{proof}



\subsection{The BLP + AIP Algorithm}
\label{sec:BLP+AIP}

We prove \Cref{th:BLP+AIP_main} in this section. This result follows from a suitable interpretation of the super-grid $\bm{\Gamma}^+$ over $\Mscr_{\BLP+\AIP}$, shown in \Cref{sec:3-grid_BLP+AIP}. 


\subsubsection{BLP + AIP: Interpreting the Super-Grid}
\label{sec:3-grid_BLP+AIP}

Let $\Mscr=\Mscr_{\BLP+\AIP}$ for the rest of this section. Recall that elements in $\Mscr(n)$ consists of pairs $(f,g)$ where $f\in [0,1]^n$ and $g\in \ZZ^n$. We consider the lexicographical order on pairs $(s,m)\in [0,1]\times \ZZ$.
We perform arithmetic on tuples coordinate-wise. We write $m \Div n$ for $n,m\in \ZZ$
to denote that there exists an integer $o\in \ZZ$ such that $o n = m$, and 
$m\nDiv n$ for the negation of this statement \footnote{The more standard notation $n \mid m$ would quickly lead to readability issues.}. Similarly, given $(s,m), (t,n)\in [0,1]\times \ZZ$,
we write $(s,m) \Div (t,n)$ if there is some integer $o\geq 0$ such that
$o(t,n)=(s,m)$.
\par

The constructions and arguments in this section are very similar to those in \Cref{sec:3-dim_grid_BLP}, so we will omit some details. \par
We define a $\Sigma_{\Gamma^+}$-interpretation $\Ical$ such that $\bGS_\Ical$ is finitely equivalent to $\bm{\Gamma}^+$. This interpretation is given by 
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{flalign*}
& U^\Ical= 
\{ 
(f,g)\in \Mscr(5) \, \vert \, f(4) < 1/3,
 g(4) \nDiv 2, \text{ and }  
(f(i),g(i)) \Div (f(4), g(4)) \text{ for each $i\in [3]$} \,
\}, & \\
&
& \\ &
O^\Ical = \{ 
(f,g)\in \Mscr(5) \, \vert
\, f(1)< 1/3, \, 
g(1) \nDiv 2, \text{ and }
 (f(i), g(i))=(f(4), g(4)) \, \text{
for all $i\in [3]$} \}, & \\
& \Pi^\Ical_{O,1} =\id, & \\
& &\\& E_i^\Ical  =
\{
(f,g)\in \Mscr(6) \, \vert
\, (f(4), g(4))=(f(5), g(5))
\}, \quad \text{ and } & \\&
\Pi^\Ical_{E_i, 1} = (1,2,3,4,5,5), \quad \quad \Pi^\Ical_{E_i, 2}  =
(1,2,3,i,4,5) \text{ for all $i\in [3]$,} & \\ &  & \\ &
\Ebb_i^\Ical =
\{
(f,g)\in \Mscr(6) \, \vert 
\, (f(4), g(4))=(f(i), g(i))
\},  \quad \text{ and } & 
\\ &
 \Pi^\Ical_{\Ebb_i,1} =
(1,2,3,4,5,5), \quad \quad
\Pi^\Ical_{\Ebb_i, 2}  =
(1,2,3,i,4,5)   \text{ for each $i\in [3]$. } &
\end{empheq} 
}


\begin{description}
    \item[Claim 1:] \textbf{The structure $\bGS=\bGS_\Ical$ induced by $\Ical$ is finitely equivalent to $\bm{\Gamma}^+$.} Given $j\in \NN$, we define $\bm{\Gamma}^+_j$ as the substructure of $\bm{\Gamma}^+$ induced on the elements $(m,n,o)\in \NN^3$ satisfying $m+n+o< j$. Consider an element $(f,g)\in U^\Ical$. Let $j= \lceil \frac{1}{f(4)} \rceil$. Then
    $\bm{\Gamma}_j^+$ is isomorphic to
    the connected component of $(f,g)$ in $\bGS$ via the bijection $(m_1, m_2, m_3) \mapsto ( f^\prime, g^\prime)$, where
    $(f^\prime(i), g^\prime(i))= m_i(f(4), g(4))$
    for $i\in [3]$,
    $(f^\prime(4), g^\prime(4))=(f(4), g(4))$,
    and $(f^\prime(5), g^\prime(5))$ is defined so that both the elements in $f^\prime$
    and the elements in $g^\prime$
    add up to $1$. We have that $\bm{\Gamma}^+$
    is finitely equivalent to the disjoint union 
    $\bigsqcup_{j\in \NN} \bm{\Gamma}_j^+$, so this proves the result.
\end{description}

Let us define a description $\Dcal\subseteq 2^\Mscr$ 
so that $\Ical$ is internal at arity $6$ w.r.t. $\Dcal$. This description consists of the properties
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{flalign*}
& U^\Ical, \quad D_<
=\{ 
(f,g)\in \Mscr(3) \, \vert
\,
(f(1), g(1)) < (f(2), g(2))
\}, & \\ &
D_{\nDiv 2}= 
\{
(f,g) \in \Mscr(2) \, \vert \, f(1) < 1/3, \,
 g(1) \nDiv 2 
\}. &
\end{empheq} 
}
Let us show that $\Ical$ is internal at arity $6$ (w.r.t. $\Dcal$). This is a consequence of the following claims.
\begin{description}
\item[Claim 2:] \textbf{The properties $U^\Ical, O^\Ical$, and $E_i^\Ical$, $\Ebb_i^\Ical$
for $i\in [3]$ are all $\Dcal$-stable.}

    \item[Claim 3:] \textbf{The property $E_i^\Ical$ is internal at arity $6$ for each $i\in [3]$}.
    This is shown in a similar way to Claim 3 in \Cref{sec:3-dim_grid_BLP}. The following is an internal definition of $E_i^\Ical$:
    \[
    \phi_{E_i}(x) \equiv x^{(3,3,3,1,2,3)} = x^{(3,3,3,2,1,3)}.
    \]
    \item[Claim 4:] \textbf{The property $\Ebb_i^\Ical$ is internal at arity $6$ for each $i\in [3]$}.
    This is shown in a similar way to Claim 4 in \Cref{sec:3-dim_grid_BLP}. The following is an internal definition of $E_i^\Ical$:
    \[
    \phi_{E_i}(x) \equiv x^\sigma = x^\tau,
    \] 
    where $\sigma: [6]\rightarrow [3]$ 
    sends $i$ to $1$, $4$ to $2$ and the other elements to $3$, and 
    $\tau:[6] \rightarrow [3]$
    sends $i$ to $2$, $4$ to $1$ and the other elements to $3$.
    \item[Claim 5:] \textbf{The property $D_{\nDiv 2}$
    is internal at arity $6$.} Indeed, the following is an internal definition of $D_{\nDiv 2}$:
    \begin{align*}
    \phi_{\nDiv 2}(x) \equiv
    \exists^5 y \Big( & 
    y^{(1,2,3,3,3)} = y^{(2,1,3,3,3)} \wedge 
    y^{(1,3,2,3,3)} = y^{(2,3,1,3,3)} \wedge \\
    &
    y^{(3,3,3,1,2)} = y^{(3,3,3,2,1)} \wedge
    x = y^{(1,2,2,2,2)}
    \Big).
    \end{align*}
    We need to show both that
    $(f,g)$ satisfy $\phi_{\nDiv 2}(x)$ on $\Mscr$
    for all $(f,g)\in D_{\nDiv 2}$ and that
    $\phi_{\nDiv 2}$ is an internal reference to
    $D_{\nDiv 2}$. Let us begin with the first statement. Let $(f,g)\in D_{\nDiv 2}$. Then let $(f_y, g_y)\in \Mscr(5)$ be defined by
    $(f_y(i),g_y(i)) = (f(1),g(1))$, for all $i\in [3]$,
    and $(f_y(i),g_y(i))=\frac{1}{2}(1-f(1), 1-g(1))$
    for $i=4,5$. The fact that $(f_y, g_y)\in \Mscr$
    follows from the definition of $D_{\nDiv 2}$. Observe that $(f,g)$ satisfies $\phi_{\nDiv 2}(x)$ on $\Mscr$ with
    $(f_y, g_y)$ as an existential witness for $y$. \par
    Now let us show that $\phi_{\nDiv 2}$ is an internal reference to $D_{\nDiv 2}$. Suppose that
    $\Mscr/\Dcal \models \phi_{\nDiv 2}(\qclass{f,g})$
    with $\qclass{f_y,g_y}$ as an existential witness for $y$. We claim that
    $(f_y(i),g_y(i))= (f_y(1), g_y(1))$ for $i\in [3]$,
    and $(f_y(4),g_y(4))=(f_y(5),g_y(5))$. Indeed, 
    suppose that $(f_y(1),g_y(1))= (f_y(2), g_y(2))$
    Then exactly one of 
    $(f_y,g_y)^{(1,2,3,3,3)}$ or 
    $(f_y, g_y)^{(2,1,3,3,3)}$ would belong to $D_<$, contradicting $ (f_y,g_y)^{(1,2,3,3,3)} \sim_\Dcal (f_y, g_y)^{(2,1,3,3,3)}$. The other identities can be argued similarly. Hence, we have that
    $3g_y(1) + 2g_y(4) = 1$, where $g_y(1), g_y(4)\in \ZZ$. This forces  $g_y(1)\nDiv 2$ and $g_y(4) \nDiv 3$. In particular $g_y(1), g_y(4)\neq 0$, 
    so $f_y(1), f_y(4) > 0$ by the definition of $\Mscr$. We also have that $3 f_y(1) + 2f_y(4)$, so
    we obtain $f_y(1)< 1/3$ using that $f_y(4)>0$. All of this together implies that
    $(f_y,g_y)^{(1,2,2,2,2)}\in D_{\nDiv 2}$. Finally, the fact that $(f,g)\sim_\Dcal (f_y,g_y)^{(1,2,2,2,2)}$ shows that 
    $(f,g)\in D_{\nDiv 2}$, as we wanted to prove. 
    \item[Claim 6:] \textbf{The property $O^\Ical$ is internal at arity $6$.} The following is an internal definition of $O^\Ical$. 
    \begin{align*}
            \phi_O(x) \equiv
    \exists y \Big( &
    \phi_{\nDiv 2}(y) \wedge
    y = x^{(1,2,2,2,2)} \wedge \\ &
    x^{(1,2,3,3,3)} = x^{(2,1,3,3,3)} \wedge
    x^{(1,3,2,3,3)} = x^{(2,3,1,3,3)} \wedge
    x^{(1,3,3,2,3)} = x^{(2,3,3,1,3)}
    \Big).
    \end{align*}
    \item[Claim 7:] \textbf{Let $i\in [3]$. Suppose $\phi(x)$ is an internal reference to $U^\Ical$. Then the following formula is also an internal reference to $U^\Ical$: }
\[
\phi^\prime(x) \equiv
\exists y \exists^6 z
\left(
\phi(y)
\wedge \phi_{E_i}(z)
\wedge y = z^{(1,2,3,4,5,5)}
\wedge x = z^{(1,2,3,4,i,5)}
\right)
\]
\textbf{Moreover, if $(f,g)$ satisfies $\phi(x)$ (on $\Mscr_\BLP$), then $(f^\prime,g^\prime)$
satisfies $\phi^\prime(x)$, where
\begin{flalign*}
    &(f^\prime(i), g^\prime(i))= (f(i),g(i))+ (f(4),g(4)), &\\&
    (f^\prime(5), g^\prime(5))= (f(5),g(5)) - (f(4),g(4)), \text{ and } & \\&
(f^\prime(j), g^\prime(j))=(f(j), g(j)), \text{  for $j\neq i, 5$.} &
\end{flalign*}
} This is shown exactly as Claim 8 in \Cref{sec:3-dim_grid_BLP}.
    \item[Claim 8:] \textbf{Let $i\in [3]$. Suppose $\phi(x)$ is an internal reference to $U^\Ical$. Then the following formula is also an internal reference to $U^\Ical$: }
\[
\phi^\prime(x) \equiv
\exists y \exists^6 z
\left(
\phi(y)
\wedge \phi_{\Ebb_i}(z)
\wedge y = z^{(1,2,3,4,5,5)}
\wedge x = z^{(1,2,3,4,i,5)}
\right)
\]
\textbf{Moreover, if $(f,g)$ satisfies $\phi(x)$ (on $\Mscr_\BLP$), then $(f^\prime,g^\prime)$
satisfies $\phi^\prime(x)$, where
\begin{flalign*}
& (f^\prime(i), g^\prime(i))= (2f(i),2g(i)), &\\&
(f^\prime(5), g^\prime(5))= (f(5),g(5)) - (f(i),g(i)), \text{ and } &\\&
 (f^\prime(j), g^\prime(j))=(f(j), g(j)), \text{ for $j\neq i, 5$.} &
\end{flalign*}
}
Again, this follows similarly to Claim 8 in \Cref{sec:3-dim_grid_BLP}.

\item[Claim 9:] \textbf{The property $U^\Ical$ is internal at arity $6$.} We prove the claim using~\Cref{le:internal_criterion}. 
For each 
$(m_1,m_2,m_3)\in \NN^3$ we define an internal reference $\phi_{m_1, m_2,m_3}(x)$ to $U^\Ical$ inductively following the lexicographical order on $\NN^3$ in such a way that $\Mscr \models \phi_{m_1, m_2, m_3}((f,g))$ for all
elements $(f,g) \in U^\Ical$ satisfying
that $(f(i),g(i))=m_i(f(4),g(4))$ for each $i\in [3]$.
We define
\[
\phi_{1,1,1}(x) \equiv 
\phi_O(x).
\]
Now, let $(m_1, m_2, m_3)\in \NN^3$ and
suppose $i\in [3]$ is the greatest index for which $m_i>1$. We have two cases. Suppose $m_i$ is odd. Then we let $n_j=m_j$ for $j\neq i$, and 
$n_i= m_i-1$, and define
\begin{align*}
\phi_{m_1,m_2, m_3}(x) \equiv
\exists y \exists^6 z
\Bigg( & 
\phi_{n_1,n_2,n_3}(y)
\wedge \phi_{E_i}(z) 
\wedge \\ & y = z^{(1,2,3,4,5,5)}
\wedge x = z^{(1,2,3,4,i,5)}
\Bigg).
\end{align*}
Otherwise, suppose $m_i$ is even. Then we let $n_j=m_j$ for $j\neq i$, and 
$n_i= m_i/2$, and define
\begin{align*}
\phi_{m_1,m_2, m_3}(x) \equiv
\exists y \exists^6 z
\Bigg( & 
\phi_{n_1,n_2,n_3}(y)
\wedge \phi_{\Ebb_i}(z) 
\wedge \\ & y = z^{(1,2,3,4,5,5)}
\wedge x = z^{(1,2,3,4,i,5)}
\Bigg).
\end{align*}
Now the statement follows from Claims 7 and 8.
\end{description}

\begin{proof}[Proof of \Cref{th:BLP+AIP_main}]
  Observe that $5\geq \arty(U^\Ical)$ and $5\geq \arty(P)$ for all $P\in \Dcal$. 
    \Cref{th:BLP+AIP_main}-(2) follows from \Cref{th:reduction_non_computability} and
    \Cref{prop:3-grid} using
    that $\bGS_\Ical$ is finitely equivalent to $\bm{\Gamma}^+$, and
    $\Ical$ is internal at arity $6$ w.r.t. $\Dcal$. \par
    We prove \Cref{th:BLP+AIP_main}-(1) using
    \Cref{th:reduction_hardness} and \Cref{prop:3-grid}. 
    To do this it is enough to define a $6$-ary pattern $\Psi$ 
    of internal references to $\Ical$ w.r.t. $\Dcal$.
    We map each finite structure $\I\in \Hom(\bm{\Gamma}^+, \cdot)$ to the minor condition
    $\Psi_\I$ defined as follows. First, we compute a homomorphism $v\mapsto (m_v, n_v, o_v)$
    from $\I$ to $\bm{\Gamma}^+$ in polynomial time, in such a way that
    $\max_{v\in I} \log_2(m_v n_v o_v) \leq |I|$. Then we set
    \[
    \Psi_I \equiv 
    \bigexists_{v\in I}
    x_v \bigexists_{R\in \Sigma_{\Gamma^+}, r\in R^I}
    x_r 
    \left(
    \bigwedge_{v\in I}
    \phi_{m_v, n_v, o_v}(x_v)
    \right) \bigwedge
    \left(
    \bigwedge_{R\in \Sigma_{\Gamma^+}, r\in R^I} 
    \phi_R(x_r) 
    \bigwedge_{i\in \arty(R)}
    x_r^{\Pi^\Ical_{R,i}} = x_{r(i)}
    \right).
    \]
    To see that $\Psi_\I$ can be computed in polynomial time, observe that $\phi_{m,n,o}$
    takes $O(\log_2(mno))$ time to be constructed inductively, and $\max_{v\in I} \log_2(m_v n_v o_v) \leq |I|$.
    In order to prove that $(\Ical, \Dcal, \Psi, 6)$ is a valid pattern we just need to show that
    $\Mscr \models \Psi_\I$.
    We give an explicit homomorphism from $\I$ to $\bGS_\Ical$. This map is defined by
    $v \mapsto (f_v, g_v)$, where
     \[
    f_v = \left( 
    \frac{m_v}{j}, \frac{n_v}{j},
    \frac{o_v}{j}, \frac{1}{j}, 
    1- \frac{m_v + n_v + o_v + 1}{j}
    \right), \]
    where $j= \max_{v\in I} m_v + n_v + o_v +1$, and    
    \[
    g_v = \left( 
    m_v, n_v,
    o_v, 1, 
    1- (m_v + n_v + o_v + 1)
    \right).
    \]
    Now $\Mscr \models \Psi_\I$ can be shown the same way as in the proof of item (1) of \Cref{th:AIP_main} in \Cref{sec:3-dim_grid_AIP}.    
\end{proof}
\subsection{Cyclic Polymorphisms}
\label{sec:cyclic}

In this section we prove items (1)(i-iv) of \Cref{th:minor_identities_main}. We begin by introducing a minion $\overline{\Cscr}$ that characterizes the existence of cyclic polymorphisms suitably. Then, item (1)(i) will follow from interpreting the grid $\bm \Gamma$ over $\overline{\Cscr}$ (\Cref{sec:all_cyclic}), and items (1)(ii-iv) from interpreting growing triangular slices $\bm{\nabla}_n$ over $\overline \Cscr$ (\Cref{sec:cyclic_exists}). \par
Given prime arity. Given a prime number $p\in \NN$, we define the minion $\mathscr{C}_p$
as follows. We let
\[
\Cscr(n) = 
\left\{
\gamma \in \left( 2^{\ZZ_p} \right)^n \, \middle\vert
\, \bigcup_{i\in [n]} \gamma(i) = \ZZ_p, \, 
\text{ and } \gamma(i)\cap \gamma(j) = \emptyset \, \text{for all } i\neq j
\right\}.
\]
The minoring operation is defined as follows. Let $\gamma\in \Cscr(n)$, $\pi:[n]\rightarrow [m]$. Then $\gamma^\pi = \omega$, where $\omega(j)=
\cup_{i\in \pi^{-1}(j)} \gamma(i)$ for each $j\in [m]$, and empty unions yield the empty set.\par

Given a set $S\subseteq \ZZ_p$ and an element $m \in \ZZ_p$ we write $S + m$ for the set
$\{ n+m \, \vert \, n\in S
\}$. Given two elements $\gamma,\omega \Cscr_p(n)$, we write 
$\gamma \sim_p \omega$ if there is some element $m\in \ZZ_p$ such that $\gamma(i) = \omega(i) + m$ for all $i\in [n]$. Observe that $\sim_p$ is an equivalence relation and it is compatible with minoring, in the sense that
$\gamma \sim_p \omega$ implies $\gamma^\pi \sim_p \omega^\pi$. We write $\overline{\gamma}$ to denote the $\sim_p$-class of an element $\gamma$, 
and define $\overline{\Cscr_p}$ as the quotient minion $\Cscr_p / \sim_p$.

\begin{lemma}
\label{le:cyclic}
    Let $\Mscr$ be a minion and $p\in \NN$ be a prime number. Then $\Mscr$ contains a cyclic element of arity $p$ if and only if $\overline{\Cscr}_p \rightarrow\Mscr$.
\end{lemma}
\begin{proof}
    We show both directions. Suppose there is a homomorphism $\alpha: \overline{\Cscr}_p \rightarrow \Mscr$. Let $\gamma=( \{0\}, \{1\}, \dots, \{p-1\})\in \Cscr_p(p)$. Then the element $\overline{\gamma}\in \overline{\Cscr}_p(p)$ is cyclic, so $\alpha(\overline{\gamma})$ must be cyclic as well. \par
    In the other direction, suppose that $f\in \Mscr(p)$ is a cyclic element. Then we define a homomorphism $\alpha: \overline{\Cscr}_p \rightarrow \Mscr$
    by setting $\alpha(\overline{\gamma}) = f$. This defines the image of any element $\overline{\omega}\in \Cscr_p(n)$. Indeed,
    we have that $\omega=\gamma^{\pi_\omega}$,
    where $\pi_{\omega}: [p] \rightarrow [n]$ is the map that sends $i\in [p]$ to $j\in [n]$ if the element $i-1\in \ZZ_p$
    belongs to $\omega(j)$. Hence, we can define $\alpha(\overline{\omega}) = f^{\pi_\omega}$.
    To see that this is well defined, we need to prove that whenever $\omega_1 \sim_p \omega_2$
    then $f^{\pi_{\omega_1}}=f^{\pi_{\omega_2}}$.
    However, if $\omega_1 \sim_p \omega_2$, then there is some $m\in \ZZ_p$ such that
    $\omega_1(i) = \omega_2(i) + m$ for all $i$.
    This means that $\pi_{\omega_2}= 
    \pi_{\omega_1} \circ \sigma^{m}$, where
    $\sigma = (p-1, 1,\dots, p-2)$ is the cyclic shift. Hence, as $f$ is cyclic,
    we obtain that $f^{\pi_{\omega_2}}=
    (f^{\sigma^m})^{\pi_{\omega_1}}= f^{\omega_1}$, as we wanted.
    We have shown that $\alpha$ is a well-defined map. The fact that $\alpha$ is a minion homomorphism now follows from the fact that
    if $\omega_1 = \omega_2^{\pi}$,
    for some elements $\omega_1, \omega_2\in \Cscr_p$
    then 
    $\pi_{\omega_1} = \pi \circ \pi_{\omega_2}$.
\end{proof}

We define $\overline{\Cscr}$ as the disjoint union
$\bigsqcup_{p \text{ prime }} \overline{\Cscr}_p$. A straight-forward corollary of last lemma is the following.

\begin{corollary}
    \label{le:minion_all_cyclic}
      Let $\Mscr$ be a minion. Then $\Mscr$ contains a cyclic element of each prime arity $p$ if and only if $\overline{\Cscr} \rightarrow\Mscr$.
\end{corollary}

\subsubsection{Cyclic Polymorphisms: Interpreting the Grid}
\label{sec:all_cyclic}

We define a $\Sigma_\Gamma$-interpretation $\Ical$ over
$\overline{\Cscr}$ satisfying that $\bGS_\Ical$ is finitely equivalent to $\bm{\Gamma}$. This interpretation is given by
{
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{flalign*}
& U^\Ical= \overline{\Cscr}(3) & \\
&
& \\ &
O^\Ical = \{
\overline{\omega} \in \overline{\Cscr}(3) \, \vert 
\, \omega(1)= \omega(2) = \emptyset
\}, 
\quad \quad \Pi^\Ical_{O,1}=\id, & \\
& &\\& 
E_i^\Ical = \{
\overline{\omega} \in \overline{\Cscr}(4) \, \big\vert 
\, |\omega(3)|= 1
\} , \quad \text{ and } & \\&
\Pi^\Ical_{E_i,1} = (1,2,3,3), \quad  
\Pi^\Ical_{E_i,2}=(1,2,i,3),  \quad \text{ for $i\in [2]$.}&
\end{empheq} 
}


Given a prime number $p$ we define $\Ical_p$ as the restriction $\Ical\vert_{\overline{\Cscr}_p}$.
Then we have that $\bGS_\Ical= \bigsqcup_{p \text{ prime}} \bGS_{\Ical_p}$.

\begin{description}
    \item[Claim 1:]  \textbf{The structure 
    $\bGS_\Ical$ induced by $\Ical$ is finitely equivalent to $\bm{\Gamma}$.}
    Given a number $m\in \NN$, we define $\bm{\Gamma}_m$ to be the substructure of $\bm{\Gamma}$ induced on the elements $(n,o)\in \NN^2$ satisfying $n+o \leq m$.
    Observe that $\bm{\Gamma}$ is finitely equivalent to the disjoint union $\bigsqcup_{i\in \NN} \bm{\Gamma}_i$, and that $\bm{\Gamma}_i\rightarrow \bm{\Gamma}_j$ for each pair $i\leq j$. We prove that
    $\bm{\Gamma}_{p+2}$ is finitely equivalent to $\bGS_{\Ical_p}$
    for each prime number $p$. 
    Observe that this proves the claim. We define suitable homomorphisms. Let $F: \bGS_{\Ical_p}
    \rightarrow \bm{\Gamma}_{p+2}$ be the map 
    $\overline{\omega}\mapsto (|\omega(1)|+1,|\omega(2)|+1)$. To see that $F$ is well defined, observe that the relation $\sim_p$ preserves the size of sets. That is,
    if $\omega_1 \sim_p \omega_2$ for some
    $\omega_1, \omega_2\in \Cscr_p$, then
    $|\omega_1(i)|=|\omega_2(i)|$ for all $i$.
    The fact that $F$ is indeed a homomorphism follows from the definition of $\bGS_{\Ical_i}$. \par
    Now let $H: \bm{\Gamma}_{p+2}\rightarrow 
    \bGS_{\Ical_p}$ be the map given by
    $(m,n)\mapsto \overline{\omega_{m,n}}$,
    where $\omega_{m,n}\in \Cscr_p(3)$ is defined as $( X_m, Y_n, \ZZ_p \setminus (X_m \cup Y_n))$, where $X_m= \{ 0,\dots, m-1\}$ and
    $Y_n= \{p-n + 1, \dots
    p -1 \}$. Observe that for $m=n=1$ we have $X_m=Y_n= \emptyset$. Hence,
    $H(1,1)\in O^{\GS_{\Ical_p}}$.    
    To see that $H$ is a homomorphism we need to prove that 
    $H$ preserves $E_1$ and $E_2$. We show the statement for $E_1$, the other case is analogous. In other words, we need to prove that
    $(\overline{\omega_{m,n}},
    \overline{\omega_{m+1,n}})\in E_1^{\GS_{\Ical_p}}$ for all $((m,n),(m+1,n))\in E_1^{\Gamma_{p+2}}$. Consider the element $\omega= ( X_m, Y_n, \{m\}, \ZZ_p\setminus (X_m \cup Y_n \cup \{m\}) )$. Then we have that $\overline{\omega}\in E_1^\Ical$, and 
    \[
    \overline{\omega}_{m,n}=
    \overline{\omega}^{\Pi^\Ical_{E_1,1}},\quad
    \overline{\omega}_{m+1,n}=
    \overline{\omega}^{\Pi^\Ical_{E_1,2}},
    \]
    as we wanted to prove. This completes the proof of the claim.
    \end{description}

    We define a description $\Dcal\subseteq 2^{\overline{\Cscr}}$ so that $\Ical$ is internal at arity $5$ w.r.t. $\Dcal$. This description consists of the properties 
    {
\setlength{\fboxsep}{1em}
\begin{empheq}[box=\fbox]{flalign*}
& D_0= \{
    \overline{\omega}\in \overline{\Cscr}(2) \, \Big\vert \, \omega(1)= \emptyset
    \},& \\ &
D_1= \{
    \overline{\omega}\in \overline{\Cscr}(2) \, \Big\vert \, |\omega(1)|= 1
    \}, & \\ &
D_<= \{
    \overline{\omega}\in \overline{\Cscr}(3) \, \Big\vert \, |\omega(1)| < |\omega(2)|
    \}, &\\&
D_\div= \{
    \overline{\omega}\in \overline{\Cscr}(3) \, \Big\vert \,  |\omega(2)| = n|\omega(1)| \text{ for some integer } n\geq 0
    \}, \text{ and } &\\&
D_== \{
    \overline{\omega}\in \overline{\Cscr}(3) \, \Big\vert \, |\omega(1)| = |\omega(2)|
    \}.
\end{empheq} 
}
We warn the reader that we deal with two nested equivalence relations from now on: An element $\qclass{\overline{\omega}}\in \overline{\Cscr}/\Dcal$ is a $\sim_\Dcal$-class of some $\overline \omega \in \overline \Cscr$, which is in turn a $\sim_p$-class of an element $\omega \in \Cscr_p$ for some prime $p$. \par
We show that $\Ical$ is internal at arity $5$ (w.r.t. $\Dcal$) through the following claims.
    \begin{description}
        \item[Claim 2:] \textbf{The properties $U^\Ical$, $O^\Ical$,
        $E_1^\Ical$ and $E_2^\Ical$ are all $\Dcal$-stable.} This is a routine check.  
        \item[Claim 3:] \textbf{The property $O^\Ical$ is internal at arity $5$.} Indeed, the following formula is an internal definition of $O^\Ical$:
        \[
        \phi_O(x) \equiv x = x^{(3,3,3)}.
        \]
        \item[Claim 4: ] \textbf{Let $p$ be a prime number. 
        Then the following property is an internal reference to $D_=$:} 
        \[
        \phi_{=,p}(x) \equiv x = x^{(2,1,3)}, 
        \]
        \textbf{if $p=2$, and }
        \begin{align*}
        \phi_{=,p}(x) = 
        &\bigexists_{i\in [p-2]}^4 y_i
        \bigexists_{i\in [p-3]}^5 z_i
        \left(
        y_1^{(1,2,3,3)} = x
        \wedge y_1^{(3,1,2,3)}= x
        \wedge y_{j+1}^{(2,3,1,3)}= x
        \right) \wedge \\
        & \left(
        \bigwedge_{i\in [p-3]}
         z_i^{(1,2,3,3,3)} =
         z_i^{(3,3,1,2,3)} \wedge
         y_i = z_i^{(1,2,3,4,4)} \wedge
         y_{p-2} = z_i^{(1,2,4,3,4)}        
        \right),
        \end{align*}
        \textbf{if $p>2$. }
        Let us show that $\phi_{=,j}(x)$ is an internal reference. The case $p=2$ is straightforward. We assume that $p\geq 3$.
        Suppose that
        $\overline{\Cscr}/\Dcal \models
        \phi_{=,j}(\qclass{\overline{\omega_x}})$
        with $\qclass{\overline{\omega_{y_i}}}$
        as the witness for $y_i$ for each $i\in [j+1]$ and 
        $\qclass{\overline{\omega_{z_i}}}$
        as the witness for $z_i$ for each $i\in [j]$. We need to show that $|\omega_x(1)| = |\omega_x(2)|$. Suppose that
        $|\omega_x(1)|<|\omega_x(2)|$ for a contradiction (the reverse inequality can be dealt with analogously). We prove that
        $|\omega_{y_i}(1)| < |\omega_{y_i}(2)|
        < |\omega_{y_i}(3)|$
        for all $i\in [p-2]$ by induction on $i$. For $i=1$, we have that $\overline{\omega_{y_1}}^{(1,2,3,3)} \sim_\Dcal
        \overline{\omega_{x}}
        $, and
        $\overline{\omega_{y_1}}^{(3,1,2,3)} \sim_\Dcal
        \overline{\omega_{x}}$,
        so necessarily 
        $|\omega_{y_1}(1)| < |\omega_{y_1}(2)|
        < |\omega_{y_1}(3)|$. Now let $i>1$ and suppose that
        \[
         |\omega_{y_{i-1}}(1)| < |\omega_{y_{i-1}}(2)|
        < |\omega_{y_{i-1}}(3)|.
        \]
        We have that
        $\overline{\omega_{y_{i-1}}}\sim_\Dcal
        \overline{\omega_{z_{i-1}}}^{(1,2,3,4,4)}$, so 
        \[
         |\omega_{z_{i-1}}(1)| < |\omega_{z_{i-1}}(2)|
        < |\omega_{z_{i-1}}(3)|.
        \]
        Additionally, $\overline{\omega_{z_{i-1}}}^{(1,2,3,3,3)}\sim_\Dcal
